import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardPostLike } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardPostLike";

/**
 * Attempt to update a non-existent (invalid or already-deleted) post like record.
 *
 * This test verifies that attempting to update a discussionboard post like using an invalid UUID (one that does not correspond to any record in the database, either because it never existed or has already been deleted) results in an appropriate error.
 * The server must not create a new like, nor return a successful update for a missing record. Proper error responses (such as 404 Not Found) are required by business logic.
 *
 * Process:
 * 1. Attempt to update a post like with an invalid or random UUID.
 * 2. Validate that the API responds with an error and does NOT mistakenly create a new post like record.
 */
export async function test_api_discussionboard_test_update_post_like_invalid_id(
  connection: api.IConnection,
) {
  // 1. Generate a random UUID, presumed not to exist in the database.
  const nonExistentId: string = typia.random<string & tags.Format<"uuid">>();
  const updatePayload: IDiscussionboardPostLike.IUpdate = {
    discussionboard_post_id: typia.random<string & tags.Format<"uuid">>(),
    discussionboard_member_id: typia.random<string & tags.Format<"uuid">>(),
  };

  // 2. Attempt update and expect error (such as 404 Not Found, or business error).
  await TestValidator.error("should error on invalid post like ID")(
    async () => {
      await api.functional.discussionboard.interactions.postLikes.putById(
        connection,
        {
          id: nonExistentId,
          body: updatePayload,
        },
      );
    },
  );
}

