import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMembers } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMembers";

/**
 * Test that duplicate member registration is properly blocked.
 *
 * This test verifies the registration endpoint correctly enforces unique constraints
 * on member identity. First, it registers a new member with a valid (random)
 * 'joined_at' timestamp and 'status'. Then, it attempts to re-register another
 * member with the *same* values for both fields, thus representing a duplicate
 * entry. The test expects the API to reject the second registration with a
 * duplication or validation error, per the business rule that member identity
 * must be unique in the system.
 *
 * Steps:
 * 1. Register an initial member with realistic values.
 * 2. Attempt to register again with the exact same payload.
 * 3. Assert that an error is thrown for the second registration.
 */
export async function test_api_discussionboard_test_create_member_with_duplicate_identifier(
  connection: api.IConnection,
) {
  // Step 1: Register the first member
  const memberInput: IDiscussionboardMembers.ICreate = {
    joined_at: typia.random<string & tags.Format<"date-time">>(),
    status: "active"
  };
  const firstMember = await api.functional.discussionboard.actors.members.post(connection, { body: memberInput });
  typia.assert(firstMember);

  // Step 2 & 3: Attempt to register the duplicate and expect an error
  await TestValidator.error("duplicate member registration should fail")(
    async () => {
      await api.functional.discussionboard.actors.members.post(connection, { body: memberInput });
    }
  );
}

