/**
 * Test that updating a moderator assignment with a non-existent or invalid ID yields a 404 Not Found error.
 *
 * This test will attempt to update a moderator role record using a UUID that should not exist in the database. It will also test
 * with an obviously invalid ID format (not a UUID). Both cases should result in a 404 Not Found error as per API contract.
 *
 * 1. Prepare a random valid UUID that does not correspond to any existing moderator assignment
 * 2. Attempt to update with a valid, but non-existent UUID (should yield 404)
 * 3. Attempt to update with a syntactically invalid ID (not a UUID, e.g., 'invalid-id') (should yield 404 or validation error)
 * 4. Assert that the correct error is thrown in each case (ideally 404)
 */
export async function test_api_discussionboard_actors_moderators_putById_test_update_moderator_assignment_not_found(
  connection: api.IConnection,
) {
  // 1. Attempt update with a random valid UUID (not associated with any moderator assignment)
  const nonExistentId: string & tags.Format<"uuid"> = typia.random<string & tags.Format<"uuid">>();

  // 2. Prepare a minimal valid update body
  const updateData: DiscussionBoardModerators.IUpdate = {
    demoted_at: new Date().toISOString() as string & tags.Format<"date-time">,
  };

  // 3. Should throw an error (404) for non-existent ID
  await TestValidator.error("404 when updating non-existent moderator record")(
    () =>
      api.functional.discussionboard.actors.moderators.putById(connection, {
        id: nonExistentId,
        body: updateData,
      })
  );

  // 4. Try with an obviously malformed ID (should throw validation or not found)
  const invalidId = "invalid-id" as string & tags.Format<"uuid">;
  await TestValidator.error("Not found or validation error for malformed id")(
    () =>
      api.functional.discussionboard.actors.moderators.putById(connection, {
        id: invalidId,
        body: updateData,
      })
  );
}

