import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardChannel } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardChannel";

/**
 * Test the soft-deletion (archiving) of a channel entity as an admin.
 *
 * This test verifies that when an admin soft-deletes a channel (discussionboard_channels),
 * the following business rules hold:
 * 1. The channel is created with valid data.
 * 2. The channel is soft-deleted (deleted_at set via DELETE endpoint).
 * 3. The returned deletion result contains the correct channel id and deleted_at ISO 8601 timestamp.
 * 4. When querying for channels (in the real system, via a list endpoint), it would not appear in defaults (not implemented here, so this is commented in code).
 * 5. The deleted_at field is set after deletion, and is null before.
 * 6. Dependent data (not testable with current endpoints—skipped).
 * 7. Audit logging confirmation is noted (cannot be tested here).
 *
 * Steps:
 * 1. Create a channel with unique code, enabled true, optional description.
 * 2. Soft-delete the channel by its id.
 * 3. Validate response has correct channel id and deleted_at, and verify API contract.
 * 4. (Comment) If a channel list/get endpoint existed, confirm the channel would be hidden/deleted.
 * 5. Ensure test only exercises accessible, contract-supported behavior with available APIs.
 */
export async function test_api_discussionboard_test_soft_delete_channel_success(
  connection: api.IConnection
) {
  // 1. Create channel
  const createInput: IDiscussionboardChannel.ICreate = {
    code: RandomGenerator.alphaNumeric(6),
    name: RandomGenerator.paragraph()(1),
    description: RandomGenerator.content()()(),
    enabled: true,
  };
  const created = await api.functional.discussionboard.systematic.channels.post(connection, {
    body: createInput,
  });
  typia.assert(created);

  // 2. Soft-delete the channel by id
  const removeResult = await api.functional.discussionboard.systematic.channels.eraseById(connection, {
    id: created.id,
  });
  typia.assert(removeResult);
  TestValidator.equals("deleted channel id")(removeResult.id)(created.id);

  // 3. Verify deleted_at is present and is an ISO string
  TestValidator.predicate("deleted_at set and is string")(
    typeof removeResult.deleted_at === "string" &&
    !isNaN(Date.parse(removeResult.deleted_at))
  );

  // 4. (Comment) If list endpoint available: verify not returned in active channel lists.
  // 5. (Comment) Dependent data and audit logging are not verifiable with current API surface. Steps skipped.
}

