import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { DiscussionBoardAdmins } from "@ORGANIZATION/PROJECT-api/lib/structures/DiscussionBoardAdmins";

/**
 * Validate error handling when attempting to promote a member to admin with an invalid member ID.
 *
 * This test ensures the system does not elevate privileges when provided a non-existent or incorrectly formatted member UUID.
 * It must:
 * 1. Attempt to elevate a member with a well-formed, but non-existent uuid.
 * 2. Attempt to elevate with a malformed (non-uuid) string.
 * 3. Assert that each operation throws an error (validation or not-found), and does not create any admin record.
 * 4. Confirm proper error occurs with no side effect (e.g., no accidental record creation).
 */
export async function test_api_discussionboard_test_promote_member_to_admin_with_invalid_member_id(connection: api.IConnection) {
  // 1. Try with a well-formed but non-existent UUID
  await TestValidator.error("non-existent member should fail")(() =>
    api.functional.discussionboard.actors.admins.post(connection, {
      body: {
        discussionboard_member_id: typia.random<string & tags.Format<"uuid">>(), // random uuid, very unlikely to match real user
        elevated_at: new Date().toISOString(),
      } satisfies DiscussionBoardAdmins.ICreate,
    })
  );

  // 2. Try with a clearly malformed member ID
  await TestValidator.error("malformed uuid should fail")(() =>
    api.functional.discussionboard.actors.admins.post(connection, {
      body: {
        discussionboard_member_id: "not-a-uuid",
        elevated_at: new Date().toISOString(),
      } satisfies DiscussionBoardAdmins.ICreate,
    })
  );
}

