import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMembers } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMembers";

/**
 * Validate that a member can view only their own permissible detail fields, and not admin/sensitive fields.
 *
 * 1. Register a new member (self-registration).
 * 2. As the new member, retrieve their details with GET /discussionboard/actors/members/:id
 * 3. Assert that all expected self-visible profile properties are present.
 * 4. Assert that there are no admin-only or sensitive fields present in the response.
 */
export async function test_api_discussionboard_actors_members_getById_test_get_self_detail_as_member_limited_fields(
  connection: api.IConnection,
) {
  // 1. Register a new member
  const member: IDiscussionboardMembers = await api.functional.discussionboard.actors.members.post(connection, {
    body: {
      joined_at: typia.random<string & tags.Format<"date-time">>(),
      status: "active",
    } satisfies IDiscussionboardMembers.ICreate,
  });
  typia.assert(member);

  // 2. Retrieve own details using own ID
  const selfDetail: IDiscussionboardMembers = await api.functional.discussionboard.actors.members.getById(connection, {
    id: member.id,
  });
  typia.assert(selfDetail);

  // 3. Assert allowed profile fields are present
  TestValidator.equals("ID matches")(selfDetail.id)(member.id);
  TestValidator.equals("status matches")(selfDetail.status)(member.status);
  TestValidator.equals("join date matches")(selfDetail.joined_at)(member.joined_at);

  // 4. Assert no admin/sensitive fields exist (by confirming only schema-defined props are present)
  const allowedKeys = ["id", "joined_at", "status"];
  TestValidator.equals("No extra fields")(Object.keys(selfDetail).sort())(allowedKeys.sort());
}

