 * This test checks that the /discussionboard/actors/members POST endpoint enforces schema and business validation rules
 * when clients attempt to create a new member with missing required fields or invalid field values.
 *
 * Steps:
 * 1. Prepare and submit a registration request with a missing `joined_at` field (should trigger a validation error)
 * 2. Prepare and submit a registration request with a missing `status` field (should trigger a validation error)
 * 3. Prepare and submit a registration request with an invalid status value (empty string)
 * 4. Optionally: send a request with a blatantly invalid date-time format for `joined_at`
 * 5. Assert that each API response indicates a validation failure (exception thrown or error response)
 * 6. Do not expect a created member to be returned in any of these error cases
 */
export async function test_api_discussionboard_test_create_member_with_malformed_data(
  connection: api.IConnection,
) {
  // Case 1: Missing required field 'joined_at'
  await TestValidator.error("Missing joined_at triggers validation error")(
    async () => {
      await api.functional.discussionboard.actors.members.post(connection, {
        body: {
          // joined_at: intentionally omitted
          status: "active",
        } as any, // This line may not be accepted if type safety must not be violated
      });
    },
  );

  // Case 2: Missing required field 'status'
