 * 3. Update the moderator assignment by setting 'demoted_at' field to a datetime value.
 * 4. Verify the returned object matches the update (demoted_at present and matches input; IDs remain unchanged).
 * 5. Optionally, assert other fields remain unaltered and no extraneous changes occur.
 */
export async function test_api_discussionboard_actors_moderators_test_update_moderator_assignment_successful(
