import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMembers } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMembers";
import type { IDiscussionboardThreads } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardThreads";

/**
 * Validates retrieval and error behaviors of thread detail API (by thread ID).
 *
 * 1. Register a new member (regular user).
 * 2. Create a new thread authored by the member (requires unique board/member IDs).
 * 3. Retrieve the thread by its ID and verify all fields are populated and correct.
 * 4. Attempt to retrieve a non-existent (random UUID) thread; must fail with not-found error.
 * 5. Soft-delete the created thread.
 * 6. Attempt to retrieve the deleted thread, expecting error or confirmation of its deleted state.
 *
 * Tests both successful and failure scenarios, error handling, and proper business logic (soft-delete effect).
 */
export async function test_api_discussionboard_test_get_thread_details_success_and_not_found(
  connection: api.IConnection,
) {
  // 1. Register a new member
  const memberInput: IDiscussionboardMembers.ICreate = {
    joined_at: new Date().toISOString(),
    status: "active",
  };
  const member = await api.functional.discussionboard.actors.members.post(connection, { body: memberInput });
  typia.assert(member);

  // 2. Create a thread for a random board authored by the member
  const threadInput: IDiscussionboardThreads.ICreate = {
    discussionboard_board_id: typia.random<string & tags.Format<"uuid">>(),
    discussionboard_member_id: member.id,
    title: "Test Thread Title",
    description: "Test thread body for E2E validation.",
    status: "open",
    created_at: new Date().toISOString(),
  };
  const thread = await api.functional.discussionboard.threads.threads.post(connection, { body: threadInput });
  typia.assert(thread);
  TestValidator.equals("discussionboard_member_id")(thread.discussionboard_member_id)(member.id);
  TestValidator.equals("title")(thread.title)(threadInput.title);
  TestValidator.equals("description")(thread.description)(threadInput.description);
  TestValidator.equals("status")(thread.status)(threadInput.status);

  // 3. Retrieve the existing thread
  const readThread = await api.functional.discussionboard.threads.threads.getById(connection, { id: thread.id });
  typia.assert(readThread);
  TestValidator.equals("id")(readThread.id)(thread.id);
  TestValidator.equals("discussionboard_board_id")(readThread.discussionboard_board_id)(threadInput.discussionboard_board_id);
  TestValidator.equals("discussionboard_member_id")(readThread.discussionboard_member_id)(member.id);
  TestValidator.equals("title")(readThread.title)(threadInput.title);
  TestValidator.equals("description")(readThread.description)(threadInput.description);
  TestValidator.equals("status")(readThread.status)(threadInput.status);
  TestValidator.equals("deleted_at")(readThread.deleted_at)(null);

  // 4. Try to fetch a random, non-existent thread
  await TestValidator.error("Fetching non-existing thread should fail")(
    async () => {
      await api.functional.discussionboard.threads.threads.getById(connection, {
        id: typia.random<string & tags.Format<"uuid">>(),
      });
    },
  );

  // 5. Soft-delete the created thread
  const deleted = await api.functional.discussionboard.threads.threads.eraseById(connection, { id: thread.id });
  typia.assert(deleted);
  TestValidator.equals("id")(deleted.id)(thread.id);
  TestValidator.predicate("deleted_at is set")(
    typeof deleted.deleted_at === "string" && deleted.deleted_at.length > 0
  );

  // 6. Attempt to retrieve the soft-deleted thread (should error or indicate deleted)
  await TestValidator.error("Fetching deleted thread should fail")(
    async () => {
      await api.functional.discussionboard.threads.threads.getById(connection, {
        id: thread.id,
