/**
 * 테스트 목적: 비관리자(또는 권한 없는 사용자)로 감사 로그를 삭제 시도하며, 이때 반드시 권한 부족(예: 403 Forbidden) 오류가 발생해야 함을 검증.
 *
 * 시나리오 요약:
 * 1. 비관리자 멤버를 생성한다.
 * 2. 감사 로그를 하나 생성한다.
 * 3. 권한 없는(관리자가 아닌) 멤버로 해당 감사 로그 삭제를 시도한다.
 * 4. 403 혹은 유사한 권한 오류가 발생해야 하고, 데이터베이스에서 해당 감사 로그가 여전히 삭제되지 않았음을 확인한다.
 *
 * 상세 단계:
 * 1. discussionboard/actors/members 엔드포인트로 status가 'active'인 새로운 멤버를 생성.
 * 2. discussionboard/systematic/auditLogs 엔드포인트로 위에서 생성된 멤버(비관리자)를 actor_id로 지정해 신규 audit log 생성.
 * 3. eraseById(DELETE) 엔드포인트로 actor가 member일 때 삭제 호출(권한 없는 상황), 반드시 실패.
 *    - TestValidator.error를 사용해 오류 발생을 확인하고, 오류 코드가 403(또는 그 외 권한 오류)임을 검증.
 * 4. delete 실패 후, 동일 audit log의 존재 여부를 확인하거나, 최소한 잘못 삭제되거나 무언가 변경되지 않았음을 검증(존재 유무 혹은 불변 증명).
 *
 * 주의
 * - 실제 구현 가능한 범위 내 (e.g., 조회 API 미제공 시 삭제 여부 상태 검증은 생략)
 * - 타입 및 엔드포인트 계약 위반 없이, 필수 필드 충족 및 권한 오류 검증 위주 집중.
 */
export async function test_api_discussionboard_test_delete_audit_log_unauthorized_failure(
  connection: api.IConnection,
) {
  // 1. 비관리자 멤버 생성
  const member = await api.functional.discussionboard.actors.members.post(connection, {
    body: {
      joined_at: new Date().toISOString(),
      status: 'active',
    },
  });
  typia.assert(member);

  // 2. 감사 로그 생성 (actor_id: 위에서 만든 member)
  const auditLog = await api.functional.discussionboard.systematic.auditLogs.post(connection, {
    body: {
      action: 'TEST_UNAUTHORIZED_DELETE',
      actor_id: member.id,
      target_table: 'discussionboard_audit_logs',
      target_id: null,
      details: '권한 없는 멤버가 삭제 시도용 테스트 로그',
    },
  });
  typia.assert(auditLog);

  // 3. 멤버(비관리자)로 해당 감사 로그 삭제 시도 (권한 없어야 하므로 오류!)
  await TestValidator.error('비관리자 삭제 시도는 실패해야 함')(async () => {
    await api.functional.discussionboard.systematic.auditLogs.eraseById(connection, {
      id: auditLog.id,
    });
  });

