 * 2. Create two categories in the same channel (will test duplicate code constraint)
 * 3. Update the first category’s name, code, enabled state, and parent (success)
 * 4. Verify attributes updated on return value
 * 5. Try updating that first category’s code to the second category’s current code; check for error (code must be unique per channel)
 * 6. Attempt to update immutable fields (e.g., discussionboard_channel_id, or created_at) and verify rejection
 */
export async function test_api_discussionboard_test_update_category_details_success_and_validation(
  connection: api.IConnection,
) {
  // Step 1: Create a channel
  const channel = await api.functional.discussionboard.systematic.channels.post(connection, {
    body: {
      code: RandomGenerator.alphaNumeric(4),
      name: RandomGenerator.name(),
      description: RandomGenerator.paragraph()(),
      enabled: true,
    } satisfies IDiscussionboardChannel.ICreate,
  });
  typia.assert(channel);

  // Step 2: Create two categories for duplicate code check and for update target
  const catA = await api.functional.discussionboard.systematic.categories.post(connection, {
    body: {
      discussionboard_channel_id: channel.id,
      parent_id: null,
      code: RandomGenerator.alphaNumeric(5),
      name: RandomGenerator.paragraph()(),
      description: RandomGenerator.paragraph()(),
      enabled: true,
    } satisfies IDiscussionboardCategory.ICreate,
  });
  typia.assert(catA);

  const catB = await api.functional.discussionboard.systematic.categories.post(connection, {
    body: {
      discussionboard_channel_id: channel.id,
      parent_id: null,
      code: RandomGenerator.alphaNumeric(5),
      name: RandomGenerator.paragraph()(),
      description: RandomGenerator.paragraph()(),
      enabled: true,
    } satisfies IDiscussionboardCategory.ICreate,
  });
  typia.assert(catB);

  // Step 3: Update catA
  const newName = RandomGenerator.name();
  const newCode = RandomGenerator.alphaNumeric(5);
  const updated = await api.functional.discussionboard.systematic.categories.putById(connection, {
    id: catA.id,
    body: {
      name: newName,
      code: newCode,
      parent_id: catB.id,
      enabled: false,
      description: "Updated description",
    } satisfies IDiscussionboardCategory.IUpdate,
  });
  typia.assert(updated);
  TestValidator.equals("category name updated")(updated.name)(newName);
  TestValidator.equals("category code updated")(updated.code)(newCode);
