/**
 * Validate successful soft-deletion (inactivation) of a topic tag.
 *
 * This test verifies the tag management lifecycle for moderators or admins in the discussion board system:
 *  - A new topic tag is created and is active by default
 *  - The tag is then deleted (which performs a soft delete by setting it inactive, not hard-deletion)
 *  - The deletion returns a successful operation status
 *  - The tag no longer appears in lists of active topic tags
 *
 * The test covers requirements for tag visibility, moderation curation, and logical deletion practices required by compliance.
 *
 * Steps:
 * 1. Create a new topic tag (unique name, is_active: true)
 * 2. Delete the tag by id
 * 3. Confirm operation status (success: true)
 * 4. (Optionally) List all tags and confirm the deleted tag is not listed as active (SKIP if no listing API)
 */
export async function test_api_discussionboard_test_delete_topic_tag_success(
  connection: api.IConnection,
) {
  // 1. Create a new topic tag
  const tag = await api.functional.discussionboard.boards.topicTags.post(connection, {
    body: {
      name: `e2e_test_${RandomGenerator.alphabets(8)}`,
      is_active: true,
    },
  });
  typia.assert(tag);
  TestValidator.equals("tag is active when created")(tag.is_active)(true);

  // 2. Delete the tag (soft-delete)
  const operation = await api.functional.discussionboard.boards.topicTags.eraseById(connection, {
    id: tag.id,
  });
  typia.assert(operation);
  TestValidator.equals("delete reports success")(operation.success)(true);

  // 3. (Optionally) There is no API for getting the tag or listing all tags, so cannot recheck its active status
}

