 * 3. action, details 필드를 바꿔서 PUT update
 * 4. 응답 레코드가 수정사항이 반영되어 있는지 확인 (action, details) 및 불변필드(created_at, id) 확인
 */
export async function test_api_discussionboard_systematic_auditLogs_putById(
