import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardChannel } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardChannel";
import type { IDiscussionboardCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardCategory";

/**
 * Validate successful creation of a discussion board category with full input.
 *
 * This test covers the end-to-end scenario where an admin wishes to create a new forum/category structure within a discussion board system. As each category must belong to a channel, the test first creates a valid channel. It then posts a new category referencing the channel. The test includes all required and optional category creation fields to verify not only minimal valid creation but also support for optional metadata (parent category, description, etc). It validates the full returned entity matches the request, ensuring business/DB constraints and normalization.
 *
 * Steps:
 * 1. Create a new channel and record its ID.
 * 2. Post a new category linked to the existing channel, providing values for all IDiscussionboardCategory.ICreate fields (including description and enabled state, and omitting parent_id for a top-level category).
 * 3. Assert the returned IDiscussionboardCategory matches all request attributes—channel link, code, name, description, enabled, parent_id is omitted or null.
 */
export async function test_api_discussionboard_test_create_category_with_valid_data(
  connection: api.IConnection,
) {
  // 1. Create a channel to link with the new category
  const channelInput: IDiscussionboardChannel.ICreate = {
    code: RandomGenerator.alphaNumeric(6),
    name: RandomGenerator.name(),
    description: RandomGenerator.paragraph()(),
    enabled: true,
  };
  const channel = await api.functional.discussionboard.systematic.channels.post(connection, { body: channelInput });
  typia.assert(channel);

  // 2. Create a new top-level category linked to that channel (all fields set)
  const categoryInput: IDiscussionboardCategory.ICreate = {
    discussionboard_channel_id: channel.id,
    code: RandomGenerator.alphaNumeric(8),
    name: RandomGenerator.name(),
    description: RandomGenerator.paragraph()(),
    enabled: true,
    // Omitting parent_id for top-level; could also test explicit null
  };
  const category = await api.functional.discussionboard.systematic.categories.post(connection, { body: categoryInput });
  typia.assert(category);

  // 3. Validate all fields were set as requested
  TestValidator.equals("discussionboard_channel_id")(category.discussionboard_channel_id)(categoryInput.discussionboard_channel_id);
  TestValidator.equals("code")(category.code)(categoryInput.code);
  TestValidator.equals("name")(category.name)(categoryInput.name);
  TestValidator.equals("description")(category.description)(categoryInput.description);
  TestValidator.equals("enabled")(category.enabled)(categoryInput.enabled);
  TestValidator.equals("parent_id is null or omitted")(category.parent_id ?? null)(null);
  // created_at/updated_at/deleted_at are timestamped, handled on server, not compared here.
}

