import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMembers } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMembers";
import type { DiscussionboardBoard } from "@ORGANIZATION/PROJECT-api/lib/structures/DiscussionboardBoard";
import type { DiscussionBoardBoardTopic } from "@ORGANIZATION/PROJECT-api/lib/structures/DiscussionBoardBoardTopic";

/**
 * Validate uniqueness constraints for topic code and title within a board.
 *
 * This test ensures that the creation of a board topic enforces uniqueness on both
 * the topic code and the topic title within the same board. It confirms that
 * attempting to create a second topic in the same board with a code or title that
 * already exists will result in a validation error or conflict response.
 *
 * Steps:
 * 1. Create a new board (using distinct code/name/category).
 * 2. Register a new member who will be the topic creator.
 * 3. Create a first topic with unique code and title using the above board/member.
 * 4. Attempt to create a second topic with:
 *    a) Duplicate code but different title (expect failure)
 *    b) Duplicate title but different code (expect failure)
 * 5. Ensure both attempts to create a duplicate topic (by code or by title) fail with validation error, confirming uniqueness is enforced.
 */
export async function test_api_discussionboard_test_create_board_topic_duplicate_title_or_code(
  connection: api.IConnection,
) {
  // 1. Create a new board
  const board: DiscussionboardBoard = await api.functional.discussionboard.boards.boards.post(connection, {
    body: {
      discussionboard_category_id: typia.random<string & tags.Format<"uuid">>(),
      code: `CODE_${RandomGenerator.alphaNumeric(6)}`,
      name: `Board ${RandomGenerator.alphabets(6)}`,
      description: RandomGenerator.paragraph()(),
      is_active: true,
    } satisfies DiscussionboardBoard.ICreate,
  });
  typia.assert(board);

  // 2. Register a new member
  const member: IDiscussionboardMembers = await api.functional.discussionboard.actors.members.post(connection, {
    body: {
      joined_at: new Date().toISOString(),
      status: 'active',
    } satisfies IDiscussionboardMembers.ICreate,
  });
  typia.assert(member);

  // 3. Create the initial topic
  const initialCode = `TOPIC_${RandomGenerator.alphaNumeric(6)}`;
  const initialTitle = `Title ${RandomGenerator.alphabets(8)}`;
  const topic: DiscussionBoardBoardTopic = await api.functional.discussionboard.boards.boardTopics.post(connection, {
    body: {
      discussionboard_board_id: board.id,
      code: initialCode,
      title: initialTitle,
      description: RandomGenerator.paragraph()(),
      created_by_member_id: member.id,
    } satisfies DiscussionBoardBoardTopic.ICreate,
  });
  typia.assert(topic);

  // 4a. Attempt to create topic with duplicate code but unique title
  await TestValidator.error("duplicate topic code in same board")(() =>
    api.functional.discussionboard.boards.boardTopics.post(connection, {
      body: {
        discussionboard_board_id: board.id,
        code: initialCode, // duplicate
        title: `Title ${RandomGenerator.alphabets(10)}`,
        description: RandomGenerator.paragraph()(),
        created_by_member_id: member.id,
      } satisfies DiscussionBoardBoardTopic.ICreate,
    })
  );

  // 4b. Attempt to create topic with unique code but duplicate title
  await TestValidator.error("duplicate topic title in same board")(() =>
    api.functional.discussionboard.boards.boardTopics.post(connection, {
      body: {
        discussionboard_board_id: board.id,
        code: `TOPIC_${RandomGenerator.alphaNumeric(8)}`,
        title: initialTitle, // duplicate
        description: RandomGenerator.paragraph()(),
        created_by_member_id: member.id,
      } satisfies DiscussionBoardBoardTopic.ICreate,
    })
  );
}

