  const now = new Date();
  for (let i = 0; i < 8; i++) {
    const status = statuses[i % statuses.length];
    // Stagger join dates between now and ~30 days ago
    const joined_at = new Date(now.getTime() - (i * 4 * 24 * 60 * 60 * 1000)).toISOString();
    const member = await api.functional.discussionboard.actors.members.post(connection, {
      body: {
