  }

  // 2. List members using pagination (limit=3, page=1)
  let resp = await api.functional.discussionboard.actors.members.patch(connection, {
    body: {
      limit: 3,
      page: 1,
    } satisfies IDiscussionboardMembers.IRequest,
  });
  typia.assert(resp);
  TestValidator.equals("limit in metadata")(resp.pagination.limit)(3);
  TestValidator.equals("current page")(resp.pagination.current)(1);
  TestValidator.equals("page size")(resp.data.length)(Math.min(3, members.length));

  // 3. Second page
  const resp2 = await api.functional.discussionboard.actors.members.patch(connection, {
    body: {
      limit: 3,
      page: 2,
    } satisfies IDiscussionboardMembers.IRequest,
  });
  typia.assert(resp2);
  TestValidator.equals("current page 2")(resp2.pagination.current)(2);

  // 4. Filter by status
  const filterStatus = statuses[1]; // 'pending'
  const resp3 = await api.functional.discussionboard.actors.members.patch(connection, {
    body: {
