  const resp4 = await api.functional.discussionboard.actors.members.patch(connection, {
    body: {
      search: searchFragment,
    } satisfies IDiscussionboardMembers.IRequest,
  });
  typia.assert(resp4);
  TestValidator.predicate("search returns target")(resp4.data.some(d => d.id === searchMember.id));

  // 6. Filter by joinedAfter (should find only newer members)
  const joinedAfter = members[5].joined_at;
  const resp5 = await api.functional.discussionboard.actors.members.patch(connection, {
    body: {
