/**
 * Test updating a board announcement with correct permission and pinning constraints.
 *
 * Business context:
 * Board announcements are curated and modified by admins or moderators; only one can be pinned per board at a time. Updates must preserve audit integrity, and only authorized actors can modify announcements. Unauthorized access or double-pinning must be denied.
 *
 * Steps:
 * 1. Simulate admin user context (assumed via connection).
 * 2. Create two board announcements on the same board via POST: one pinned, one not pinned.
 * 3. Update content, title, and pin status of the unpinned announcement (should succeed, including pinning it if we unpin the first one).
 * 4. Try to pin a second announcement without unpinning the first (should fail enforcement of single pin rule).
 * 5. Attempt to update an announcement as an unauthorized user (simulate by clearing or altering authorization in connection - not possible if no such function exists, so skip if not feasible).
 * 6. Attempt to update a non-existent or deleted announcement (use random UUID or soft delete if possible; check error).
 * 7. Validate announcement data after successful update, permissions, and that pin property changes as expected.
 * 8. Validate update audit logging if possible (skip log API checks if none exist, but explain as comments).
 */
export async function test_api_discussionboard_boards_boardAnnouncements_putById_with_permissions_and_pin_constraints(
  connection: api.IConnection,
) {
  // [Preparation] Generate fixed board/admin IDs for use
  const boardId = typia.random<string & tags.Format<"uuid">>();
  const adminId = typia.random<string & tags.Format<"uuid">>();

  // 1. Create a pinned announcement
  const pinnedAnn = await api.functional.discussionboard.boards.boardAnnouncements.post(
    connection,
    {
      body: {
        discussionboard_board_id: boardId,
        published_by_admin_id: adminId,
        title: "Pinned Announcement",
        body: "Important message.",
        is_pinned: true,
      },
    },
  );
  typia.assert(pinnedAnn);
  TestValidator.equals("pinned flag should be true")(pinnedAnn.is_pinned)(true);

  // 2. Create a non-pinned announcement
  const unpinnedAnn = await api.functional.discussionboard.boards.boardAnnouncements.post(
    connection,
    {
      body: {
        discussionboard_board_id: boardId,
        published_by_admin_id: adminId,
        title: "General News",
        body: "Routine update.",
        is_pinned: false,
      },
    },
  );
  typia.assert(unpinnedAnn);
  TestValidator.equals("not pinned")(unpinnedAnn.is_pinned)(false);

  // 3. Update title and body for the unpinned announcement - remain unpinned
  const updatedAnn = await api.functional.discussionboard.boards.boardAnnouncements.putById(
    connection,
    {
      id: unpinnedAnn.id,
      body: {
        title: "Updated News",
        body: "Edited content.",
        is_pinned: false,
      },
    },
  );
  typia.assert(updatedAnn);
  TestValidator.equals("updated title")(updatedAnn.title)("Updated News");
  TestValidator.equals("updated body")(updatedAnn.body)("Edited content.");
  TestValidator.equals("pin unchanged")(updatedAnn.is_pinned)(false);

  // 4. Try to pin the unpinned announcement (should fail since another is pinned)
  await TestValidator.error("single pin per board")(async () => {
    await api.functional.discussionboard.boards.boardAnnouncements.putById(
      connection,
      {
        id: unpinnedAnn.id,
        body: {
          title: "Try pin conflict",
          body: "Trying to pin a second announcement.",
          is_pinned: true,
        },
      },
    );
  });

  // 5. Unpin the first and pin the second (should succeed)
  const updatedPinnedFirst = await api.functional.discussionboard.boards.boardAnnouncements.putById(
    connection,
    {
      id: pinnedAnn.id,
      body: {
        title: pinnedAnn.title,
        body: pinnedAnn.body,
        is_pinned: false,
      },
    },
  );
  typia.assert(updatedPinnedFirst);
  TestValidator.equals("first is now unpinned")(updatedPinnedFirst.is_pinned)(false);

  const pin2 = await api.functional.discussionboard.boards.boardAnnouncements.putById(
    connection,
    {
      id: unpinnedAnn.id,
      body: {
        title: updatedAnn.title,
        body: updatedAnn.body,
        is_pinned: true,
      },
    },
  );
  typia.assert(pin2);
  TestValidator.equals("unpinned announcement is now pinned")(pin2.is_pinned)(true);

  // 6. Attempt update on non-existent announcement (random UUID)
  await TestValidator.error("non-existent announcement update fails")(async () => {
    await api.functional.discussionboard.boards.boardAnnouncements.putById(
      connection,
      {
        id: typia.random<string & tags.Format<"uuid">>(),
        body: {
          title: "Should fail",
          body: "Not found error.",
          is_pinned: false,
        },
      },
    );
  });

  // 7. (Unauthorized update attempt skipped as no auth API present)
  //
  // 8. (Audit log check skipped)
}

