  const admin = await api.functional.discussionboard.actors.admins.post(connection, {
    body: {
      discussionboard_member_id: memberId,
      elevated_at: new Date().toISOString(),
    },
  });
  typia.assert(admin);

  // 2-1. 필수 필드 action 미입력
  TestValidator.error("action 누락, 400 에러 반환")(() =>
    api.functional.discussionboard.systematic.auditLogs.post(connection, {
      body: {
        // action: intentionally omitted
        actor_id: memberId,
      } as any, // 타입 비우기 테스트이므로 예외적 as any 사용 (실제 구현시 타입 오류로 스킵)
    }),
  );

  // 2-2. actor_id 가 uuid 형식 위반
  TestValidator.error("actor_id 형식 위반, 400 에러 반환")(() =>
    api.functional.discussionboard.systematic.auditLogs.post(connection, {
      body: {
        action: "SETTING_CREATE",
        actor_id: "not-a-uuid", // uuid 가 아닌 임의 문자열
      } satisfies IDiscussionboardAuditLogs.ICreate,
    }),
  );

  // 2-3. action 빈 문자열
  TestValidator.error("action 빈 문자열, 400 에러 반환")(() =>
    api.functional.discussionboard.systematic.auditLogs.post(connection, {
      body: {
        action: "",
        actor_id: memberId,
      } satisfies IDiscussionboardAuditLogs.ICreate,
    }),
  );

  // 2-4. actor_id 누락
  TestValidator.error("actor_id 누락, 400 에러 반환")(() =>
    api.functional.discussionboard.systematic.auditLogs.post(connection, {
      body: {
        action: "SETTING_CREATE",
        // actor_id: intentionally omitted
      } as any, // as any 사용 (실제 타입 위반, TS 수준 오류로 skip)
    }),
  );
}

