 * Validate successful deletion (soft or hard) of a board topic by its creator and by a staff role.
 *
 * Business context:
 * - The ability to delete a board topic should only be granted to its creator (board member who created the topic), or to a privileged staff account (admin/moderator). Deletion should remove the topic from standard topic listings.
 * - The operation may be implemented as a soft-delete: record is not physically removed, but marked so it does not appear in list results. Audit trails may still reveal the topic.
 *
 * Step-by-step process:
 * 1. Create a new member who will become the creator of the topic.
 * 2. Create a new board entity.
 * 3. The created member also creates a topic belonging to the board.
 * 4. As the topic creator, attempt to delete (erase) the topic. The request should succeed.
 * 5. Validate that operationStatus.success is true.
 *
 * (Optional for error case/role switch: If API/SDK supported a staff/admin account, switch context & repeat to test admin can also delete topic. But absent staff account creation API, only test basic creator-case deletion.)
 *
 * 6. (Omission) List/fetch topic is not possible since there is no SDK/list endpoint for topics, so validation for visibility cannot be performed.
 */
export async function test_api_discussionboard_test_delete_board_topic_success_by_creator_or_staff(
  connection: api.IConnection,
) {
  // 1. Create a member (creator)
  const member = await api.functional.discussionboard.actors.members.post(connection, {
    body: {
      joined_at: new Date().toISOString(),
      status: 'active',
    } satisfies IDiscussionboardMembers.ICreate,
  });
  typia.assert(member);

  // 2. Create a board
  const board = await api.functional.discussionboard.boards.boards.post(connection, {
    body: {
      discussionboard_category_id: typia.random<string & tags.Format<'uuid'>>(),
      code: RandomGenerator.alphaNumeric(8),
      name: RandomGenerator.alphabets(6),
      description: RandomGenerator.paragraph()(),
      is_active: true,
    } satisfies DiscussionboardBoard.ICreate,
  });
  typia.assert(board);

  // 3. Create a topic as the member (creator)
  const topic = await api.functional.discussionboard.boards.boardTopics.post(connection, {
    body: {
      discussionboard_board_id: board.id,
      code: RandomGenerator.alphaNumeric(10),
      title: RandomGenerator.alphabets(8),
      description: RandomGenerator.paragraph()(),
      created_by_member_id: member.id,
    } satisfies DiscussionBoardBoardTopic.ICreate,
  });
  typia.assert(topic);

  // 4. Attempt to delete the topic as the creator
  const operationStatus = await api.functional.discussionboard.boards.boardTopics.eraseById(connection, {
    id: topic.id,
  });
  typia.assert(operationStatus);
  TestValidator.predicate('topic delete should succeed')(operationStatus.success === true);

  // 5. No list endpoint to validate invisible topic, so test ends here (further soft-delete/audit checks omitted)
}

