/**
 * Validate updating a discussion board post report by moderator/admin and permission denial for regular members.
 *
 * This test ensures post report update mechanics, role-based access control, and error handling:
 *
 * 1. Create a discussion board post as a member (prerequisite for report).
 * 2. File a report on the post as a (different) member (prerequisite for updating report).
 * 3. As moderator/admin, update the report's reason and verify the response reflects the change.
 * 4. As a regular member (not moderator/admin or the original reporter), attempt to update the report and expect an error/denial.
 * 5. Attempt to update a non-existent report and expect an error.
 *
 * Only fields allowed by API and DTO are updated; all business and access rules enforced by available endpoints. Unavailable business logic (e.g., status/resolution fields) is omitted.
 */
export async function test_api_discussionboard_test_update_post_report_resolution_by_moderator_admin_and_permission_error(connection: api.IConnection) {
  // 1. Create a post to be reported (using a random member ID and thread ID).
  const threadId: string = typia.random<string & tags.Format<"uuid">>();
  const reportingMemberId: string = typia.random<string & tags.Format<"uuid">>();
  const postAuthorId: string = typia.random<string & tags.Format<"uuid">>();
  const post = await api.functional.discussionboard.threads.posts.post(connection, {
    body: {
      discussionboard_thread_id: threadId,
      discussionboard_member_id: postAuthorId,
      body: "This is a test post for report.",
