  // 3. Update the report as a moderator/admin (simulate role by context; business logic via endpoint access)
  const updatedReason = "Reviewed and confirmed as resolved.";
  const updatedReport = await api.functional.discussionboard.interactions.postReports.putById(connection, {
    id: report.id,
    body: { reason: updatedReason },
  });
