  TestValidator.equals("reason updated")(updatedReport.reason)(updatedReason);

  // 4. Attempt to update as a regular member (simulate insufficient permission; expect error)
  await TestValidator.error("non-moderator update denied")(() =>
    api.functional.discussionboard.interactions.postReports.putById(connection, {
      id: report.id,
      body: { reason: "Malicious update attempt." },
