import type { IDiscussionboardMembers } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMembers";

/**
 * [Unauthorized Audit Log Update Failure Test]
 *
 * This test verifies that an unauthorized (non-admin) user cannot update audit log records, upholding strict audit trail integrity.
 *
 * 1. Create a non-admin member (mimics an ordinary user).
 * 2. Using this member as the actor, create an audit log record for update attempt.
 * 3. Attempt to update the created audit log record as this non-admin member.
 * 4. Assert that the operation fails with a 403 Forbidden error, confirming access is restricted to privileged roles only.
 */
export async function test_api_discussionboard_test_update_audit_log_unauthorized_failure(connection: api.IConnection) {
  // 1. Create a non-admin member
  const member = await api.functional.discussionboard.actors.members.post(connection, {
    body: {
      joined_at: new Date().toISOString(),
      status: "active",
    } satisfies IDiscussionboardMembers.ICreate,
  });
  typia.assert(member);

  // 2. Create an audit log, actor is the non-admin member
  const auditLog = await api.functional.discussionboard.systematic.auditLogs.post(connection, {
    body: {
      action: "TEST_ACTION",
      actor_id: member.id,
      target_table: null,
      target_id: null,
      details: "Initial audit log for unauthorized update test",
    } satisfies IDiscussionboardAuditLogs.ICreate,
  });
  typia.assert(auditLog);

  // 3. Attempt to update the audit log as a non-admin (not privileged)
  await TestValidator.error("unauthorized audit log update should fail with 403")(
    () => api.functional.discussionboard.systematic.auditLogs.putById(connection, {
      id: auditLog.id,
      body: {
        action: "MODIFIED_ACTION",
        details: "This modification should not be allowed for non-admin",
      } satisfies IDiscussionboardAuditLogs.IUpdate,
    })
  );
}

