      action: "TEST_ACTION",
      actor_id: member.id,
      target_table: null,
      target_id: null,
      details: "Unauthorized update attempt base log.",
    } satisfies IDiscussionboardAuditLogs.ICreate,
  });
  typia.assert(auditLog);

  // 3. 비관리자(일반 멤버)로 감사 로그 갱신(수정) 시도 - 반드시 403 Forbidden 발생해야 함
