/**
 * Test the creation of a new member suspension in the Discussion Board system.
 *
 * This test verifies the following:
 * 1. That a member can be suspended (with provided reason, start, end times) by a privileged issuer (admin or moderator).
 * 2. The system returns the correct suspension record with all details matching the request and fills audit fields.
 * 3. Business logic that prevents:
 *    - Creating duplicate/overlapping suspensions (cannot suspend an already suspended user)
 *    - Inadequate privilege (issuer must have moderator or admin role)
 * 4. Handles required audit data (IDs, timestamps) correctly.
 * 5. Suspension durations and reasons are stored and reflected exactly.
 *
 * Test Steps:
 * 1. Create a normal member who will be the suspension target.
 * 2. Create a privileged member (admin or moderator) who will issue the suspension.
 * 3. Attempt to suspend the target member (valid reason, various duration).
 * 4. Confirm the returned suspension data matches the request; audit fields (issuer IDs, timestamps) are set.
 * 5. Attempt to re-suspend the same member (should fail as already suspended).
 * 6. Attempt to suspend with a non-privileged issuer (should fail: privilege enforcement).
 */
export async function test_api_discussionboard_test_create_member_suspension_with_valid_data(
  connection: api.IConnection,
) {
  // 1. Create a normal discussion board member (the suspension target)
  const targetMember = await api.functional.discussionboard.actors.members.post(connection, {
    body: {
      joined_at: new Date().toISOString(),
      status: "active"
    } satisfies IDiscussionboardMembers.ICreate,
  });
  typia.assert(targetMember);

  // 2. Create a privileged issuer (simulate as an admin - could also be moderator)
  const issuerAdmin = await api.functional.discussionboard.actors.members.post(connection, {
    body: {
      joined_at: new Date().toISOString(),
      status: "active"
    } satisfies IDiscussionboardMembers.ICreate,
  });
  typia.assert(issuerAdmin);

  // 3. Successfully create a member suspension as admin (short suspension)
  const reason1 = "Spamming links";
  const startsAt1 = new Date(Date.now() + 1 * 60 * 1000).toISOString(); // 1 minute from now
  const endsAt1 = new Date(Date.now() + 5 * 60 * 1000).toISOString(); // 5 minutes later
  const res1 = await api.functional.discussionboard.actors.memberSuspensions.post(connection, {
    body: {
      discussionboard_member_id: targetMember.id,
      issued_by_admin_id: issuerAdmin.id,
      issued_by_moderator_id: null,
      reason: reason1,
      starts_at: startsAt1,
      ends_at: endsAt1,
    } satisfies IDiscussionBoardMemberSuspension.ICreate,
  });
  typia.assert(res1);
  TestValidator.equals("target member matches")(res1.discussionboard_member_id)(targetMember.id);
  TestValidator.equals("admin issued")(res1.issued_by_admin_id)(issuerAdmin.id);
  TestValidator.equals("moderator null")(res1.issued_by_moderator_id)(null);
  TestValidator.equals("reason matches")(res1.reason)(reason1);
  TestValidator.equals("starts_at matches")(res1.starts_at)(startsAt1);
  TestValidator.equals("ends_at matches")(res1.ends_at)(endsAt1);

  // 4. Attempt to re-suspend the already suspended member (should error)
  await TestValidator.error("cannot suspend already-suspended member")(
    async () => {
      await api.functional.discussionboard.actors.memberSuspensions.post(connection, {
        body: {
          discussionboard_member_id: targetMember.id,
          issued_by_admin_id: issuerAdmin.id,
          issued_by_moderator_id: null,
          reason: "Double Suspension Attempt",
          starts_at: startsAt1,
          ends_at: endsAt1,
        } satisfies IDiscussionBoardMemberSuspension.ICreate,
      });
    }
  );

  // 5. Attempt with a non-privileged issuer (should fail privilege enforcement)
  const nonPrivMember = await api.functional.discussionboard.actors.members.post(connection, {
    body: {
      joined_at: new Date().toISOString(),
      status: "active"
    } satisfies IDiscussionboardMembers.ICreate,
  });
  typia.assert(nonPrivMember);

  await TestValidator.error("must have privileged issuer")(
    async () => {
      await api.functional.discussionboard.actors.memberSuspensions.post(connection, {
        body: {
          discussionboard_member_id: targetMember.id,
          issued_by_admin_id: null,
          issued_by_moderator_id: nonPrivMember.id,
          reason: "Unprivileged Issuer Attempt",
          starts_at: new Date(Date.now() + 60 * 1000).toISOString(),
          ends_at: new Date(Date.now() + 120 * 1000).toISOString(),
        } satisfies IDiscussionBoardMemberSuspension.ICreate,
      });
    }
  );

  // 6. Try a permanent suspension (no ends_at)
  const reason2 = "Severe violation - Permanent";
  const startsAt2 = new Date(Date.now() + 60 * 1000).toISOString();
  const permanentRes = await api.functional.discussionboard.actors.memberSuspensions.post(connection, {
    body: {
      discussionboard_member_id: targetMember.id,
      issued_by_admin_id: issuerAdmin.id,
      issued_by_moderator_id: null,
      reason: reason2,
      starts_at: startsAt2,
      ends_at: null,
    } satisfies IDiscussionBoardMemberSuspension.ICreate,
  });
  typia.assert(permanentRes);
  TestValidator.equals("no end time")(permanentRes.ends_at)(null);
  TestValidator.equals("permanent reason")(permanentRes.reason)(reason2);
}

