/**
 * Test permission enforcement when deleting a post like as a non-owner.
 *
 * This test ensures that a post like (engagement) can only be deleted by its owner/buyer.
 * The scenario validates API access controls so that one member cannot remove another member's like.
 * Expected result: The API should return a permission denied/forbidden error and NOT delete the like.
 *
 * Step-by-step process:
 * 1. Register two members: Member A (owner of like) and Member B (attempted deleter)
 * 2. Member A creates and posts a like on a post.
 * 3. Member B attempts to delete Member A's like using the like ID.
 * 4. The API must reject the deletion with a proper error (permission denied/forbidden).
 */
export async function test_api_discussionboard_test_delete_post_like_by_non_owner(
  connection: api.IConnection,
) {
  // 1. Register Member A
  const memberA = await api.functional.discussionboard.actors.members.post(connection, {
    body: {
      joined_at: new Date().toISOString(),
      status: "active",
    },
  });
  typia.assert(memberA);

  // 2. Register Member B
  const memberB = await api.functional.discussionboard.actors.members.post(connection, {
    body: {
      joined_at: new Date().toISOString(),
      status: "active",
    },
  });
  typia.assert(memberB);

  // 3. Member A creates a post (in this scenario, simulate thread id for completeness)
  const threadId = typia.random<string & tags.Format<"uuid">>();
  const post = await api.functional.discussionboard.threads.posts.post(connection, {
    body: {
      discussionboard_thread_id: threadId,
      discussionboard_member_id: memberA.id,
      body: "Test Post Like Permission",
      created_at: new Date().toISOString(),
    },
  });
  typia.assert(post);

  // 4. Member A likes the post
  const like = await api.functional.discussionboard.interactions.postLikes.post(connection, {
    body: {
      discussionboard_post_id: post.id,
      discussionboard_member_id: memberA.id,
    },
  });
  typia.assert(like);

  // 5. Member B attempts to delete Member A's like (should fail)
  await TestValidator.error("Non-owner should not be able to delete another's like")(
    async () => {
      await api.functional.discussionboard.interactions.postLikes.eraseById(connection, {
        id: like.id,
      });
    },
  );
}

