import type { IDiscussionboardMembers } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMembers";
import type { IDiscussionboardTagProposal } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardTagProposal";

/**
 * Test updating an existing tag proposal by the proposing member (owner)
 * and by a moderator/admin.
 *
 * 1. Register at least three members:
 *    - Member A (proposer)
 *    - Member B (non-owner member, for negative test)
 *    - Member C (to represent moderator/admin if policy allows update; if not, C is an extra normal member)
 * 2. Member A creates a new tag proposal with a unique tag string
 * 3. Member A updates the tag proposal using a new valid string while under review. Confirm the change is applied.
 * 4. Simulate the proposal as “reviewed or approved” and try to update again as Member A. (Skip if status management is not implemented in DTO/API)
 * 5. Attempt to update the proposal using a duplicate proposed_tag as Member A — expect an error according to business rule.
 * 6. Attempt to update with a tag string that would violate system rules (e.g., banned words) — expect an error (Skip if no interface to set such logic).
 * 7. Attempt to update as Member B (non-owner) — expect forbidden (if membership logic enforced).
 * 8. If moderator/admin update is possible (policy), perform update as Member C and confirm result. Otherwise, skip.
 * 9. Ensure that the result of each update matches API contract (typia.assert) and appropriate errors are thrown for negative cases.
 * Note: Since API/DTO does not expose status/moderation, skip moderation review state and banned content tests. Focus on owner vs non-owner logic, allowed/duplicate value, and contract validation.
 */
export async function test_api_discussionboard_test_update_tag_proposal_as_owner_and_moderator(connection: api.IConnection) {
  // 1. Register three members (A - proposer, B - non-owner, C - mod/admin like)
  const memberA = await api.functional.discussionboard.actors.members.post(connection, {body: {joined_at: new Date().toISOString(), status: 'active'}});
  typia.assert(memberA);
  const memberB = await api.functional.discussionboard.actors.members.post(connection, {body: {joined_at: new Date().toISOString(), status: 'active'}});
  typia.assert(memberB);
  const memberC = await api.functional.discussionboard.actors.members.post(connection, {body: {joined_at: new Date().toISOString(), status: 'active'}});
  typia.assert(memberC);

  // 2. Member A proposes a new tag
  const proposal = await api.functional.discussionboard.interactions.tagProposals.post(connection, {body: {discussionboard_member_id: memberA.id, proposed_tag: 'UniqueTagA1'}});
  typia.assert(proposal);

  // 3. Owner (A) updates their own tag proposal (valid change)
