import type { IPageDiscussionboardAuditLogs } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageDiscussionboardAuditLogs";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { DiscussionBoardAdmins } from "@ORGANIZATION/PROJECT-api/lib/structures/DiscussionBoardAdmins";

/**
 * 성공적인 감사 로그 목록 페이지네이션 테스트 (필터링 포함)
 *
 * 이 테스트는 관리자 권한 사용자가 action, actor_id, 또는 날짜 범위 등 다양한 필터 파라미터를 포함해
 * PATCH /discussionboard/systematic/auditLogs 엔드포인트에서 감사 로그 레코드를 성공적으로 조회할 수 있음을 검증합니다.
 *
 * 1. 테스트용 멤버를 임의의 UUID (또는 랜덤 값)로 가정해 admin 계정으로 승급 처리합니다.
 * 2. admin 권한 상태에서 action, actor_id, 생성일 범위(createdAfter, createdBefore) 등 다양한 필터 조건과 페이지네이션 정보를 담아 PATCH 요청을 보냅니다.
 * 3. 반환되는 response가 filter와 pagination 조건에 부합하는 IPageDiscussionboardAuditLogs 타입임을 typia로 검증합니다.
 * 4. query로 넘긴 필터 파라미터에 대해 데이터가 반드시 반영되었는지, 페이지네이션 메타 정보 및 각 로그 레코드가 조건에 맞는지 추가 검증합니다.
 */
export async function test_api_discussionboard_test_list_audit_logs_with_filters_success(
  connection: api.IConnection,
) {
  // 1. 테스트용 멤버를 임의의 UUID로 가정 (실제 회원 생성 API는 없으므로 랜덤 UUID 사용)
  const adminMemberId = typia.random<string & tags.Format<"uuid">>();

  // 2. admin 권한 부여
  const createdAdmin = await api.functional.discussionboard.actors.admins.post(connection, {
    body: {
      discussionboard_member_id: adminMemberId,
      elevated_at: new Date().toISOString(),
    },
  });
  typia.assert(createdAdmin);
  TestValidator.equals("admin id matches")(createdAdmin.discussionboard_member_id)(adminMemberId);

  // 3. 감사 로그 목록 필터 & 페이지네이션 요청 (action, actor_id, 날짜, search 등 조합)
  const filterAction = "SETTING_UPDATE";
  const before = new Date(Date.now() + 10000).toISOString(); // 미래
  const after = new Date(Date.now() - 1000 * 60 * 60 * 12).toISOString(); // 12시간 전
  const page = 1;
  const limit = 5;
  const output = await api.functional.discussionboard.systematic.auditLogs.patch(connection, {
    body: {
      action: filterAction,
      actor_id: adminMemberId,
      createdAfter: after,
      createdBefore: before,
      page,
      limit,
    },
  });
  typia.assert(output);

  // 4. 반환된 로그 레코드들의 필터 조건 일관성 및 페이지네이션 결과 검증
  TestValidator.equals("page meta current")(output.pagination.current)(page);
  TestValidator.equals("page meta limit")(output.pagination.limit)(limit);
  // 반환된 모든 로그 엔트리가 action, actor_id, createdAfter/createdBefore 조건을 만족
  for (const log of output.data) {
    if (filterAction) TestValidator.equals("action matches")(log.action)(filterAction);
    if (adminMemberId) TestValidator.equals("actor id matches")(log.actor_id)(adminMemberId);
    if (after) TestValidator.predicate("createdAfter filter")(log.created_at >= after);
    if (before) TestValidator.predicate("createdBefore filter")(log.created_at <= before);
  }
}

