import type { DiscussionBoardBoardTopic } from "@ORGANIZATION/PROJECT-api/lib/structures/DiscussionBoardBoardTopic";

/**
 * Validate error handling for missing required fields when creating a board topic.
 *
 * This test checks that the API correctly enforces validation of required fields (title, code, discussionboard_board_id, created_by_member_id) when attempting to create a new board topic. For each required field, we will attempt to create a topic with that field omitted, and verify that the API responds with an error (typically 400 or similar), confirming correct backend validation.
 *
 * Steps:
 * 1. Register a new discussion board member (for created_by_member_id)
 * 2. Create a new board (for discussionboard_board_id)
 * 3. For each required field (title, code, discussionboard_board_id, created_by_member_id):
 *     a. Construct a topic creation request with that field omitted
 *     b. Attempt to call the boardTopics.post API
 *     c. Validate that an error is thrown for the missing required field
 */
export async function test_api_discussionboard_test_create_board_topic_missing_required_fields(connection: api.IConnection) {
  // 1. Register a new member
  const member = await api.functional.discussionboard.actors.members.post(connection, {
    body: {
      joined_at: new Date().toISOString(),
      status: "active",
    } satisfies IDiscussionboardMembers.ICreate,
  });
  typia.assert(member);

  // 2. Create a new board
  const board = await api.functional.discussionboard.boards.boards.post(connection, {
    body: {
      discussionboard_category_id: typia.random<string & tags.Format<"uuid">>(),
      code: "BOARD_" + Math.random().toString(36).substring(2, 10),
      name: "Test Board",
      is_active: true,
    } satisfies DiscussionboardBoard.ICreate,
  });
  typia.assert(board);

  // Prepare all fields
  const fullTopic: DiscussionBoardBoardTopic.ICreate = {
    discussionboard_board_id: board.id,
    code: "TOPIC_" + Math.random().toString(36).substring(2, 10),
    title: "Test Topic",
    created_by_member_id: member.id,
  };

  // Each required field
  const requiredFields = [
    "discussionboard_board_id",
    "code",
    "title",
    "created_by_member_id"
  ];

  for (const missingField of requiredFields) {
    const topic: Partial<DiscussionBoardBoardTopic.ICreate> = { ...fullTopic };
    // Remove the required field
    delete topic[missingField as keyof DiscussionBoardBoardTopic.ICreate];

    await TestValidator.error(`Missing required field: ${missingField}`)(async () => {
      await api.functional.discussionboard.boards.boardTopics.post(connection, {
        body: topic as DiscussionBoardBoardTopic.ICreate, // will be missing one required field
      });
    });
  }
