 * on request parameters. The following steps simulate a typical admin workflow:
 *
 * 1. Create three channels via the POST API.
 * 2. Soft-delete (archive) the second channel using DELETE.
 * 3. Retrieve the channel list without filters and confirm the deleted channel is hidden.
 * 4. Retrieve the channel list with no enabled/disabled filter and confirm the deleted channel is still hidden (unless soft-deleted are always included).
 * 5. (If supported by implementation) Test retrieval with a filter or search parameter which could include or expose soft-deleted records (e.g. paging/sorting/searching edge cases) and check that the deleted channel appears with deleted_at set.
 * 6. Confirm that all existing (non-deleted) channels appear in list and not marked deleted.
 */
export async function test_api_discussionboard_test_list_channels_show_soft_deleted_when_requested(
  connection: api.IConnection,
) {
  // 1. Create three channels with distinct codes/names
  const channels: IDiscussionboardChannel[] = await Promise.all([
    api.functional.discussionboard.systematic.channels.post(connection, { body: { code: RandomGenerator.alphabets(5), name: RandomGenerator.alphabets(8), enabled: true } }),
    api.functional.discussionboard.systematic.channels.post(connection, { body: { code: RandomGenerator.alphabets(5), name: RandomGenerator.alphabets(8), enabled: true } }),
    api.functional.discussionboard.systematic.channels.post(connection, { body: { code: RandomGenerator.alphabets(5), name: RandomGenerator.alphabets(8), enabled: false } }),
  ]);
  channels.forEach(ch => typia.assert(ch));

  // 2. Soft-delete the second channel
  const deletedChannel = channels[1];
  const removeResult = await api.functional.discussionboard.systematic.channels.eraseById(connection, { id: deletedChannel.id });
  typia.assert(removeResult);

  // 3. List all channels (default - should not include soft-deleted)
  const listDefault = await api.functional.discussionboard.systematic.channels.patch(connection, { body: {} });
  typia.assert(listDefault);
  // Confirm soft-deleted channel is not included
  TestValidator.predicate("deleted channel hidden by default")(
    !listDefault.data.some(ch => ch.id === deletedChannel.id)
  );

  // 4. List channels with explicit enabled: null (should also not include soft-deleted)
  const listNoStatus = await api.functional.discussionboard.systematic.channels.patch(connection, { body: { enabled: null } });
  typia.assert(listNoStatus);
  TestValidator.predicate("deleted channel hidden when enabled: null")(
    !listNoStatus.data.some(ch => ch.id === deletedChannel.id)
  );

  // 5. Try searching explicitly by code to catch soft-deleted (if searchable).
  const listByCode = await api.functional.discussionboard.systematic.channels.patch(connection, { body: { search: deletedChannel.code } });
  typia.assert(listByCode);
  if (listByCode.data.some(ch => ch.id === deletedChannel.id)) {
    // Deleted channel is present — it should have deleted_at set
    const found = listByCode.data.find(ch => ch.id === deletedChannel.id)!;
    TestValidator.predicate("deleted_at is set on soft-deleted channel")(!!found.deleted_at);
  }

  // 6. The rest of channels are present and not marked as deleted
  const activeIds = channels.filter((_, i) => i !== 1).map(ch => ch.id);
  for (const ch of listDefault.data) {
    TestValidator.predicate("active channel present")(
      activeIds.includes(ch.id)
    );
    TestValidator.predicate("active channel not marked as deleted")(ch.deleted_at === null || ch.deleted_at === undefined);
  }
}

