import type { DiscussionBoardBoardAnnouncement } from "@ORGANIZATION/PROJECT-api/lib/structures/DiscussionBoardBoardAnnouncement";
import type { IPageDiscussionBoardBoardAnnouncement } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageDiscussionBoardBoardAnnouncement";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IDiscussionboardBoardAnnouncements } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardBoardAnnouncements";

/**
 * E2E test for listing board announcements with various filters and pagination.
 *
 * This test covers these scenarios:
 * 1. Admin creates two announcements (one pinned, one not) for the same board.
 * 2. Authenticated user fetches paginated and filtered list of announcements:
 *    a. By board (should return both announcements)
 *    b. By pin status (pinned only/unpinned only)
 *    c. By search string (filter)
 *    d. With pagination (limit = 1, page 1 and 2)
 *    e. By invalid board (should return empty)
 *    f. Out-of-range page (should return empty)
 */
export async function test_api_discussionboard_boards_test_list_board_announcements_with_various_filters_and_pagination(
  connection: api.IConnection,
) {
  // --- Setup: create a common board and admin IDs ---
  const boardId = typia.random<string & tags.Format<"uuid">>();
  const adminId = typia.random<string & tags.Format<"uuid">>();
  // --- Step 1: Create two announcements (one pinned, one not) ---
  const announcementPinned = await api.functional.discussionboard.boards.boardAnnouncements.post(
    connection,
    {
      body: {
        discussionboard_board_id: boardId,
        published_by_admin_id: adminId,
        title: "Pinned Announcement",
        body: "This is a pinned announcement.",
        is_pinned: true,
      },
    },
  );
  typia.assert(announcementPinned);

  const announcementUnpinned = await api.functional.discussionboard.boards.boardAnnouncements.post(
    connection,
    {
      body: {
        discussionboard_board_id: boardId,
        published_by_admin_id: adminId,
        title: "Normal Announcement",
        body: "This is a normal announcement.",
        is_pinned: false,
      },
    },
  );
  typia.assert(announcementUnpinned);

  // --- Step 2a: Fetch all announcements by board ID ---
  const { data: allAnnouncements, pagination: allMeta } = await api.functional.discussionboard.boards.boardAnnouncements.patch(
    connection,
    {
      body: {
        board_id: boardId,
      },
    },
  );
  typia.assert(allAnnouncements);
  TestValidator.equals("all announcements (by board)")(allAnnouncements.length)(2);

  // --- Step 2b: Fetch only pinned announcements ---
  const { data: pinnedAnnouncements } = await api.functional.discussionboard.boards.boardAnnouncements.patch(
    connection,
    {
      body: {
        board_id: boardId,
        is_pinned: true,
      },
    },
  );
  typia.assert(pinnedAnnouncements);
  TestValidator.equals("only 1 pinned announcement")(pinnedAnnouncements.length)(1);
  TestValidator.equals("pinned title")(
    pinnedAnnouncements[0]?.title,
  )(announcementPinned.title);

  // --- Step 2c: Fetch only unpinned announcements ---
  const { data: unpinnedAnnouncements } = await api.functional.discussionboard.boards.boardAnnouncements.patch(
    connection,
    {
      body: {
        board_id: boardId,
        is_pinned: false,
      },
    },
  );
  typia.assert(unpinnedAnnouncements);
  TestValidator.equals("only 1 unpinned announcement")(unpinnedAnnouncements.length)(1);
  TestValidator.equals("unpinned title")(
    unpinnedAnnouncements[0]?.title,
  )(announcementUnpinned.title);

  // --- Step 2d: Filter announcements by search string in title ---
  const { data: filteredPinned } = await api.functional.discussionboard.boards.boardAnnouncements.patch(
    connection,
    {
      body: {
        board_id: boardId,
        filter: "Pinned",
      },
    },
  );
  typia.assert(filteredPinned);
  TestValidator.equals("filtered announcements (title: Pinned)")(filteredPinned.length)(1);
  TestValidator.equals("filtered matched")(filteredPinned[0].title)(announcementPinned.title);

  // --- Step 2e: Pagination -- page 1 (limit 1) ---
  const { data: page1 } = await api.functional.discussionboard.boards.boardAnnouncements.patch(
    connection,
    {
      body: {
        board_id: boardId,
        page: 1,
        limit: 1,
      },
    },
  );
  typia.assert(page1);
  TestValidator.equals("page 1 has 1 item")(page1.length)(1);
  TestValidator.predicate("page 1 has valid title")(
    page1[0].title === announcementPinned.title || page1[0].title === announcementUnpinned.title,
  );

  // --- Step 2f: Pagination -- page 2 (limit 1) ---
  const { data: page2 } = await api.functional.discussionboard.boards.boardAnnouncements.patch(
    connection,
    {
      body: {
        board_id: boardId,
        page: 2,
        limit: 1,
      },
    },
  );
  typia.assert(page2);
  TestValidator.equals("page 2 has 1 item")(page2.length)(1);
  TestValidator.predicate("page 2 has valid title")(
    page2[0].title === announcementPinned.title || page2[0].title === announcementUnpinned.title,
  );
  TestValidator.notEquals("page 1 and 2 announcements")(
    page2[0].title,
  )(page1[0].title);

  // --- Step 2g: Filter by invalid board ID (should return empty) ---
  const { data: invalidBoard } = await api.functional.discussionboard.boards.boardAnnouncements.patch(
    connection,
    {
      body: {
        board_id: typia.random<string & tags.Format<"uuid">>(),
      },
    },
  );
  typia.assert(invalidBoard);
  TestValidator.equals("invalid board returns nothing")(invalidBoard.length)(0);

  // --- Step 2h: Out-of-range page (should return empty) ---
  const { data: outOfRangePage } = await api.functional.discussionboard.boards.boardAnnouncements.patch(
    connection,
    {
      body: {
        board_id: boardId,
        page: 99,
        limit: 1,
      },
    },
  );
  typia.assert(outOfRangePage);
  TestValidator.equals("out of range page returns nothing")(outOfRangePage.length)(0);
}

