/**
 * Validate behavior when retrieving a soft-deleted discussion board channel.
 *
 * This test ensures that the system correctly handles requests for channels that have been soft-deleted (i.e., marked with a non-null deleted_at but not physically removed from the database).
 * Workflow:
 * 1. Create a new discussionboard channel as an admin.
 * 2. Soft-delete (archive) the created channel using the DELETE endpoint.
 * 3. Immediately attempt to retrieve the soft-deleted channel by its ID.
 * 4. Assert that one of the following business-rule-compliant behaviors occurs:
 *     a. The retrieval endpoint returns an error (e.g., 404 or forbidden), OR
 *     b. The channel record is returned with a non-null deleted_at timestamp indicating it is soft-deleted.
 * This validates both error signaling and inclusion of deletion status per audit/compliance requirements.
 */
export async function test_api_discussionboard_systematic_channels_getById_soft_deleted(
  connection: api.IConnection,
) {
  // 1. Create channel
  const newChannelInput: IDiscussionboardChannel.ICreate = {
    code: RandomGenerator.alphaNumeric(6),
    name: RandomGenerator.paragraph()(1, 3),
    description: RandomGenerator.paragraph()(2, 10),
    enabled: true,
  };
  const created: IDiscussionboardChannel =
    await api.functional.discussionboard.systematic.channels.post(connection, {
      body: newChannelInput,
    });
  typia.assert(created);
  TestValidator.equals("Channel code")(created.code)(newChannelInput.code);
  TestValidator.equals("Channel enabled")(created.enabled)(true);

  // 2. Soft-delete the channel
  const removed: IDiscussionboardChannel.IRemoveResult =
    await api.functional.discussionboard.systematic.channels.eraseById(connection, {
      id: created.id,
    });
  typia.assert(removed);
  TestValidator.equals("Removed channel ID matches")(removed.id)(created.id);
  TestValidator.predicate("deleted_at is now set")(
    typeof removed.deleted_at === "string" && removed.deleted_at.length > 10
  );

  // 3. Attempt to retrieve the soft-deleted channel
  let retrievalError: Error | null = null;
  let channelAfterDelete: IDiscussionboardChannel | null = null;
  try {
    channelAfterDelete = await api.functional.discussionboard.systematic.channels.getById(connection, {
      id: created.id,
    });
    typia.assert(channelAfterDelete);
  } catch (err) {
    retrievalError = err as Error;
  }

  // 4. Validate system behavior depending on implementation:
  if (channelAfterDelete) {
    // Returned channel may have deleted_at set
    TestValidator.equals("Soft-deleted flag present")(channelAfterDelete.deleted_at !== null && channelAfterDelete.deleted_at !== undefined)(true);
    TestValidator.equals("deleted_at matches erase result")(channelAfterDelete.deleted_at)(removed.deleted_at);
  } else {
    // Retrieval error (e.g., 404)
    TestValidator.predicate("Should return error for soft-deleted channel")(retrievalError !== null);
  }
}

