import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMembers } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMembers";
import type { IDiscussionboardThreads } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardThreads";
import type { IDiscussionboardPosts } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardPosts";

/**
 * Validate updating a discussion post's content as the original author within allowed edit window.
 *
 * This test simulates the real-world workflow to exercise correct permissions and sequencing:
 *
 * 1. Register a new Discussion Board member (user) as the future post author.
 * 2. Create a new thread (topic) as that member.
 * 3. Create a new post within the thread authored by the member.
 * 4. Update the post's body using the same member and a new body string.
 * 5. Validate that the response reflects the updated content and all relevant fields are correct.
 *
 * All entities must be freshly created within this test to ensure isolation. All API responses are type-checked and logical business assertions are applied at each step.
 */
export async function test_api_discussionboard_test_update_post_success_with_author_permission(
  connection: api.IConnection,
) {
  // 1. Register member for post author
  const memberInput: IDiscussionboardMembers.ICreate = {
    joined_at: new Date().toISOString(),
    status: "active",
  };
  const member = await api.functional.discussionboard.actors.members.post(connection, {
    body: memberInput,
  });
  typia.assert(member);

  // 2. Create a thread as this member (assume test board exists; use random UUID)
  const boardId = typia.random<string & tags.Format<"uuid">>();
  const threadInput: IDiscussionboardThreads.ICreate = {
    discussionboard_board_id: boardId,
    discussionboard_member_id: member.id,
    title: `Test Thread ${Date.now()}`,
    description: "Initial test thread description.",
    status: "open",
    created_at: new Date().toISOString(),
  };
  const thread = await api.functional.discussionboard.threads.threads.post(connection, {
    body: threadInput,
  });
  typia.assert(thread);

  // 3. Create a post in the thread
  const postInput: IDiscussionboardPosts.ICreate = {
    discussionboard_thread_id: thread.id,
    discussionboard_member_id: member.id,
    body: "Original post content.",
    created_at: new Date().toISOString(),
  };
  const post = await api.functional.discussionboard.threads.posts.post(connection, {
    body: postInput,
  });
  typia.assert(post);

  // 4. Update the post's body as the same author
  const updatedBody = "Updated post content by author.";
  const updateInput: IDiscussionboardPosts.IUpdate = {
    body: updatedBody,
    updated_at: new Date().toISOString(),
  };
  const updatedPost = await api.functional.discussionboard.threads.posts.putById(connection, {
    id: post.id,
    body: updateInput,
  });
  typia.assert(updatedPost);

  // 5. Validate that body was updated and authorship/thread relation is unchanged
  TestValidator.equals("updated body")(updatedPost.body)(updatedBody);
  TestValidator.equals("author unchanged")(updatedPost.discussionboard_member_id)(post.discussionboard_member_id);
  TestValidator.equals("thread id unchanged")(updatedPost.discussionboard_thread_id)(post.discussionboard_thread_id);
  TestValidator.predicate("updated_at is newer")(
    new Date(updatedPost.updated_at).getTime() >= new Date(post.updated_at).getTime()
  );
}

