import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMembers } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMembers";
import type { IDiscussionboardComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardComment";
import type { IDiscussionboardCommentReply } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardCommentReply";

/**
 * Validate retrieval, existence, and error handling for Discussion Board comment reply relations by ID.
 *
 * This test verifies the correct behavior of the GET /discussionboard/threads/commentReplies/:id endpoint across success and error cases.
 *
 * 1. Member creation (needed to author comments).
 * 2. Two comments are created under the same post by the members (as base for parent and reply).
 * 3. A comment reply mapping is established (parent-reply link).
 * 4. Successfully retrieve the comment reply using its ID—assert all core fields (id, comment_id, reply_id, created_at) match expectation.
 * 5. Delete the created comment reply mapping.
 * 6. Attempt to fetch the reply mapping after deletion—expect a 404 error.
 * 7. Attempt to retrieve a truly non-existent ID (random UUID)—expect a 404 error (not found).
 */
export async function test_api_discussionboard_test_get_comment_reply_by_id_existing_and_deleted(connection: api.IConnection) {
  // 1. Create two members.
  const member1 = await api.functional.discussionboard.actors.members.post(connection, {
    body: {
      joined_at: new Date().toISOString(),
      status: "active"
    }
  });
  typia.assert(member1);
  const member2 = await api.functional.discussionboard.actors.members.post(connection, {
    body: {
      joined_at: new Date().toISOString(),
      status: "active"
    }
  });
  typia.assert(member2);

  // 2. Create a thread post ID for the comments (simulate with uuid since no post API is available).
  const postId = typia.random<string & tags.Format<"uuid">>();

  // 3. Create parent and reply comments.
  const parentComment = await api.functional.discussionboard.threads.comments.post(connection, {
    body: {
      discussionboard_post_id: postId,
      discussionboard_member_id: member1.id,
      body: "This is the parent comment."
    }
  });
  typia.assert(parentComment);
  const replyComment = await api.functional.discussionboard.threads.comments.post(connection, {
    body: {
      discussionboard_post_id: postId,
      discussionboard_member_id: member2.id,
      body: "This is the reply comment.",
      parent_id: parentComment.id
    }
  });
  typia.assert(replyComment);

  // 4. Create a comment reply mapping.
  const commentReply = await api.functional.discussionboard.threads.commentReplies.post(connection, {
    body: {
      comment_id: parentComment.id,
      reply_id: replyComment.id
    }
  });
  typia.assert(commentReply);

  // 5. Retrieve the comment reply mapping successfully by id.
  const fetchedReply = await api.functional.discussionboard.threads.commentReplies.getById(connection, {
    id: commentReply.id
  });
  typia.assert(fetchedReply);
  TestValidator.equals("comment reply id matches")(fetchedReply.id)(commentReply.id);
  TestValidator.equals("parent comment id matches")(fetchedReply.comment_id)(parentComment.id);
  TestValidator.equals("reply comment id matches")(fetchedReply.reply_id)(replyComment.id);
  TestValidator.predicate("createdAt should be a string with ISO format")(typeof fetchedReply.created_at === "string" && !Number.isNaN(Date.parse(fetchedReply.created_at)));

  // 6. Delete the comment reply mapping.
  await api.functional.discussionboard.threads.commentReplies.eraseById(connection, { id: commentReply.id });

  // 7. Try to fetch after deletion: expect 404 (not found).
  await TestValidator.error("deleted reply mapping should not be found")(
    async () => {
      await api.functional.discussionboard.threads.commentReplies.getById(connection, { id: commentReply.id });
    }
  );

  // 8. Try to fetch a non-existent random ID: expect 404.
  const randomId = typia.random<string & tags.Format<"uuid">>();
  await TestValidator.error("random non-existent id should return 404")(
    async () => {
      await api.functional.discussionboard.threads.commentReplies.getById(connection, { id: randomId });
    }
  );
}

