  const admin: DiscussionBoardAdmins = await api.functional.discussionboard.actors.admins.post(connection, {
    body: {
      discussionboard_member_id: typia.random<string & tags.Format<"uuid">>(),
      elevated_at: new Date().toISOString(),
    },
  });
  typia.assert(admin);

  // 2. Create a moderator action for test data (with known filterable values)
  const moderatorAction: DiscussionboardModeratorAction = await api.functional.discussionboard.actors.moderatorActions.post(connection, {
