      action_type: "delete_comment",
      target_type: "comment",
      target_id: typia.random<string & tags.Format<"uuid">>(),
      details: "Deleted inappropriate comment as per community guidelines.",
      action_at: new Date().toISOString(),
    },
  });
  typia.assert(moderatorAction);

