 * 3. As memberA, request the details of memberB
 * 4. Assert response includes basic public profile fields only (id, joined_at, status)
 * 5. Assert response does not expose fields outside schema (future schema hardened)
 * 6. Assert id of memberB in response matches expected
 * 7. Negative edge: (by policy, but not testable in schema now) cannot access fields outside allowed set
 */
export async function test_api_discussionboard_actors_members_getById(
  connection: api.IConnection
) {
  // 1. Register memberA
  const memberA = await api.functional.discussionboard.actors.members.post(connection, {
