import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMembers } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMembers";
import type { IDiscussionboardPosts } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardPosts";
import type { IDiscussionboardPostLike } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardPostLike";
import type { IDeleteResult } from "@ORGANIZATION/PROJECT-api/lib/structures/IDeleteResult";

/**
 * Test successful unlike (delete like) operation by the creator of the like on a post.
 *
 * Validates the ability for a member to remove their own like from a post. This scenario ensures:
 * - The member is properly registered
 * - A post is available to like (created by the member or for them)
 * - Member likes the post and receives a like record/ID
 * - The same member then deletes (unlikes) the like
 * - The like record is removed (cannot be fetched again or is missing in listing)
 * - Engagement counts (such as total like count) are updated accordingly if applicable
 * - The delete result returns a status and audit timestamp
 *
 * Steps:
 * 1. Register a Discussion Board member
 * 2. Create a post for the member to like
 * 3. Like the post as the registered member
 * 4. Delete (unlike) the just-created like as the same member
 * 5. Confirm the response deletion result and that the like cannot be deleted again
 */
export async function test_api_discussionboard_test_delete_post_like_by_owner(connection: api.IConnection) {
  // 1. Register a Discussion Board member
  const memberInput: IDiscussionboardMembers.ICreate = {
    joined_at: new Date().toISOString(),
    status: "active"
  };
  const member = await api.functional.discussionboard.actors.members.post(connection, {
    body: memberInput,
  });
  typia.assert(member);

  // 2. Create a post for the member to like
  const postInput: IDiscussionboardPosts.ICreate = {
    discussionboard_thread_id: typia.random<string & tags.Format<"uuid">>(),
    discussionboard_member_id: member.id,
    body: "Test post for like/unlike scenario.",
    created_at: new Date().toISOString(),
  };
  const post = await api.functional.discussionboard.threads.posts.post(connection, {
    body: postInput,
  });
  typia.assert(post);

  // 3. Like the post as the registered member
  const likeInput: IDiscussionboardPostLike.ICreate = {
    discussionboard_post_id: post.id,
    discussionboard_member_id: member.id,
  };
  const like = await api.functional.discussionboard.interactions.postLikes.post(connection, {
    body: likeInput,
  });
  typia.assert(like);

  // 4. Delete (unlike) the just-created like as the same member
  const deleteResult = await api.functional.discussionboard.interactions.postLikes.eraseById(connection, {
    id: like.id,
  });
  typia.assert(deleteResult);
  TestValidator.equals("delete result status is success")(deleteResult.status)("success");
  TestValidator.predicate("deletion timestamp present")(typeof deleteResult.deleted_at === "string" && deleteResult.deleted_at.length > 0);

  // 5. Confirm the like cannot be deleted again (should fail)
  await TestValidator.error("delete again should fail")(() =>
    api.functional.discussionboard.interactions.postLikes.eraseById(connection, { id: like.id }),
  );
}

