import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardPosts } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardPosts";
import type { IDiscussionboardPostReport } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardPostReport";

/**
 * Validate discussion board post report creation with daily member quota enforcement and input authentication.
 *
 * This test covers two main aspects:
 * 1. Ensures an authenticated member can create post reports up to the allowed daily limit (e.g., 10 reports).
 * 2. Exceeding the quota, malformed request input, or missing authentication results in appropriate errors.
 *
 * Steps:
 * 1. Setup - Create a valid post as the reporting target (simulate needed member/thread IDs).
 * 2. Report submissions: As an authenticated member, submit post reports up to the quota (10), checking each for success.
 * 3. Submit one additional report exceeding the quota, validating that a quota-exceeded error is returned.
 * 4. Attempt creating a report as unauthenticated user - assert it fails (e.g., HTTP 401/403).
 * 5. Input validation: Attempt to create reports with malformed/missing required fields - assert API returns input validation error.
 */
export async function test_api_discussionboard_test_create_post_report_within_daily_quota_success_and_exceed_limit(connection: api.IConnection) {
  // Step 1: Setup - create a post
  const post = await api.functional.discussionboard.threads.posts.post(connection, {
    body: {
      discussionboard_thread_id: typia.random<string & tags.Format<"uuid">>(),
      discussionboard_member_id: typia.random<string & tags.Format<"uuid">>(),
      body: "Sample post body for reporting.",
      created_at: new Date().toISOString() as string & tags.Format<"date-time">,
    },
  });
  typia.assert(post);

  // Step 2: Successfully create reports up to (limit = 10, for example)
  const dailyLimit = 10;
  for (let i = 0; i < dailyLimit; ++i) {
    const report = await api.functional.discussionboard.interactions.postReports.post(connection, {
      body: {
        discussionboard_post_id: post.id,
        reason: `Report reason ${i+1}`,
      },
    });
    typia.assert(report);
    TestValidator.equals("Reported post matches")(report.discussionboard_post_id)(post.id);
  }

  // Step 3: Next submission should fail due to quota (business logic: quota exceeded)
  await TestValidator.error("Exceeding report daily quota should fail")(async () => {
    await api.functional.discussionboard.interactions.postReports.post(connection, {
      body: {
        discussionboard_post_id: post.id,
        reason: "Exceed quota",
      },
    });
  });

  // Step 4: Attempt report creation without authentication
  const unauthConn = { ...connection, headers: {} };
  await TestValidator.error("Post report in unauthenticated state fails")(async () => {
    await api.functional.discussionboard.interactions.postReports.post(unauthConn, {
      body: {
        discussionboard_post_id: post.id,
        reason: "Test unauthenticated",
      },
    });
  });

  // Step 5: Malformed/missing fields input validation
  await TestValidator.error("Missing reason should fail validation")(async () => {
    await api.functional.discussionboard.interactions.postReports.post(connection, {
      body: {
        discussionboard_post_id: post.id,
        reason: "", // Empty string not allowed (business rule usually enforced)
      },
    });
  });
  await TestValidator.error("Missing discussionboard_post_id fails")(async () => {
    await api.functional.discussionboard.interactions.postReports.post(connection, {
      body: {
        // discussionboard_post_id omitted intentionally
        // This would be a compile error in types so we do not implement property omission error in TypeScript
        discussionboard_post_id: "" as string & tags.Format<"uuid">,
        reason: "Missing post_id",
      },
    });
  });
}

