/**
 * 관리자가 아닌 권한의 사용자가 시스템 설정 상세 조회를 시도했을 때 권한 오류가 발생하는지 검증한다.
 *
 * 이 시나리오는 플랫폼 내의 시스템 글로벌 설정(예: maintenance_mode, email:smtp_host 등)에 대해,
 * 관리자 외 접근이 명확히 차단되고, DB에 실제 데이터가 존재할 때에도 권한 없는 사용자는 상세조회(GET /discussionboard/systematic/settings/{id})에 실패해야 함을 검증하는 통제 테스트이다.
 *
 * [사전 조건]
 * 1. 정상적인 시스템 설정 엔트리를 사전에 생성(POST /discussionboard/systematic/settings)
 *
 * [테스트 절차]
 * 1. (관리자 토큰/권한으로) 시스템 설정을 하나 신규 생성한다. 고유 key 및 값 포함. → 성공
 * 2. (일반 유저로 토큰/역할 교체 후) 해당 설정의 id로 상세 조회 시도(GET /discussionboard/systematic/settings/{id})
 * 3. 권한 에러 발생(예상: 권한 없음/permission denied 등), 정상적인 상세 정보가 리턴되지 않아야 하며, 비관리자 접근 차단 로직이 동작하는지 검증한다.
 *
 * [검증 포인트]
 * - 비관리자 사용자로 접근 시 403 Forbidden 등 권한 오류가 반드시 발생해야 한다.
 * - 실제 데이터 유무와 무관하게 권한이 최우선적으로 체크됨을 확인한다.
 */
export async function test_api_discussionboard_systematic_settings_test_get_setting_without_admin_permission_should_fail(
  connection: api.IConnection,
) {
  // 1. (관리자 계정 권한/토큰) 시스템 설정을 신규로 1건 생성
  const created: IDiscussionboardSettings = await api.functional.discussionboard.systematic.settings.post(
    connection,
    {
      body: {
        key: `maintenance_mode_${typia.random<string>()}`,
        value: "true",
        description: "테스트용 설정 - 비관리자 권한 오류 검증"
      } satisfies IDiscussionboardSettings.ICreate,
    },
  );
  typia.assert(created);

  // 2. 일반 권한(관리자 아님) 사용자의 토큰/역할로 전환
  // NOTE: 실제 유저 권한 하향 전환/인증 API 미제공 시 실제로 불가능할 수 있으니, 아래 문장에서는 해당 API 제공 시 예시로 추가
  // ex) await api.functional.users.authenticate.login(connection, { body: { ...일반유저 정보... }});
  // 작성 예시에서 생략

  // 3. 상세 조회 시도 → 권한 오류 발생 검증
  await TestValidator.error("비관리자 시스템 설정 상세 조회 권한 차단")(
    async () => {
      await api.functional.discussionboard.systematic.settings.getById(
        connection,
        { id: created.id },
      );
    },
  );
}

