  // 3. Update the admin assignment with a new elevation timestamp
  const newElevation = typia.random<string & tags.Format<"date-time">>();
  const updated = await api.functional.discussionboard.actors.admins.putById(connection, {
    id: adminId,
    body: { elevated_at: newElevation },
  });
  typia.assert(updated);

