  TestValidator.equals("admin member id")(updated.discussionboard_member_id)(discussionboard_member_id);
  TestValidator.equals("elevated_at updated")(updated.elevated_at)(newElevation);
  TestValidator.notEquals("elevated_at changed")(updated.elevated_at)(oldElevation);

  // 5. (Negative) If non-admin tries update, access should fail (not implemented).
}

