 * Only the owner of the notification settings or an admin should be allowed to delete their notification settings. If a different (non-owner, non-admin) member attempts to delete another member’s notification settings, the system must respond with a 403 error (forbidden), confirming that permission checks are properly enforced.
 *
 * Test flow:
 * 1. Register Member A (will own the notification settings)
 * 2. Register Member B (will attempt unauthorized deletion)
 * 3. As Member A, create notification settings associated with Member A's member_id
 * 4. Attempt to delete Member A's notification settings as Member B (not the owner and not an admin)
 * 5. Confirm that a 403 Forbidden error is thrown and no settings are deleted
 */
export async function test_api_discussionboard_test_delete_member_notification_settings_permission_denied_for_other_member(
  connection: api.IConnection,
) {
  // 1. Register Member A
  const memberA = await api.functional.discussionboard.actors.members.post(connection, {
    body: {
      joined_at: new Date().toISOString(),
      status: "active",
    },
  });
  typia.assert(memberA);

  // 2. Register Member B
  const memberB = await api.functional.discussionboard.actors.members.post(connection, {
    body: {
      joined_at: new Date().toISOString(),
      status: "active",
    },
  });
  typia.assert(memberB);

  // 3. As Member A, create notification settings (simulate as if authenticated as Member A)
  const notificationSettings = await api.functional.discussionboard.notifications.memberNotificationSettings.post(connection, {
    body: {
      discussionboard_member_id: memberA.id,
      in_app_enabled: true,
      email_enabled: false,
      reply_notification_enabled: true,
      mention_notification_enabled: true,
      moderation_notification_enabled: false,
      announcement_notification_enabled: true,
    },
  });
  typia.assert(notificationSettings);

  // 4. Attempt to delete Member A's notification settings as Member B (simulate as if logged in as Member B)
  // This must throw a 403 Forbidden error, which we check using TestValidator.error
  await TestValidator.error("non-owner Delete triggers 403 Forbidden")(
    async () => {
      await api.functional.discussionboard.notifications.memberNotificationSettings.eraseById(connection, {
        id: notificationSettings.id,
      });
    },
  );
}

