  const initialSettingsInput: IDiscussionboardMemberNotificationSettings.ICreate = {
    discussionboard_member_id: member.id,
    in_app_enabled: true,
    email_enabled: false,
    reply_notification_enabled: true,
    mention_notification_enabled: false,
    moderation_notification_enabled: true,
    announcement_notification_enabled: false,
  };
  const initialSettings = await api.functional.discussionboard.notifications.memberNotificationSettings.post(
    connection,
