  TestValidator.equals("reply_notification_enabled updated")(updatedSettings.reply_notification_enabled)(updateInput.reply_notification_enabled);
  TestValidator.equals("moderation_notification_enabled updated")(updatedSettings.moderation_notification_enabled)(updateInput.moderation_notification_enabled);
  TestValidator.equals("announcement_notification_enabled updated")(updatedSettings.announcement_notification_enabled)(updateInput.announcement_notification_enabled);
  TestValidator.equals("in_app_enabled unchanged")(updatedSettings.in_app_enabled)(initialSettings.in_app_enabled);
