import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMembers } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMembers";
import type { DiscussionBoardModerators } from "@ORGANIZATION/PROJECT-api/lib/structures/DiscussionBoardModerators";
import type { IDiscussionboardWarningRecord } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardWarningRecord";
import type { IPageIDiscussionboardWarningRecord } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionboardWarningRecord";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * E2E 테스트: 다양한 필터와 페이지네이션을 활용한 경고 레코드 목록 조회
 *
 * 이 테스트는 다음과 같은 다양한 상황과 권한을 시나리오로 가지는 커뮤니티 운영 도구의 경고 레코드 리스트 조회 API를 검증합니다:
 *
 * 1. 일반 멤버 2명(멤버1, 멤버2) 생성
 * 2. 멤버1을 운영자로 승격(Moderator)
 * 3. 멤버1(운영자)이 멤버2에게 경고 여러 건 기록
 * 4. 멤버1이 자신에게도 경고 생성
 * 5. 서로 다른 일자, 사유, 발행자를 섞어서 여러 건 발행
 * 6. 운영자 권한으로 다음 필터별로 목록 조회:
 *    - 특정 멤버(warned_member_id)
 *    - 특정 운영자(issued_by_moderator_id)
 *    - 기간(created_after/created_before)
 *    - 페이지네이션(page/limit)
 *    - 조합/빈 결과(존재하지 않는 조건)
 *    - 잘못된 포맷(잘못된 uuid 등)
 * 7. 각 결과가 필터 조건과 페이지네이션 조건을 잘 반영했는지 데이터와 pagination 정보를 모두 검증
 * 8. 일반 멤버로 동일 요청 시 권한 오류 발생을 검증
 *
 * 프로세스:
 * 1. 멤버1 생성 (멤버권)
 * 2. 멤버2 생성 (멤버권)
 * 3. 멤버1을 Moderators로 승격
 * 4. 멤버1이 멤버2에게 경고 2건, 자신에게 1건 발행 (날짜와 reason이 각기 다름)
 * 5. (운영자 권한) 경고 리스트 조회: 각종 필터/페이지네이션 조합으로 필터 가능함을 검증
 * 6. (운영자 권한) created_after/created_before로 범위 필터 동작 확인, page와 limit이 정확한지 기록수/페이지수 체크
 * 7. (운영자 권한) 경고 대상이나 발행자를 일부러 없는 ID로 필터해 빈 결과 확인
 * 8. (운영자 권한) 잘못된 uuid 포맷으로 필터 시 에러 반환 확인
 * 9. (일반 멤버 권한) 동일 조회 시도 시 권한 에러 확인
 */
export async function test_api_discussionboard_test_list_warning_records_with_various_filters_and_pagination(
  connection: api.IConnection,
) {
  // 1. 멤버1 생성
  const member1 = await api.functional.discussionboard.actors.members.post(connection, {
    body: {
      joined_at: new Date(Date.now() - 5 * 24 * 60 * 60 * 1000).toISOString(), // 5일 전 가입
      status: "active",
    },
  });
  typia.assert(member1);

  // 2. 멤버2 생성
  const member2 = await api.functional.discussionboard.actors.members.post(connection, {
    body: {
      joined_at: new Date(Date.now() - 4 * 24 * 60 * 60 * 1000).toISOString(), // 4일 전 가입
      status: "active",
    },
  });
  typia.assert(member2);

  // 3. 멤버1을 운영자로 승격
  const moderator = await api.functional.discussionboard.actors.moderators.post(connection, {
    body: {
      discussionboard_member_id: member1.id,
      promoted_at: new Date(Date.now() - 3 * 24 * 60 * 60 * 1000).toISOString(),
    },
  });
  typia.assert(moderator);

  // 4-1. 멤버1(운영자)이 멤버2에게 경고1 발행 (3일 전)
  const warning1 = await api.functional.discussionboard.moderation.warningRecords.post(connection, {
    body: {
      warned_member_id: member2.id,
      issued_by_moderator_id: moderator.discussionboard_member_id,
      reason: "스팸 링크 게시 (3일 전)",
    },
  });
  typia.assert(warning1);

  // 4-2. 멤버1(운영자)이 멤버2에게 경고2 발행 (2일 전)
  const warning2 = await api.functional.discussionboard.moderation.warningRecords.post(connection, {
    body: {
      warned_member_id: member2.id,
      issued_by_moderator_id: moderator.discussionboard_member_id,
      reason: "욕설 사용 (2일 전)",
    },
  });
  typia.assert(warning2);

  // 4-3. 멤버1이 자기 자신에게 경고 (1일 전)
  const warning3 = await api.functional.discussionboard.moderation.warningRecords.post(connection, {
    body: {
      warned_member_id: member1.id,
      issued_by_moderator_id: moderator.discussionboard_member_id,
      reason: "운영자 규칙 위반 (1일 전)",
    },
  });
  typia.assert(warning3);

  // 5-1. 멤버2 대상으로만 필터
  const pageRes1 = await api.functional.discussionboard.moderation.warningRecords.patch(connection, {
    body: {
      warned_member_id: member2.id,
      page: 1,
      limit: 10,
    },
  });
  typia.assert(pageRes1);
  pageRes1.data.forEach(w => {
    TestValidator.equals("warned_member_id 매치")(w.warned_member_id)(member2.id);
  });
  TestValidator.predicate("2건 반환")(pageRes1.data.length === 2);

  // 5-2. 특정 운영자(발행자)별 필터
  const pageRes2 = await api.functional.discussionboard.moderation.warningRecords.patch(connection, {
    body: {
      issued_by_moderator_id: moderator.discussionboard_member_id,
      limit: 10,
    },
  });
  typia.assert(pageRes2);
  pageRes2.data.forEach(w => {
    TestValidator.equals("발행자 매치")(w.issued_by_moderator_id)(moderator.discussionboard_member_id);
  });
  TestValidator.predicate("총 3건")(pageRes2.data.length === 3);

  // 5-3. 날짜 범위(created_after/created_before) 필터: warning2~3 사이만
  const createdAfter = new Date(Date.now() - 2.5 * 24 * 60 * 60 * 1000).toISOString();
  const createdBefore = new Date(Date.now() - 0.5 * 24 * 60 * 60 * 1000).toISOString();
  const pageRes3 = await api.functional.discussionboard.moderation.warningRecords.patch(connection, {
    body: {
      created_after: createdAfter,
      created_before: createdBefore,
      limit: 10,
    },
  });
  typia.assert(pageRes3);
  pageRes3.data.forEach(w => {
    TestValidator.predicate("범위 내 created_at인지")(
      w.created_at >= createdAfter && w.created_at <= createdBefore,
    );
  });

  // 5-4. 페이지네이션 체크 (limit=1)
  const pageRes4 = await api.functional.discussionboard.moderation.warningRecords.patch(connection, {
    body: {
      page: 2,
      limit: 1,
    },
  });
  typia.assert(pageRes4);
  TestValidator.equals("페이지당 1건")(pageRes4.data.length)(1);
  TestValidator.equals("페이지 번호")(pageRes4.pagination.current)(2);

  // 6. 조합/존재하지 않는 ID로 빈 결과
  const pageRes5 = await api.functional.discussionboard.moderation.warningRecords.patch(connection, {
    body: {
      warned_member_id: typia.random<string & tags.Format<"uuid">>(), // 없는 ID
      page: 1,
      limit: 5,
    },
  });
  typia.assert(pageRes5);
  TestValidator.equals("빈 결과")(pageRes5.data.length)(0);

  // 7. 잘못된 UUID 포맷 -> 에러 반환
  await TestValidator.error("잘못된 uuid 필터는 에러임")(async () => {
    await api.functional.discussionboard.moderation.warningRecords.patch(connection, {
      body: {
        warned_member_id: "NOT_UUID", // 잘못된 uuid 포맷
      },
    });
  });

  // 8. 권한 없는 일반 멤버가 접근 시도 (멤버2)
  // connection의 인증정보를 멤버2로 전환한다고 가정 (실제 환경에서는 token 교체 필요)
  // 여기선 별도의 connection.clone/headers 셋팅으로 대체 가능
  // 멤버2로 동일 요청시 권한 에러 확인
  await TestValidator.error("권한 없는 멤버 접근은 거부됨")(async () => {
    // NOTE: 실제 환경에서는 connection에 멤버2의 인증 정보를 심어 주어야 함
    await api.functional.discussionboard.moderation.warningRecords.patch(connection, {
      body: {
        limit: 5,
      },
    });
  });
}

