 * 
 * Steps:
 * 1. Create a new member
 * 2. Create a profile linked to this member
 * 3. Retrieve the profile by its ID and assert properties match
 * 4. Attempt to fetch a non-existent profile by random UUID and expect 404 error
 * 5. Create a second member (non-owner), attempt to fetch the first member's profile as this member, confirm compliance
 * 6. Delete the original member and attempt to retrieve their profile - assert correct masking or error behavior
 */
export async function test_api_discussionboard_test_get_member_profile_by_id_success_and_edge_cases(
  connection: api.IConnection,
) {
  // 1. Create a new board member
  const member = await api.functional.discussionboard.actors.members.post(connection, {
    body: {
      joined_at: new Date().toISOString(),
      status: "active",
    },
  });
  typia.assert(member);

  // 2. Create member profile for the new member
  const createProfileInput = {
    discussionboard_member_id: member.id,
    display_name: "TestUser",
    bio: "This is a test user bio.",
    avatar_uri: null,
    website: null,
    location: null,
  } satisfies IDiscussionBoardMemberProfile.ICreate;
  const profile = await api.functional.discussionboard.actors.memberProfiles.post(connection, { body: createProfileInput });
  typia.assert(profile);

  // 3. Retrieve the created profile by its ID
  const fetchedProfile = await api.functional.discussionboard.actors.memberProfiles.getById(connection, { id: profile.id });
  typia.assert(fetchedProfile);
  TestValidator.equals("profile id")(fetchedProfile.id)(profile.id);
  TestValidator.equals("member id")(fetchedProfile.discussionboard_member_id)(member.id);
  TestValidator.equals("display name")(fetchedProfile.display_name)(createProfileInput.display_name);
  TestValidator.equals("bio")(fetchedProfile.bio)(createProfileInput.bio);

  // 4. Attempt to fetch a non-existent profile (random UUID)
  await TestValidator.error("404 on non-existent profile")(() =>
    api.functional.discussionboard.actors.memberProfiles.getById(connection, {
      id: typia.random<string & tags.Format<"uuid">>(),
    })
  );

  // 5. Create another member (non-owner), and attempt profile access
  const member2 = await api.functional.discussionboard.actors.members.post(connection, {
    body: {
      joined_at: new Date().toISOString(),
      status: "active",
    },
  });
  typia.assert(member2);
  // This environment does not model access tokens/user context switching, so test self-contained compliance
  // In real scenario, would assert blocked or masked fields if policy dictates

  // 6. Delete the original member, attempt to retrieve their profile
  await api.functional.discussionboard.actors.members.eraseById(connection, {
    id: member.id,
  });
  await TestValidator.error("profile fetch after member deleted")(() =>
    api.functional.discussionboard.actors.memberProfiles.getById(connection, { id: profile.id })
  );
}

