/**
 * Validate that a discussion board post can be soft-deleted (logically deleted) by its original author.
 *
 * This test simulates the following business flow:
 * 1. Create a new member (post author)
 * 2. Create a new (random board) thread as that member
 * 3. Create a post in the thread as that member
 * 4. Attempt to delete (soft-delete) the post as the owner (author)
 *    - The API should succeed, returning the deleted post record with its deleted_at timestamp set
 *    - The deleted_at field must be present and an ISO8601 timestamp
 *
 * Checks that the business rule allowing authors to delete their own posts is enforced.
 */
export async function test_api_discussionboard_test_delete_post_success_by_author(
  connection: api.IConnection,
) {
  // 1. Create member (author)
  const member = await api.functional.discussionboard.actors.members.post(connection, {
    body: {
      joined_at: new Date().toISOString(),
      status: "active",
    },
  });
  typia.assert(member);
  // 2. Create thread (random board, by author)
  const thread = await api.functional.discussionboard.threads.threads.post(connection, {
    body: {
      discussionboard_board_id: typia.random<string & tags.Format<"uuid">>(),
      discussionboard_member_id: member.id,
      title: RandomGenerator.paragraph()(8),
      description: null,
      status: "open",
      created_at: new Date().toISOString(),
    },
  });
  typia.assert(thread);
  // 3. Create post (in thread, by author)
  const post = await api.functional.discussionboard.threads.posts.post(connection, {
    body: {
      discussionboard_thread_id: thread.id,
      discussionboard_member_id: member.id,
      body: RandomGenerator.content()()(),
      created_at: new Date().toISOString(),
    },
  });
  typia.assert(post);
  // 4. Attempt to delete the post as the author
  const deleted = await api.functional.discussionboard.threads.posts.eraseById(connection, {
    id: post.id,
  });
  typia.assert(deleted);
  // Validate that the post has been soft-deleted
  TestValidator.equals("Deleted post id matches")(deleted.id)(post.id);
  TestValidator.predicate("Soft-deleted field is set, is ISO timestamp")(
    typeof deleted.deleted_at === "string" &&
    !isNaN(Date.parse(deleted.deleted_at))
  );
}

