  // 6. Register authentication for member #2
  const auth2 = await api.functional.discussionboard.actors.memberAuthentications.post(connection, {
    body: {
      discussionboard_member_id: member2.id,
      provider: "local",
      provider_identifier: RandomGenerator.alphaNumeric(10),
      password_hash: RandomGenerator.alphaNumeric(40)
    }
  });
  typia.assert(auth2);

  // 7. Attempt to delete auth2 as member1 (should fail, insufficient privileges)
  // (Assume privilege boundary enforced by auth context, but using same connection here)
  await TestValidator.error("insufficient-privilege delete should fail")(() =>
    api.functional.discussionboard.actors.memberAuthentications.eraseById(connection, { id: auth2.id })
  );

  // 8. Attempt to delete a random, non-existent id (should fail)
  await TestValidator.error("delete on non-existent id should fail")(() =>
