export async function test_api_discussionboard_test_list_moderators_with_valid_filters_and_pagination(connection: api.IConnection) {
  // 1. Create first member
  const member1 = await api.functional.discussionboard.actors.members.post(connection, {
    body: {
      joined_at: new Date(Date.now() - 1000 * 60 * 60 * 24).toISOString(), // yesterday
      status: "active",
    }
  });
  typia.assert(member1);

  // 2. Create second member
  const member2 = await api.functional.discussionboard.actors.members.post(connection, {
    body: {
      joined_at: new Date().toISOString(), // now
      status: "active",
    }
  });
  typia.assert(member2);

  // 3. Promote both members to moderator with distinct promoted_at
  const promoted1 = await api.functional.discussionboard.actors.moderators.post(connection, {
    body: {
      discussionboard_member_id: member1.id,
      promoted_at: new Date(Date.now() - 1000 * 60 * 60).toISOString(), // 1 hour ago
    }
  });
  typia.assert(promoted1);
  const promoted2 = await api.functional.discussionboard.actors.moderators.post(connection, {
    body: {
      discussionboard_member_id: member2.id,
      promoted_at: new Date().toISOString(), // now
    }
  });
