/**
 * E2E test for creating comments on discussion board posts covering both valid and invalid scenarios.
 *
 * This test covers the following flows:
 * 1. Register two member accounts (one active, one suspended)
 * 2. Create a post as the active member
 * 3. Create a top-level comment on the post as the active member
 * 4. Create a reply to the previous comment (nested comment)
 * 5. Validate response structure: presence of IDs, timestamps, correct relations, body, etc.
 * 6. Attempt to create a comment as the suspended member (expect 403 error)
 * 7. Attempt to comment on invalid or non-existent post (expect 404 error)
 * 8. Attempt to create a comment with missing or empty body (expect 400 error)
 * 9. Attempt to reply to a deleted/invalid parent comment (expect 404 or 400 error)
 * 10. (Optionally, if possible) Test maximum nesting depth or comment quota business rule violations
*/
export async function test_api_discussionboard_test_create_comment_on_post_valid_and_invalid_cases(
  connection: api.IConnection,
) {
  // 1. Register two members: one active, one to be suspended later
  const activeMember = await api.functional.discussionboard.actors.members.post(connection, { body: { joined_at: new Date().toISOString(), status: "active" }});
  typia.assert(activeMember);
  const suspendedMember = await api.functional.discussionboard.actors.members.post(connection, { body: { joined_at: new Date().toISOString(), status: "active" }});
  typia.assert(suspendedMember);

  // 2. Create a post as activeMember
  const threadId = typia.random<string & tags.Format<"uuid">>();
  const post = await api.functional.discussionboard.threads.posts.post(connection, { body: { discussionboard_thread_id: threadId, discussionboard_member_id: activeMember.id, body: RandomGenerator.paragraph()(), created_at: new Date().toISOString() }});
  typia.assert(post);

  // 3. Create a top-level comment
  const comment = await api.functional.discussionboard.threads.comments.post(connection, { body: { discussionboard_post_id: post.id, discussionboard_member_id: activeMember.id, body: RandomGenerator.content()()(), parent_id: null }});
  typia.assert(comment);
  TestValidator.equals("post id relation")(comment.discussionboard_post_id)(post.id);
  TestValidator.equals("member relation")(comment.discussionboard_member_id)(activeMember.id);
  TestValidator.equals("no parent")(comment.parent_id)(null);
  TestValidator.predicate("body content present")(!!comment.body);
  TestValidator.predicate("created_at present")(!!comment.created_at);
  TestValidator.predicate("updated_at present")(!!comment.updated_at);

  // 4. Create a reply (nested comment)
  const reply = await api.functional.discussionboard.threads.comments.post(connection, { body: { discussionboard_post_id: post.id, discussionboard_member_id: activeMember.id, body: RandomGenerator.content()()(), parent_id: comment.id }});
  typia.assert(reply);
