  );

  // 7. Attempt comment with invalid post id (should fail)
  await TestValidator.error("invalid post id")(() =>
    api.functional.discussionboard.threads.comments.post(connection, { body: { discussionboard_post_id: "00000000-0000-0000-0000-000000000000", discussionboard_member_id: activeMember.id, body: "Bad post id", parent_id: null }})
  );

  // 8. Missing body (should fail)
  await TestValidator.error("missing body")(() =>
    api.functional.discussionboard.threads.comments.post(connection, { body: { discussionboard_post_id: post.id, discussionboard_member_id: activeMember.id, body: "", parent_id: null }})
