/**
 * Test listing and searching channels as an admin with pagination and filter options.
 *
 * This test ensures that:
 * 1. Multiple channels are created with diverse 'enabled' states, codes, names, and descriptions.
 * 2. Channels can be retrieved with search term (name/description), filtering by enabled/disabled,
 *    and with pagination (page/limit).
 * 3. The filtered result contains only channels matching the query and pagination settings.
 * 4. All necessary fields are present in channel results.
 * 
 * Step-by-step process:
 * 1. Create several channels with a mix of properties:
 *    - At least 3 channels enabled=true, unique code/name/desc
 *    - At least 2 channels enabled=false, unique code/name/desc
 * 2. List channels with:
 *    a. No filter (default): expect all channels
 *    b. enabled=true filter: only enabled channels
 *    c. enabled=false filter: only disabled channels
 *    d. search by partial name/description: expect correct filtered subset
 *    e. Pagination: (limit=2, page=1 and 2): correct slicing and metadata
 * 3. Validate results for each query:
 *    - Data matches intended channels (codes/names/descriptions)
 *    - Pagination metadata (current, limit, pages, records) is correct
 *    - Channel properties in result objects are as per schema (all fields)
 */
export async function test_api_discussionboard_systematic_channels_test_list_channels_with_search_and_pagination_by_admin(
  connection: api.IConnection,
) {
  // 1. Seed channel data
  const channelData = [
    { code: "ECON_1", name: "Economics Alpha", description: "Economic analysis", enabled: true },
    { code: "POLI_1", name: "Politics Beta", description: "Political forum", enabled: true },
    { code: "SCI_1", name: "Science Gamma", description: "Science discussion", enabled: true },
    { code: "ART_1", name: "Art Delta", description: "Art and culture", enabled: false },
    { code: "SPORT_1", name: "Sports Epsilon", description: "Sports fans club", enabled: false },
  ];
  const createdChannels: IDiscussionboardChannel[] = [];
  for(const input of channelData) {
    const channel = await api.functional.discussionboard.systematic.channels.post(connection, {
      body: {
        code: input.code,
        name: input.name,
        description: input.description,
        enabled: input.enabled
      } satisfies IDiscussionboardChannel.ICreate,
    });
    typia.assert(channel);
    createdChannels.push(channel);
  }

