      await api.functional.discussionboard.notifications.notifications.putById(connection, {
        id: randomNotificationId,
        body: {
          title: "Updated Title",
        },
      });
    }
  );

  // 3. Attempt to update with an empty payload (no updatable fields)
  await TestValidator.error("should return 400 for invalid/missing update fields")(
    async () => {
      await api.functional.discussionboard.notifications.notifications.putById(connection, {
        id: randomNotificationId,
        body: {},
      });
    }
  );

  // 4. Attempt to update with a forbidden or undeclared field. (skip if not technically possible)
}

