import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMembers } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMembers";
import type { IDiscussionboardPosts } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardPosts";
import type { IDiscussionboardPostLike } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardPostLike";

/**
 * Validate access control enforcement when updating a post like entry.
 *
 * This scenario ensures that only the member who created a post like (or a privileged user) is allowed to update it. Unauthorized members or non-members must be strictly denied—verifying security best-practice for sensitive engagement interactions.
 *
 * Workflow:
 * 1. Register two board members: Member1 (who creates the like), and Member2 (who will attempt the unauthorized update).
 * 2. Member1 creates a post in a thread (simulate thread ID as a UUID—there is no provided API for thread creation).
 * 3. Member1 likes their own post. The postLike is associated to Member1 and the created post.
 * 4. Member2 attempts to update the postLike, using the postLike ID, but is not the owner nor privileged.
 * 5. API must reject Member2’s attempt—permission is denied.
 *
 * Validates enforcement of resource ownership and privilege restrictions for interaction resources.
 */
export async function test_api_discussionboard_test_update_post_like_by_non_owner_or_forbidden_user(
  connection: api.IConnection,
) {
  // 1. Register two members
  const member1 = await api.functional.discussionboard.actors.members.post(connection, {
    body: {
      joined_at: new Date().toISOString(),
      status: "active",
    },
  });
  typia.assert(member1);
  const member2 = await api.functional.discussionboard.actors.members.post(connection, {
    body: {
      joined_at: new Date().toISOString(),
      status: "active",
    },
  });
  typia.assert(member2);

  // 2. Member1 creates a post (simulate thread_id as UUID)
  const threadId = typia.random<string & tags.Format<"uuid">>();
  const post = await api.functional.discussionboard.threads.posts.post(connection, {
    body: {
      discussionboard_thread_id: threadId,
      discussionboard_member_id: member1.id,
      body: "Test post for like permission check.",
      created_at: new Date().toISOString(),
    },
  });
  typia.assert(post);

  // 3. Member1 likes the post
  const postLike = await api.functional.discussionboard.interactions.postLikes.post(connection, {
    body: {
      discussionboard_post_id: post.id,
      discussionboard_member_id: member1.id,
    },
  });
  typia.assert(postLike);

  // 4. Member2 attempts to update Member1's postLike
  await TestValidator.error("Updating post like by non-owner must be forbidden")(
    async () => {
      await api.functional.discussionboard.interactions.postLikes.putById(connection, {
        id: postLike.id,
        body: {
          // Try to update member attribution to Member2 (should be forbidden)
          discussionboard_member_id: member2.id,
        },
      });
    },
  );
}

