import type { IDiscussionboardNotification } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardNotification";

/**
 * Validate error handling when creating discussion board notifications with
 * missing required fields or lack of authorization/authentication.
 *
 * This test checks that the API correctly rejects invalid notification creation
 * attempts, including:
 * - Missing required fields (title, body, type, delivered_at, recipient)
 * - Creation attempts with empty request body or with only partial info
 * - Unauthorized/unauthenticated user attempts (assuming authentication is enforced)
 * - Validation: the API should return appropriate error responses and prevent
 *   creation of any notification on failure
 *
 * Test Steps:
 * 1. Register a valid member for use as recipient.
 * 2. For each of the following invalid notification creation attempts, assert
 *    that an error is thrown:
 *    a) Missing title
 *    b) Missing body
 *    c) Missing type
 *    d) Missing delivered_at
 *    e) Missing discussionboard_member_id
 *    f) Completely empty body
 *    g) Extra/malformed fields (should be rejected)
 * 3. If authentication is required, attempt creation without authentication and expect an error.
 * 4. Confirm that no notification is created after failed attempts (if listing API is available; otherwise skip).
 */
export async function test_api_discussionboard_notifications_test_create_notification_invalid_missing_fields_or_unauthorized(
  connection: api.IConnection,
) {
  // 1. Register a member for recipient
  const member = await api.functional.discussionboard.actors.members.post(connection, {
    body: {
      joined_at: new Date().toISOString(),
      status: "active",
    },
  });
  typia.assert(member);

  // 2. Invalid notification creation cases
  const base: IDiscussionboardNotification.ICreate = {
    discussionboard_member_id: member.id,
    type: "test_type",
    title: "Test notification",
    body: "Test body",
    delivered_at: new Date().toISOString(),
  };

  // a) Missing title
  await TestValidator.error("missing title should fail")(async () => {
    const { title, ...body } = base;
    await api.functional.discussionboard.notifications.notifications.post(connection, {
      body: body as IDiscussionboardNotification.ICreate,
    });
  });
  // b) Missing body
  await TestValidator.error("missing body should fail")(async () => {
    const { body: _body, ...rest } = base;
    await api.functional.discussionboard.notifications.notifications.post(connection, {
      body: rest as IDiscussionboardNotification.ICreate,
    });
  });
  // c) Missing type
  await TestValidator.error("missing type should fail")(async () => {
    const { type, ...body } = base;
    await api.functional.discussionboard.notifications.notifications.post(connection, {
      body: body as IDiscussionboardNotification.ICreate,
    });
  });
  // d) Missing delivered_at
  await TestValidator.error("missing delivered_at should fail")(async () => {
    const { delivered_at, ...body } = base;
    await api.functional.discussionboard.notifications.notifications.post(connection, {
      body: body as IDiscussionboardNotification.ICreate,
    });
  });
  // e) Missing recipient
  await TestValidator.error("missing recipient should fail")(async () => {
    const { discussionboard_member_id, ...body } = base;
    await api.functional.discussionboard.notifications.notifications.post(connection, {
      body: body as IDiscussionboardNotification.ICreate,
    });
  });
  // f) Completely empty body
  await TestValidator.error("empty body should fail")(async () => {
    await api.functional.discussionboard.notifications.notifications.post(connection, {
      body: {} as IDiscussionboardNotification.ICreate,
    });
  });
  // g) Extra/malformed field
  await TestValidator.error("extra property should fail")(async () => {
    await api.functional.discussionboard.notifications.notifications.post(connection, {
      body: {
        ...base,
        extra_field: "not allowed",
      } as any,
    });
  });

  // 3. Unauthenticated attempt (if API enforces authentication, simulate logout and try)
  // (Omitted: no mechanism to change connection state without user/session API)

  // 4. Cannot confirm notification was not created since no list API exists (skip)
}

