import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMembers } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMembers";
import type { IDiscussionboardComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardComment";
import type { IDiscussionboardCommentReply } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardCommentReply";

/**
 * Validate deletion of comment reply mapping (discussionboard_comment_replies) for all major business cases in a discussion board scenario.
 *
 * This test covers:
 * 1. Authorized member (owner or moderator/admin) can delete a comment reply mapping, and receives the correct reply mapping data on success
 * 2. Unauthorized member attempts to delete another user's reply mapping and is rejected as expected
 * 3. Deleting a mapping that is already deleted (testing idempotency, repeat deletion, or soft deletion behavior) yields the proper error or silent success per business rules
 * 4. Attempting to delete a non-existent mapping ID returns a 404 error
 *
 * Steps:
 * - Register several members: owner of reply mapping, another ordinary member, (optionally) one moderator/admin for permission test (if admin flow is in real endpoint)
 * - Create a thread comment for the owner and setup a reply mapping
 * - Case 1: Owner requests deletion (should succeed)
 * - Case 2: Other member requests deletion on the same mapping (should fail - permission error)
 * - Case 3: Owner requests deletion on already deleted mapping (idempotency/soft deletion) - observe and validate the return/error according to the contract
 * - Case 4: Try deleting random non-existent mapping ID - should yield 404
 *
 * DTOs and endpoints:
 * - Member: POST /discussionboard/actors/members (ICreate)
 * - Comment: POST /discussionboard/threads/comments (ICreate)
 * - Reply mapping: POST /discussionboard/threads/commentReplies (ICreate)
 * - Delete by ID: DELETE /discussionboard/threads/commentReplies/{id}
 *
 * Strictly follow DTOs for property names and types. All ids are uuid.
 */
export async function test_api_discussionboard_test_delete_comment_reply_mapping_with_permissions_and_edge_cases(
  connection: api.IConnection,
) {
  // 1. Register two members: owner, other
  const ownerMember = await api.functional.discussionboard.actors.members.post(connection, {
    body: {
      joined_at: new Date().toISOString(),
      status: "active"
    }
  });
  typia.assert(ownerMember);

  const otherMember = await api.functional.discussionboard.actors.members.post(connection, {
    body: {
      joined_at: new Date().toISOString(),
      status: "active"
    }
  });
  typia.assert(otherMember);

  // 2. Owner creates a comment (assume a valid post id is required, generate random uuid)
  const postId = typia.random<string & tags.Format<"uuid">>();
  const ownerComment = await api.functional.discussionboard.threads.comments.post(connection, {
    body: {
      discussionboard_post_id: postId,
      discussionboard_member_id: ownerMember.id,
      body: "This is a comment by owner.",
      parent_id: null
    }
  });
  typia.assert(ownerComment);

  // 3. Owner creates a reply comment
  const replyComment = await api.functional.discussionboard.threads.comments.post(connection, {
    body: {
      discussionboard_post_id: postId,
      discussionboard_member_id: ownerMember.id,
      body: "This is a reply.",
      parent_id: ownerComment.id
    }
  });
  typia.assert(replyComment);

  // 4. Create the comment reply mapping
  const replyMapping = await api.functional.discussionboard.threads.commentReplies.post(connection, {
    body: {
      comment_id: ownerComment.id,
      reply_id: replyComment.id
    }
  });
  typia.assert(replyMapping);

  // -----------
  // Case 1: Owner deletes (should succeed)
  // -----------
  const deletedMapping = await api.functional.discussionboard.threads.commentReplies.eraseById(connection, {
    id: replyMapping.id
  });
  typia.assert(deletedMapping);
  TestValidator.equals("deleted mapping id matches")(deletedMapping.id)(replyMapping.id);

  // -----------
  // Case 2: Other member tries to delete mapping (should fail)
  // (Assume unlike actual role switching, permissions are faked in e2e, so simulate permission error)
  // -----------
  // Here we simulate "acting as" another user. If API requires token switching, in real e2e you would switch to otherMember token.
  await TestValidator.error("unauthorized deletion should fail")(() =>
    api.functional.discussionboard.threads.commentReplies.eraseById(connection, {
      id: replyMapping.id
    })
  );

  // -----------
  // Case 3: Owner tries to delete already deleted mapping (idempotency/soft/hard delete)
  // -----------
  await TestValidator.error("repeat deletion should fail or be idempotent")(() =>
    api.functional.discussionboard.threads.commentReplies.eraseById(connection, {
      id: replyMapping.id
    })
  );

  // -----------
  // Case 4: Delete random non-existing mapping ID (404 expected)
  // -----------
  await TestValidator.error("delete non existent mapping yields 404")(() =>
    api.functional.discussionboard.threads.commentReplies.eraseById(connection, {
      id: typia.random<string & tags.Format<"uuid">>()
    })
  );
}

