import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardCategory";

/**
 * Validate category deletion access control and error handling.
 *
 * This test checks two aspects:
 * 1. Nonexistent category deletion returns a 404 error.
 * 2. Only admin accounts may delete categories. Attempt to delete a valid category as a moderator and regular member, expecting permission denied errors.
 *
 * Process:
 * 1. Login as admin (assumed authenticated by test environment).
 * 2. Create a category (admin privileges required).
 * 3. Attempt to delete a completely random (nonexistent) category id and verify 404 error is thrown.
 * 4. Logout admin, login as moderator, attempt to soft-delete the created category, expecting forbidden or permission denied error.
 * 5. Logout moderator, login as normal member, attempt to delete the same category, expecting forbidden or permission denied error.
 * 6. Finally, login as admin and properly delete the created category. Validate result object and its properties.
 */
export async function test_api_discussionboard_test_delete_category_not_found_and_access_control(
  connection: api.IConnection,
) {
  // 1. Assume we have an authenticated admin account (the test runner does this)
  // 2. Create a category as admin
  const createInput: IDiscussionboardCategory.ICreate = {
    discussionboard_channel_id: typia.random<string & tags.Format<"uuid">>(),
    code: RandomGenerator.alphabets(8),
    name: RandomGenerator.alphabets(12),
    enabled: true,
    // Optionally include parent_id/description
    parent_id: null,
    description: RandomGenerator.paragraph()(),
  };
  const created = await api.functional.discussionboard.systematic.categories.post(connection, { body: createInput });
  typia.assert(created);

  // 3. Try to delete a completely random category id (should 404)
  await TestValidator.error("nonexistent category should return 404")(
    async () => {
      await api.functional.discussionboard.systematic.categories.eraseById(connection, {
        id: typia.random<string & tags.Format<"uuid">>(),
      });
    },
  );

  // 4. Assume we can switch connections to moderator: simulate by changing connection.headers.Authorization
  // (In real E2E, would perform explicit login—here pseudo-logic)
  const moderatorConn = { ...connection };
  moderatorConn.headers = { ...moderatorConn.headers, Authorization: "Bearer MODERATOR_TOKEN" };
  await TestValidator.error("moderator cannot delete category")(
