 *
 * 1. Register a new member via /discussionboard/actors/members (status should be 'active')
 * 2. Issue a suspension on that member with /discussionboard/actors/memberSuspensions, effective now
 * 3. Attempt to create a new post via /discussionboard/threads/posts as this member
 * 4. Confirm that the post creation fails and a suspension-related error is returned
 */
export async function test_api_discussionboard_test_create_post_fails_for_suspended_member(
  connection: api.IConnection,
) {
