 * Steps:
 * 1. Compose unique and valid IDiscussionboardChannel.ICreate input (ensuring uniqueness of 'code').
 * 2. Call the API as an admin to create a new channel with the above data.
 * 3. Assert the response is a valid IDiscussionboardChannel.
 * 4. Assert the response fields (code, name, enabled, description) agree with input.
 * 5. Assert that audit fields are present and valid (id: uuid, created_at: datetime, updated_at: datetime, deleted_at: null or undefined).
 */
export async function test_api_discussionboard_test_create_channel_with_valid_data(connection: api.IConnection) {
  // Step 1: Generate unique, valid channel creation input
  const channelInput: IDiscussionboardChannel.ICreate = {
    code: `CHAN-${typia.random<number & tags.Type<"uint32"> & tags.Minimum<1000> & tags.Maximum<9999>>()}`,
    name: RandomGenerator.paragraph()(3),
    description: RandomGenerator.paragraph()(),
    enabled: true,
  };

  // Step 2: Call the API to create the channel
  const output = await api.functional.discussionboard.systematic.channels.post(connection, { body: channelInput });
  typia.assert(output);

