  TestValidator.equals("channel name")(output.name)(channelInput.name);
  TestValidator.equals("channel description")(output.description)(channelInput.description);
  TestValidator.equals("enabled flag")(output.enabled)(channelInput.enabled);

  // Step 4: Business/audit field assertions
  TestValidator.predicate("id is uuid")(
    typeof output.id === "string" && output.id.length > 0,
  );
  TestValidator.predicate("created_at is ISO")(
    !!output.created_at && typeof output.created_at === "string",
  );
  TestValidator.predicate("updated_at is ISO")(
    !!output.updated_at && typeof output.updated_at === "string",
  );
  // deleted_at is either null or undefined on creation
  TestValidator.predicate("not deleted")(
    !("deleted_at" in output) || output.deleted_at == null,
  );
}

