 * 4. Attempt to retrieve the topic as the unauthorized member using the GET by ID endpoint.
 * 5. Assert that the request is denied (catch HttpError exception), meaning the topic is not accessible to unauthorized users.
 *
 * Note: Since there is no explicit 'private' field on the topic or board, this test only covers potential membership-based access control –
 * the API may return permission denied (e.g., 403) or not found (e.g., 404).
 */
export async function test_api_discussionboard_test_get_board_topic_by_id_access_denied_for_private_topic(
  connection: api.IConnection,
) {
