      joined_at: new Date().toISOString(),
      status: "active",
    },
  });
  typia.assert(creator);
  const unauthorized = await api.functional.discussionboard.actors.members.post(connection, {
    body: {
      joined_at: new Date().toISOString(),
      status: "active",
    },
  });
  typia.assert(unauthorized);

  // 3. Create a board topic as the creator
  const topic = await api.functional.discussionboard.boards.boardTopics.post(connection, {
    body: {
      discussionboard_board_id: board.id,
      code: RandomGenerator.alphaNumeric(12),
      title: RandomGenerator.alphabets(16),
      description: RandomGenerator.paragraph()(),
      created_by_member_id: creator.id,
    },
  });
  typia.assert(topic);

  // 4-5. Attempt to retrieve topic as the unauthorized member (simulate by context or in actual role-aware e2e test infra)
  await TestValidator.error("unauthorized/insufficient member cannot access private topic")(async () => {
    await api.functional.discussionboard.boards.boardTopics.getById(connection, { id: topic.id });
  });
}

