import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMembers } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMembers";
import type { DiscussionboardBoard } from "@ORGANIZATION/PROJECT-api/lib/structures/DiscussionboardBoard";
import type { IDiscussionboardThreads } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardThreads";

/**
 * Validate updating threads including title, description, and status changes, as well as comprehensive permission and error handling flows on the DiscussionBoard platform.
 *
 * This scenario ensures thread updates work as intended for valid authors while verifying the API enforces correct access control and business rules regarding thread status changes and user roles. It also tests error responses when the update operation is performed by unauthorized users, for suspended accounts, invalid status transitions, and with deleted/nonexistent threads.
 *
 * Step-by-step process:
 * 1. Register a board member (user) to act as the thread's creator.
 * 2. Create a new board entity for the thread.
 * 3. Create a thread in the board as that member.
 * 4. Update the thread's title, description, and status as the creator. Confirm changes.
 * 5. Try updating the thread as a different, unauthorized member. Assert an error is returned (permission denied).
 * 6. (Simulate) Suspend the original member, then try updating again; expect a permission error.
 * 7. Attempt illegal status transitions as a regular member (e.g., locking/unlocking) and check errors.
 * 8. Delete the thread.
 * 9. Attempt to update the deleted thread and check for the correct not-found/deleted error.
 * 10. Attempt to update a completely non-existent thread ID and expect a not-found error.
 */
export async function test_api_discussionboard_test_update_thread_success_and_invalid_operations(connection: api.IConnection) {
  // 1. Register a board member
  const member = await api.functional.discussionboard.actors.members.post(connection, {
    body: {
      joined_at: new Date().toISOString(),
      status: 'active',
    },
  });
  typia.assert(member);

  // 2. Register a board
  const board = await api.functional.discussionboard.boards.boards.post(connection, {
    body: {
      discussionboard_category_id: typia.random<string & tags.Format<'uuid'>>() ,
      code: RandomGenerator.alphabets(8),
      name: RandomGenerator.paragraph()(1).slice(0,30),
      description: RandomGenerator.paragraph()(1),
      is_active: true,
    },
  });
  typia.assert(board);

  // 3. Create a thread as this member
  const thread = await api.functional.discussionboard.threads.threads.post(connection, {
    body: {
      discussionboard_board_id: board.id,
      discussionboard_member_id: member.id,
      title: 'Original Title',
      description: 'Initial description.',
      status: 'open',
      created_at: new Date().toISOString(),
    },
  });
  typia.assert(thread);

  // 4. Update thread title & description as the creator
  const newTitle = 'Updated Title';
  const newDesc = 'Updated thread description.';
  const newStatus = 'closed';
  const updateRes = await api.functional.discussionboard.threads.threads.putById(connection, {
    id: thread.id,
    body: {
      title: newTitle,
      description: newDesc,
      status: newStatus,
      updated_at: new Date().toISOString(),
    },
  });
  typia.assert(updateRes);
  TestValidator.equals('thread title update')(updateRes.title)(newTitle);
  TestValidator.equals('thread description update')(updateRes.description)(newDesc);
  TestValidator.equals('thread status update')(updateRes.status)(newStatus);

  // 5. Unauthorized update: register another member and try to update thread
  const otherMember = await api.functional.discussionboard.actors.members.post(connection, {
    body: {
      joined_at: new Date().toISOString(),
      status: 'active',
    },
  });
  typia.assert(otherMember);
  // Simulate acting as an unauthorized member (manual switch for test)
  // (Assume API enforces current user context, here we try direct update to check security edge)
  await TestValidator.error('unauthorized user cannot update thread')(async () => {
    await api.functional.discussionboard.threads.threads.putById(connection, {
      id: thread.id,
      body: {
        title: 'Hack attempt',
        updated_at: new Date().toISOString(),
      },
    });
  });

  // 6. Simulate: suspend the creator, then update thread
  // (In absence of real update, recreate member as suspended)
  const suspendedMember = await api.functional.discussionboard.actors.members.post(connection, {
    body: {
      joined_at: new Date().toISOString(),
      status: 'suspended',
    },
  });
  typia.assert(suspendedMember);
  await TestValidator.error('suspended member cannot update thread')(async () => {
    await api.functional.discussionboard.threads.threads.putById(connection, {
      id: thread.id,
      body: {
        description: 'Should fail: account suspended',
        updated_at: new Date().toISOString(),
      },
    });
  });

  // 7. Illegal status change: try to lock/unlock as regular member (should fail if non-moderator logic enforced)
  await TestValidator.error('regular member cannot lock thread')(async () => {
    await api.functional.discussionboard.threads.threads.putById(connection, {
      id: thread.id,
      body: {
        status: 'locked',
        updated_at: new Date().toISOString(),
      },
    });
  });
  await TestValidator.error('regular member cannot unlock thread')(async () => {
    await api.functional.discussionboard.threads.threads.putById(connection, {
      id: thread.id,
      body: {
        status: 'open',
        updated_at: new Date().toISOString(),
      },
    });
  });

  // 8. Delete the thread and 9. Try updating the deleted thread
  await api.functional.discussionboard.threads.threads.eraseById(connection, { id: thread.id });
  await TestValidator.error('cannot update deleted thread')(async () => {
    await api.functional.discussionboard.threads.threads.putById(connection, {
      id: thread.id,
      body: {
        description: 'Should fail: thread deleted',
        updated_at: new Date().toISOString(),
      },
    });
  });

  // 10. Attempt update on non-existent thread ID
  const nonExistentThreadId = typia.random<string & tags.Format<'uuid'>>() /* assured not to exist */;
  await TestValidator.error('cannot update non-existent thread')(async () => {
    await api.functional.discussionboard.threads.threads.putById(connection, {
      id: nonExistentThreadId,
      body: {
        title: 'Should fail: thread does not exist',
        updated_at: new Date().toISOString(),
      },
    });
  });
}

