import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardCategory";

/**
 * Test access control and error handling when updating a discussion board category by ID.
 *
 * This E2E test covers two security/business logic concerns for the category update API:
 *
 * 1. Updating a NON-EXISTENT category should result in a 404 error.
 * 2. Only admin users have permission to update a category. Moderator and member updates must be denied (expected 403 or access denied error).
 *
 * Step-by-step process:
 * 1. Admin user creates a new discussion board category (using dependency API).
 * 2. Admin updates the created category by ID (expecting SUCCESS).
 * 3. Attempt to update a NON-EXISTENT category ID as admin (expecting 404 error).
 * 4. Authenticate/switch to a MODERATOR account, attempt category update (expecting 403/access denied error).
 * 5. Authenticate/switch to a regular MEMBER account, attempt category update (expecting 403/access denied error).
 *
 * Validates backend role-based access control for the update endpoint and confirms correct HTTP error codes for invalid targets.
 */
export async function test_api_discussionboard_test_update_category_not_found_and_access_control(
  connection: api.IConnection,
) {
  // Step 1: Create a category as admin
  const category = await api.functional.discussionboard.systematic.categories.post(
    connection,
    {
      body: typia.random<IDiscussionboardCategory.ICreate>(),
    },
  );
  typia.assert(category);

  // Step 2: Update the created category (should succeed)
  const updated = await api.functional.discussionboard.systematic.categories.putById(
    connection,
    {
      id: category.id,
      body: {
        name: "Updated Name",
      } satisfies IDiscussionboardCategory.IUpdate,
    },
  );
  typia.assert(updated);

  // Step 3: Try updating a non-existent category (should fail with 404)
  await TestValidator.error("404 for non-existent category")(
    async () => {
      await api.functional.discussionboard.systematic.categories.putById(
        connection,
        {
          id: typia.random<string & tags.Format<"uuid">>(),
          body: { name: "NoSuchCategory" },
        },
      );
    },
  );

  // Step 4: Authenticate (or switch) as moderator (simulate if API exists)
  // Assume a switch function api.functional.discussionboard.auth.moderator.login, else omit this step if not defined
  // If the API does NOT exist, you may add a comment explaining omission.

  // Step 5: Attempt category update as MODERATOR (expect 403/denied)
  // (Replace code below with actual moderator login API call if such exists)
  await TestValidator.error("403 for moderator")(
    async () => {
      // Login/switch to moderator role here if API exists
      // e.g., await api.functional.discussionboard.auth.moderator.login(connection, ...);
      await api.functional.discussionboard.systematic.categories.putById(
        connection,
        {
          id: category.id,
          body: { name: "Moderator Attempt" },
        },
      );
    },
  );

  // Step 6: Authenticate (or switch) as member (simulate if API exists)
  // Again, only if API exists (see above comment).

  // Step 7: Attempt category update as regular MEMBER (expect 403/denied)
  await TestValidator.error("403 for member")(
    async () => {
      // Login/switch to member role here if API exists
      await api.functional.discussionboard.systematic.categories.putById(
        connection,
        {
          id: category.id,
          body: { name: "Member Attempt" },
        },
      );
    },
  );
}

