import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMembers } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMembers";
import type { IDiscussionboardThreads } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardThreads";
import type { IDiscussionboardPosts } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardPosts";
import type { IDiscussionboardPostAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardPostAttachment";

/**
 * Validate post-attachment detail retrieval, permissions, and error handling.
 *
 * Ensures that a post attachment can be viewed by its uploader, any thread participant, and cannot be accessed by non-participants.
 * Also checks correct error responses for missing IDs.
 *
 * Workflow:
 * 1. Create three members: uploader, participant, and outsider.
 * 2. Uploader creates a thread and initial post.
 * 3. Uploader uploads a post attachment (record ID).
 * 4. Uploader gets the attachment by ID (success, verify fields).
 * 5. Participant creates a post in the same thread.
 * 6. Participant gets the attachment by ID (success, verify fields).
 * 7. Outsider (no post in thread) gets the attachment by ID (expect permission error).
 * 8. Query a random, non-existent attachment ID (expect not found error).
 */
export async function test_api_discussionboard_test_get_post_attachment_detail_success_and_permission(connection: api.IConnection) {
  // 1. Create three members: uploader, participant, outsider.
  const now = new Date().toISOString();
  const uploader = await api.functional.discussionboard.actors.members.post(connection, {
    body: { joined_at: now, status: "active" },
  });
  typia.assert(uploader);
  const participant = await api.functional.discussionboard.actors.members.post(connection, {
    body: { joined_at: now, status: "active" },
  });
  typia.assert(participant);
  const outsider = await api.functional.discussionboard.actors.members.post(connection, {
    body: { joined_at: now, status: "active" },
  });
  typia.assert(outsider);

  // 2. Uploader creates a thread and initial post.
  const boardId = typia.random<string & tags.Format<"uuid">>();
  const thread = await api.functional.discussionboard.threads.threads.post(connection, {
    body: {
      discussionboard_board_id: boardId,
      discussionboard_member_id: uploader.id,
      title: "Test Thread Title",
      description: "E2E Test Thread for attachments",
      status: "open",
      created_at: now,
    },
  });
  typia.assert(thread);
  const post = await api.functional.discussionboard.threads.posts.post(connection, {
    body: {
      discussionboard_thread_id: thread.id,
      discussionboard_member_id: uploader.id,
      body: "Initial E2E post body",
      created_at: now,
    },
  });
  typia.assert(post);

  // 3. Uploader uploads an attachment on post
  const attachment = await api.functional.discussionboard.threads.postAttachments.post(connection, {
    body: {
      discussionboard_post_id: post.id,
      file_uri: "https://cdn.example.com/e2e-file.jpg",
      file_name: "e2e-file.jpg",
      file_type: "image/jpeg",
      uploaded_by: uploader.id,
    },
  });
  typia.assert(attachment);

  // 4. Uploader fetches attachment by ID
  let output = await api.functional.discussionboard.threads.postAttachments.getById(connection, {
    id: attachment.id
  });
  typia.assert(output);
  TestValidator.equals("file name matches")(output.file_name)("e2e-file.jpg");
  TestValidator.equals("file type matches")(output.file_type)("image/jpeg");
  TestValidator.equals("uploader ID matches")(output.uploaded_by)(uploader.id);

  // 5. Thread participant creates a new post in the thread
  const participantPost = await api.functional.discussionboard.threads.posts.post(connection, {
    body: {
      discussionboard_thread_id: thread.id,
      discussionboard_member_id: participant.id,
      body: "Participant joins thread",
      created_at: now,
    },
  });
  typia.assert(participantPost);

  // 6. Participant fetches attachment by ID (should succeed)
  output = await api.functional.discussionboard.threads.postAttachments.getById(connection, {
    id: attachment.id,
  });
  typia.assert(output);
  TestValidator.equals("file name matches - participant")(output.file_name)("e2e-file.jpg");

  // 7. Outsider fetches attachment by ID (should fail permission)
  await TestValidator.error("outsider access is forbidden")(
    async () => {
      await api.functional.discussionboard.threads.postAttachments.getById(connection, {
        id: attachment.id,
      });
    }
  );

  // 8. Query a random, non-existent attachment ID
  await TestValidator.error("non-existent attachment not found")(
    async () => {
      await api.functional.discussionboard.threads.postAttachments.getById(connection, {
        id: typia.random<string & tags.Format<"uuid">>(),
      });
    }
  );
}

