 * 4. Retrieve the created post by its ID using GET /discussionboard/threads/posts/{id}.
 * 5. Confirm that the retrieved post data matches the original post: author, thread, content, created/updated timestamps, and no accidental field mutation.
 *
 * Steps:
 * 1. Register a minimal member (joined_at, status)
 * 2. Create a thread (link to board, link to the created member, provide a random title, description, status, and created_at)
 * 3. Create a post (link to thread, link to the created member, random body, created_at)
 * 4. Retrieve post detail by ID
 * 5. Assert post detail matches the created data, including author, thread linkage, content, and created_at/updated_at
 */
export async function test_api_discussionboard_test_get_post_detail_success_with_valid_id(
  connection: api.IConnection,
) {
  // 1. Register a new member
  const memberInput: IDiscussionboardMembers.ICreate = {
    joined_at: new Date().toISOString(),
    status: "active",
  };
  const member = await api.functional.discussionboard.actors.members.post(connection, { body: memberInput });
  typia.assert(member);

  // 2. Create a new thread linked to this member and a random board
  const threadInput: IDiscussionboardThreads.ICreate = {
    discussionboard_board_id: typia.random<string & tags.Format<"uuid">>(),
    discussionboard_member_id: member.id,
    title: RandomGenerator.paragraph()(),
    description: RandomGenerator.content()()(),
    status: "open",
    created_at: new Date().toISOString(),
  };
  const thread = await api.functional.discussionboard.threads.threads.post(connection, { body: threadInput });
  typia.assert(thread);

  // 3. Create a new post within this thread
  const postInput: IDiscussionboardPosts.ICreate = {
    discussionboard_thread_id: thread.id,
    discussionboard_member_id: member.id,
    body: RandomGenerator.paragraph()(),
    created_at: new Date().toISOString(),
  };
  const post = await api.functional.discussionboard.threads.posts.post(connection, { body: postInput });
  typia.assert(post);

  // 4. Retrieve the post by its ID
  const fetched = await api.functional.discussionboard.threads.posts.getById(connection, { id: post.id });
  typia.assert(fetched);

  // 5. Assert equivalence for critical fields
  TestValidator.equals("post.id matches")(fetched.id)(post.id);
  TestValidator.equals("discussionboard_thread_id matches")(fetched.discussionboard_thread_id)(thread.id);
  TestValidator.equals("discussionboard_member_id matches")(fetched.discussionboard_member_id)(member.id);
  TestValidator.equals("body matches")(fetched.body)(postInput.body);
  TestValidator.equals("created_at matches")(fetched.created_at)(postInput.created_at);
  TestValidator.equals("updated_at matches")(fetched.updated_at)(post.updated_at);
  // Optional: deleted_at should be null/undefined
  TestValidator.predicate("deleted_at is null or undefined")(fetched.deleted_at == null);
}

