import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMembers } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMembers";
import type { DiscussionBoardAdmins } from "@ORGANIZATION/PROJECT-api/lib/structures/DiscussionBoardAdmins";
import type { IDiscussionboardModerationLog } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardModerationLog";

/**
 * Validate privileges and error handling when retrieving a specific moderation log entry by ID.
 *
 * This test verifies proper permission enforcement, error returns, and audit data accuracy.
 * It covers all major edge cases, from success as admin to expected denials for unauthorized or unauthenticated reads and missing resources.
 *
 * Steps:
 * 1. Register a new discussion board member (to be promoted).
 * 2. Promote the member to admin, making them eligible for privileged moderation log read.
 * 3. As admin, create a moderation log entry (e.g., action_type='suspend_user').
 * 4. Fetch the created moderation log entry by ID as the admin. Assert the returned object matches what was written.
 * 5. As admin, attempt to fetch a non-existent moderation log ID (random UUID). Assert a 404 not found error.
 * 6. As a regular member (not admin), attempt to fetch the valid moderation log entry by ID and assert 403 forbidden error.
 * 7. As an unauthenticated client, attempt to fetch the valid moderation log entry by ID and assert 403 forbidden error.
 */
export async function test_api_discussionboard_test_get_moderation_log_detail_valid_and_invalid_id(connection: api.IConnection) {
  // 1. Register new member
  const member = await api.functional.discussionboard.actors.members.post(connection, {
    body: {
      joined_at: new Date().toISOString(),
      status: 'active',
    },
  });
  typia.assert(member);

  // 2. Promote member to admin
  const admin = await api.functional.discussionboard.actors.admins.post(connection, {
    body: {
      discussionboard_member_id: member.id,
      elevated_at: new Date().toISOString(),
    },
  });
  typia.assert(admin);

  // 3. As admin, create a moderation log entry
  const log = await api.functional.discussionboard.moderation.moderationLogs.post(connection, {
    body: {
      moderator_id: member.id,
      action_type: 'suspend_user',
      target_member_id: null,
      target_post_id: null,
      target_comment_id: null,
      action_details: 'User suspended for violating guidelines',
    },
  });
  typia.assert(log);

  // 4. Fetch the moderation log by ID as admin
  const fetched = await api.functional.discussionboard.moderation.moderationLogs.getById(connection, {
    id: log.id,
  });
  typia.assert(fetched);
  TestValidator.equals('moderation log id matches')(fetched.id)(log.id);

  // 5. Fetch a non-existent moderation log (should return 404)
  await TestValidator.error('404 when fetching nonexistent moderation log')(async () => {
    await api.functional.discussionboard.moderation.moderationLogs.getById(connection, {
      id: typia.random<string & tags.Format<'uuid'>>(),
    });
  });

  // 6. As regular member, fetch the valid log (403 expected)
  // Re-register as a fresh member
  const regularMember = await api.functional.discussionboard.actors.members.post(connection, {
    body: {
      joined_at: new Date().toISOString(),
      status: 'active',
    }
  });
  typia.assert(regularMember);
  await TestValidator.error('403 for regular member fetching moderation log')(async () => {
    await api.functional.discussionboard.moderation.moderationLogs.getById(connection, {
      id: log.id,
    });
  });

  // 7. As unauthenticated, fetch the valid log (403 expected)
  // Simulate unauthenticated by stripping auth headers
  const unauthConnection = {
    ...connection,
    headers: {
      ...connection.headers,
      Authorization: undefined,
    },
  };
  await TestValidator.error('403 for unauthenticated fetch moderation log')(async () => {
    await api.functional.discussionboard.moderation.moderationLogs.getById(unauthConnection, {
      id: log.id,
    });
  });
}

