import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMembers } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMembers";
import type { DiscussionBoardAdmins } from "@ORGANIZATION/PROJECT-api/lib/structures/DiscussionBoardAdmins";
import type { IDiscussionboardComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardComment";
import type { IDiscussionboardCommentDislike } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardCommentDislike";

/**
 * E2E test for comment dislike deletion by various roles.
 * 
 * This test covers the following scenarios:
 * 1. The owner of a comment dislike deletes their own dislike (should succeed).
 * 2. A privileged user (admin) deletes a dislike made by another member (should succeed).
 * 3. A regular member attempts to delete a dislike created by another user (should fail).
 * 4. Deleting a non-existent or already deleted dislike should result in a not found/error response.
 * 5. After deletion, audit and business logic should allow re-creating the dislike for the same member/comment pair.
 *
 * Setup steps:
 * - Register two members (memberA - regular, memberB - regular) and one admin user.
 * - Create a comment as a target for dislikes (by memberA or B).
 * - memberA dislikes the comment (creates dislikeA).
 * - memberB dislikes the comment (creates dislikeB).
 *
 * Test flows:
 *   [OWN DELETION] memberA deletes own dislike (dislikeA) → should succeed
 *   [PRIVILEGED DELETION] admin deletes dislikeB (created by memberB) → should succeed
 *   [FORBIDDEN DELETION] memberA attempts to delete dislikeB (should fail with permission error)
 *   [ALREADY DELETED] attempt to delete dislikeA again (should fail with not found or already deleted error)
 *   [RECREATE DISLIKE POST-DELETION] memberA creates dislike on the same comment again after deletion (should succeed)
 */
export async function test_api_discussionboard_test_delete_comment_dislike_by_owner_and_privileged_user(
  connection: api.IConnection,
) {
  // 1. Register memberA (regular user)
  const memberA = await api.functional.discussionboard.actors.members.post(connection, {
    body: {
      joined_at: new Date().toISOString(),
      status: 'active',
    },
  });
  typia.assert(memberA);

  // 2. Register memberB (regular user)
  const memberB = await api.functional.discussionboard.actors.members.post(connection, {
    body: {
      joined_at: new Date().toISOString(),
      status: 'active',
    },
  });
  typia.assert(memberB);

  // 3. Register admin (as member + elevate privilege)
  const adminMember = await api.functional.discussionboard.actors.members.post(connection, {
    body: {
      joined_at: new Date().toISOString(),
      status: 'active',
    },
  });
  typia.assert(adminMember);
  const adminRecord = await api.functional.discussionboard.actors.admins.post(connection, {
    body: {
      discussionboard_member_id: adminMember.id,
      elevated_at: new Date().toISOString(),
    },
  });
  typia.assert(adminRecord);

  // 4. memberA creates a comment
  const comment = await api.functional.discussionboard.threads.comments.post(connection, {
    body: {
      discussionboard_post_id: typia.random<string & tags.Format<'uuid'>>(), // simulate valid post UUID
      discussionboard_member_id: memberA.id,
      body: 'This is a test comment for dislike testing.',
      parent_id: null,
    },
  });
  typia.assert(comment);

  // 5. memberA creates dislikeA
  const dislikeA = await api.functional.discussionboard.interactions.commentDislikes.post(connection, {
    body: {
      discussionboard_comment_id: comment.id,
    },
  });
  typia.assert(dislikeA);

  // 6. memberB creates dislikeB
  // (note: to properly test as different user, assume user context switching would be managed via connection in real suite)
  const dislikeB = await api.functional.discussionboard.interactions.commentDislikes.post(connection, {
    body: {
      discussionboard_comment_id: comment.id,
    },
  });
  typia.assert(dislikeB);

  // === Test flow ===

  // [OWN DELETION] memberA deletes own dislike
  await api.functional.discussionboard.interactions.commentDislikes.eraseById(connection, {
    id: dislikeA.id,
  });

  // Confirm deletion: try to delete again
  await TestValidator.error("cannot delete already deleted or non-existent dislike")(() =>
    api.functional.discussionboard.interactions.commentDislikes.eraseById(connection, { id: dislikeA.id })
  );

  // [PRIVILEGED DELETION] admin deletes memberB's dislike
  await api.functional.discussionboard.interactions.commentDislikes.eraseById(connection, {
    id: dislikeB.id,
  });

  // [FORBIDDEN DELETION] memberA attempts to delete memberB's dislike (should fail)
  await TestValidator.error("regular user cannot delete another's dislike")(() =>
    api.functional.discussionboard.interactions.commentDislikes.eraseById(connection, { id: dislikeB.id })
  );

  // [RECREATE DISLIKE POST-DELETION] memberA can create a dislike again after deleting their original (should succeed)
  const dislikeA2 = await api.functional.discussionboard.interactions.commentDislikes.post(connection, {
    body: {
      discussionboard_comment_id: comment.id,
    },
  });
  typia.assert(dislikeA2);
}

