import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMembers } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMembers";
import type { IDiscussionboardPosts } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardPosts";
import type { IDiscussionboardComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardComment";
import type { IDiscussionboardReport } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardReport";

/**
 * 종합적인 신고 시스템 테스트: 포스트와 댓글 대상, 유효성, 비즈니스 규칙, 권한 제약까지 모두 검증
 * 
 * 이 테스트는 다음을 종합적으로 검증한다:
 * - (1) 일반 회원이 포스트/댓글 모두 정상적으로 신고 가능한지(필수값 포함)
 * - (2) 존재하지 않는 대상/누락값에 대해 오류가 나는지
 * - (3) 하루 신고 개수 제한(10회) 초과시 거부되는지
 * - (4) 비회원 및 정지/비활성화 회원이 신고 시도하면 실패하는지
 *
 * 절차:
 * 1. 정상적인 회원 계정 생성
 * 2. 포스트 생성(신고 대상)
 * 3. 댓글 생성(신고 대상)
 * 4. 회원이 포스트에 대해 신고 - 성공 및 반환값 검증
 * 5. 회원이 댓글에 대해 신고 - 성공 및 반환값 검증
 * 6. (에지) 존재하지 않는 포스트ID와 댓글ID로 신고 시도 - 오류 검증
 * 7. (에지) 필수값 누락 시도 - 오류 검증: reason 없음/대상ID 없음
 * 8. (비즈니스 제약) 동일 회원이 10회 신고 - 모두 성공, 11회째는 오류
 * 9. (권한제약) 회원을 suspended로 변경 → 신고 시 오류
 * 10. (권한제약) 비회원(미등록)에서 신고 시도 → 오류
 */
export async function test_api_discussionboard_test_create_moderation_report_for_post_and_comment_and_validate_constraints(
  connection: api.IConnection,
) {
  // 1. 정상 회원 생성
  const member: IDiscussionboardMembers = await api.functional.discussionboard.actors.members.post(connection, {
    body: {
      joined_at: new Date().toISOString(),
      status: "active",
    } satisfies IDiscussionboardMembers.ICreate,
  });
  typia.assert(member);

  // 2. 포스트 생성 (신고 대상)
  const post: IDiscussionboardPosts = await api.functional.discussionboard.threads.posts.post(connection, {
    body: {
      discussionboard_thread_id: typia.random<string & tags.Format<"uuid">>(),
      discussionboard_member_id: member.id,
      body: "신고 대상 포스트 내용",
      created_at: new Date().toISOString(),
    } satisfies IDiscussionboardPosts.ICreate,
  });
  typia.assert(post);

  // 3. 댓글 생성 (신고 대상)
  const comment: IDiscussionboardComment = await api.functional.discussionboard.threads.comments.post(connection, {
    body: {
      discussionboard_post_id: post.id,
      discussionboard_member_id: member.id,
      body: "신고 대상 댓글 내용",
    } satisfies IDiscussionboardComment.ICreate,
  });
  typia.assert(comment);

  // 4. 포스트 신고(정상)
  const postReport: IDiscussionboardReport = await api.functional.discussionboard.moderation.reports.post(connection, {
    body: {
      reported_by_member_id: member.id,
      target_post_id: post.id,
      reason: "스팸 신고",
    } satisfies IDiscussionboardReport.ICreate,
  });
  typia.assert(postReport);
  TestValidator.equals("포스트 신고 대조")(postReport.target_post_id)(post.id);
  TestValidator.equals("신고자 대조")(postReport.reported_by_member_id)(member.id);

  // 5. 댓글 신고(정상)
  const commentReport: IDiscussionboardReport = await api.functional.discussionboard.moderation.reports.post(connection, {
    body: {
      reported_by_member_id: member.id,
      target_comment_id: comment.id,
      reason: "규정 위반",
    } satisfies IDiscussionboardReport.ICreate,
  });
  typia.assert(commentReport);
  TestValidator.equals("댓글 신고 대조")(commentReport.target_comment_id)(comment.id);

  // 6. 존재하지 않는 포스트/댓글 ID 신고(오류)
  await TestValidator.error("존재하지 않는 포스트 신고오류")(() =>
    api.functional.discussionboard.moderation.reports.post(connection, {
      body: {
        reported_by_member_id: member.id,
        target_post_id: typia.random<string & tags.Format<"uuid">>(),
        reason: "잘못된 포스트ID",
      } satisfies IDiscussionboardReport.ICreate,
    })
  );
  await TestValidator.error("존재하지 않는 댓글 신고오류")(() =>
    api.functional.discussionboard.moderation.reports.post(connection, {
      body: {
        reported_by_member_id: member.id,
        target_comment_id: typia.random<string & tags.Format<"uuid">>(),
        reason: "잘못된 댓글ID",
      } satisfies IDiscussionboardReport.ICreate,
    })
  );

  // 7. 필수값 누락 (reason 없음)
  await TestValidator.error("이유 누락시 실패")(() =>
    api.functional.discussionboard.moderation.reports.post(connection, {
      body: {
        reported_by_member_id: member.id,
        target_post_id: post.id
        // reason 누락 (타입오류라 실제로는 아예 패스할 수 없음)
      } as any,
    })
  );
  // 7-2. 대상 ID 없음 (포스트/댓글 없음)
  await TestValidator.error("대상ID 미입력시 실패")(() =>
    api.functional.discussionboard.moderation.reports.post(connection, {
      body: {
        reported_by_member_id: member.id,
        reason: "대상ID 없음"
        // target_post_id, target_comment_id 없음
      } as any,
    })
  );

  // 8. 일일 신고 한도 초과 (10회 성공, 11회째 실패)
  for (let i = 0; i < 10; ++i) {
    const report: IDiscussionboardReport = await api.functional.discussionboard.moderation.reports.post(connection, {
      body: {
        reported_by_member_id: member.id,
        target_post_id: post.id,
        reason: `중복 신고 ${i+1}`,
      } satisfies IDiscussionboardReport.ICreate,
    });
    typia.assert(report);
  }
  await TestValidator.error("11회째 신고 차단")(() =>
    api.functional.discussionboard.moderation.reports.post(connection, {
      body: {
        reported_by_member_id: member.id,
        target_post_id: post.id,
        reason: "11번째 신고",
      } satisfies IDiscussionboardReport.ICreate,
    })
  );

  // 9. 회원 정지 상태에서 신고 금지
  const suspended: IDiscussionboardMembers = await api.functional.discussionboard.actors.members.putById(connection, {
    id: member.id,
    body: { status: "suspended" } satisfies IDiscussionboardMembers.IUpdate,
  });
  typia.assert(suspended);
  await TestValidator.error("정지회원 신고 차단")(() =>
    api.functional.discussionboard.moderation.reports.post(connection, {
      body: {
        reported_by_member_id: member.id,
        target_post_id: post.id,
        reason: "정지 중 신고",
      } satisfies IDiscussionboardReport.ICreate,
    })
  );

  // 10. 비회원(없는ID) 신고 금지
  await TestValidator.error("비회원 신고 차단")(() =>
    api.functional.discussionboard.moderation.reports.post(connection, {
      body: {
        reported_by_member_id: typia.random<string & tags.Format<"uuid">>(),
        target_post_id: post.id,
        reason: "비회원 신고",
      } satisfies IDiscussionboardReport.ICreate,
    })
  );
}

