/**
 * Test listing of suspension records with multiple filters and pagination.
 *
 * This E2E test covers the business rules and technical validation for the API endpoint allowing retrieval of suspension records with filter and pagination support.
 *
 * Test steps:
 * 1. Register two regular members: one to be suspended (target) and one with no suspensions for negative filter testing.
 * 2. Register a moderator (simply as a member in this test context).
 * 3. As moderator/admin, create several suspension records:
 *    - One active (ongoing, not revoked, end date in future)
 *    - One revoked (revoked attribute true, revoked_at populated)
 *    - One expired (end_at in the past, revoked false)
 * 4. As moderator/admin, call the suspensionRecords PATCH endpoint with various filters:
 *    a. Filter by suspended_member_id and confirm only the records for that user are returned.
 *    b. Filter by issued_by_moderator_id and confirm only records issued by that moderator are returned.
 *    c. Filter by revoked true/false and check result contents and attributes.
 *    d. Filter by active/expired (simulate by using timeframe filters: start_after, end_before) and assert logic.
 *    e. Use pagination: limit=1, page=2, verify meta and returned results.
 *    f. Check audit fields (created_at, revoked_at, etc) present.
 * 5. Attempt listing as a regular member (not moderator/admin) and assert access is denied.
 * 6. Attempt malformed filter (e.g., bad date in filter) and expect error.
 */
export async function test_api_discussionboard_test_list_suspension_records_with_multiple_filters_and_pagination(connection: api.IConnection) {
  // Step 1: Create regular members
  const memberToSuspend = await api.functional.discussionboard.actors.members.post(connection, {
    body: {
      joined_at: new Date().toISOString(),
      status: 'active',
    },
  });
  typia.assert(memberToSuspend);
  const unrelatedMember = await api.functional.discussionboard.actors.members.post(connection, {
    body: {
      joined_at: new Date().toISOString(),
      status: 'active',
    },
  });
  typia.assert(unrelatedMember);

  // Step 2: Register a moderator (works as a member here)
  const moderator = await api.functional.discussionboard.actors.members.post(connection, {
    body: {
      joined_at: new Date().toISOString(),
      status: 'active',
    },
  });
  typia.assert(moderator);

  // Step 3: As moderator, create suspension records of all status types
  // Active
  const activeSuspension = await api.functional.discussionboard.moderation.suspensionRecords.post(connection, {
    body: {
      suspended_member_id: memberToSuspend.id,
      issued_by_moderator_id: moderator.id,
      start_at: new Date(Date.now() - 1000 * 60 * 60).toISOString(),
      end_at: new Date(Date.now() + 1000 * 60 * 60).toISOString(),
      reason: 'Ongoing inappropriate behavior',
    },
  });
  typia.assert(activeSuspension);
  // Revoked
  const revokedSuspension = await api.functional.discussionboard.moderation.suspensionRecords.post(connection, {
    body: {
      suspended_member_id: memberToSuspend.id,
      issued_by_moderator_id: moderator.id,
      start_at: new Date(Date.now() - 1000 * 60 * 120).toISOString(),
      end_at: new Date(Date.now() + 1000 * 60 * 60).toISOString(),
      reason: 'Later revoked',
    },
  });
  typia.assert(revokedSuspension);
  // Simulate revocation: Manually update revoked attribute if possible, else rely on mocked API's revoked_at field population (for now just proceed)
  // Expired
  const expiredSuspension = await api.functional.discussionboard.moderation.suspensionRecords.post(connection, {
    body: {
      suspended_member_id: memberToSuspend.id,
      issued_by_moderator_id: moderator.id,
      start_at: new Date(Date.now() - 1000 * 60 * 240).toISOString(),
      end_at: new Date(Date.now() - 1000 * 60 * 60).toISOString(),
      reason: 'Expired now',
    },
  });
  typia.assert(expiredSuspension);

  // Step 4a: Filter by suspended_member_id
  const listByMember = await api.functional.discussionboard.moderation.suspensionRecords.patch(connection, {
    body: {
      suspended_member_id: memberToSuspend.id,
      page: 1,
      limit: 10,
    },
  });
  typia.assert(listByMember);
  TestValidator.predicate('Should only contain records for the specified member')(
    listByMember.data.every(rec => rec.suspended_member_id === memberToSuspend.id)
  );

  // Step 4b: Filter by unrelated member should be empty
  const listByUnrelated = await api.functional.discussionboard.moderation.suspensionRecords.patch(connection, {
    body: {
      suspended_member_id: unrelatedMember.id,
      page: 1,
      limit: 10,
    },
  });
  typia.assert(listByUnrelated);
  TestValidator.equals('Should be empty for unrelated member')(listByUnrelated.data.length)(0);

  // Step 4c: Filter by moderator
  const listByModerator = await api.functional.discussionboard.moderation.suspensionRecords.patch(connection, {
    body: {
      issued_by_moderator_id: moderator.id,
      page: 1,
      limit: 10,
    },
  });
  typia.assert(listByModerator);
  TestValidator.predicate('All records issued by the moderator')(listByModerator.data.every(rec => rec.issued_by_moderator_id === moderator.id));

  // Step 4d: Revoked filter
  const listRevoked = await api.functional.discussionboard.moderation.suspensionRecords.patch(connection, {
    body: {
      revoked: true,
    },
  });
  typia.assert(listRevoked);
  TestValidator.predicate('All revoked records')(listRevoked.data.every(rec => rec.revoked));

  // Step 4e: Active filter (end in future, revoked false) by end_before (simulate)
  const now = new Date().toISOString();
  const listActive = await api.functional.discussionboard.moderation.suspensionRecords.patch(connection, {
    body: {
      // No revoked, and end in future
      revoked: false,
      end_before: new Date(Date.now() + 1000 * 60 * 61).toISOString(),
    },
  });
  typia.assert(listActive);
  TestValidator.predicate('Active record(s) present')(listActive.data.some(rec => !rec.revoked && (!rec.end_at || rec.end_at > now)));

  // Step 4f: Pagination test limit=1, page=2
  const paged = await api.functional.discussionboard.moderation.suspensionRecords.patch(connection, {
    body: {
      page: 2,
      limit: 1,
    },
  });
  typia.assert(paged);
  TestValidator.equals('Page number')(paged.pagination.current)(2);
  TestValidator.equals('Limit')(paged.pagination.limit)(1);
  TestValidator.predicate('Data length matches limit or records available')(paged.data.length <= 1);

  // Step 4g: Check audit trail fields are present
  TestValidator.predicate('Audit fields - created_at present')(paged.data.every(rec => typeof rec.created_at === 'string'));
  TestValidator.predicate('Audit fields - id present')(paged.data.every(rec => typeof rec.id === 'string'));

  // Step 5: Try as "unauthorized" member (simulate privilege drop)
  // (See note: if access tokens or role logic were exposed, you would simulate new connection with "member" role)
  // For now, expect error when listing with a new normal member connection
  TestValidator.error('Regular members should be denied access')(async () => {
    await api.functional.discussionboard.moderation.suspensionRecords.patch(connection, {
      body: {}, // minimal request
    });
  });

  // Step 6: Malformed filter (bad date format)
  TestValidator.error('Bad date/time rejects')(async () => {
    await api.functional.discussionboard.moderation.suspensionRecords.patch(connection, {
      body: {
        start_after: 'not-a-date',
      },
    });
  });
}

