event.draft:
import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMembers } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMembers";
import type { IDiscussionboardComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardComment";
import type { IDiscussionboardCommentReport } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardCommentReport";
import type { IPageDiscussionboardCommentReport } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageDiscussionboardCommentReport";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Test listing and searching comment reports as a moderator/admin using multiple filtering criteria, pagination, and sorting.
 *
 * Scenario includes:
 * - Filtering by reported comment ID, reporter member ID, reason
 * - Pagination (page number, limit)
 * - Edge cases: empty results, max limit, invalid values
 * - Verifying accurate filtering, correct pagination metadata, permissions enforcement
 * - Unauthorized user should be restricted
 *
 * Steps:
 * 1. Create two board members (reporter and another member)
 * 2. Reporter member creates a post and a comment (no /thread/posts API, so simulate minimal with post_id as uuid)
 * 3. Another member creates a comment on same post
 * 4. Submit several reports (different reasons, reporter/member ids)
 * 5. As admin (assume default test connection is admin), test listing without filters returns all
 * 6. Filter by comment id, reporter id, reason; check returned count, all fields match filters
 * 7. Paginate (page/limit), verify metadata matches
 * 8. Edge: No results (non-existent filter)
 * 9. Edge: Very large limit (e.g. 100)
 * 10. Edge: Invalid filter values (invalid uuids)
 * 11. (Permission) Call as non-admin/user should error
 */
export async function test_api_discussionboard_test_list_comment_reports_with_various_filters(connection: api.IConnection) {
  // --- Setup test data: members, comments, reports ---
  // 1. Create reporter member
  const reporter: IDiscussionboardMembers = await api.functional.discussionboard.actors.members.post(connection, {
    body: {
      joined_at: new Date().toISOString(),
      status: 'active',
    },
  });
  typia.assert(reporter);
  // 2. Create target post as random uuid (simulate, since only comment creation supported)
  const post_id = typia.random<string & tags.Format<'uuid'>>();
  // 3. Reporter leaves a comment (to be reported)
  const comment: IDiscussionboardComment = await api.functional.discussionboard.threads.comments.post(connection, {
    body: {
      discussionboard_post_id: post_id,
      discussionboard_member_id: reporter.id,
      body: 'Offending comment',
    },
  });
  typia.assert(comment);
  // 4. Non-reporter member
  const nonreporter: IDiscussionboardMembers = await api.functional.discussionboard.actors.members.post(connection, {
    body: {
      joined_at: new Date().toISOString(),
      status: 'active',
    },
  });
  typia.assert(nonreporter);
  // 5. Another comment
  const nonreported_comment: IDiscussionboardComment = await api.functional.discussionboard.threads.comments.post(connection, {
    body: {
      discussionboard_post_id: post_id,
      discussionboard_member_id: nonreporter.id,
      body: "Harmless reply"
    },
  });
  typia.assert(nonreported_comment);
  // 6. Create multiple reports for the comment (with different reasons, members)
  const reason1 = "Spam";
  const reason2 = "Abuse";
  const report1: IDiscussionboardCommentReport = await api.functional.discussionboard.interactions.commentReports.post(connection, {
    body: {
      discussionboard_comment_id: comment.id,
      reason: reason1
    },
  });
  typia.assert(report1);
  const report2: IDiscussionboardCommentReport = await api.functional.discussionboard.interactions.commentReports.post(connection, {
    body: {
      discussionboard_comment_id: comment.id,
      reason: reason2
    },
  });
  typia.assert(report2);
  // Also create a report for non-offending comment
  const report3: IDiscussionboardCommentReport = await api.functional.discussionboard.interactions.commentReports.post(connection, {
    body: {
      discussionboard_comment_id: nonreported_comment.id,
      reason: "Other"
    },
  });
  typia.assert(report3);
  // --- 1. List all reports (admin role, no filters) ---
  const allReports = await api.functional.discussionboard.interactions.commentReports.patch(connection, { body: {} });
  typia.assert(allReports);
  TestValidator.predicate("empty result returns at least 3 reports")(
    allReports.data.length >= 3
  );
  // 2. Filter by discussionboard_comment_id (should match only reports for 'comment')
  const filterByComment = await api.functional.discussionboard.interactions.commentReports.patch(connection, {
    body: { discussionboard_comment_id: comment.id },
  });
  typia.assert(filterByComment);
  TestValidator.predicate("only filtered comment")(
    filterByComment.data.every((r) => r.discussionboard_comment_id === comment.id)
  );
  // 3. Filter by reporter id (simulate: always admin in test, but check with at least one real member id)
  const filterByReporter = await api.functional.discussionboard.interactions.commentReports.patch(connection, {
    body: { discussionboard_member_id: reporter.id },
  });
  typia.assert(filterByReporter);
  TestValidator.predicate("reporter id match")(
    filterByReporter.data.every((r) => r.discussionboard_member_id === reporter.id)
  );
  // 4. Filter by reason
  const filterByReason = await api.functional.discussionboard.interactions.commentReports.patch(connection, {
    body: { reason: reason1 },
  });
  typia.assert(filterByReason);
  TestValidator.predicate("reason matches")(
    filterByReason.data.every((r) => r.reason === reason1)
  );
  // 5. Paginate: limit 1
  const paginated = await api.functional.discussionboard.interactions.commentReports.patch(connection, {
    body: { limit: 1 },
  });
  typia.assert(paginated);
  TestValidator.equals("one result returned")(paginated.data.length)(1);
  TestValidator.equals("pagination.limit")(paginated.pagination.limit)(1);
  // 6. Paginate: limit 100 (max allowed or large batch)
