    body: {
      status: 'open',
    },
  });
  typia.assert(listByStatus);
  listByStatus.data.forEach((thread) => TestValidator.equals('status=open')(thread.status)('open'));

  // 6. (case 3) 제목 내 특정 단어로 검색
  const keyword = '테스트 스레드_open_';
  const listByFilter = await api.functional.discussionboard.threads.threads.patch(connection, {
    body: {
      filter: keyword,
    },
  });
  typia.assert(listByFilter);
  listByFilter.data.forEach((thread) => TestValidator.predicate('제목 키워드')(thread.title.includes('open')));

  // 7. (case 4) pagination: limit, page
  const paged = await api.functional.discussionboard.threads.threads.patch(connection, {
    body: {
      limit: 3,
      page: 2,
    },
  });
  typia.assert(paged);
  TestValidator.equals('2번째 페이지')(paged.pagination.current)(2);
  TestValidator.equals('페이지 사이즈')(paged.data.length <= 3)(true);

  // 8. (case 5) no-matching: filter, board, status 등으로 빈 결과 반환
  const empty = await api.functional.discussionboard.threads.threads.patch(connection, {
    body: {
      status: 'locked',
      discussionboard_board_id: board1.id,
      filter: 'not_exist_keyword',
    },
  });
  typia.assert(empty);
  TestValidator.equals('empty data')(empty.data.length)(0);

  // 9. (case 6) thread soft-delete 후 미포함 여부
  const deletedThread = threads[0];
  await api.functional.discussionboard.threads.threads.eraseById(connection, {
    id: deletedThread.id,
  });
  const listAfterDelete = await api.functional.discussionboard.threads.threads.patch(connection, {
    body: {
      discussionboard_board_id: deletedThread.discussionboard_board_id,
    },
  });
  typia.assert(listAfterDelete);
  TestValidator.notEquals('삭제된 thread 미포함')(listAfterDelete.data.find((th) => th.id === deletedThread.id))(deletedThread);

  // 10. 인증이 없는 경우/권한이 부족한 경우 (인증 API 미제공으로 생략)
}

