import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMembers } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMembers";
import type { IDiscussionboardComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardComment";
import type { IDiscussionboardCommentReport } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardCommentReport";

/**
 * Test the creation of comment reports via POST /discussionboard/interactions/commentReports, covering:
 *   - Valid report creation by a regular member
 *   - Failures: exceeding daily quota (over 10 reports), missing required fields, 
 *     reporting non-existent or deleted comment, attempts by non-active/suspended members,
 *     and duplicate same-day report on same comment
 *   - Output verification for correctness of returned entity
 * Steps:
 * 1. Create a member (reporter)
 * 2. Create a comment for reporting
 * 3. (SUCCESS) Reporter submits a valid report
 *     - Check: response contains correct reporter, comment, and timestamp
 * 4. (FAIL) Attempt report with missing reason
 * 5. (FAIL) Attempt report with missing comment ID
 * 6. (FAIL) Attempt report for a random non-existent comment ID
 * 7. (FAIL) Attempt report for (soft-)deleted comment
 * 8. (FAIL) Exceed daily report quota: submit 10 reports, then one more -- last must fail
 * 9. (FAIL) Suspended or non-active member attempts report (must fail)
 * 10. (FAIL) Duplicate report on same comment by same member, same day
 */
export async function test_api_discussionboard_test_create_comment_report_with_valid_and_invalid_input(connection: api.IConnection) {
  // 1. Create a member (reporter)
  const member = await api.functional.discussionboard.actors.members.post(connection, {
    body: {
      joined_at: new Date().toISOString(),
      status: "active",
    }
  });
  typia.assert(member);

  // 2. Create a comment for reporting
  const comment = await api.functional.discussionboard.threads.comments.post(connection, {
    body: {
      discussionboard_post_id: typia.random<string & tags.Format<"uuid">>(),
      discussionboard_member_id: member.id,
      body: "Test comment for reporting."
    }
  });
  typia.assert(comment);

  // 3. Success – Report comment
  const reason = "Spam or inappropriate content";
  const report = await api.functional.discussionboard.interactions.commentReports.post(connection, {
    body: {
      discussionboard_comment_id: comment.id,
      reason
    }
  });
  typia.assert(report);
  TestValidator.equals("reporter matches")(report.discussionboard_member_id)(member.id);
  TestValidator.equals("comment matches")(report.discussionboard_comment_id)(comment.id);
  TestValidator.predicate("created_at is present")(!!report.created_at);

  // 4. Failure – Missing reason
  await TestValidator.error("should fail: missing reason")(() =>
    api.functional.discussionboard.interactions.commentReports.post(connection, {
      body: {
        discussionboard_comment_id: comment.id
      } as any // Reason omitted intentionally for test, expect runtime/business validation error
    })
  );

  // 5. Failure – Missing comment ID
  await TestValidator.error("should fail: missing comment ID")(() =>
    api.functional.discussionboard.interactions.commentReports.post(connection, {
      body: {
        reason
      } as any // comment ID omitted intentionally, expect validation error
    })
  );

  // 6. Failure – Non-existent comment
  await TestValidator.error("should fail: report non-existent comment")(() =>
    api.functional.discussionboard.interactions.commentReports.post(connection, {
      body: {
        discussionboard_comment_id: typia.random<string & tags.Format<"uuid">>(),
        reason
      }
    })
  );

  // 7. Failure – Deleted comment (simulate by creating-deleting or using deleted_at)
  // Here, we simulate by using a deleted comment entity
  const deletedComment = {
    ...comment,
    id: typia.random<string & tags.Format<"uuid">>(),
    deleted_at: new Date().toISOString()
  };
  await TestValidator.error("should fail: report deleted comment")(() =>
    api.functional.discussionboard.interactions.commentReports.post(connection, {
      body: {
        discussionboard_comment_id: deletedComment.id,
        reason
      }
    })
  );

  // 8. Failure – Exceed daily report quota (10 allowed per day)
  const toReport = [];
  for (let i = 0; i < 10; ++i) {
    // create unique comments for each test
    const cmt = await api.functional.discussionboard.threads.comments.post(connection, {
      body: {
        discussionboard_post_id: typia.random<string & tags.Format<"uuid">>(),
        discussionboard_member_id: member.id,
        body: `Comment ${i}`
      }
    });
    typia.assert(cmt);
    toReport.push(cmt);
    const rpt = await api.functional.discussionboard.interactions.commentReports.post(connection, {
      body: {
        discussionboard_comment_id: cmt.id,
        reason: `Reason ${i}`
      }
    });
    typia.assert(rpt);
  }
  // 11th report should fail
  const extraComment = await api.functional.discussionboard.threads.comments.post(connection, {
    body: {
      discussionboard_post_id: typia.random<string & tags.Format<"uuid">>(),
      discussionboard_member_id: member.id,
      body: "11th comment"
    }
  });
  await TestValidator.error("should fail: exceed 10 reports/day")(() =>
    api.functional.discussionboard.interactions.commentReports.post(connection, {
      body: {
        discussionboard_comment_id: extraComment.id,
        reason: "Exceed quota"
      }
    })
  );

  // 9. Failure – Suspended member (change status)
  const suspended = await api.functional.discussionboard.actors.members.post(connection, {
    body: {
      joined_at: new Date().toISOString(),
      status: "suspended"
    }
  });
  typia.assert(suspended);
  const commentForSuspended = await api.functional.discussionboard.threads.comments.post(connection, {
    body: {
      discussionboard_post_id: typia.random<string & tags.Format<"uuid">>(),
      discussionboard_member_id: suspended.id,
      body: "Comment for suspended member test."
    }
  });
  typia.assert(commentForSuspended);
  await TestValidator.error("should fail: suspended member cannot report")(() =>
    api.functional.discussionboard.interactions.commentReports.post(connection, {
      body: {
        discussionboard_comment_id: commentForSuspended.id,
        reason: "Test by suspended member"
      }
    })
  );

  // 10. Failure – Duplicate report for same comment by same member, same day
  const dupeComment = await api.functional.discussionboard.threads.comments.post(connection, {
    body: {
      discussionboard_post_id: typia.random<string & tags.Format<"uuid">>(),
      discussionboard_member_id: member.id,
      body: "Comment to test duplicate report"
    }
  });
  typia.assert(dupeComment);
  const dupeReport = await api.functional.discussionboard.interactions.commentReports.post(connection, {
    body: {
      discussionboard_comment_id: dupeComment.id,
      reason: "First report"
    }
  });
  typia.assert(dupeReport);
  await TestValidator.error("should fail: duplicate report on same comment by same user")(() =>
    api.functional.discussionboard.interactions.commentReports.post(connection, {
      body: {
        discussionboard_comment_id: dupeComment.id,
        reason: "Duplicate report"
      }
    })
  );
}

