import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMembers } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMembers";
import type { DiscussionboardBoard } from "@ORGANIZATION/PROJECT-api/lib/structures/DiscussionboardBoard";
import type { DiscussionBoardBoardTopic } from "@ORGANIZATION/PROJECT-api/lib/structures/DiscussionBoardBoardTopic";

/**
 * Validate the Discussion Board topic update API's handling of uniqueness and schema violations.
 *
 * This test ensures that when updating a board topic, the system correctly rejects attempts to:
 * - Change the topic to use a code that is already in use by another topic in the same board.
 * - Change the topic title to one that already exists under the same board.
 * - Provide a blank (empty) title or invalid code (such as a code that is too long) according to business/schema validation rules.
 *
 * Steps:
 * 1. Create a Discussion Board member (for topic creation).
 * 2. Create a Board for the topics.
 * 3. Create two topics in the board (to establish existing values for uniqueness violations).
 * 4. Attempt to update topic1 using code already used by topic2 — expect failure.
 * 5. Attempt to update topic1 using title already used by topic2 — expect failure.
 * 6. Attempt to update topic1 using empty title — expect failure.
 * 7. Attempt to update topic1 with an invalid code (overly long, for example if business rule restricts).
 * 8. Each invalid update attempt should result in a validation error and not update the topic.
 */
export async function test_api_discussionboard_test_update_board_topic_with_invalid_fields(
  connection: api.IConnection,
) {
  // 1. Create a member for topic creation
  const member = await api.functional.discussionboard.actors.members.post(connection, {
    body: {
      joined_at: new Date().toISOString(),
      status: "active",
    },
  });
  typia.assert(member);

  // 2. Create a board
  const board = await api.functional.discussionboard.boards.boards.post(connection, {
    body: {
      discussionboard_category_id: typia.random<string & tags.Format<"uuid">>(),
      code: "test-board-" + RandomGenerator.alphaNumeric(8),
      name: "Test Board",
      is_active: true,
      description: "A board for testing uniqueness",
    },
  });
  typia.assert(board);

  // 3. Create two topics in that board
  const topic1 = await api.functional.discussionboard.boards.boardTopics.post(connection, {
    body: {
      discussionboard_board_id: board.id,
      code: "topic1" + RandomGenerator.alphaNumeric(4),
      title: "First Unique Title " + RandomGenerator.alphaNumeric(4),
      description: "First topic description",
      created_by_member_id: member.id,
    },
  });
  typia.assert(topic1);
  const topic2 = await api.functional.discussionboard.boards.boardTopics.post(connection, {
    body: {
      discussionboard_board_id: board.id,
      code: "topic2" + RandomGenerator.alphaNumeric(4),
      title: "Second Unique Title " + RandomGenerator.alphaNumeric(4),
      description: "Second topic description",
      created_by_member_id: member.id,
    },
  });
  typia.assert(topic2);

  // 4. Try to update topic1 to use topic2's code
  await TestValidator.error("duplicate code should fail")(() =>
    api.functional.discussionboard.boards.boardTopics.putById(connection, {
      id: topic1.id,
      body: {
        code: topic2.code,
      },
    })
  );

  // 5. Try to update topic1 to use topic2's title
  await TestValidator.error("duplicate title should fail")(() =>
    api.functional.discussionboard.boards.boardTopics.putById(connection, {
      id: topic1.id,
      body: {
        title: topic2.title,
      },
    })
  );

  // 6. Try to update topic1 with an empty title
  await TestValidator.error("empty title should fail")(() =>
    api.functional.discussionboard.boards.boardTopics.putById(connection, {
      id: topic1.id,
      body: {
        title: "",
      },
    })
  );

  // 7. Try to update topic1 with an invalid (too long) code
  await TestValidator.error("too long code should fail")(() =>
    api.functional.discussionboard.boards.boardTopics.putById(connection, {
      id: topic1.id,
      body: {
        code: RandomGenerator.alphaNumeric(256), // assume max length is less than 256
      },
    })
  );
}

