import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMembers } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMembers";
import type { IDiscussionboardSuspensionRecord } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardSuspensionRecord";

/**
 * Test updating an existing member suspension record's duration, revoked status, and reason.
 *
 * This scenario validates the DiscussionBoard suspension record update API, focusing on business rules, field correctness, and access control. Specifically:
 * - Only moderators or admins may perform updates (update as plain user or with invalid user should fail)
 * - Fields may be updated singly or in combination: end_at (shorten/extend duration), reason (correction), revoked (lift suspension), revoked_at (record when revoked)
 * - All updates must be returned in the record and reflect changes
 * - Updating with an invalid (nonexistent) ID must return a clear error
 *
 * Test flow:
 * 1. Create three members: target to suspend, moderator (as updater), and a regular member (should not be allowed to update)
 * 2. As moderator, create one suspension record for the target
 * 3. As moderator, update end_at (extend duration), verify result fields
 * 4. Update reason, verify updated reason
 * 5. Mark as revoked with revoked = true and revoked_at, check returned record
 * 6. Try updating as regular member (no privilege): should fail with error
 * 7. Try updating nonexistent suspension record (invalid id) as moderator: should fail with error
 */
export async function test_api_discussionboard_moderation_suspensionRecords_test_update_suspension_record_duration_and_revoke_status(connection: api.IConnection) {
  // 1. Create members
  const targetMember = await api.functional.discussionboard.actors.members.post(connection, {
    body: {
      joined_at: new Date().toISOString(),
      status: "active",
    },
  });
  typia.assert(targetMember);

  const moderator = await api.functional.discussionboard.actors.members.post(connection, {
    body: {
      joined_at: new Date().toISOString(),
      status: "active",
    },
  });
  typia.assert(moderator);

  const regularUser = await api.functional.discussionboard.actors.members.post(connection, {
    body: {
      joined_at: new Date().toISOString(),
      status: "active",
    },
  });
  typia.assert(regularUser);

  // 2. As moderator, create a suspension record for the target
  const created = await api.functional.discussionboard.moderation.suspensionRecords.post(connection, {
    body: {
      suspended_member_id: targetMember.id,
      issued_by_moderator_id: moderator.id,
      start_at: new Date().toISOString(),
      end_at: new Date(Date.now() + 3600 * 1000).toISOString(),
      reason: "Test suspension for E2E",
    },
  });
  typia.assert(created);

  // 3. As moderator, extend end_at (duration)
  const extended = await api.functional.discussionboard.moderation.suspensionRecords.putById(connection, {
    id: created.id,
    body: {
      end_at: new Date(Date.now() + 7200 * 1000).toISOString(),
    },
  });
  typia.assert(extended);
  TestValidator.equals("end_at extended")(extended.end_at)(new Date(Date.now() + 7200 * 1000).toISOString());
  TestValidator.equals("other fields remain")(extended.suspended_member_id)(created.suspended_member_id);

  // 4. Update reason
  const updatedReason = await api.functional.discussionboard.moderation.suspensionRecords.putById(connection, {
    id: created.id,
    body: {
      reason: "Updated reason text",
    },
  });
  typia.assert(updatedReason);
  TestValidator.equals("reason updated")(updatedReason.reason)("Updated reason text");

  // 5. Mark as revoked (revoked true + revoked_at)
  const revokedAt = new Date().toISOString();
  const revoked = await api.functional.discussionboard.moderation.suspensionRecords.putById(connection, {
    id: created.id,
    body: {
      revoked: true,
      revoked_at: revokedAt,
    },
  });
  typia.assert(revoked);
  TestValidator.equals("revoked updated")(revoked.revoked)(true);
  TestValidator.equals("revoked_at set")(revoked.revoked_at)(revokedAt);

  // 6. Try updating as a regular user: simulate by referencing another member's id as the issued_by_moderator_id (should be RBAC checked)
  try {
    await api.functional.discussionboard.moderation.suspensionRecords.putById(connection, {
      id: created.id,
      body: {
        reason: "Attempted by unauthorized user",
      },
    });
    throw new Error("Should have failed as unauthorized user");
  } catch (error) {
    if (!error || !error.message) throw error;
  }

  // 7. Try updating invalid ID as moderator
  await TestValidator.error("updating non-existent suspension should fail")(async () => {
    await api.functional.discussionboard.moderation.suspensionRecords.putById(connection, {
      id: typia.random<string & tags.Format<"uuid">>(),
      body: { reason: "Should not exist" },
    });
  });
}

