import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMembers } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMembers";
import type { IDiscussionBoardMemberSuspension } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMemberSuspension";
import type { IDiscussionboardComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardComment";
import type { IDiscussionboardCommentDislike } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardCommentDislike";

/**
 * Test successful creation of a comment dislike and enforcement of one-dislike-per-member rule.
 *
 * - Validate that an authenticated member can successfully dislike a comment.
 * - Ensure that a duplicate dislike attempt (from the same member on the same comment) is rejected (conflict/validation error).
 * - Confirm error handling for invalid comment IDs and unauthenticated requests.
 * - Suspend a member and ensure suspended/banned members are prohibited from disliking comments (should result in error).
 * - Ensure audit/log events occur for the dislike events (assume success if request completes; auditing not directly testable via API).
 *
 * Steps:
 * 1. Register Member #1 (regular, active)
 * 2. Register Member #2 (supposed to be suspended later)
 * 3. Create a valid comment as Member #1 (so both members can interact with it)
 * 4. As Member #1, successfully create a dislike on the comment
 * 5. Attempt to create a second dislike by Member #1 for the same comment (should fail: only one allowed)
 * 6. Attempt to dislike the comment as unauthenticated (simulate by clearing connection headers)
 * 7. Suspend Member #2
 * 8. As Member #2, try to dislike the same comment (should fail due to suspension)
 * 9. Attempt to dislike a non-existent comment (should fail with not found/validation error)
 * 10. (Indirect) Confirm each dislike attempt returns proper type/validation result (no direct audit log/assert)
 */
export async function test_api_discussionboard_test_create_comment_dislike_success_and_duplicate_prevention(connection: api.IConnection) {
  // 1. Register Member #1
  const member1 = await api.functional.discussionboard.actors.members.post(connection, {
    body: {
      joined_at: new Date().toISOString(),
      status: 'active',
    },
  });
  typia.assert(member1);

  // 2. Register Member #2
  const member2 = await api.functional.discussionboard.actors.members.post(connection, {
    body: {
      joined_at: new Date().toISOString(),
      status: 'active',
    },
  });
  typia.assert(member2);

  // 3. Create a comment (as Member #1)
  // We'll fudge the post ID since IDiscussionboardComment.ICreate requires one, but no post API exists: use random UUID.
  const fakePostId: string = typia.random<string & tags.Format<'uuid'>>();
  const comment = await api.functional.discussionboard.threads.comments.post(connection, {
    body: {
      discussionboard_post_id: fakePostId,
      discussionboard_member_id: member1.id,
      body: 'This is a test comment.',
      parent_id: null,
    },
  });
  typia.assert(comment);

  // 4. Member #1 dislikes the comment
  const dislike1 = await api.functional.discussionboard.interactions.commentDislikes.post(connection, {
    body: { discussionboard_comment_id: comment.id },
  });
  typia.assert(dislike1);
  TestValidator.equals('dislike is for comment')(dislike1.discussionboard_comment_id)(comment.id);
  TestValidator.equals('dislike by member1')(dislike1.discussionboard_member_id)(member1.id);

  // 5. Try to dislike again (should fail)
  await TestValidator.error('duplicate dislike prevents 2x dislikes')(() =>
    api.functional.discussionboard.interactions.commentDislikes.post(connection, {
      body: { discussionboard_comment_id: comment.id },
    })
  );

  // 6. As unauthenticated: clear connection headers if possible
  const unauthenticatedConn: api.IConnection = { ...connection, headers: {} };
  await TestValidator.error('unauthenticated cannot dislike')(() =>
    api.functional.discussionboard.interactions.commentDislikes.post(unauthenticatedConn, {
      body: { discussionboard_comment_id: comment.id },
    })
  );

  // 7. Suspend member2
  const suspension = await api.functional.discussionboard.actors.memberSuspensions.post(connection, {
    body: {
      discussionboard_member_id: member2.id,
      reason: 'Testing suspension',
      starts_at: new Date().toISOString(),
      ends_at: null,
    },
  });
  typia.assert(suspension);

  // 8. As member2, try dislike (simulate context switch by assuming connection w/ member2 active)
  const connectionMember2 = { ...connection, headers: { ...connection.headers, 'X-Member-ID': member2.id } }; // Simulate, as auth context unclear
  await TestValidator.error('suspended member cannot dislike')(() =>
    api.functional.discussionboard.interactions.commentDislikes.post(connectionMember2, {
      body: { discussionboard_comment_id: comment.id },
    })
  );

  // 9. Try to dislike a non-existent comment
  await TestValidator.error('dislike fails for nonexistent comment')(() =>
    api.functional.discussionboard.interactions.commentDislikes.post(connection, {
      body: { discussionboard_comment_id: typia.random<string & tags.Format<'uuid'>>() },
    })
  );
}

