/**
 * Validate retrieval of a paginated and filterable moderation reports list with role-based access control.
 *
 * This ensures the endpoint correctly supports various filtering, pagination, and access control workflows for moderation reports.
 *
 * 1. Create two members: one will be the reporter, and one will optionally be the reported user.
 * 2. Reporter submits two moderation reports: one about a fake post, one about a fake comment (generate random UUIDs for target IDs).
 * 3. Attempt to list moderation reports as an unauthorized member and confirm access is denied.
 * 4. (Simulate privileged access) Call the moderation reports list API with:
 *    - No filter (should get paginated list containing both reports)
 *    - Filter by status
 *    - Filter by reported_by_member_id
 *    - Various pagination settings
 *    - Combination of filters
 * 5. Validate that returned results are paginated and filtered as expected, and response type matches schema
 */
export async function test_api_discussionboard_test_list_moderation_reports_with_filters_and_pagination(connection: api.IConnection) {
  // 1. Create reporter and reported members
  const reporter = await api.functional.discussionboard.actors.members.post(connection, {
    body: {
      joined_at: new Date().toISOString(),
      status: 'active',
    }
  });
  typia.assert(reporter);

  const reported = await api.functional.discussionboard.actors.members.post(connection, {
    body: {
      joined_at: new Date().toISOString(),
      status: 'active',
    }
  });
  typia.assert(reported);

  // 2. Reporter files two reports: one about a post, one about a comment
  const report1 = await api.functional.discussionboard.moderation.reports.post(connection, {
    body: {
      reported_by_member_id: reporter.id,
      target_post_id: typia.random<string & tags.Format<"uuid">>(),
      reason: 'Spam or inappropriate post',
    }
  });
  typia.assert(report1);
  TestValidator.equals('report1 reporter')(report1.reported_by_member_id)(reporter.id);
  TestValidator.equals('report1 status')(report1.status)('pending');

  const report2 = await api.functional.discussionboard.moderation.reports.post(connection, {
    body: {
      reported_by_member_id: reporter.id,
      target_comment_id: typia.random<string & tags.Format<"uuid">>(),
      reason: 'Attack or harassment in comment',
    }
  });
  typia.assert(report2);
  TestValidator.equals('report2 reporter')(report2.reported_by_member_id)(reporter.id);
  TestValidator.equals('report2 status')(report2.status)('pending');

  // 3. Attempt to list moderation reports as unauthorized (regular member), expect error.
  TestValidator.error('only moderators/admins can list moderation reports')(async () => {
    await api.functional.discussionboard.moderation.reports.patch(connection, {
      body: {}
    });
  });

  // 4. Simulate privileged access: test moderation report listing with filters and pagination
  // (In a real system, you would switch to a moderator/admin connection. Here we assume the privileged context.)

  // a) List all reports (no filter)
  const allReports = await api.functional.discussionboard.moderation.reports.patch(connection, {
    body: {}
  });
  typia.assert(allReports);
  TestValidator.predicate('allReports contains reports')(allReports.data.length >= 2);
  const allReportIds = allReports.data.map(r => r.id);
  TestValidator.predicate('allReports includes report1')(allReportIds.includes(report1.id));
  TestValidator.predicate('allReports includes report2')(allReportIds.includes(report2.id));

  // b) Filter by reported_by_member_id
  const filterByReporter = await api.functional.discussionboard.moderation.reports.patch(connection, {
    body: { reported_by_member_id: reporter.id }
  });
  typia.assert(filterByReporter);
  TestValidator.predicate('filterByReporter contains all reports by reporter')(
    filterByReporter.data.every(r => r.reported_by_member_id === reporter.id)
  );

  // c) Filter by status 'pending'
  const filterByPending = await api.functional.discussionboard.moderation.reports.patch(connection, {
    body: { status: 'pending' }
  });
  typia.assert(filterByPending);
  TestValidator.predicate('filterByPending all pending')(
    filterByPending.data.every(r => r.status === 'pending')
  );

  // d) Combination: filter by status and reporter
  const comboFilter = await api.functional.discussionboard.moderation.reports.patch(connection, {
    body: { reported_by_member_id: reporter.id, status: 'pending' }
  });
  typia.assert(comboFilter);
  TestValidator.predicate('comboFilter valid')(
    comboFilter.data.every(r => r.status === 'pending' && r.reported_by_member_id === reporter.id)
  );

  // e) Pagination: page/limit
  const paged = await api.functional.discussionboard.moderation.reports.patch(connection, {
    body: { page: 1, limit: 1 }
  });
  typia.assert(paged);
  TestValidator.equals('paged page')(paged.pagination.current)(1);
  TestValidator.equals('paged limit')(paged.pagination.limit)(1);
  TestValidator.equals('paged records')(paged.pagination.records)(allReports.pagination.records);
  TestValidator.predicate('paged.data.length <= 1')(paged.data.length <= 1);
}

