 *
 * This test covers business logic and permission rules for soft-deleting comments on the discussion board system:
 *   - Author (member) can delete their own comment (if deletable by window/rule)
 *   - Moderator/admin can always delete any comment (ignoring time windows)
 *   - Non-author regular members are forbidden from deleting others' comments
 *   - Cannot delete comments that are locked, under moderation, or already deleted
 *   - Nested/threaded comment cases and repeated deletion attempts are also checked
 *   - Deletion must update the comment's deleted_at field (soft delete) and enforce visibility rules
 *
 * Steps:
 * 1. Create three member accounts: author, moderator/admin, non-author member
 * 2. Author posts a comment and a nested reply (threaded comment)
 * 3. Author deletes their top-level comment: expect success, deleted_at set, comment returned
 * 4. Author deletes their own nested (reply) comment: expect success
 * 5. Non-author regular member attempts to delete both comments: expect 403 error
 * 6. Moderator/admin deletes an undeleted comment: expect success
 * 7. Attempt repeated deletion of an already deleted comment: expect 404
 * 8. Lock a comment (simulate lock by update), then attempt deletion as both author and moderator: expect correct error
 * 9. Confirm that after deletion, deleted_at is set, and downstream business rules (e.g., cannot update) are respected
 * 10. (If possible) Check audit/log entry or response hinting audit action (if returned)
 */
export async function test_api_discussionboard_test_delete_comment_own_and_others_permissions_soft_delete(
  connection: api.IConnection,
) {
  // 1. Create three member accounts
  const author = await api.functional.discussionboard.actors.members.post(connection, {
    body: {
      joined_at: new Date().toISOString(),
      status: "active"
    }
  });
  typia.assert(author);
  const moderator = await api.functional.discussionboard.actors.members.post(connection, {
    body: {
      joined_at: new Date().toISOString(),
      status: "active"
    }
  });
  typia.assert(moderator);
  const other = await api.functional.discussionboard.actors.members.post(connection, {
    body: {
      joined_at: new Date().toISOString(),
      status: "active"
    }
  });
  typia.assert(other);

  // 2. Author creates a post/thread id (mocked as uuid, since no post-creation API)
  const post_id = typia.random<string & tags.Format<"uuid">>();
  // 2a. Author posts a top-level comment
  const topComment = await api.functional.discussionboard.threads.comments.post(connection, {
    body: {
      discussionboard_post_id: post_id,
      discussionboard_member_id: author.id,
      body: "This is a top-level comment"
    }
  });
  typia.assert(topComment);
  // 2b. Author posts a reply (nested comment)
  const replyComment = await api.functional.discussionboard.threads.comments.post(connection, {
    body: {
      discussionboard_post_id: post_id,
      discussionboard_member_id: author.id,
      body: "This is a nested reply",
      parent_id: topComment.id
    }
  });
  typia.assert(replyComment);

  // 3. Author deletes their top-level comment
  const deletedTop = await api.functional.discussionboard.threads.comments.eraseById(connection, { id: topComment.id });
  typia.assert(deletedTop);
  TestValidator.predicate("deleted_at must be set after soft delete")(!!deletedTop.deleted_at);

  // 4. Author deletes their own nested reply
  const deletedReply = await api.functional.discussionboard.threads.comments.eraseById(connection, { id: replyComment.id });
  typia.assert(deletedReply);
  TestValidator.predicate("deleted_at must be set for nested delete")(!!deletedReply.deleted_at);

  // 5. Non-author attempts to delete
  TestValidator.error("non-author cannot delete")(() =>
    api.functional.discussionboard.threads.comments.eraseById(connection, {
      id: topComment.id
    })
  );
  TestValidator.error("non-author cannot delete nested")(() =>
    api.functional.discussionboard.threads.comments.eraseById(connection, {
      id: replyComment.id
    })
  );

