  // 3. owner가 토픽 생성
  const topic = await api.functional.discussionboard.boards.boardTopics.post(connection, {
    body: {
      discussionboard_board_id: board.id,
      code: RandomGenerator.alphabets(6),
      title: RandomGenerator.alphabets(12),
      created_by_member_id: owner.id,
    },
  });
  typia.assert(topic);

  // 4. intruder 회원 생성 (서로 다른 id)
  const intruder = await api.functional.discussionboard.actors.members.post(connection, {
    body: {
      joined_at: new Date().toISOString(),
      status: "active",
    },
  });
  typia.assert(intruder);

  // 5. intruder로 토픽 수정 시도 (권한 없음)
  await TestValidator.error("권한 없는 회원이 토픽을 수정하려 하면 403 에러")(
    async () => {
      await api.functional.discussionboard.boards.boardTopics.putById(connection, {
        id: topic.id,
        body: {
          title: "해킹 시도: 침입자",
        },
      });
    },
  );

  // 6. 인증 해제 상태에서 토픽 수정 시도 (비로그인 상태)
  const unauthenticatedConn: api.IConnection = {
    ...connection,
    headers: { ...connection.headers },
