  };
  delete unauthenticatedConn.headers.Authorization;
  await TestValidator.error("비로그인 사용자가 토픽을 수정하려 하면 403 에러")(
    async () => {
      await api.functional.discussionboard.boards.boardTopics.putById(unauthenticatedConn, {
        id: topic.id,
        body: {
          title: "해킹 시도: 비로그인",
        },
      });
    },
  );

