import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMembers } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMembers";
import type { IDiscussionboardComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardComment";
import type { IDiscussionboardCommentLike } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardCommentLike";
import type { IPageIDiscussionboardCommentLike } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionboardCommentLike";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * List and filter comment likes with various parameters and permissions.
 *
 * This test simulates a realistic environment for listing/searching comment likes. Multiple members and comments are created, and likes are seeded for a diverse dataset. It then verifies the behavior of the list/search API (PATCH /discussionboard/interactions/commentLikes) under a variety of conditions:
 *
 * Steps:
 * 1. Create multiple members. Collect their IDs for target filtering.
 * 2. Create multiple comments, each by different members (covering different parent posts and authors). Collect comment IDs for target filtering.
 * 3. For each member, like several comments (some likes per member, overlapping likes on some comments for cross-filter validation).
 * 4. Use the comment like list/search endpoint to:
 *    a. Retrieve all likes for a specific comment (with/without pagination and sorting).
 *    b. Retrieve all likes by a specific member (with pagination and sort order checks).
 *    c. Perform time-window searches to ensure 'created_after' and 'created_before' filters work.
 *    d. Query with both member and comment filters to verify accurate intersection results.
 *    e. Run pagination/limit tests (e.g., small limits and page > 1) and validate pagination metadata.
 *    f. Check results as both a regular member (should only see their own likes) and an admin/moderator (should see all).
 * 5. Edge cases: submit invalid or out-of-range parameter combinations (invalid UUID, negative page, excessive limit) and validate error handling.
 *
 * Validation points:
 * - All matching records returned for valid queries, with correct pagination and sort order.
 * - Regular members are not able to access other users' like records.
 * - Admin/mod roles (if accessible via public API) show all results; otherwise, skip this check.
 * - Proper error responses for malformed or unauthorized queries.
 */
export async function test_api_discussionboard_test_list_comment_likes_with_various_filters_and_pagination(connection: api.IConnection) {
  // 1. Create members
  const members = [];
  for (let i = 0; i < 3; ++i) {
    const member = await api.functional.discussionboard.actors.members.post(connection, {
      body: {
        joined_at: new Date(Date.now() - (i * 3600 * 1000)).toISOString(),
        status: 'active',
      },
    });
    typia.assert(member);
    members.push(member);
  }
  // 2. Create comments
  const comments = [];
  for (let i = 0; i < 4; ++i) {
    const comment = await api.functional.discussionboard.threads.comments.post(connection, {
      body: {
        discussionboard_post_id: typia.random<string & tags.Format<"uuid">>(),
        discussionboard_member_id: members[i%members.length].id,
        body: `Test comment ${i + 1}`,
      },
    });
    typia.assert(comment);
    comments.push(comment);
  }
  // 3. Create likes (cross likes: members like multiple comments)
  const likeRecords = [];
  for (let i = 0; i < members.length; ++i) {
    for (let j = 0; j < comments.length; ++j) {
      // Not all members like all comments; vary overlap
      if ((i + j) % 2 === 0) {
        // Create like as current member
        const like = await api.functional.discussionboard.interactions.commentLikes.post(connection, {
          body: {
            discussionboard_comment_id: comments[j].id,
          },
        });
        typia.assert(like);
        likeRecords.push({...like, member: members[i], comment: comments[j]});
      }
    }
  }

  // 4a. List likes for a specific comment
  const targetComment = comments[0];
  const likesForComment = await api.functional.discussionboard.interactions.commentLikes.patch(connection, {
    body: {
      comment_id: targetComment.id,
      page: 1,
      limit: 10,
      sort_key: "created_at",
      sort_order: "asc",
    },
  });
  typia.assert(likesForComment);
  likesForComment.data.forEach((like) =>
    TestValidator.equals('commentId matches target')(like.discussionboard_comment_id)(targetComment.id)
  );

  // 4b. List likes by a specific member, check pagination
  const targetMember = members[1];
  const likesByMember = await api.functional.discussionboard.interactions.commentLikes.patch(connection, {
    body: {
      member_id: targetMember.id,
      page: 1,
      limit: 2,
      sort_key: "created_at",
      sort_order: "desc",
    },
  });
  typia.assert(likesByMember);
  likesByMember.data.forEach((like) =>
    TestValidator.equals('memberId matches filter')(like.discussionboard_member_id)(targetMember.id)
  );
  TestValidator.equals('limit')(likesByMember.pagination.limit)(2);
  TestValidator.predicate('Pagination correct')(likesByMember.pagination.pages >= 1);

  // 4c. Time window search
  const earliestLike = likeRecords.map((rec) => rec.created_at).sort()[0];
  const latestLike = likeRecords.map((rec) => rec.created_at).sort().slice(-1)[0];
  const likesInRange = await api.functional.discussionboard.interactions.commentLikes.patch(connection, {
    body: {
      created_after: earliestLike,
      created_before: latestLike,
    },
  });
  typia.assert(likesInRange);
  likesInRange.data.forEach((like) => {
    TestValidator.predicate('after')(like.created_at >= earliestLike);
    TestValidator.predicate('before')(like.created_at <= latestLike);
  });

  // 4d. Combined filters
  const unionLike = likeRecords.find((rec) => rec.discussionboard_member_id === targetMember.id && rec.discussionboard_comment_id === targetComment.id);
  if (unionLike) {
    const result = await api.functional.discussionboard.interactions.commentLikes.patch(connection, {
      body: {
        member_id: targetMember.id,
        comment_id: targetComment.id,
      },
    });
    typia.assert(result);
    result.data.forEach(like => {
      TestValidator.equals('filter memberId')(like.discussionboard_member_id)(targetMember.id);
      TestValidator.equals('filter commentId')(like.discussionboard_comment_id)(targetComment.id);
    });
  }

  // 4e. Pagination/limit edge: page 2 out of bounds, limit > max
  const outOfRange = await api.functional.discussionboard.interactions.commentLikes.patch(connection, {
    body: {
      page: 999,
      limit: 20,
    },
  });
  typia.assert(outOfRange);
  TestValidator.equals('empty page')(outOfRange.data.length)(0);

  await TestValidator.error('Excessive limit should fail')(async () => {
    await api.functional.discussionboard.interactions.commentLikes.patch(connection, {
      body: {
        limit: 123456,
      },
    });
  });
  await TestValidator.error('Negative page should fail')(async () => {
    await api.functional.discussionboard.interactions.commentLikes.patch(connection, {
      body: {
        page: -5,
      },
    });
  });
  await TestValidator.error('Invalid UUID in filter should fail')(async () => {
    await api.functional.discussionboard.interactions.commentLikes.patch(connection, {
      body: {
        comment_id: 'not-a-uuid',
      },
    });
  });
}

