  // Use two fictitious board IDs
  const boardIdA: string = typia.random<string & tags.Format<"uuid">>();
  const boardIdB: string = typia.random<string & tags.Format<"uuid">>();

  // 2. Each creates a thread
  const threadA = await api.functional.discussionboard.threads.threads.post(connection, {
    body: {
      discussionboard_board_id: boardIdA,
      discussionboard_member_id: memberA.id,
      title: "Thread by A - PNG/Image Docs",
      description: "Discussion by A",
      status: "open",
      created_at: new Date(Date.now() - 2 * 24 * 60 * 60 * 1000).toISOString()
    } satisfies IDiscussionboardThreads.ICreate
  });
  typia.assert(threadA);
  const threadB = await api.functional.discussionboard.threads.threads.post(connection, {
    body: {
      discussionboard_board_id: boardIdB,
      discussionboard_member_id: memberB.id,
      title: "Thread by B - PDF/Pics",
      description: "Discussion by B",
      status: "open",
      created_at: new Date(Date.now() - 24 * 60 * 60 * 1000).toISOString()
    } satisfies IDiscussionboardThreads.ICreate
  });
  typia.assert(threadB);

  // 3. Each creates a post
  const postA = await api.functional.discussionboard.threads.posts.post(connection, {
    body: {
      discussionboard_thread_id: threadA.id,
      discussionboard_member_id: memberA.id,
      body: "Post from member A",
      created_at: new Date(Date.now() - 2.5 * 24 * 60 * 60 * 1000).toISOString()
    } satisfies IDiscussionboardPosts.ICreate
  });
  typia.assert(postA);
  const postB = await api.functional.discussionboard.threads.posts.post(connection, {
    body: {
      discussionboard_thread_id: threadB.id,
      discussionboard_member_id: memberB.id,
      body: "Post from member B",
      created_at: new Date(Date.now() - 1.5 * 24 * 60 * 60 * 1000).toISOString()
    } satisfies IDiscussionboardPosts.ICreate
  });
  typia.assert(postB);

  // 4. Each uploads two attachments to their posts (stagger file_name/type/uploaded_at)
  // Attachments for A (image/png, application/pdf)
  const attachmentA1 = await api.functional.discussionboard.threads.postAttachments.post(connection, {
    body: {
      discussionboard_post_id: postA.id,
      file_uri: "https://example.com/a1.png",
      file_name: "cat-picture.png",
      file_type: "image/png",
      uploaded_by: memberA.id
    } satisfies IDiscussionboardPostAttachment.ICreate
  });
  typia.assert(attachmentA1);
  const attachmentA2 = await api.functional.discussionboard.threads.postAttachments.post(connection, {
    body: {
      discussionboard_post_id: postA.id,
      file_uri: "https://example.com/a2.pdf",
      file_name: "notes.pdf",
      file_type: "application/pdf",
      uploaded_by: memberA.id
    } satisfies IDiscussionboardPostAttachment.ICreate
  });
  typia.assert(attachmentA2);

  // Attachments for B (mix types)
  const attachmentB1 = await api.functional.discussionboard.threads.postAttachments.post(connection, {
    body: {
      discussionboard_post_id: postB.id,
      file_uri: "https://example.com/b1.png",
      file_name: "dog-picture.png",
      file_type: "image/png",
      uploaded_by: memberB.id
    } satisfies IDiscussionboardPostAttachment.ICreate
  });
  typia.assert(attachmentB1);
  const attachmentB2 = await api.functional.discussionboard.threads.postAttachments.post(connection, {
    body: {
      discussionboard_post_id: postB.id,
      file_uri: "https://example.com/b2.pdf",
      file_name: "assignment.pdf",
      file_type: "application/pdf",
      uploaded_by: memberB.id
    } satisfies IDiscussionboardPostAttachment.ICreate
  });
  typia.assert(attachmentB2);

  // As memberA, test various PATCH searches

  // a. All attachments for own post (should be only A’s attachments)
  {
    const res = await api.functional.discussionboard.threads.postAttachments.patch(connection, {
      body: {
        discussionboard_post_id: postA.id,
        uploaded_by: undefined,
        file_type: undefined,
        uploaded_at_from: undefined,
        uploaded_at_to: undefined,
        page: 1,
        limit: 10,
        sort_by: null,
        sort_order: null
      } satisfies IDiscussionboardPostAttachment.IRequest
    });
    typia.assert(res);
    // Only attachments A1/A2 should appear
    TestValidator.predicate("only own post attachments")(res.data.every(att => att.discussionboard_post_id === postA.id));
    TestValidator.equals("count attachments")(res.data.length)(2);
    TestValidator.predicate("correct file names & types")([attachmentA1.file_name, attachmentA2.file_name].every(fn => res.data.map(x => x.file_name).includes(fn)));
  }

  // b. Filter by file_type (image/png), should see ‘cat-picture.png’ and 'dog-picture.png' if memberA can see postB's attachment (but generally should see only own post since A cannot access B's post)
  {
    const res = await api.functional.discussionboard.threads.postAttachments.patch(connection, {
      body: {
        file_type: "image/png",
        page: 1,
        limit: 10
      } satisfies IDiscussionboardPostAttachment.IRequest
    });
    typia.assert(res);
    // Only image/png attachments visible to memberA should appear
    TestValidator.predicate("filter file_type=image/png")(res.data.every(att => att.file_type === "image/png"));
    // memberA should not see B's attachments
    TestValidator.predicate("no B attachments seen")(res.data.every(att => att.uploaded_by !== memberB.id));
  }

  // c. Filter by uploaded_by=memberB.id (should see nothing, unless there's a thread where both were participants, which isn't set up in this test)
  {
    const res = await api.functional.discussionboard.threads.postAttachments.patch(connection, {
      body: {
        uploaded_by: memberB.id,
        page: 1,
        limit: 10
      } satisfies IDiscussionboardPostAttachment.IRequest
    });
    typia.assert(res);
    // memberA should not see B's attachments
    TestValidator.equals("should not see memberB attachments in unaccessible posts")(res.data.length)(0);
  }

  // d. Pagination: limit=2, page=1 (should see first 2 attachments, probably A's attachments, since only accessible)
  {
    const res1 = await api.functional.discussionboard.threads.postAttachments.patch(connection, {
      body: {
        page: 1,
        limit: 2
      } satisfies IDiscussionboardPostAttachment.IRequest
    });
    typia.assert(res1);
    TestValidator.predicate("page size=2")(res1.data.length <= 2);
    const res2 = await api.functional.discussionboard.threads.postAttachments.patch(connection, {
      body: {
        page: 2,
        limit: 2
      } satisfies IDiscussionboardPostAttachment.IRequest
    });
    typia.assert(res2);
    // Each page is distinct, no overlap
    if (res1.data.length > 0 && res2.data.length > 0) {
      const ids1 = res1.data.map(x => x.id);
      const ids2 = res2.data.map(x => x.id);
      TestValidator.predicate("no overlap between page 1 and 2")(ids1.every(id => !ids2.includes(id)));
    }
  }

  // e. Searching with a postId memberA cannot access (use postB.id)
  {
    const res = await api.functional.discussionboard.threads.postAttachments.patch(connection, {
      body: {
        discussionboard_post_id: postB.id,
        page: 1,
        limit: 10
      } satisfies IDiscussionboardPostAttachment.IRequest
    });
    typia.assert(res);
    TestValidator.equals("forbidden post attachments not visible")(res.data.length)(0);
  }

  // f. Invalid pagination (limit=0/page=0/limit>100), and random not-existent postId
  {
    // limit=0 → should error or empty result
    TestValidator.error("limit=0 yields error or empty")(async () => {
      await api.functional.discussionboard.threads.postAttachments.patch(connection, {
        body: {
          limit: 0,
          page: 1
        } satisfies IDiscussionboardPostAttachment.IRequest
      });
    });
    // page=0 → error or empty
    TestValidator.error("page=0 yields error or empty")(async () => {
      await api.functional.discussionboard.threads.postAttachments.patch(connection, {
        body: {
          limit: 2,
          page: 0
        } satisfies IDiscussionboardPostAttachment.IRequest
      });
    });
    // limit>100 → error or empty
    TestValidator.error("limit>100 yields error or empty")(async () => {
      await api.functional.discussionboard.threads.postAttachments.patch(connection, {
        body: {
          limit: 150,
          page: 1
        } satisfies IDiscussionboardPostAttachment.IRequest
      });
    });
    // Bad UUID for postId
    TestValidator.error("non-existent postId yields error or empty")(async () => {
      await api.functional.discussionboard.threads.postAttachments.patch(connection, {
        body: {
          discussionboard_post_id: "00000000-0000-0000-0000-000000000000",
          limit: 5,
          page: 1
        } satisfies IDiscussionboardPostAttachment.IRequest
      });
    });
  }

  // g. Optionally: filtering by uploaded_at range if timestamps differ
  {
    const res = await api.functional.discussionboard.threads.postAttachments.patch(connection, {
      body: {
        uploaded_at_from: new Date(Date.now() - 3 * 24 * 60 * 60 * 1000).toISOString(),
        uploaded_at_to: new Date().toISOString(),
        limit: 10,
        page: 1
      } satisfies IDiscussionboardPostAttachment.IRequest
    });
    typia.assert(res);
    TestValidator.predicate("uploaded_at range filter – all timestamps in range")(res.data.every(att => new Date(att.uploaded_at).getTime() >= Date.now() - 3*24*60*60*1000 && new Date(att.uploaded_at).getTime() <= Date.now()));
  }
}

