/**
 * 게시글 신고 삭제 API - 권한 및 오류 케이스 E2E 테스트
 * 
 * 목적:
 * - 신고 삭제 기능의 접근 권한(관리자/회원) 검증
 * - 허가되지 않은 사용자의 삭제 시 에러 처리 검증
 * - 이미 삭제된 혹은 존재하지 않는 신고 삭제 시 에러 반환 검증
 * 
 * 시나리오:
 * 1. 테스트용 게시글 생성(필수 필드만 활용)
 * 2. 일반 회원(신고자)로 해당 게시글을 신고(신고 ID 확보)
 * 3. (정상) 관리자 connection에서 신고 삭제 → 성공 여부/ID 확인
 * 4. (실패) 일반 회원 connection에서 동일 신고 삭제 재시도 → 권한에러 발생 확인
 * 5. (실패) 무작위 uuid(존재하지 않거나 이미 삭제된 신고) 삭제 시도 → 에러 반환 확인
 * 
 * 비고:
 * - 실제 인증/회원/관리자 계정 생성 API 부재로, connection 인스턴스가 권한(헤더 등) 맥락을 가정한다고 판단
 * - 모든 request/response에 typia.assert, 성공/실패 경계 TestValidator 활용
 */
export async function test_api_discussionboard_test_delete_post_report_authorized_vs_unauthorized_error_cases(
  connection: api.IConnection,
) {
  // 1. 테스트용 게시글 생성
  const threadId: string = typia.random<string & tags.Format<"uuid">>();
  const memberId: string = typia.random<string & tags.Format<"uuid">>();
  const now: string = new Date().toISOString();
  const post = await api.functional.discussionboard.threads.posts.post(
    connection,
    {
      body: {
        discussionboard_thread_id: threadId,
        discussionboard_member_id: memberId,
        body: RandomGenerator.paragraph()(),
        created_at: now,
      } satisfies IDiscussionboardPosts.ICreate,
    },
  );
  typia.assert(post);

  // 2. 일반 회원(신고자)로 해당 게시글 신고 생성 (신고 ID 확보)
  const report = await api.functional.discussionboard.interactions.postReports.post(
    connection,
    {
      body: {
        discussionboard_post_id: post.id,
        reason: "Spam or test report for E2E",
      } satisfies IDiscussionboardPostReport.ICreate,
    },
  );
  typia.assert(report);
  const reportId = report.id;

  // 3. (정상) 관리자 connection에서 신고 삭제
  //    (실제 환경에서는 connection 인스턴스에 header를 통한 role context 부여로 판단)
  const adminConnection = {
    ...connection,
    headers: {
      ...connection.headers,
      "x-user-role": "admin",
    },
  };
  const deleteResult = await api.functional.discussionboard.interactions.postReports.eraseById(
    adminConnection as api.IConnection,
    { id: reportId },
  );
  typia.assert(deleteResult);
  TestValidator.equals("Delete success")(deleteResult.success)(true);
  TestValidator.equals("Deleted ID matches")(deleteResult.deleted_id)(reportId);

  // 4. (실패) 동일 신고 일반 회원이 삭제 시도 → 권한 에러
  await TestValidator.error("Unauthorized member cannot delete report")(
    async () => {
      await api.functional.discussionboard.interactions.postReports.eraseById(
        connection,
        { id: reportId },
      );
    },
  );

  // 5. (실패) 무작위 uuid로 삭제 시도(존재X)
  const randomNonExistentId = typia.random<string & tags.Format<"uuid">>();
  await TestValidator.error("Delete non-existent report ID fails")(
    async () => {
      await api.functional.discussionboard.interactions.postReports.eraseById(
        adminConnection as api.IConnection,
        { id: randomNonExistentId },
      );
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMembers } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMembers";
import type { DiscussionBoardMemberProfiles } from "@ORGANIZATION/PROJECT-api/lib/structures/DiscussionBoardMemberProfiles";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IDiscussionBoardMemberProfile } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMemberProfile";

/**
 * Test listing member profiles with various search, filter, and pagination options (admin/moderator view).
 *
 * Business context:
 * Validates listing and search functionality for member profiles table. Assumes admin/moderator role access; ensures profile listing supports display_name search, join date range filtering, and paginated results. Also checks negative/no-match filters and response page metadata.
 *
 * Test workflow:
 * 1. Register three members (distinct join dates/status values)
 * 2. Create a profile for each (unique display_name)
 * 3. List profiles (no filters), ensure all created are returned and page meta is correct
 * 4. Search by display_name (partial & exact), checking accurate matching
 * 5. Filter by joined_after / joined_before dates, verifying only correct profiles are present
 * 6. Paginate with limit/page, validate returned data and meta
 * 7. Do a search with an obviously invalid display_name, asserting result is empty
 * 8. (Comment only) Access control: Endpoint requires admin/moderator role – actual role switching not testable via current APIs, but document expectation.
 */
export async function test_api_discussionboard_test_list_member_profiles_with_various_search_filters(
  connection: api.IConnection,
) {
  // Step 1: Register three members with distinct join dates and status
  const baseDate = new Date();
  // Create 3 different join_at dates (spread +/-1 day)
  const joinedA = new Date(baseDate);
  joinedA.setDate(baseDate.getDate() - 1);
  const joinedB = new Date(baseDate);
  const joinedC = new Date(baseDate);
  joinedC.setDate(baseDate.getDate() + 1);

  const statuses = ["active", "pending", "suspended"];

  const members = await Promise.all([
    api.functional.discussionboard.actors.members.post(connection, {
      body: {
        joined_at: joinedA.toISOString(),
        status: statuses[0],
      } satisfies IDiscussionboardMembers.ICreate,
    }),
    api.functional.discussionboard.actors.members.post(connection, {
      body: {
        joined_at: joinedB.toISOString(),
        status: statuses[1],
      } satisfies IDiscussionboardMembers.ICreate,
    }),
    api.functional.discussionboard.actors.members.post(connection, {
      body: {
        joined_at: joinedC.toISOString(),
        status: statuses[2],
      } satisfies IDiscussionboardMembers.ICreate,
    })
  ]);
  members.forEach(typia.assert);

  // Step 2: Create a profile for each member, each with a unique display_name
  const displayNames = [
    "AlphaUser" + typia.random<string>(),
    "BravoUser" + typia.random<string>(),
    "CharlieUser" + typia.random<string>()
  ];
  const bios = ["Bio A", "Bio B", "Bio C"];
  const profiles = await Promise.all(
    members.map((m, i) =>
      api.functional.discussionboard.actors.memberProfiles.post(connection, {
        body: {
          discussionboard_member_id: m.id,
          display_name: displayNames[i],
          bio: bios[i],
          avatar_uri: null,
          website: null,
          location: null,
        } satisfies IDiscussionBoardMemberProfile.ICreate,
      })
    )
  );
  profiles.forEach(typia.assert);

  // Step 3: List all profiles (no filters)
  {
    const res = await api.functional.discussionboard.actors.memberProfiles.patch(connection, {
      body: {} satisfies DiscussionBoardMemberProfiles.IRequest,
    });
    typia.assert(res);
    // Must include all created profiles
    const returnedIds = res.data.map(x => x.id);
    profiles.forEach(profile => {
      TestValidator.predicate("profile returned")(returnedIds.includes(profile.id));
    });
    // Page meta non-null, data array length >= created
    TestValidator.predicate("returns at least created profiles")(res.data.length >= profiles.length);
  }

  // Step 4: Search by display_name: exact and partial
  for (let i=0; i<profiles.length; ++i) {
    // Exact match
    const resExact = await api.functional.discussionboard.actors.memberProfiles.patch(connection, {
      body: { display_name: displayNames[i] } satisfies DiscussionBoardMemberProfiles.IRequest,
    });
    typia.assert(resExact);
    TestValidator.equals("exact name count")(resExact.data.length)(1);
    TestValidator.equals("exact name match")(resExact.data[0].display_name)(displayNames[i]);
    // Partial (first 6 chars)
    const partial = displayNames[i].slice(0, 6);
    const resPartial = await api.functional.discussionboard.actors.memberProfiles.patch(connection, {
      body: { display_name: partial } satisfies DiscussionBoardMemberProfiles.IRequest,
    });
    typia.assert(resPartial);
    TestValidator.predicate("partial include")(resPartial.data.some(x => x.display_name?.includes(partial)));
  }

  // Step 5: joined_after / joined_before filters
  {
    // Profiles for joined_after joinedA (so B and C)
    const res = await api.functional.discussionboard.actors.memberProfiles.patch(connection, {
      body: { joined_after: joinedA.toISOString() } satisfies DiscussionBoardMemberProfiles.IRequest,
    });
    typia.assert(res);
    // Should include all except member[0]
    profiles.slice(1).forEach(p => TestValidator.predicate("joined_after present")(res.data.some(x => x.id === p.id)));
    TestValidator.predicate("joined_after not present")(res.data.every(x => x.id !== profiles[0].id));
  }
  {
    // Profiles for joined_before joinedC (so A and B)
    const res = await api.functional.discussionboard.actors.memberProfiles.patch(connection, {
      body: { joined_before: joinedC.toISOString() } satisfies DiscussionBoardMemberProfiles.IRequest,
    });
    typia.assert(res);
    // Should include all except member[2]
    profiles.slice(0,2).forEach(p => TestValidator.predicate("joined_before present")(res.data.some(x => x.id === p.id)));
    TestValidator.predicate("joined_before not present")(res.data.every(x => x.id !== profiles[2].id));
  }
  // Step 6: Pagination (limit=1, page=2)
  {
    const res = await api.functional.discussionboard.actors.memberProfiles.patch(connection, {
      body: { limit: 1, page: 2 } satisfies DiscussionBoardMemberProfiles.IRequest,
    });
    typia.assert(res);
    TestValidator.equals("page meta current")(res.pagination.current)(2);
    TestValidator.equals("page meta limit")(res.pagination.limit)(1);
    TestValidator.predicate("page data length == 1")(res.data.length === 1);
  }
  // Step 7: No-match filter
  {
    const res = await api.functional.discussionboard.actors.memberProfiles.patch(connection, {
      body: { display_name: "NO_SUCH_USER_PROFILE_NAME____" } satisfies DiscussionBoardMemberProfiles.IRequest,
    });
    typia.assert(res);
    TestValidator.equals("empty data for bad name")(res.data.length)(0);
  }
  // Step 8: Access control (comment)
  // NOTE: There is no SDK API to create a non-admin/moderator user or to simulate auth headers/roles.
  // If the API supported it, here we would try to call patch as an ordinary (unauthorized) user
  // or missing credentials, and expect a forbidden/denied error. Here, just document this.
}

