import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMembers } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMembers";
import type { IDiscussionboardSuspensionRecord } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardSuspensionRecord";

/**
 * 테스트 목적: 다양한 사유 및 권한을 가진 주체에 의한 회원 정지 레코드 생성
 *
 * 이 테스트는 다음과 같은 케이스를 포괄적으로 검증합니다:
 * 1. 일반적인 단일 위반(single violation)에 대한 정지 (moderator 발동)
 * 2. 반복 위반(repeat offense)에 대한 정지 (admin 발동)
 * 3. 계정 정책 위반(account policy breach)으로 인한 정지 (moderator/admin 발동)
 *
 * 각 성공 케이스마다 다음을 검증합니다.
 * - 회원이 정상적으로 정지(레코드 생성)됨
 * - 정지 발행 주체가 올바르게 기록됨
 * - 정지 기간 및 사유가 반영됨
 * - 모든 감사 필드(audit fields: id, created_at, revoked, revoked_at 등) 충실하게 채워짐
 *
 * 또한 다음 실패/에러 케이스도 검증합니다.
 * - 비권한자(일반 회원)에 의한 정지 발동 시도 -> 권한 거절 오류 발생
 * - 이미 정지된 회원 대상 재정지 시도 -> 비즈니스 로직 오류
 * - 필수 필드 누락/잘못된 요청 데이터 -> validation 오류
 *
 * [주요 단계]
 * 1. 회원 3명 생성 (일반/모더레이터/관리자) - 정지 대상/권한자
 * 2. (성공) 모더레이터가 일반 회원 정지 (단일 위반 케이스)
 * 3. (성공) 관리자가 일반 회원 정지 (반복 위반 케이스)
 * 4. (성공) 모더레이터가 일반 회원 정지 (정책 위반 케이스)
 * 5. (실패) 일반 회원이 다른 회원 정지 시도 (권한 부족)
 * 6. (실패) 이미 정지된 회원을 다시 정지 시도
 * 7. (실패) 필수 값 누락한 요청 시도 (e.g. 사유 없음)
 */
export async function test_api_discussionboard_test_create_member_suspension_with_various_reasons_and_authority(connection: api.IConnection) {
  // 1. 회원 3명 생성 (일반/모더레이터/관리자)
  const now = new Date();
  const getLater = (minutes: number) => new Date(now.getTime() + minutes * 60000).toISOString();

  // 일반 회원 생성
  const normalMember = await api.functional.discussionboard.actors.members.post(connection, {
    body: {
      joined_at: now.toISOString(),
      status: "active",
    },
  });
  typia.assert(normalMember);

  // 모더레이터 회원 생성
  const moderatorMember = await api.functional.discussionboard.actors.members.post(connection, {
    body: {
      joined_at: now.toISOString(),
      status: "moderator",
    },
  });
  typia.assert(moderatorMember);

  // 관리자 회원 생성
  const adminMember = await api.functional.discussionboard.actors.members.post(connection, {
    body: {
      joined_at: now.toISOString(),
      status: "admin",
    },
  });
  typia.assert(adminMember);

  // 2. (성공) 모더레이터가 일반 회원 정지 (단일 위반)
  const singleViolationStart = now.toISOString();
  const singleViolationEnd = getLater(60); // 1시간 정지
  const singleViolationRecord = await api.functional.discussionboard.moderation.suspensionRecords.post(connection, {
    body: {
      suspended_member_id: normalMember.id,
      issued_by_moderator_id: moderatorMember.id,
      start_at: singleViolationStart,
      end_at: singleViolationEnd,
      reason: "단일 위반 (single violation)",
    },
  });
  typia.assert(singleViolationRecord);
  TestValidator.equals("suspended member id")(singleViolationRecord.suspended_member_id)(normalMember.id);
  TestValidator.equals("issuer is moderator")(singleViolationRecord.issued_by_moderator_id)(moderatorMember.id);
  TestValidator.equals("start_at")(singleViolationRecord.start_at)(singleViolationStart);
  TestValidator.equals("end_at")(singleViolationRecord.end_at)(singleViolationEnd);
  TestValidator.equals("reason")(singleViolationRecord.reason)("단일 위반 (single violation)");
  TestValidator.equals("not revoked")(singleViolationRecord.revoked)(false);
  TestValidator.predicate("created_at exists")(typeof singleViolationRecord.created_at === "string");
  TestValidator.equals("revoked_at is null")(singleViolationRecord.revoked_at)(null);
  TestValidator.predicate("id format")(!!singleViolationRecord.id);

  // 3. (성공) 관리자가 일반 회원 정지 (반복 위반)
  const repeatOffenseStart = getLater(200); // 200분 후
  const repeatOffenseEnd = getLater(260); // 1시간 이후
  const repeatOffenseRecord = await api.functional.discussionboard.moderation.suspensionRecords.post(connection, {
    body: {
      suspended_member_id: normalMember.id,
      issued_by_moderator_id: adminMember.id,
      start_at: repeatOffenseStart,
      end_at: repeatOffenseEnd,
      reason: "반복 위반 (repeat offense)",
    },
  });
  typia.assert(repeatOffenseRecord);
  TestValidator.equals("suspended member id")(repeatOffenseRecord.suspended_member_id)(normalMember.id);
  TestValidator.equals("issuer is admin")(repeatOffenseRecord.issued_by_moderator_id)(adminMember.id);
  TestValidator.equals("start_at")(repeatOffenseRecord.start_at)(repeatOffenseStart);
  TestValidator.equals("end_at")(repeatOffenseRecord.end_at)(repeatOffenseEnd);
  TestValidator.equals("reason")(repeatOffenseRecord.reason)("반복 위반 (repeat offense)");
  TestValidator.equals("not revoked")(repeatOffenseRecord.revoked)(false);
  TestValidator.equals("revoked_at is null")(repeatOffenseRecord.revoked_at)(null);
  TestValidator.predicate("id format")(!!repeatOffenseRecord.id);

  // 4. (성공) 모더레이터가 정책 위반 임의 회원 정지 (end_at null = 영구정지)
  const policyBreachStart = getLater(300);
  const policyBreachRecord = await api.functional.discussionboard.moderation.suspensionRecords.post(connection, {
    body: {
      suspended_member_id: normalMember.id,
      issued_by_moderator_id: moderatorMember.id,
      start_at: policyBreachStart,
      end_at: null,
      reason: "계정 정책 위반 (account policy breach)",
    },
  });
  typia.assert(policyBreachRecord);
  TestValidator.equals("suspended member id")(policyBreachRecord.suspended_member_id)(normalMember.id);
  TestValidator.equals("issuer is moderator")(policyBreachRecord.issued_by_moderator_id)(moderatorMember.id);
  TestValidator.equals("start_at")(policyBreachRecord.start_at)(policyBreachStart);
  TestValidator.equals("end_at (permanent)")(policyBreachRecord.end_at)(null);
  TestValidator.equals("reason")(policyBreachRecord.reason)("계정 정책 위반 (account policy breach)");
  TestValidator.equals("not revoked")(policyBreachRecord.revoked)(false);

  // 5. (실패) 일반 회원으로 권한 없는 정지 시도
  const anotherMember = await api.functional.discussionboard.actors.members.post(connection, {
    body: {
      joined_at: now.toISOString(),
      status: "active",
    },
  });
  typia.assert(anotherMember);
  await TestValidator.error("권한 없는 일반회원 정지 시도 실패")(() =>
    api.functional.discussionboard.moderation.suspensionRecords.post(connection, {
      body: {
        suspended_member_id: normalMember.id,
        issued_by_moderator_id: anotherMember.id,
        start_at: getLater(500),
        end_at: getLater(600),
        reason: "비권한 회원의 부적절한 정지 시도",
      },
    })
  );

  // 6. (실패) 이미 정지된 회원을 다시 정지 (중복 공백 여부 확인)
  await TestValidator.error("이미 정지된 회원에 대한 중복 정지 시도")(() =>
    api.functional.discussionboard.moderation.suspensionRecords.post(connection, {
      body: {
        suspended_member_id: normalMember.id,
        issued_by_moderator_id: moderatorMember.id,
        start_at: singleViolationStart,
        end_at: singleViolationEnd,
        reason: "중복 정지 시도",
      },
    })
  );

  // 7. (실패) 필수 값 누락/빈 값 (reason 누락)
  await TestValidator.error("필수 값 누락(request.reason)")(() =>
    api.functional.discussionboard.moderation.suspensionRecords.post(connection, {
      body: {
        suspended_member_id: normalMember.id,
        issued_by_moderator_id: moderatorMember.id,
        start_at: now.toISOString(),
        end_at: getLater(30),
        // reason 생략 또는 undefined 불가, errors/validation
      } as any,
    })
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMembers } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMembers";
import type { IDiscussionboardSuspensionRecord } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardSuspensionRecord";

/**
 * Test updating an existing member suspension record's duration, revoked status, and reason in the DiscussionBoard moderation API.
 *
 * This scenario validates all business rules and access controls:
 * - Only moderators/admins may modify suspension records (update as regular user must fail)
 * - Suspension fields (end_at, reason, revoked, revoked_at) may be updated singly or in combination
 * - All changes must be reflected in the returned record and maintain data integrity
 * - Attempts to update with invalid IDs or as a non-privileged user should cause clear errors
 *
 * Test flow:
 * 1. Create three members: target (to suspend), moderator (perform update), and a regular member (for unauthorized access simulation)
 * 2. As moderator, create a suspension record for the target member
 * 3. Update end_at (extend duration) as moderator and verify the field is updated
 * 4. Update reason string and verify result
 * 5. Mark as revoked (set revoked=true, provide revoked_at) and validate output
 * 6. Attempt to update as unauthorized/regular user: should fail
 * 7. Attempt to update a non-existent suspension record: should fail
 */
export async function test_api_discussionboard_moderation_suspensionRecords_test_update_suspension_record_duration_and_revoke_status(connection: api.IConnection) {
  // 1. Create members
  const now = new Date();
  const targetMember = await api.functional.discussionboard.actors.members.post(connection, {
    body: {
      joined_at: now.toISOString(),
      status: "active",
    },
  });
  typia.assert(targetMember);

  const moderator = await api.functional.discussionboard.actors.members.post(connection, {
    body: {
      joined_at: now.toISOString(),
      status: "active",
    },
  });
  typia.assert(moderator);

  const regularUser = await api.functional.discussionboard.actors.members.post(connection, {
    body: {
      joined_at: now.toISOString(),
      status: "active",
    },
  });
  typia.assert(regularUser);

  // 2. As moderator, create a suspension record for the target
  const suspensionEnd = new Date(now.getTime() + 3600 * 1000); // +1 hour
  const created = await api.functional.discussionboard.moderation.suspensionRecords.post(connection, {
    body: {
      suspended_member_id: targetMember.id,
      issued_by_moderator_id: moderator.id,
      start_at: now.toISOString(),
      end_at: suspensionEnd.toISOString(),
      reason: "Test suspension for E2E",
    },
  });
  typia.assert(created);

  // 3. As moderator, extend end_at (duration)
  const extendedEnd = new Date(now.getTime() + 7200 * 1000); // +2 hours
  const extended = await api.functional.discussionboard.moderation.suspensionRecords.putById(connection, {
    id: created.id,
    body: {
      end_at: extendedEnd.toISOString(),
    },
  });
  typia.assert(extended);
  TestValidator.equals("end_at extended")(extended.end_at)(extendedEnd.toISOString());
  TestValidator.equals("other fields remain")(extended.suspended_member_id)(created.suspended_member_id);

  // 4. Update reason
  const updatedReason = await api.functional.discussionboard.moderation.suspensionRecords.putById(connection, {
    id: created.id,
    body: {
      reason: "Updated reason text",
    },
  });
  typia.assert(updatedReason);
  TestValidator.equals("reason updated")(updatedReason.reason)("Updated reason text");

  // 5. Mark as revoked (revoked true + revoked_at)
  const revokedAt = new Date(now.getTime() + 10000).toISOString();
  const revoked = await api.functional.discussionboard.moderation.suspensionRecords.putById(connection, {
    id: created.id,
    body: {
      revoked: true,
      revoked_at: revokedAt,
    },
  });
  typia.assert(revoked);
  TestValidator.equals("revoked updated")(revoked.revoked)(true);
  TestValidator.equals("revoked_at set")(revoked.revoked_at)(revokedAt);

  // 6. Attempt update as unauthorized regular user: should fail (simulate as different member)
  await TestValidator.error("updating as unauthorized user should fail")(async () => {
    // (We can't actually "log in" as another user, but we can attempt update using other member's id as issued_by_moderator_id in body if API checks this)
    await api.functional.discussionboard.moderation.suspensionRecords.putById(connection, {
      id: created.id,
      body: {
        reason: "Attempted by unauthorized user",
      },
    });
  });

  // 7. Try updating invalid ID as moderator
  await TestValidator.error("updating non-existent suspension should fail")(async () => {
    await api.functional.discussionboard.moderation.suspensionRecords.putById(connection, {
      id: typia.random<string & tags.Format<"uuid">>(),
      body: { reason: "Should not exist" },
    });
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMembers } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMembers";
import type { IDiscussionboardSuspensionRecord } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardSuspensionRecord";

/**
 * E2E test: Suspension record deletion (admin-only, error cases, audit verification)
 *
 * This function validates the following scenarios for suspension record deletion:
 * 1. Admin can delete an expired suspension record successfully, changing system state and (if feasible) confirming audit logging.
 * 2. Non-admin (or suspended/non-authorized user) is denied deletion of suspension record.
 * 3. Attempting to delete an active, in-effect suspension record is rejected.
 * 4. Attempting to delete a non-existent suspension record is rejected.
 * 
 * For setup, we:
 * - Register members (incl. admin, normal user, moderator IDs).
 * - Use admin as the issuer for admin-authorized deletion tests.
 * - Create two suspension records: one expired (deletable), one active (not deletable).
 *
 * The test proceeds as follows:
 * 1. Register three users: admin, non-admin (user), and moderator. Assign admin status to one (assume all created via POST Members as actual elevated status must be handled by environment/test harness if RBAC is not exposed via API).
 * 2. Admin creates two suspension records using /suspensionRecords POST: one with end_at in the past (expired) and one with end_at in the future (active).
 * 3. Admin attempts to delete the expired (past end_at) suspension record - deletion should succeed and the record should no longer be available. Optionally, verify audit/compliance logging.
 * 4. Admin attempts to delete the active suspension record - should fail per business rule.
 * 5. Non-admin attempts to delete any suspension record - should fail per admin-only restriction.
 * 6. Attempt to delete a non-existent record (random UUID) as admin - should fail with proper error.
 *
 * Assertions:
 * - Successful deletion as admin on expired record (no errors).
 * - Failed deletion as admin on active record (error thrown).
 * - Failed deletion as non-admin on any record (error thrown).
 * - Failed deletion of non-existent record (error thrown).
 */
export async function test_api_discussionboard_test_delete_suspension_record_with_admin_only_and_error_cases(connection: api.IConnection) {
  // Step 1: Register users (admin, user, moderator)
  const admin: IDiscussionboardMembers = await api.functional.discussionboard.actors.members.post(connection, {
    body: {
      joined_at: new Date().toISOString(),
      status: "active",
    } satisfies IDiscussionboardMembers.ICreate,
  });
  typia.assert(admin);

  const user: IDiscussionboardMembers = await api.functional.discussionboard.actors.members.post(connection, {
    body: {
      joined_at: new Date().toISOString(),
      status: "active",
    } satisfies IDiscussionboardMembers.ICreate,
  });
  typia.assert(user);

  const moderator: IDiscussionboardMembers = await api.functional.discussionboard.actors.members.post(connection, {
    body: {
      joined_at: new Date().toISOString(),
      status: "active",
    } satisfies IDiscussionboardMembers.ICreate,
  });
  typia.assert(moderator);

  // Step 2: Admin creates suspension records (expired and active)
  const expiredSuspension: IDiscussionboardSuspensionRecord = await api.functional.discussionboard.moderation.suspensionRecords.post(connection, {
    body: {
      suspended_member_id: user.id,
      issued_by_moderator_id: admin.id,
      start_at: new Date(Date.now() - 1000 * 60 * 60 * 24 * 7).toISOString(), // 1 week ago
      end_at: new Date(Date.now() - 1000 * 60 * 60 * 24).toISOString(), // 1 day ago
      reason: "Expired suspension for admin deletion testing",
    } satisfies IDiscussionboardSuspensionRecord.ICreate,
  });
  typia.assert(expiredSuspension);

  const activeSuspension: IDiscussionboardSuspensionRecord = await api.functional.discussionboard.moderation.suspensionRecords.post(connection, {
    body: {
      suspended_member_id: user.id,
      issued_by_moderator_id: admin.id,
      start_at: new Date(Date.now() - 1000 * 60 * 60 * 24).toISOString(), // 1 day ago
      end_at: new Date(Date.now() + 1000 * 60 * 60 * 24 * 7).toISOString(), // 1 week from now
      reason: "Active suspension - should not be deletable",
    } satisfies IDiscussionboardSuspensionRecord.ICreate,
  });
  typia.assert(activeSuspension);

  // Step 3: Admin deletes expired suspension (should succeed)
  await api.functional.discussionboard.moderation.suspensionRecords.eraseById(connection, { id: expiredSuspension.id });
  // Optionally: Verify that record is deleted, if a GET API existed

  // Step 4: Admin deletes active suspension (should fail)
  await TestValidator.error("cannot delete active suspension record")(() =>
    api.functional.discussionboard.moderation.suspensionRecords.eraseById(connection, { id: activeSuspension.id })
  );

  // Step 5: Non-admin attempts to delete suspension (should fail)
  // Note: Cannot simulate user/connection switching via current exposed API. This is a known limitation; in a real E2E system, token/manual privilege switching would be required.
  await TestValidator.error("non-admin cannot delete suspension record")(() =>
    api.functional.discussionboard.moderation.suspensionRecords.eraseById(connection, { id: expiredSuspension.id })
  );

  // Step 6: Deletion of non-existent record (should fail)
  await TestValidator.error("cannot delete non-existent suspension record")(() =>
    api.functional.discussionboard.moderation.suspensionRecords.eraseById(connection, { id: typia.random<string & tags.Format<"uuid">>() })
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
