/**
 * Test retrieval of a single board by ID, including both success and not-found scenarios.
 *
 * This test validates both the happy path (fetching an existing board by UUID)
 * and the error path (attempting to fetch a board that does not exist).
 *
 * 1. Create a new board using the POST endpoint, filling in all required fields.
 * 2. Immediately fetch the board using its returned ID.
 * 3. Assert that all non-audit fields match between the created and fetched objects.
 * 4. Attempt to fetch a board with a random/invalid UUID and verify that an error is thrown.
 */
export async function test_api_discussionboard_boards_boards_getById_success_and_failure(
  connection: api.IConnection,
) {
  // 1. Create a new board
  const createInput: DiscussionboardBoard.ICreate = {
    discussionboard_category_id: typia.random<string & tags.Format<"uuid">>(),
    code: `BOARD_${RandomGenerator.alphaNumeric(6)}`,
    name: RandomGenerator.paragraph()(1),
    description: RandomGenerator.paragraph()(),
    is_active: true,
  };
  const created: DiscussionboardBoard = await api.functional.discussionboard.boards.boards.post(connection, {
    body: createInput,
  });
  typia.assert(created);

  // 2. Retrieve the board by its ID
  const fetched: DiscussionboardBoard = await api.functional.discussionboard.boards.boards.getById(connection, {
    id: created.id,
  });
