  TestValidator.equals("discussionboard_category_id matches")(fetched.discussionboard_category_id)(created.discussionboard_category_id);
  TestValidator.equals("code matches")(fetched.code)(created.code);
  TestValidator.equals("name matches")(fetched.name)(created.name);
  TestValidator.equals("description matches")(fetched.description)(created.description);
  TestValidator.equals("is_active matches")(fetched.is_active)(created.is_active);

  // 4. Not-found: use a random UUID
  const invalidId: string = typia.random<string & tags.Format<"uuid">>();
  TestValidator.error("should throw for non-existent board")(
    async () => {
      await api.functional.discussionboard.boards.boards.getById(connection, { id: invalidId });
    },
  );
}

