import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMembers } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMembers";
import type { IDiscussionboardComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardComment";
import type { IDiscussionboardCommentReport } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardCommentReport";
import type { IPageDiscussionboardCommentReport } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageDiscussionboardCommentReport";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Test listing and searching comment reports as a moderator/admin using multiple filtering criteria, pagination, and sorting.
 *
 * Scenario includes:
 * - Filtering by reported comment ID, reporter member ID, reason
 * - Pagination (page number, limit)
 * - Edge cases: empty results, max limit, invalid values
 * - Verifying accurate filtering, correct pagination metadata, permissions enforcement
 * - Unauthorized user should be restricted
 *
 * Steps:
 * 1. Create two board members (reporter and another member)
 * 2. Reporter member creates a post and a comment (no /thread/posts API, so simulate minimal with post_id as uuid)
 * 3. Another member creates a comment on same post
 * 4. Submit several reports (different reasons, reporter/member ids)
 * 5. As admin (assume default test connection is admin), test listing without filters returns all
 * 6. Filter by comment id, reporter id, reason; check returned count, all fields match filters
 * 7. Paginate (page/limit), verify metadata matches
 * 8. Edge: No results (non-existent filter)
 * 9. Edge: Very large limit (e.g. 100)
 * 10. Edge: Invalid filter values (invalid uuids)
 * 11. (Permission) Call as non-admin/user should error (cannot be implemented with provided functions)
 */
export async function test_api_discussionboard_test_list_comment_reports_with_various_filters(connection: api.IConnection) {
  // --- Setup test data: members, comments, reports ---
  // 1. Create reporter member
  const reporter: IDiscussionboardMembers = await api.functional.discussionboard.actors.members.post(connection, {
    body: {
      joined_at: new Date().toISOString(),
      status: 'active',
    },
  });
  typia.assert(reporter);
  // 2. Create target post as random uuid (simulate, since only comment creation supported)
  const post_id = typia.random<string & tags.Format<'uuid'>>();
  // 3. Reporter leaves a comment (to be reported)
  const comment: IDiscussionboardComment = await api.functional.discussionboard.threads.comments.post(connection, {
    body: {
      discussionboard_post_id: post_id,
      discussionboard_member_id: reporter.id,
      body: 'Offending comment',
    },
  });
  typia.assert(comment);
  // 4. Non-reporter member
  const nonreporter: IDiscussionboardMembers = await api.functional.discussionboard.actors.members.post(connection, {
    body: {
      joined_at: new Date().toISOString(),
      status: 'active',
    },
  });
  typia.assert(nonreporter);
  // 5. Another comment
  const nonreported_comment: IDiscussionboardComment = await api.functional.discussionboard.threads.comments.post(connection, {
    body: {
      discussionboard_post_id: post_id,
      discussionboard_member_id: nonreporter.id,
      body: "Harmless reply"
    },
  });
  typia.assert(nonreported_comment);
  // 6. Create multiple reports for the comment (with different reasons, members)
  const reason1 = "Spam";
  const reason2 = "Abuse";
  const report1: IDiscussionboardCommentReport = await api.functional.discussionboard.interactions.commentReports.post(connection, {
    body: {
      discussionboard_comment_id: comment.id,
      reason: reason1
    },
  });
  typia.assert(report1);
  const report2: IDiscussionboardCommentReport = await api.functional.discussionboard.interactions.commentReports.post(connection, {
    body: {
      discussionboard_comment_id: comment.id,
      reason: reason2
    },
  });
  typia.assert(report2);
  // Also create a report for non-offending comment
  const report3: IDiscussionboardCommentReport = await api.functional.discussionboard.interactions.commentReports.post(connection, {
    body: {
      discussionboard_comment_id: nonreported_comment.id,
      reason: "Other"
    },
  });
  typia.assert(report3);
  // --- 1. List all reports (admin role, no filters) ---
  const allReports = await api.functional.discussionboard.interactions.commentReports.patch(connection, { body: {} });
  typia.assert(allReports);
  TestValidator.predicate("empty result returns at least 3 reports")(
    allReports.data.length >= 3
  );
  // 2. Filter by discussionboard_comment_id (should match only reports for 'comment')
  const filterByComment = await api.functional.discussionboard.interactions.commentReports.patch(connection, {
    body: { discussionboard_comment_id: comment.id },
  });
  typia.assert(filterByComment);
  TestValidator.predicate("only filtered comment")(
    filterByComment.data.every((r) => r.discussionboard_comment_id === comment.id)
  );
  // 3. Filter by reporter id (simulate: always admin in test, but check with at least one real member id)
  const filterByReporter = await api.functional.discussionboard.interactions.commentReports.patch(connection, {
    body: { discussionboard_member_id: reporter.id },
  });
  typia.assert(filterByReporter);
  TestValidator.predicate("reporter id match")(
    filterByReporter.data.every((r) => r.discussionboard_member_id === reporter.id)
  );
  // 4. Filter by reason
  const filterByReason = await api.functional.discussionboard.interactions.commentReports.patch(connection, {
    body: { reason: reason1 },
  });
  typia.assert(filterByReason);
  TestValidator.predicate("reason matches")(
    filterByReason.data.every((r) => r.reason === reason1)
  );
  // 5. Paginate: limit 1
  const paginated = await api.functional.discussionboard.interactions.commentReports.patch(connection, {
    body: { limit: 1 },
  });
  typia.assert(paginated);
  TestValidator.equals("one result returned")(paginated.data.length)(1);
  TestValidator.equals("pagination.limit")(paginated.pagination.limit)(1);
  // 6. Paginate: limit 100 (max allowed or large batch)
  const maxPaginated = await api.functional.discussionboard.interactions.commentReports.patch(connection, {
    body: { limit: 100 },
  });
  typia.assert(maxPaginated);
  TestValidator.predicate("limit at most 100")(
    maxPaginated.data.length <= 100
  );
  // 7. Page number (if >1 pages exist)
  if (allReports.pagination.pages > 1) {
    const page2 = await api.functional.discussionboard.interactions.commentReports.patch(connection, {
      body: { page: 2, limit: 1 },
    });
    typia.assert(page2);
    TestValidator.equals("pagination.current")(page2.pagination.current)(2);
  }
  // 8. Edge: no results (random uuid filter)
  const noResult = await api.functional.discussionboard.interactions.commentReports.patch(connection, {
    body: { discussionboard_comment_id: typia.random<string & tags.Format<'uuid'>>() },
  });
  typia.assert(noResult);
  TestValidator.equals("no results for non-existent id")(noResult.data.length)(0);
  // 9. Edge: invalid filter (invalid uuid)
  await TestValidator.error("invalid uuid should error")(async () => {
    await api.functional.discussionboard.interactions.commentReports.patch(connection, {
      body: { discussionboard_comment_id: "invalid-uuid" as any },
    });
  });
  // 10. Permission: should restrict regular user (simulate by switching connection role if API supported)
  // Not implemented due to lack of user roles in provided API
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMembers } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMembers";
import type { IDiscussionboardComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardComment";
import type { IDiscussionboardCommentReport } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardCommentReport";

/**
 * Test retrieval of a comment report by its unique ID under various valid and invalid conditions.
 *
 * Business context:
 * Ensures that only the member who filed the report can retrieve it. Validates correct behavior for error scenarios including forbidden access (non-reporter), invalid UUID, and non-existent/deleted report IDs.
 * Note: Since authentication and privilege elevation APIs for admins/moderators are not available, admin-side access is not tested here.
 *
 * Steps:
 * 1. Register a reporting member.
 * 2. Create a comment as the reporter (must use valid dummy post ID).
 * 3. File a comment report by the reporter.
 * 4. Retrieve the report by ID as reporter (expect success, strict equality).
 * 5. Register a second member (not the reporter).
 * 6. Attempt to fetch the report as a non-reporter (expect forbidden error).
 * 7. Attempt fetch with invalid UUID format (expect error).
 * 8. Attempt fetch with random valid but unused UUID (expect not found error).
 */
export async function test_api_discussionboard_test_get_comment_report_details_valid_and_invalid_id(
  connection: api.IConnection,
) {
  // 1. Register a reporting member
  const reportingMember = await api.functional.discussionboard.actors.members.post(connection, {
    body: {
      joined_at: new Date().toISOString(),
      status: "active",
    } satisfies IDiscussionboardMembers.ICreate,
  });
  typia.assert(reportingMember);

  // 2. Create a comment authored by the reporting member
  const dummyPostId = typia.random<string & tags.Format<"uuid">>();
  const comment = await api.functional.discussionboard.threads.comments.post(connection, {
    body: {
      discussionboard_post_id: dummyPostId,
      discussionboard_member_id: reportingMember.id,
      body: "This is a comment to be reported.",
      parent_id: null,
    } satisfies IDiscussionboardComment.ICreate,
  });
  typia.assert(comment);

  // 3. File a comment report
  const report = await api.functional.discussionboard.interactions.commentReports.post(connection, {
    body: {
      discussionboard_comment_id: comment.id,
      reason: "Spam or inappropriate content.",
    } satisfies IDiscussionboardCommentReport.ICreate,
  });
  typia.assert(report);

  // 4. Retrieve the report by ID as reporting member (positive path)
  const fetched = await api.functional.discussionboard.interactions.commentReports.getById(connection, {
    id: report.id,
  });
  typia.assert(fetched);
  TestValidator.equals("report fetched matches report filed")(fetched)(report);

  // 5. Register a second member (non-reporter)
  const nonReporter = await api.functional.discussionboard.actors.members.post(connection, {
    body: {
      joined_at: new Date().toISOString(),
      status: "active",
    } satisfies IDiscussionboardMembers.ICreate,
  });
  typia.assert(nonReporter);

  // 6. Attempt retrieval by non-reporting member (should error/forbidden)
  // In base API, user context is simulated through connection; here we just document intended role logic.
  TestValidator.error("non-reporter forbidden to fetch report")(
    async () => {
      await api.functional.discussionboard.interactions.commentReports.getById(connection, {
        id: report.id,
      });
    },
  );

  // 7. Attempt to fetch with invalid UUID format
  TestValidator.error("invalid UUID format fails")(
    async () => {
      await api.functional.discussionboard.interactions.commentReports.getById(connection, {
        id: "invalid-uuid-format" as any,
      });
    },
  );

  // 8. Attempt to fetch with random, unused (non-existent) UUID
  TestValidator.error("not found with unused UUID")(
    async () => {
      await api.functional.discussionboard.interactions.commentReports.getById(connection, {
        id: typia.random<string & tags.Format<"uuid">>(),
      });
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMembers } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMembers";
import type { IDiscussionboardComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardComment";
import type { IDiscussionboardCommentReport } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardCommentReport";

/**
 * Test the creation of comment reports via POST /discussionboard/interactions/commentReports, covering:
 *   - Valid report creation by a regular member
 *   - Failures: exceeding daily quota (over 10 reports), missing required fields, 
 *     reporting non-existent or deleted comment, attempts by non-active/suspended members,
 *     and duplicate same-day report on same comment
 *   - Output verification for correctness of returned entity
 *
 * Steps:
 * 1. Create a member (reporter)
 * 2. Create a comment for reporting
 * 3. (SUCCESS) Reporter submits a valid report
 *     - Check: response contains correct reporter, comment, and timestamp
 * 4. (FAIL) Attempt report for non-existent comment ID
 * 5. (FAIL) Attempt report for (soft-)deleted comment
 * 6. (FAIL) Exceed daily report quota: submit 10 reports, then one more -- last must fail
 * 7. (FAIL) Suspended member attempts report (must fail)
 * 8. (FAIL) Duplicate report on same comment by same member, same day
 */
export async function test_api_discussionboard_test_create_comment_report_with_valid_and_invalid_input(
  connection: api.IConnection,
) {
  // 1. Create a member (reporter)
  const member = await api.functional.discussionboard.actors.members.post(
    connection,
    {
      body: {
        joined_at: new Date().toISOString(),
        status: "active",
      } satisfies IDiscussionboardMembers.ICreate,
    },
  );
  typia.assert(member);

  // 2. Create a comment for reporting
  const comment = await api.functional.discussionboard.threads.comments.post(
    connection,
    {
      body: {
        discussionboard_post_id: typia.random<string & tags.Format<"uuid">>(),
        discussionboard_member_id: member.id,
        body: "Test comment for reporting.",
      } satisfies IDiscussionboardComment.ICreate,
    },
  );
  typia.assert(comment);

  // 3. SUCCESS: Reporter submits a valid report
  const reason = "Spam or inappropriate content";
  const report = await api.functional.discussionboard.interactions.commentReports.post(
    connection,
    {
      body: {
        discussionboard_comment_id: comment.id,
        reason,
      } satisfies IDiscussionboardCommentReport.ICreate,
    },
  );
  typia.assert(report);
  TestValidator.equals("reporter matches")(report.discussionboard_member_id)(member.id);
  TestValidator.equals("comment matches")(report.discussionboard_comment_id)(comment.id);
  TestValidator.predicate("created_at is present")(!!report.created_at);

  // 4. FAIL: Non-existent comment ID
  await TestValidator.error("should fail: report non-existent comment")(
    async () =>
      await api.functional.discussionboard.interactions.commentReports.post(
        connection,
        {
          body: {
            discussionboard_comment_id: typia.random<string & tags.Format<"uuid">>(),
            reason: "Non-existent comment",
          } satisfies IDiscussionboardCommentReport.ICreate,
        },
      ),
  );

  // 5. FAIL: Deleted comment
  // Simulate by creating a comment and assuming deleted_at would make it ineligible
  const deletedComment = await api.functional.discussionboard.threads.comments.post(
    connection,
    {
      body: {
        discussionboard_post_id: typia.random<string & tags.Format<"uuid">>(),
        discussionboard_member_id: member.id,
        body: "Deleted comment.",
      } satisfies IDiscussionboardComment.ICreate,
    },
  );
  typia.assert(deletedComment);
  // Pretend this comment is now deleted (business logic would prevent report)
  await TestValidator.error("should fail: report deleted comment")(
    async () =>
      await api.functional.discussionboard.interactions.commentReports.post(
        connection,
        {
          body: {
            discussionboard_comment_id: deletedComment.id,
            reason: "Report deleted comment",
          } satisfies IDiscussionboardCommentReport.ICreate,
        },
      ),
  );

  // 6. FAIL: Exceed daily report quota: submit 10 valid reports, then one more (should fail)
  const quotaReports = [] as IDiscussionboardComment[];
  for (let i = 0; i < 10; ++i) {
    const toReport = await api.functional.discussionboard.threads.comments.post(
      connection,
      {
        body: {
          discussionboard_post_id: typia.random<string & tags.Format<"uuid">>(),
          discussionboard_member_id: member.id,
          body: `Quota test comment ${i}`,
        } satisfies IDiscussionboardComment.ICreate,
      },
    );
    typia.assert(toReport);
    quotaReports.push(toReport);
    const reportResult = await api.functional.discussionboard.interactions.commentReports.post(
      connection,
      {
        body: {
          discussionboard_comment_id: toReport.id,
          reason: `Reason ${i}`,
        } satisfies IDiscussionboardCommentReport.ICreate,
      },
    );
    typia.assert(reportResult);
  }
  // Attempt 11th report (should fail)
  const extraComment = await api.functional.discussionboard.threads.comments.post(
    connection,
    {
      body: {
        discussionboard_post_id: typia.random<string & tags.Format<"uuid">>(),
        discussionboard_member_id: member.id,
        body: "11th quota comment",
      } satisfies IDiscussionboardComment.ICreate,
    },
  );
  typia.assert(extraComment);
  await TestValidator.error("should fail: exceed 10 reports/day")(
    async () =>
      await api.functional.discussionboard.interactions.commentReports.post(
        connection,
        {
          body: {
            discussionboard_comment_id: extraComment.id,
            reason: "Exceed quota",
          } satisfies IDiscussionboardCommentReport.ICreate,
        },
      ),
  );

  // 7. FAIL: Suspended member attempts to report
  const suspended = await api.functional.discussionboard.actors.members.post(
    connection,
    {
      body: {
        joined_at: new Date().toISOString(),
        status: "suspended",
      } satisfies IDiscussionboardMembers.ICreate,
    },
  );
  typia.assert(suspended);
  const suspendedComment = await api.functional.discussionboard.threads.comments.post(
    connection,
    {
      body: {
        discussionboard_post_id: typia.random<string & tags.Format<"uuid">>(),
        discussionboard_member_id: suspended.id,
        body: "Comment for suspended user report test.",
      } satisfies IDiscussionboardComment.ICreate,
    },
  );
  typia.assert(suspendedComment);
  await TestValidator.error("should fail: suspended member cannot report")(
    async () =>
      await api.functional.discussionboard.interactions.commentReports.post(
        connection,
        {
          body: {
            discussionboard_comment_id: suspendedComment.id,
            reason: "Test by suspended member",
          } satisfies IDiscussionboardCommentReport.ICreate,
        },
      ),
  );

  // 8. FAIL: Duplicate report for same comment by same member, same day
  const dupeComment = await api.functional.discussionboard.threads.comments.post(
    connection,
    {
      body: {
        discussionboard_post_id: typia.random<string & tags.Format<"uuid">>(),
        discussionboard_member_id: member.id,
        body: "Comment to test duplicate report",
      } satisfies IDiscussionboardComment.ICreate,
    },
  );
  typia.assert(dupeComment);
  const dupeReport = await api.functional.discussionboard.interactions.commentReports.post(
    connection,
    {
      body: {
        discussionboard_comment_id: dupeComment.id,
        reason: "First report",
      } satisfies IDiscussionboardCommentReport.ICreate,
    },
  );
  typia.assert(dupeReport);
  await TestValidator.error("should fail: duplicate report on same comment by same user")(
    async () =>
      await api.functional.discussionboard.interactions.commentReports.post(
        connection,
        {
          body: {
            discussionboard_comment_id: dupeComment.id,
            reason: "Duplicate report",
