  typia.assert(pageRes1);
  pageRes1.data.forEach(w => {
    TestValidator.equals("warned_member_id 매치")(w.warned_member_id)(member2.id);
  });
  TestValidator.predicate("2건 반환")(pageRes1.data.length === 2);

  // 5-2. issued_by_moderator_id로 필터
  const pageRes2 = await api.functional.discussionboard.moderation.warningRecords.patch(connection, {
    body: {
      issued_by_moderator_id: moderator.discussionboard_member_id,
      limit: 10,
    },
  });
  typia.assert(pageRes2);
  pageRes2.data.forEach(w => {
    TestValidator.equals("발행자 일치")(w.issued_by_moderator_id)(moderator.discussionboard_member_id);
  });
  TestValidator.predicate("3건 반환")(pageRes2.data.length === 3);

  // 5-3. created_after/created_before 범위 내만 필터 (warning2, warning3 구간)
  const createdAfter = new Date(Date.now() - 2.5 * 24 * 60 * 60 * 1000).toISOString();
  const createdBefore = new Date(Date.now() - 0.5 * 24 * 60 * 60 * 1000).toISOString();
  const pageRes3 = await api.functional.discussionboard.moderation.warningRecords.patch(connection, {
    body: {
      created_after: createdAfter,
      created_before: createdBefore,
      limit: 10,
    },
  });
  typia.assert(pageRes3);
  pageRes3.data.forEach(w => {
    TestValidator.predicate("범위 내 created_at인지")(
      w.created_at >= createdAfter && w.created_at <= createdBefore,
    );
  });

  // 5-4. 페이지네이션 (limit=1) 두번째 페이지
  const pageRes4 = await api.functional.discussionboard.moderation.warningRecords.patch(connection, {
    body: {
      page: 2,
      limit: 1,
    },
  });
  typia.assert(pageRes4);
  TestValidator.equals("페이지 데이터 개수")(pageRes4.data.length)(1);
  TestValidator.equals("페이지 번호")(pageRes4.pagination.current)(2);

  // 6. 빈 결과: 존재하지 않는 멤버 ID
  const pageRes5 = await api.functional.discussionboard.moderation.warningRecords.patch(connection, {
    body: {
      warned_member_id: typia.random<string & tags.Format<"uuid">>(),
      page: 1,
      limit: 5,
    },
  });
  typia.assert(pageRes5);
  TestValidator.equals("빈 결과 반환")(pageRes5.data.length)(0);

  // 7. 잘못된 uuid 포맷 -> 에러 발생
  await TestValidator.error("warned_member_id 잘못된 uuid 포맷은 에러")(async () => {
    await api.functional.discussionboard.moderation.warningRecords.patch(connection, {
      body: {
        warned_member_id: "NOT_UUID",
      },
    });
  });

  // 8. 권한 없는 멤버(멤버2)가 접근 시 권한 에러
  await TestValidator.error("일반 멤버는 접근 금지")(async () => {
    // 실제 환경에서는 connection에 멤버2의 인증정보를 세팅해야 함 (여기선 connection 객체를 그대로 사용)
    await api.functional.discussionboard.moderation.warningRecords.patch(connection, {
      body: {
        limit: 5,
      },
    });
