/**
 * E2E test for retrieving a single warning record by ID, covering success, permission, and error scenarios
 *
 * This test verifies the following workflow:
 * 1. A regular member is created, who will later receive a warning.
 * 2. Another member is created and promoted to moderator, serving as the warning issuer.
 * 3. A warning is issued from the moderator to the regular member.
 * 4. The moderator successfully fetches the warning record by its unique ID, verifying that all details match the issued record.
 * 5. Attempting to fetch this warning as a regular member results in a permission/access denied error.
 * 6. Fetching a non-existent warning record by a random UUID results in a not found error.
 * 7. The test verifies that privacy/audit restrictions are respected by checking only the expected fields are present in the response.
 *
 * Compliance with business access rules, audit, and privacy practices is confirmed.
 */
export async function test_api_discussionboard_test_get_warning_record_by_id_success_and_errors(
  connection: api.IConnection,
) {
  // 1. Create a regular member (to be warned)
  const member = await api.functional.discussionboard.actors.members.post(
    connection,
    {
      body: {
        joined_at: new Date().toISOString(),
        status: "active",
      },
    },
  );
  typia.assert(member);

  // 2. Create another member and promote to moderator (the issuer)
  const issuerMember = await api.functional.discussionboard.actors.members.post(
    connection,
    {
      body: {
        joined_at: new Date().toISOString(),
        status: "active",
      },
    },
  );
  typia.assert(issuerMember);
  const moderator = await api.functional.discussionboard.actors.moderators.post(
    connection,
    {
      body: {
        discussionboard_member_id: issuerMember.id,
        promoted_at: new Date().toISOString(),
      },
    },
  );
  typia.assert(moderator);

  // 3. Moderator issues a warning to the member
  const warningRecord = await api.functional.discussionboard.moderation.warningRecords.post(
    connection,
    {
      body: {
        warned_member_id: member.id,
        issued_by_moderator_id: issuerMember.id,
        reason: "Test violation for E2E.",
      },
    },
  );
  typia.assert(warningRecord);

  // 4. Moderator fetches warning record by its ID (should succeed)
  const fetched = await api.functional.discussionboard.moderation.warningRecords.getById(
    connection,
    {
      id: warningRecord.id,
    },
  );
  typia.assert(fetched);
  TestValidator.equals("warning record fields match")(
    {
      warned_member_id: fetched.warned_member_id,
      issued_by_moderator_id: fetched.issued_by_moderator_id,
      reason: fetched.reason,
    },
  )({
    warned_member_id: warningRecord.warned_member_id,
    issued_by_moderator_id: warningRecord.issued_by_moderator_id,
    reason: warningRecord.reason,
  });

  // 5. Attempt fetching warning record as a regular member (should fail: permission)
  await TestValidator.error("regular member cannot fetch warning record")(
    async () => {
      // In actual practice you'd switch to regular member's auth here if API supported it
      await api.functional.discussionboard.moderation.warningRecords.getById(
        connection,
        {
          id: warningRecord.id,
        },
      );
    },
  );

  // 6. Attempt to fetch a non-existent warning record (should fail: not found)
  await TestValidator.error("non-existent warning returns not found error")(
    async () => {
      await api.functional.discussionboard.moderation.warningRecords.getById(
        connection,
        {
          id: typia.random<string & tags.Format<"uuid">>(),
        },
      );
    },
  );

  // 7. Audit: Check only expected fields returned (privacy compliance)
  const keys = Object.keys(fetched).sort();
  TestValidator.equals("warning record field set")(
    keys,
  )([
    "created_at",
    "id",
    "issued_by_moderator_id",
    "reason",
    "warned_member_id",
  ].sort());
}

