import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMembers } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMembers";
import type { DiscussionBoardModerators } from "@ORGANIZATION/PROJECT-api/lib/structures/DiscussionBoardModerators";
import type { IDiscussionboardWarningRecord } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardWarningRecord";

/**
 * E2E test for deleting a warning record from the discussion board moderation module.
 *
 * This test verifies that only users with sufficient privilege (admin; possibly senior moderator) can successfully delete warning records, and:
 * - Deletions (soft/hard) are permitted for these users and forbidden for others
 * - All required business rules around authorization are enforced by attempting deletion as admin, moderator, outsider, and for a random nonexistent record
 * - Aspects like audit logging and special escalation protections are mentioned in scenario, but omitted since there are no corresponding APIs for audit/query/or flagging in escalation sequences
 *
 * Steps:
 * 1. Create several board members (including one to be warned, others to act as normal users, one as moderator, one as admin)
 * 2. Promote one member to moderator and one to admin via the moderators endpoint
 * 3. Have the admin issue a warning to the member, creating a warning record
 * 4. Delete the warning record as admin – should succeed
 * 5. Attempt to delete the same warning record again as moderator – should fail with authorization error
 * 6. Attempt to delete as a non-moderator/non-admin (outsider) – should fail
 * 7. Attempt to delete a record with a random (nonexistent) ID – should fail with not found error
 */
export async function test_api_discussionboard_test_delete_warning_record_authorized_and_blocked_cases(connection: api.IConnection) {
  // 1. Create four members: toWarn, admin, moderator, outsider
  const toWarn = await api.functional.discussionboard.actors.members.post(connection, {
    body: {
      joined_at: new Date().toISOString(),
      status: "active",
    },
  });
  typia.assert(toWarn);

  const admin = await api.functional.discussionboard.actors.members.post(connection, {
    body: {
      joined_at: new Date().toISOString(),
      status: "active",
    },
  });
  typia.assert(admin);

  const moderator = await api.functional.discussionboard.actors.members.post(connection, {
    body: {
      joined_at: new Date().toISOString(),
      status: "active",
    },
  });
  typia.assert(moderator);

  const outsider = await api.functional.discussionboard.actors.members.post(connection, {
    body: {
      joined_at: new Date().toISOString(),
      status: "active",
    },
  });
  typia.assert(outsider);

  // 2. Promote moderator and admin
  const promotedModerator = await api.functional.discussionboard.actors.moderators.post(connection, {
    body: {
      discussionboard_member_id: moderator.id,
      promoted_at: new Date().toISOString(),
    },
  });
  typia.assert(promotedModerator);

  const promotedAdmin = await api.functional.discussionboard.actors.moderators.post(connection, {
    body: {
      discussionboard_member_id: admin.id,
      promoted_at: new Date().toISOString(),
    },
  });
  typia.assert(promotedAdmin);

  // 3. Admin issues a warning to toWarn (subject member)
  const warningRecord = await api.functional.discussionboard.moderation.warningRecords.post(connection, {
    body: {
      warned_member_id: toWarn.id,
      issued_by_moderator_id: admin.id,
      reason: "Test guideline violation for deletion E2E.",
    },
  });
  typia.assert(warningRecord);

  // 4. Deleting as admin (should succeed)
  await api.functional.discussionboard.moderation.warningRecords.eraseById(connection, {
    id: warningRecord.id,
  });

  // 5. Attempt to delete as moderator (should fail; not enough privs)
  TestValidator.error("Moderator cannot delete warning record")(() =>
    api.functional.discussionboard.moderation.warningRecords.eraseById(connection, {
      id: warningRecord.id,
    })
  );

  // 6. Attempt to delete as outsider (never promoted to mod/admin; should fail)
  TestValidator.error("Outsider cannot delete warning record")(() =>
    api.functional.discussionboard.moderation.warningRecords.eraseById(connection, {
      id: warningRecord.id,
    })
  );

  // 7. Attempt to delete a random (nonexistent) warning record – should yield error
  TestValidator.error("Deleting nonexistent warning record yields error")(() =>
    api.functional.discussionboard.moderation.warningRecords.eraseById(connection, {
      id: typia.random<string & tags.Format<"uuid">>(),
    })
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMembers } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMembers";
import type { IDiscussionboardComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardComment";
import type { IDiscussionboardCommentReply } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardCommentReply";
import type { IPageIDiscussionboardCommentReply } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionboardCommentReply";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validate listing and searching of comment replies with multiple filters and pagination.
 *
 * Business Context:
 * This test validates the flexible search/list operation for threaded comment replies in the discussion board. It ensures that reply relationships are correctly retrievable by various filters (parent_id, reply_id, member_id), pagination parameters, and ordering, as required for UI and moderation flows.
 *
 * Test Steps:
 * 1. Create several members (at least 3) representing different users.
 * 2. For a fixed post/thread (simulate a shared discussionboard_post_id), create at least 3 base comments authored by different members.
 * 3. Associate those comments into reply chains by creating reply relationships (e.g., comment A is replied by B, B by C, forming A->B->C chains, and cross-replying across comments for additional complexity).
 * 4. Perform PATCH /discussionboard/threads/commentReplies with various filter combinations:
 *    - By comment_id (parent): fetch all direct replies to a given comment (should match reply mappings)
 *    - By reply_id: fetch reply relationships involving a specific reply comment
 *    - By discussionboard_member_id: filter reply mappings where the member is involved (either parent or reply)
 *    - Pagination: limit, page, and ordering (sort_by, sort_order) checks, validate correctness of result windowing and metadata
 *    - Combination filter: e.g., parent+reply, parent+member, etc.
 *    - Negative test: a filter combination guaranteed to return no results
 * 5. Assert that each search result data matches expectation—correct chains, member associations, and pagination meta. Edge cases (empty) must return empty array & valid pagination meta.
 */
export async function test_api_discussionboard_test_list_comment_replies_with_various_filters_and_pagination(
  connection: api.IConnection,
) {
  // Step 1: Create members
  const members = await ArrayUtil.asyncRepeat(3)(async () =>
    api.functional.discussionboard.actors.members.post(connection, {
      body: {
        joined_at: new Date().toISOString(),
        status: "active",
      },
    })
  );
  members.forEach(typia.assert);

  // Step 2: Create base comments for a single post/thread
  const postId = typia.random<string & tags.Format<"uuid">>();
  const comments = await ArrayUtil.asyncRepeat(3)(async (i) =>
    api.functional.discussionboard.threads.comments.post(connection, {
      body: {
        discussionboard_post_id: postId,
        discussionboard_member_id: members[i].id,
        body: `Comment ${i + 1} body`,
      },
    })
  );
  comments.forEach(typia.assert);

  // Step 3: Create threaded reply relationships (A->B, B->C, and cross-links)
  // Reply 1: Comment 1 -> Comment 2
  const reply1 = await api.functional.discussionboard.threads.commentReplies.post(connection, {
    body: {
      comment_id: comments[0].id,
      reply_id: comments[1].id,
    },
  });
  typia.assert(reply1);
  // Reply 2: Comment 2 -> Comment 3
  const reply2 = await api.functional.discussionboard.threads.commentReplies.post(connection, {
    body: {
      comment_id: comments[1].id,
      reply_id: comments[2].id,
    },
  });
  typia.assert(reply2);
  // Cross-reply: Comment 1 -> Comment 3
  const reply3 = await api.functional.discussionboard.threads.commentReplies.post(connection, {
    body: {
      comment_id: comments[0].id,
      reply_id: comments[2].id,
    },
  });
  typia.assert(reply3);

  //---------- SEARCH TESTS ----------
  // a) By parent_id (comment_id): should return direct replies to Comment 1 (should include Comment 2 & 3 as replies)
  const byParent = await api.functional.discussionboard.threads.commentReplies.patch(connection, {
    body: {
      comment_id: comments[0].id,
    },
  });
  typia.assert(byParent);
  TestValidator.predicate("parent_id filter count")(byParent.data.length === 2 && byParent.data.every(x => x.comment_id === comments[0].id));

  // b) By reply_id: should return only relationships where reply is Comment 3
  const byReply = await api.functional.discussionboard.threads.commentReplies.patch(connection, {
    body: {
      reply_id: comments[2].id,
    },
  });
  typia.assert(byReply);
  TestValidator.predicate("reply_id filter count")(byReply.data.length === 2 && byReply.data.every(x => x.reply_id === comments[2].id));

  // c) By discussionboard_member_id: pick member who authored comment 1
  const byMember = await api.functional.discussionboard.threads.commentReplies.patch(connection, {
    body: {
      discussionboard_member_id: members[0].id,
    },
  });
  typia.assert(byMember);
  TestValidator.predicate("member_id filter includes mappings with member as parent or reply")(
    byMember.data.some(x => comments.find(c => c.id === x.comment_id)?.discussionboard_member_id === members[0].id) ||
    byMember.data.some(x => comments.find(c => c.id === x.reply_id)?.discussionboard_member_id === members[0].id)
  );

  // d) Pagination: request page 1 with limit 1, sort by created_at descending
  const paginated = await api.functional.discussionboard.threads.commentReplies.patch(
    connection,
    {
      body: {
        page: 1,
        limit: 1,
        sort_by: "created_at",
        sort_order: "desc",
      },
    },
  );
  typia.assert(paginated);
  TestValidator.equals("pagination page 1 count")(paginated.data.length)(1);
  TestValidator.equals("pagination meta limit")(paginated.pagination.limit)(1);
  TestValidator.equals("pagination meta page")(paginated.pagination.current)(1);

  // e) Pagination: request page 2 with limit 1, expect one element
  const paginated2 = await api.functional.discussionboard.threads.commentReplies.patch(
    connection,
    {
      body: {
        page: 2,
        limit: 1,
        sort_by: "created_at",
        sort_order: "desc",
      },
    },
  );
  typia.assert(paginated2);
  TestValidator.equals("pagination page 2 count")(paginated2.data.length)(1);

  // f) Pagination: request beyond available pages, expect empty data
  const paginatedEmpty = await api.functional.discussionboard.threads.commentReplies.patch(
    connection,
    {
      body: {
        page: 10,
        limit: 1,
        sort_by: "created_at",
        sort_order: "desc",
      },
    },
  );
  typia.assert(paginatedEmpty);
  TestValidator.equals("pagination empty count")(paginatedEmpty.data.length)(0);

  // g) Combination filter: filter by parent_id and reply_id that doesn't exist
  const nonExistent = await api.functional.discussionboard.threads.commentReplies.patch(
    connection,
    {
      body: {
        comment_id: comments[2].id,
        reply_id: comments[0].id,
      },
    },
  );
  typia.assert(nonExistent);
  TestValidator.equals("combination filter returns 0")(nonExistent.data.length)(0);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMembers } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMembers";
import type { IDiscussionboardComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardComment";
import type { IDiscussionboardCommentReply } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardCommentReply";

/**
 * Validate retrieval, existence, and error handling for Discussion Board comment reply relations by ID.
 *
 * This test verifies the correct behavior of the GET /discussionboard/threads/commentReplies/:id endpoint across success and error cases.
 *
 * 1. Member creation (needed to author comments).
 * 2. Two comments are created under the same post by the members (as base for parent and reply).
 * 3. A comment reply mapping is established (parent-reply link).
 * 4. Successfully retrieve the comment reply using its ID—assert all core fields (id, comment_id, reply_id, created_at) match expectation.
 * 5. Delete the created comment reply mapping.
 * 6. Attempt to fetch the reply mapping after deletion—expect a 404 error.
 * 7. Attempt to retrieve a truly non-existent ID (random UUID)—expect a 404 error (not found).
 */
export async function test_api_discussionboard_test_get_comment_reply_by_id_existing_and_deleted(connection: api.IConnection) {
  // 1. Create two members.
  const member1 = await api.functional.discussionboard.actors.members.post(connection, {
    body: {
      joined_at: new Date().toISOString(),
      status: "active"
    }
  });
  typia.assert(member1);
  const member2 = await api.functional.discussionboard.actors.members.post(connection, {
    body: {
      joined_at: new Date().toISOString(),
      status: "active"
    }
  });
  typia.assert(member2);

  // 2. Create a thread post ID for the comments (simulate with uuid since no post API is available).
  const postId = typia.random<string & tags.Format<"uuid">>();

  // 3. Create parent and reply comments.
  const parentComment = await api.functional.discussionboard.threads.comments.post(connection, {
    body: {
      discussionboard_post_id: postId,
      discussionboard_member_id: member1.id,
      body: "This is the parent comment."
    }
  });
  typia.assert(parentComment);
  const replyComment = await api.functional.discussionboard.threads.comments.post(connection, {
    body: {
      discussionboard_post_id: postId,
      discussionboard_member_id: member2.id,
      body: "This is the reply comment.",
      parent_id: parentComment.id
    }
  });
  typia.assert(replyComment);

  // 4. Create a comment reply mapping.
  const commentReply = await api.functional.discussionboard.threads.commentReplies.post(connection, {
    body: {
      comment_id: parentComment.id,
      reply_id: replyComment.id
    }
  });
  typia.assert(commentReply);

  // 5. Retrieve the comment reply mapping successfully by id.
  const fetchedReply = await api.functional.discussionboard.threads.commentReplies.getById(connection, {
    id: commentReply.id
  });
  typia.assert(fetchedReply);
  TestValidator.equals("comment reply id matches")(fetchedReply.id)(commentReply.id);
  TestValidator.equals("parent comment id matches")(fetchedReply.comment_id)(parentComment.id);
  TestValidator.equals("reply comment id matches")(fetchedReply.reply_id)(replyComment.id);
  TestValidator.predicate("createdAt should be a string with ISO format")(typeof fetchedReply.created_at === "string" && !Number.isNaN(Date.parse(fetchedReply.created_at)));

  // 6. Delete the comment reply mapping.
  await api.functional.discussionboard.threads.commentReplies.eraseById(connection, { id: commentReply.id });

  // 7. Try to fetch after deletion: expect 404 (not found).
  await TestValidator.error("deleted reply mapping should not be found")(
    async () => {
      await api.functional.discussionboard.threads.commentReplies.getById(connection, { id: commentReply.id });
    }
  );

  // 8. Try to fetch a non-existent random ID: expect 404.
  const randomId = typia.random<string & tags.Format<"uuid">>();
  await TestValidator.error("random non-existent id should return 404")(
    async () => {
      await api.functional.discussionboard.threads.commentReplies.getById(connection, { id: randomId });
    }
  );
}

