  TestValidator.equals("reply comment in mapping")(replyMapping.reply_id)(replyComment.id);
  TestValidator.predicate("mapping id is uuid")(/^[0-9a-fA-F-]{36}$/.test(replyMapping.id));
  TestValidator.predicate("mapping created_at is date-time")(!!Date.parse(replyMapping.created_at));

  // 4. Error: non-existent parent or reply comment
  const fakeUUID = typia.random<string & tags.Format<"uuid">>();
  await TestValidator.error("mapping with non-existent parent should fail")(() =>
    api.functional.discussionboard.threads.commentReplies.post(connection, {
      body: { comment_id: fakeUUID, reply_id: replyComment.id },
