  );

  // 5. Error: duplicate mapping (same parent-reply pair)
  await TestValidator.error("duplicate mapping should fail")(() =>
    api.functional.discussionboard.threads.commentReplies.post(connection, {
      body: {
        comment_id: parentComment.id,
        reply_id: replyComment.id,
      },
    })
