/**
 * Validate deletion of comment reply mapping (discussionboard_comment_replies) for all major business cases in a discussion board scenario.
 *
 * This test covers:
 * 1. Authorized member (owner) can delete a comment reply mapping, and receives the correct reply mapping data on success.
 * 2. Unauthorized member attempts to delete another user's reply mapping and is rejected (permission error).
 * 3. Deleting a mapping that has already been deleted triggers correct error or demonstrates idempotency as per API contract.
 * 4. Deleting a non-existent mapping ID returns a 404 error.
 *
 * Steps:
 * - Register several members: owner of reply mapping, and another member for negative test case.
 * - Create a thread comment for the owner and setup a reply mapping.
 * - Case 1: Owner requests deletion (should succeed).
 * - Case 2: Other member requests deletion on the same mapping (should fail - permission error).
 * - Case 3: Owner requests deletion on already deleted mapping (test soft/hard delete/idempotency behavior).
 * - Case 4: Try deleting random non-existent mapping ID - should yield 404.
 *
 * Strictly follows DTOs for property names and types. All IDs are uuid.
 */
export async function test_api_discussionboard_test_delete_comment_reply_mapping_with_permissions_and_edge_cases(
  connection: api.IConnection,
) {
  // 1. Register two members: owner and another user
  const ownerMember = await api.functional.discussionboard.actors.members.post(connection, {
    body: {
      joined_at: new Date().toISOString(),
      status: "active"
    }
  });
  typia.assert(ownerMember);

  const otherMember = await api.functional.discussionboard.actors.members.post(connection, {
    body: {
      joined_at: new Date().toISOString(),
      status: "active"
    }
  });
  typia.assert(otherMember);

  // 2. Owner creates a comment (a fake random post id is generated)
  const postId = typia.random<string & tags.Format<"uuid">>();
  const ownerComment = await api.functional.discussionboard.threads.comments.post(connection, {
    body: {
      discussionboard_post_id: postId,
      discussionboard_member_id: ownerMember.id,
      body: "This is a comment by owner.",
      parent_id: null
    }
  });
  typia.assert(ownerComment);

  // 3. Owner creates a reply comment
  const replyComment = await api.functional.discussionboard.threads.comments.post(connection, {
    body: {
      discussionboard_post_id: postId,
      discussionboard_member_id: ownerMember.id,
      body: "This is a reply.",
      parent_id: ownerComment.id
    }
  });
  typia.assert(replyComment);

  // 4. Create the comment reply mapping
  const replyMapping = await api.functional.discussionboard.threads.commentReplies.post(connection, {
    body: {
      comment_id: ownerComment.id,
      reply_id: replyComment.id
    }
  });
  typia.assert(replyMapping);

  // -----
  // Case 1: Owner deletes (should succeed)
  // -----
  const deletedMapping = await api.functional.discussionboard.threads.commentReplies.eraseById(connection, {
    id: replyMapping.id
  });
  typia.assert(deletedMapping);
  TestValidator.equals("deleted mapping id matches")(deletedMapping.id)(replyMapping.id);

  // -----
  // Case 2: Other member tries to delete mapping (should fail with permission error)
  //  (Assume real token switching per user in real E2E, not shown here)
  await TestValidator.error("unauthorized deletion should fail")(() =>
    api.functional.discussionboard.threads.commentReplies.eraseById(connection, {
      id: replyMapping.id
    })
  );

  // -----
  // Case 3: Owner tries to delete already deleted mapping (should fail or demonstrate idempotency)
  await TestValidator.error("repeat deletion should fail or be idempotent")(() =>
    api.functional.discussionboard.threads.commentReplies.eraseById(connection, {
      id: replyMapping.id
    })
  );

  // -----
  // Case 4: Delete random non-existing mapping ID (404 expected)
  await TestValidator.error("delete non existent mapping yields 404")(() =>
    api.functional.discussionboard.threads.commentReplies.eraseById(connection, {
      id: typia.random<string & tags.Format<"uuid">>()
    })
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMembers } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMembers";
import type { IPageDiscussionboardMembers } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageDiscussionboardMembers";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Test listing board members with pagination and search filters.
 *
 * This test verifies that the member list endpoint correctly implements:
 * - Pagination parameters (page/limit)
 * - Advanced filters (status, joinedAfter, joinedBefore)
 * - Partial search across identity fields (supports 'search' param)
 * - Correct pagination meta info (current, limit, records, pages)
 *
 * Step-by-step:
 * 1. Create multiple members with differing statuses and join dates
 * 2. List with pagination and validate subsets
 * 3. Filter by status and assert correctness
 * 4. Search by part of a member's ID (fuzzy match)
 * 5. Filter by joinedAfter
 * 6. Negative case with a non-matching status
 */
export async function test_api_discussionboard_test_list_members_with_pagination_and_search(connection: api.IConnection) {
  // 1. Create multiple members with various statuses and join dates
  const members: IDiscussionboardMembers[] = [];
  const statuses = ["active", "pending", "suspended"];
  const now = new Date();
  for (let i = 0; i < 8; i++) {
    const status = statuses[i % statuses.length];
    // Staggered join dates (newest first)
    const joined_at = new Date(now.getTime() - i * 5 * 24 * 60 * 60 * 1000).toISOString();
    const member = await api.functional.discussionboard.actors.members.post(connection, {
      body: {
        joined_at,
        status,
      } satisfies IDiscussionboardMembers.ICreate,
    });
    typia.assert(member);
    members.push(member);
  }

  // 2. Paginate results (limit=3, page=1)
  const pageSize = 3;
  const page1 = await api.functional.discussionboard.actors.members.patch(connection, {
    body: {
      limit: pageSize,
      page: 1,
    } satisfies IDiscussionboardMembers.IRequest,
  });
  typia.assert(page1);
  TestValidator.equals("page 1: limit match")(page1.pagination.limit)(pageSize);
  TestValidator.equals("page 1: current page")(page1.pagination.current)(1);
  TestValidator.equals("page 1: result length")(page1.data.length)(Math.min(pageSize, members.length));

  // 3. Paginate next page and make sure it is not identical
  const page2 = await api.functional.discussionboard.actors.members.patch(connection, {
    body: {
      limit: pageSize,
      page: 2,
    } satisfies IDiscussionboardMembers.IRequest,
  });
  typia.assert(page2);
  TestValidator.equals("page 2: current page")(page2.pagination.current)(2);
  TestValidator.notEquals("page 1/2 data differs")(page2.data.map(d => d.id))(page1.data.map(d => d.id));

  // 4. Filter by status (e.g., 'pending')
  const filterStatus = statuses[1]; // 'pending'
  const filterResp = await api.functional.discussionboard.actors.members.patch(connection, {
    body: {
      status: filterStatus,
    } satisfies IDiscussionboardMembers.IRequest,
  });
  typia.assert(filterResp);
  TestValidator.predicate("filter by status -- all match")(filterResp.data.every(d => d.status === filterStatus));

  // 5. Search by partial ID (first 8 chars of a known member)
  const searchTarget = members[0];
  const searchFragment = searchTarget.id.substring(0, 8);
  const searchResp = await api.functional.discussionboard.actors.members.patch(connection, {
    body: {
      search: searchFragment,
    } satisfies IDiscussionboardMembers.IRequest,
  });
  typia.assert(searchResp);
  TestValidator.predicate("search returns correct member")(searchResp.data.some(d => d.id === searchTarget.id));

  // 6. Filter by joinedAfter (only recent members)
  const afterDate = members[5].joined_at;
  const afterResp = await api.functional.discussionboard.actors.members.patch(connection, {
    body: {
      joinedAfter: afterDate,
    } satisfies IDiscussionboardMembers.IRequest,
  });
  typia.assert(afterResp);
  TestValidator.predicate("all joined_at >= afterDate")(afterResp.data.every(d => d.joined_at >= afterDate));

  // 7. No matches for made-up status
  const emptyResp = await api.functional.discussionboard.actors.members.patch(connection, {
    body: {
      status: "definitely_not_a_status",
    } satisfies IDiscussionboardMembers.IRequest,
  });
  typia.assert(emptyResp);
  TestValidator.equals("empty result for fake status")(emptyResp.data.length)(0);
  TestValidator.predicate("meta pages >= 1")(emptyResp.pagination.pages >= 1);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
