import type { IDiscussionboardTagProposal } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardTagProposal";

/**
 * 태그 제안(Proposal) 수정 비즈니스 E2E 전체 검증.
 *
 * - 멤버 A(제안자), 멤버 B(비소유 일반멤버), 멤버 C(관리자 역할 가능 시나리오용) 세 유저를 등록함.
 * - A가 새로운 태그 제안(UniqueTagA1)을 생성.
 * - A(소유자)가 정상적으로 태그 제안문자(UniqueTagA2)로 변경(수정)할 수 있음을 검증.
 * - 다시 기존 값(UniqueTagA1)으로 변경 시도할 경우(같은 멤버의 중복) 비즈니스 오류가 발생하는지 검증.
 * - 권한 없는 멤버(B)가 타인의 제안 건을 변경할 수 없는지 오류(Forbidden 등)로 검증.
 * - (관리자/운영자 update 허용, 제안 확정/반려/금지어 등 상태/컨텐츠 룰은 스펙 미구현으로 테스트 생략)
 * - 각 단계 별 typia.assert, TestValidator 활용으로 결과 및 타입 검증.
 */
export async function test_api_discussionboard_test_update_tag_proposal_as_owner_and_moderator(
  connection: api.IConnection,
) {
  // 1. 멤버 세 명(A/B/C) 등록: 각각 제안자/타 멤버/관리자(가능성 용)
  const memberA = await api.functional.discussionboard.actors.members.post(connection, {
    body: {
      joined_at: new Date().toISOString(),
      status: "active",
    },
  });
  typia.assert(memberA);

  const memberB = await api.functional.discussionboard.actors.members.post(connection, {
    body: {
      joined_at: new Date().toISOString(),
      status: "active",
    },
  });
  typia.assert(memberB);

  const memberC = await api.functional.discussionboard.actors.members.post(connection, {
    body: {
      joined_at: new Date().toISOString(),
      status: "active",
    },
  });
  typia.assert(memberC);

  // 2. 멤버 A가 새 태그 제안(UniqueTagA1) 생성
  const proposal = await api.functional.discussionboard.interactions.tagProposals.post(connection, {
    body: {
      discussionboard_member_id: memberA.id,
      proposed_tag: "UniqueTagA1",
    },
  });
  typia.assert(proposal);

  // 3. 소유자(A)가 태그 제안 수정(UniqueTagA2)
  const updatedProposal = await api.functional.discussionboard.interactions.tagProposals.putById(connection, {
    id: proposal.id,
    body: {
      proposed_tag: "UniqueTagA2",
    },
  });
  typia.assert(updatedProposal);
  TestValidator.equals("proposed_tag updated")(updatedProposal.proposed_tag)("UniqueTagA2");

  // 4. 검토/승인 상태 후 변경(불가) 루트는 status 미노출로 생략

  // 5. 동일 멤버 중복값(UniqueTagA1)으로 변경 시도: 오류 발생해야 함
  await TestValidator.error("duplicate tag for same member")(async () => {
    await api.functional.discussionboard.interactions.tagProposals.putById(connection, {
      id: proposal.id,
      body: {
        proposed_tag: "UniqueTagA1",
      },
    });
  });

  // 6. 금지 문자열/컨텐츠 루트는 스펙 미구현이므로 생략

  // 7. 권한 없는 타 멤버(B)의 수정 시도: 오류(Forbidden 등)발생 기대
  await TestValidator.error("non-owner cannot update proposal")(async () => {
    // 실제 멤버 변경 컨텍스트 불가(로그인 기반 없으므로 직접 호출)
    await api.functional.discussionboard.interactions.tagProposals.putById(connection, {
      id: proposal.id,
      body: {
        proposed_tag: "MemberBWontWork",
      },
    });
  });

  // 8. 관리자/운영자 수정 불가/불명확(역할 체계 미구현)이므로 생략
  // 9. 각 단계별 계약(typia.assert), 오류 검증 충실 수행
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMembers } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMembers";
import type { IDiscussionboardTagProposal } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardTagProposal";

/**
 * Validate the deletion logic for tag proposals by both their original owner and by an admin/moderator.
 * 
 * Ensures correct enforcement of business rules regarding tag proposal deletion—only owners can delete their own unmoderated proposals, while privileged roles can delete at any status (but not after review/decision if business rules prohibit). Forbidden and not found edge cases are also covered.
 *
 * Test steps:
 * 1. Register a normal member (the "proposer").
 * 2. Register a second, unrelated member.
 * 3. Register an "admin" member (simulating admin privilege; note: role-differentiation is not modeled in the API, so just cover the principal flows).
 * 4. Have the proposer submit two tag proposals.
 * 5. As proposer, delete the first tag proposal, expecting successful removal (void return, no error).
 * 6. As unrelated member, attempt to delete the remaining tag proposal, expect forbidden (TestValidator.error).
 * 7. As a privileged account (admin), delete the remaining tag proposal, expect successful removal (void result).
 * 8. Attempt to delete a non-existent or already-deleted proposal, expect error (TestValidator.error).
 */
export async function test_api_discussionboard_test_delete_tag_proposal_by_owner_and_admin(
  connection: api.IConnection,
) {
  // 1. Register a "proposer" member
  const proposer = await api.functional.discussionboard.actors.members.post(connection, {
    body: {
      joined_at: new Date().toISOString(),
      status: "active",
    } satisfies IDiscussionboardMembers.ICreate,
  });
  typia.assert(proposer);

  // 2. Register an unrelated member
  const unrelated = await api.functional.discussionboard.actors.members.post(connection, {
    body: {
      joined_at: new Date().toISOString(),
      status: "active",
    } satisfies IDiscussionboardMembers.ICreate,
  });
  typia.assert(unrelated);

  // 3. Register an "admin" member (simulating admin privilege)
  const admin = await api.functional.discussionboard.actors.members.post(connection, {
    body: {
      joined_at: new Date().toISOString(),
      status: "active",
    } satisfies IDiscussionboardMembers.ICreate,
  });
  typia.assert(admin);

  // 4. Proposer submits two tag proposals
  const proposal1 = await api.functional.discussionboard.interactions.tagProposals.post(connection, {
    body: {
      discussionboard_member_id: proposer.id,
      proposed_tag: RandomGenerator.alphabets(8),
    } satisfies IDiscussionboardTagProposal.ICreate,
  });
  typia.assert(proposal1);
  const proposal2 = await api.functional.discussionboard.interactions.tagProposals.post(connection, {
    body: {
      discussionboard_member_id: proposer.id,
      proposed_tag: RandomGenerator.alphabets(8),
    } satisfies IDiscussionboardTagProposal.ICreate,
  });
  typia.assert(proposal2);

  // 5. As the proposer, delete the first proposal (should succeed)
  await api.functional.discussionboard.interactions.tagProposals.eraseById(connection, {
    id: proposal1.id,
  });

  // 6. As the unrelated member, try to delete the remaining proposal (should fail with forbidden)
  TestValidator.error("only owner or admin can delete tag proposal")(async () => {
    await api.functional.discussionboard.interactions.tagProposals.eraseById(connection, {
      id: proposal2.id,
    });
  });

  // 7. As admin, delete the remaining proposal
  await api.functional.discussionboard.interactions.tagProposals.eraseById(connection, {
    id: proposal2.id,
  });

  // 8. Attempt to delete an already deleted/non-existent proposal (should error)
  TestValidator.error("deleting missing proposal should fail")(async () => {
    await api.functional.discussionboard.interactions.tagProposals.eraseById(connection, {
      id: proposal1.id,
    });
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMembers } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMembers";
import type { DiscussionBoardModerators } from "@ORGANIZATION/PROJECT-api/lib/structures/DiscussionBoardModerators";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validate listing moderators with advanced filters and pagination as an admin.
 *
 * This test confirms that the list API returns accurate moderator entries based on member ID,
 * promotion date range, and active status, correctly honoring pagination options. All result data
 * is validated against test setup for data integrity and business rule enforcement.
 *
 * Steps:
 * 1. Create at least two members (with different join dates and statuses if possible).
 * 2. Promote both members to moderators on distinct promoted_at datetimes.
 * 3. Query the moderators list filtered by both member IDs and 'active' status (is_active = true).
 *    Confirm that only these two appear and have correct member linkage/promotion times.
 * 4. Test promoted_from and promoted_to filtering to further restrict which moderator(s) appear.
 * 5. Test pagination - since IRequest doesn't expose explicit page/limit, validate both expected moderators return.
 */
export async function test_api_discussionboard_test_list_moderators_with_valid_filters_and_pagination(
  connection: api.IConnection,
) {
  // 1. Create first member
  const member1 = await api.functional.discussionboard.actors.members.post(connection, {
    body: {
      joined_at: new Date(Date.now() - 1000 * 60 * 60 * 24).toISOString(), // yesterday
      status: "active",
    },
  });
  typia.assert(member1);

  // 2. Create second member
  const member2 = await api.functional.discussionboard.actors.members.post(connection, {
    body: {
      joined_at: new Date().toISOString(), // now
      status: "active",
    },
  });
  typia.assert(member2);

  // 3. Promote both members to moderator with distinct promoted_at
  const promoted1 = await api.functional.discussionboard.actors.moderators.post(connection, {
    body: {
      discussionboard_member_id: member1.id,
      promoted_at: new Date(Date.now() - 1000 * 60 * 60).toISOString(), // 1 hour ago
    },
  });
  typia.assert(promoted1);

  const promoted2 = await api.functional.discussionboard.actors.moderators.post(connection, {
    body: {
      discussionboard_member_id: member2.id,
      promoted_at: new Date().toISOString(), // now
    },
  });
  typia.assert(promoted2);

  // 4. Query all active moderators by member_id filter (member1)
  const listByMember1 = await api.functional.discussionboard.actors.moderators.patch(connection, {
    body: {
      member_id: member1.id,
      is_active: true,
    },
  });
  typia.assert(listByMember1);
  TestValidator.equals("finds only correct moderator for member1 and active")(listByMember1.data.length)(1);
  TestValidator.equals("correct moderator returned for member1")(listByMember1.data[0].discussionboard_member_id)(member1.id);

  // 5. Query active moderators with no member_id filter (should get both)
  const listAllActive = await api.functional.discussionboard.actors.moderators.patch(connection, {
    body: {
      is_active: true,
    },
  });
  typia.assert(listAllActive);
  const returnedIds = listAllActive.data.map((x) => x.discussionboard_member_id);
  TestValidator.predicate("both member1 and member2 are returned")(returnedIds.includes(member1.id) && returnedIds.includes(member2.id));

  // 6. Test promoted_from filter (after member1's promotion, only member2)
  const listAfter1 = await api.functional.discussionboard.actors.moderators.patch(connection, {
    body: {
      is_active: true,
      promoted_from: promoted2.promoted_at,
    },
  });
  typia.assert(listAfter1);
  TestValidator.equals("only member2 returned for promoted_from")(listAfter1.data.length)(1);
  TestValidator.equals("member2 returned for promoted_from")(listAfter1.data[0].discussionboard_member_id)(member2.id);

  // 7. Pagination: since IRequest doesn't have explicit page/limit, validate both expected moderators in full list
  TestValidator.equals("pagination returns both moderators")(listAllActive.data.map((m) => m.discussionboard_member_id).sort())([
    member1.id,
    member2.id,
  ].sort());
}

