 * - Covers creation of both the prerequisite member and a valid suspension (as admin), then looks up that suspension.
 * - Asserts all key output fields match the creation inputs for integrity.
 * - Verifies that a non-existent (random) suspension ID results in a 404 error.
 * - Assumes caller holds sufficient admin/moderator privs in the `connection` context (auth checks for forbidden/unauthorized not enforceable with current test infra).
 *
 * Steps:
 * 1. Create a discussion board member.
 * 2. Create a suspension for that member with explicit payload (admin-signed).
 * 3. Retrieve the created suspension by ID and assert all fields.
 * 4. Attempt to retrieve a random, non-existent suspension ID (expect 404).
 */
export async function test_api_discussionboard_actors_memberSuspensions_getById_test_get_member_suspension_detail_with_valid_id(
  connection: api.IConnection,
) {
  // 1. Create a discussion board member
  const createdMember = await api.functional.discussionboard.actors.members.post(connection, {
    body: {
      joined_at: new Date().toISOString(),
      status: "active",
    },
  });
