  // 2. (as admin) Create a suspension for the new member
  const now = new Date();
  const starts_at = now.toISOString();
  const ends_at = new Date(now.getTime() + 1000 * 60 * 60 * 24).toISOString(); // +1 day
  const suspensionInput = {
    discussionboard_member_id: createdMember.id,
    issued_by_admin_id: typia.random<string & tags.Format<"uuid">>(),
    issued_by_moderator_id: null,
    reason: "Policy violation: spam or abuse",
    starts_at,
    ends_at,
  } satisfies IDiscussionBoardMemberSuspension.ICreate;
  const createdSuspension = await api.functional.discussionboard.actors.memberSuspensions.post(connection, {
    body: suspensionInput,
  });
  typia.assert(createdSuspension);

  // 3. Retrieve the suspension by its ID
  const fetched = await api.functional.discussionboard.actors.memberSuspensions.getById(connection, {
    id: createdSuspension.id,
  });
  typia.assert(fetched);
  TestValidator.equals("suspension id")(fetched.id)(createdSuspension.id);
  TestValidator.equals("affected member")(fetched.discussionboard_member_id)(createdMember.id);
  TestValidator.equals("admin issuer")(fetched.issued_by_admin_id)(suspensionInput.issued_by_admin_id);
  TestValidator.equals("moderator issuer")(fetched.issued_by_moderator_id)(suspensionInput.issued_by_moderator_id);
  TestValidator.equals("reason")(fetched.reason)(suspensionInput.reason);
  TestValidator.equals("starts_at")(fetched.starts_at)(suspensionInput.starts_at);
  TestValidator.equals("ends_at")(fetched.ends_at)(suspensionInput.ends_at);
  TestValidator.equals("revoked_at should be null")(fetched.revoked_at)(null);

  // 4. Try retrieving a random non-existent suspension; expect 404
  await TestValidator.error("get non-existent suspension returns 404")(async () => {
    await api.functional.discussionboard.actors.memberSuspensions.getById(connection, {
      id: typia.random<string & tags.Format<"uuid">>(),
    });
