/**
 * Test member suspension deletion with permission checks.
 *
 * This test verifies that a moderator or admin can delete (revoke) a suspension record for a member and that unauthorized actors are properly rejected.
 *
 * Flow in summary:
 * 1. Create a member (who will be suspended)
 * 2. (Assumed: Moderator or admin context, as no explicit actor APIs exist)
 * 3. Create a suspension for that member (by acting as moderator, using issued_by_moderator_id filled in)
 * 4. Successfully delete the suspension with moderator/admin privilege
 * 5. Test error: Attempt to delete the same suspension again (should return 404, as it is gone or revoked)
 * 6. Test error: Try to delete a (random) non-existent suspension ID (should return 404)
 * 7. (Access control simulation: if no privilege-enforcement API, document, but skip implementation)
 * 8. Optionally: Query the affected member to check status update is as expected (not possible - missing relevant read endpoint in provided APIs)
 *
 * Permissions: as there is no explicit login or actor switching system in these APIs, all calls happen in the same privilege context (assumed to be privileged or simulated). Skipped permission-denied (403) scenario as not technically possible with the provided surface.
 */
export async function test_api_discussionboard_test_delete_member_suspension_with_permission_checks(
  connection: api.IConnection,
) {
  // 1. Create a member
  const member = await api.functional.discussionboard.actors.members.post(connection, {
    body: {
      joined_at: new Date().toISOString(),
      status: "active",
    },
  });
  typia.assert(member);

  // 2. Create a suspension for that member (as moderator)
  // We'll generate a random moderator ID (UUID), as there's no moderator management API
  const moderatorId = typia.random<string & tags.Format<"uuid">>();
  const suspension = await api.functional.discussionboard.actors.memberSuspensions.post(connection, {
    body: {
      discussionboard_member_id: member.id,
      issued_by_moderator_id: moderatorId, // Pretend this is a real moderator
      reason: "Violation of community rules",
      starts_at: new Date().toISOString(),
      ends_at: null,
    },
  });
  typia.assert(suspension);

  // 3. Delete (revoke) the suspension by its ID (success expected)
  await api.functional.discussionboard.actors.memberSuspensions.eraseById(connection, {
    id: suspension.id,
  }); // Success, expects void response

  // 4. Attempt to delete the same suspension again (should return 404)
  await TestValidator.error("Deleting already deleted suspension returns 404")(
    async () => {
      await api.functional.discussionboard.actors.memberSuspensions.eraseById(connection, {
        id: suspension.id,
      });
    },
  );

  // 5. Attempt to delete a non-existent suspension (random UUID) (should return 404)
  const randomSuspensionId = typia.random<string & tags.Format<"uuid">>();
  await TestValidator.error("Deleting non-existent suspension returns 404")(
    async () => {
      await api.functional.discussionboard.actors.memberSuspensions.eraseById(connection, {
        id: randomSuspensionId,
      });
    }
  );

  // NOTE: Cannot test for status update/audit log or member's account reactivation, as there is no read/update endpoint for members or suspensions.
  // NOTE: Cannot test permission-rejection (403), as there is no login, user role, or session in provided API.
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardSetting } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardSetting";
import type { IPageIDiscussionboardSetting } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionboardSetting";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * 관리자 권한으로 시스템 전체 설정 목록(글로벌 setting) 페이징 조회 기능 검증.
 *
 * PATCH /discussionboard/systematic/settings 엔드포인트를 통해, 기본/변경 페이징 옵션에 따라
 * 설정 리스트와 pagination 메타 정보가 정확히 반환되는지 확인합니다.
 * 각 setting의 id, key, value, description, created_at, updated_at 필드 및 데이터 다양성,
 * 그리고 페이지네이션 메타데이터의 정상 여부를 assert합니다.
 *
 * 1. 관리자 connection에서 기본 조회(page:1, limit:10) 실행, 결과 pagination/data assert
 * 2. 반환된 설정 리스트 각 항목의 필드 및 타입 assert
 * 3. key/value 데이터 다양성(중복 없는 여러 값 존재) 확인
 * 4. page:2, limit:5 등 페이징 옵션 변경 시 결과 pagination 및 data assert
 * 5. (엣지) 데이터 없는 페이지에도 pagination 구조 및 타입 일관성 검증
 */
export async function test_api_discussionboard_test_list_settings_with_valid_admin_permission_and_pagination(
  connection: api.IConnection,
) {
  // 1. 기본 페이징 요청(page:1, limit:10)
  const page1 = await api.functional.discussionboard.systematic.settings.patch(connection, {
    body: {
      page: 1,
      limit: 10,
    },
  });
  typia.assert(page1);

  // 2. pagination 메타데이터 assert
  TestValidator.equals("current page")(page1.pagination.current)(1);
  TestValidator.equals("limit per page")(page1.pagination.limit)(10);
  TestValidator.predicate("records count 0 이상")(page1.pagination.records >= 0);
  TestValidator.predicate("전체 페이지 1 이상")(page1.pagination.pages >= 1);

  // 3. 각 설정 객체 타입 및 필드 assert
  page1.data.forEach((setting, idx) => {
    typia.assert(setting);
    TestValidator.predicate(`필수필드 검증#${idx}`)(
      !!setting.id &&
      !!setting.key &&
      !!setting.value &&
      typeof setting.created_at === "string" &&
      typeof setting.updated_at === "string"
    );
  });

  // 4. key/value 다양성(중복x 복수 키/값) 체크
  if (page1.data.length > 1) {
    const keys = page1.data.map(s => s.key);
    const values = page1.data.map(s => s.value);
    TestValidator.predicate("key 다양성")(new Set(keys).size > 1);
    TestValidator.predicate("value 다양성")(new Set(values).size > 1);
  }

  // 5. 두번째 페이지/소수 limit(5)로 조회
  const page2 = await api.functional.discussionboard.systematic.settings.patch(connection, {
    body: {
      page: 2,
      limit: 5,
    },
  });
  typia.assert(page2);
  TestValidator.equals("current page")(page2.pagination.current)(2);
  TestValidator.equals("limit per page")(page2.pagination.limit)(5);
  TestValidator.predicate("전체 페이지 1 이상")(page2.pagination.pages >= 1);

  // 6. (엣지) 데이터 없는 빈 페이지도 pagination/type 구조 고정
  if (page2.data.length === 0) {
    TestValidator.equals("빈 data 배열")(page2.data.length)(0);
    typia.assert(page2.pagination);
  } else {
    page2.data.forEach(setting => typia.assert(setting));
  }
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardSetting } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardSetting";
import type { IPageIDiscussionboardSetting } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionboardSetting";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IDiscussionboardSettings } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardSettings";

/**
 * 관리자가 시스템 설정 목록을 텍스트 검색 및 필터로 조회하는 기능을 검증합니다.
 *
 * 이 테스트는 관리자가 설정 키 또는 설명에서 부분일치로 텍스트 검색(search)을 수행할 수 있으며,
 * 그 결과가 올바르게 필터링되고, 페이지네이션(limit 기반)도 정확히 적용되는지 검증합니다.
 * 
 * 비즈니스 시나리오:
 * 1. 텍스트 검색 대상이 되도록 고유 key 또는 description을 갖는 설정 3건을 생성합니다
 *    - 이 중 최소 2건 이상이 중복된 fragment("maint")를 name/설명에 포함하도록 구성합니다.
 *    - 1건은 검색어와 완전히 무관하도록 만듭니다
 * 2. search 파라미터로 fragment("maint")를 사용해 PATCH /discussionboard/systematic/settings API 호출
 * 3. 반환 결과 목록의 모든 key 또는 description에 해당 fragment가 부분일치 되는지(대소문자 무관) 검증
 * 4. 검색 결과 건수가 2건 이상임을 비교
 * 5. limit=1로 요청 후 한 페이지에 1건만 반환되고 pagination.limit이 1인지 점검
 */
export async function test_api_discussionboard_test_list_settings_with_text_search_and_filter(
  connection: api.IConnection,
) {
  // 1. 테스트용: search fragment "maint"가 들어가는 설정 2건, 무관 1건 생성
  const settingsToCreate = [
    { key: `maintenance_mode_${RandomGenerator.alphabets(6)}`, value: "on", description: "사이트 유지보수 모드 여부 테스트용" },
    { key: `maint_log_${RandomGenerator.alphabets(6)}`, value: "enabled", description: "메인로그 테스팅" },
    { key: `unrelated_setting_${RandomGenerator.alphabets(6)}`, value: "value", description: "검색과 무관한 설명" }
  ];
  const createdSettings: IDiscussionboardSettings[] = [];
  for (const setting of settingsToCreate) {
    const result = await api.functional.discussionboard.systematic.settings.post(connection, {
      body: setting satisfies IDiscussionboardSettings.ICreate,
    });
    typia.assert(result);
    createdSettings.push(result);
  }

  // 2. 검색어 fragment
  const searchTerm = "maint";

  // 3. search 파라미터로 목록 API 호출
  const pageResult = await api.functional.discussionboard.systematic.settings.patch(connection, {
    body: { search: searchTerm } satisfies IDiscussionboardSetting.IRequest,
  });
  typia.assert(pageResult);

  // 4. 결과 데이터의 key 또는 description이 모두 searchTerm 포함 여부 확인
  for (const setting of pageResult.data) {
    const matches =
      (setting.key && setting.key.toLowerCase().includes(searchTerm)) ||
      (setting.description && setting.description.toLowerCase().includes(searchTerm));
    TestValidator.predicate(
      `[검색어 ${searchTerm}]는 시스템 설정의 key 또는 description에 반드시 포함되어야 함`
    )(matches === true);
  }
  TestValidator.predicate("최소 2건 이상 반환되어야 함")(pageResult.data.length >= 2);

  // 5. limit=1로 페이징 검증
  const pageOneResult = await api.functional.discussionboard.systematic.settings.patch(connection, {
    body: { search: searchTerm, limit: 1 } satisfies IDiscussionboardSetting.IRequest,
  });
  typia.assert(pageOneResult);
  TestValidator.equals("페이지 당 1건만 노출되어야 함")(
    pageOneResult.data.length
  )(1);
  TestValidator.equals("pagination.limit에 1 리턴")(
    pageOneResult.pagination.limit
  )(1);
}

