import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardSetting } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardSetting";
import type { IDiscussionboardSettings } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardSettings";

/**
 * 시스템 환경설정 상세 조회(관리자 권한, 신규 생성 기반)
 *
 * 관리자 권한으로 시스템 환경설정(GET /discussionboard/systematic/settings/{id}) 상세 단건을 정확히 조회할 수 있는지 검증합니다.
 * 1. 새로운 시스템 글로벌 환경설정(key, value, description 포함)을 POST로 생성
 * 2. 생성시 얻은 id 값으로 단건 상세 조회(GET)을 수행
 * 3. 상세 응답에 key/value/description/timestamps 등 모든 필드가 올바로 포함되는지 검증
 * 4. POST로 직접 생성한 값과 GET 상세 응답이 정확히 일치하는지 비교 검증
 */
export async function test_api_discussionboard_test_get_system_setting_details_with_valid_id(
  connection: api.IConnection,
) {
  // 1. 새로운 시스템 환경설정 생성(고유 key, 값, description 모두 포함)
  const createInput = {
    key: `e2e_${RandomGenerator.alphaNumeric(8)}`,
    value: RandomGenerator.alphaNumeric(12),
    description: RandomGenerator.paragraph()(1),
  } satisfies IDiscussionboardSettings.ICreate;
  const created = await api.functional.discussionboard.systematic.settings.post(connection, {
    body: createInput,
  });
  typia.assert(created);

  // 2. 단건 상세 조회(GET, id 지정)
  const fetched = await api.functional.discussionboard.systematic.settings.getById(connection, {
    id: created.id,
  });
  typia.assert(fetched);

  // 3. 주요 필드, 전체 값 검증 - 생성/조회 응답값 및 입력과 비교
  TestValidator.equals("id")(fetched.id)(created.id);
