import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardSettings } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardSettings";

/**
 * Validate error behavior for system setting creation with a duplicate key (case insensitive scenario).
 *
 * This test simulates an administrator attempting to create a new system setting where the setting key is already in use (with a different casing). The system must enforce uniqueness of the key regardless of letter case.
 *
 * Steps:
 * 1. Create an initial system setting with a specific key as prerequisite
 * 2. Attempt to create another setting using the same key but in a different letter-case
 * 3. Expect an error indicating a unique key constraint violation
 * 4. Optionally, re-attempt with the original case to confirm uniqueness
 */
export async function test_api_discussionboard_test_create_setting_with_duplicate_key_should_fail(
  connection: api.IConnection,
) {
  // 1. Create initial system setting (dependency)
  const originalKey = "Maintenance_Mode";
  const createSettingRequest: IDiscussionboardSettings.ICreate = {
    key: originalKey,
    value: "off",
    description: "Enable/disable maintenance mode feature",
  };
  const initialSetting = await api.functional.discussionboard.systematic.settings.post(connection, { body: createSettingRequest });
  typia.assert(initialSetting);

  // 2. Attempt to create duplicate setting with different case
  const duplicateKey = originalKey.toLowerCase();
  const duplicateSettingRequest: IDiscussionboardSettings.ICreate = {
    key: duplicateKey,
    value: "on",
    description: "Should trigger duplicate key (case-insensitive) error",
  };
  await TestValidator.error("Should raise unique key error on duplicate system setting key")(
    async () => {
      await api.functional.discussionboard.systematic.settings.post(connection, { body: duplicateSettingRequest });
    },
  );

  // 3. Optionally: Try exact case again
  await TestValidator.error("Should also raise error for exact duplicate key")(
    async () => {
      await api.functional.discussionboard.systematic.settings.post(connection, { body: createSettingRequest });
    },
  );
}

