  const createDto = {
    key: RandomGenerator.alphaNumeric(10),
    value: RandomGenerator.alphaNumeric(12),
    description: "테스트용 설정 설명",
  } satisfies IDiscussionboardSettings.ICreate;
  const created = await api.functional.discussionboard.systematic.settings.post(connection, { body: createDto });
  typia.assert(created);

  // 2. 비관리자 connection 준비
  // 실제로 일반 회원 권한을 가진 connection을 발급/스위칭하는 로직이 필요합니다.
  // 예시에서는 memberConnection이라는 별도 connection 객체가 생성된다고 가정합니다.
  // (테스트 인프라에서 회원 가입 및 인증 시스템이 있고, 그 결과 memberConnection을 얻을 수 있어야 함)
  // 아래 코드는 해당 memberConnection이 이미 준비된 것으로 간주하고 예시를 작성합니다.
  // 만약 일반회원 connection 생성이 불가하면 이 부분은 실제 실행시 동작하지 않을 수 있습니다.

  // 3. 비관리자 권한으로 수정 시도 => 권한 거부 에러 발생해야 함
  await TestValidator.error("비관리자는 시스템 설정을 수정할 수 없어야 함")(
    async () => {
      await api.functional.discussionboard.systematic.settings.putById(
        memberConnection, // (비관리자 connection, 테스트 인프라에서 제공 필요)
        {
          id: created.id,
          body: {
            value: "FORBIDDEN_UPDATE",
            description: "비관리자 수정시도",
          } satisfies IDiscussionboardSettings.IUpdate,
        },
      );
    },
  );

  // 4. (관리자 connection으로 복귀 후 실제 변경 없는지 확인) Get API 미제공으로 생략
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardSettings } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardSettings";

/**
 * 시스템 설정을 관리자가 ID로 삭제할 수 있는지 검증합니다.
 *
 * 1. 시스템 설정을 생성합니다(선행 작업).
 * 2. 생성 결과의 id로 DELETE 요청을 합니다.
 * 3. 삭제 API의 반환 값이 올바른 설정 객체(삭제된 내용 기록)임을 확인합니다.
 * 4. (GET API가 존재할 경우) 삭제 이후 해당 id로 조회가 불가함을 검증합니다.
 * 5. 실제 DB에서 삭제되거나, 삭제 상태로 처리됨(이력 감사 로그로 남아야 함)을 후행 검증(가능 시).
 */
export async function test_api_discussionboard_test_delete_system_setting_successfully_by_admin(
  connection: api.IConnection,
) {
  // 1. 시스템 설정을 생성합니다.
  const createInput = {
    key: `test_key_${RandomGenerator.alphaNumeric(12)}`,
    value: "test_value",
    description: "테스트용 시스템 설정입니다.",
  } satisfies IDiscussionboardSettings.ICreate;
  const created = await api.functional.discussionboard.systematic.settings.post(connection, {
    body: createInput,
  });
  typia.assert(created);

  // 2. 생성된 id로 시스템 설정을 삭제합니다.
  const deleted = await api.functional.discussionboard.systematic.settings.eraseById(connection, {
    id: created.id,
  });
  typia.assert(deleted);
  TestValidator.equals("삭제된 설정 id 일치")(deleted.id)(created.id);

  // 3. 삭제된 설정의 값(삭제 전후 기록) 필드 검증
  TestValidator.equals("삭제된 설정 key")(deleted.key)(createInput.key);
  TestValidator.equals("삭제된 설정 value")(deleted.value)(createInput.value);

  // 4. (GET API 미존재로 미확인)
  // 만약 GET /discussionboard/systematic/settings/{id} 지원 시, try-catch로 조회가 실패하는지 검증 필요
  // (예시)
  // await TestValidator.error("삭제 후 조회 불가")(() =>
  //   api.functional.discussionboard.systematic.settings.at(connection, { id: created.id })
  // );

  // 별도 감사/로그 검증은 현재 API 스펙 범위에서는 수행 불가
}

