        description: "E2E test setting for permission test",
      } satisfies IDiscussionboardSettings.ICreate,
    },
  );
  typia.assert(adminSetting);

  // 2. (비관리자 권한)(세션 전환 구현 필요) 삭제 시도 → 권한 거부 에러 발생 검증
  // 실제 환경에서 비관리자 connection을 전달해야 제대로 검증됩니다.
  await TestValidator.error("permission denied for non-admin should throw")(
    async () => {
      await api.functional.discussionboard.systematic.settings.eraseById(
