    body: {
      joined_at: now,
      status: 'active',
    }
  });
  typia.assert(anotherMember);

  const adminMember = await api.functional.discussionboard.actors.members.post(connection, {
    body: {
      joined_at: now,
      status: 'admin', // Emulate admin via status (for test)
    }
  });
  typia.assert(adminMember);

  // 2. ordinaryMember creates a thread.
  const thread = await api.functional.discussionboard.threads.threads.post(connection, {
    body: {
      discussionboard_board_id: typia.random<string & tags.Format<'uuid'>>(),
      discussionboard_member_id: ordinaryMember.id,
      title: RandomGenerator.paragraph()(8),
      description: RandomGenerator.paragraph()(24),
      status: 'open',
      created_at: now,
    }
  });
  typia.assert(thread);

  // 3. ordinaryMember creates a post in the thread.
  const post = await api.functional.discussionboard.threads.posts.post(connection, {
    body: {
      discussionboard_thread_id: thread.id,
      discussionboard_member_id: ordinaryMember.id,
      body: RandomGenerator.content()()(),
      created_at: now,
    }
  });
  typia.assert(post);

  // 4. ordinaryMember dislikes their own post.
  const dislike = await api.functional.discussionboard.interactions.postDislikes.post(connection, {
    body: {
      discussionboard_post_id: post.id,
      discussionboard_member_id: ordinaryMember.id,
    }
  });
  typia.assert(dislike);

  // 5. ordinaryMember deletes their own dislike.
  await api.functional.discussionboard.interactions.postDislikes.eraseById(connection, {
    id: dislike.id,
  });

  // Try deleting again (should be gone), expect not found
  await TestValidator.error("Deleting already-deleted dislike returns error")(
    async () => {
      await api.functional.discussionboard.interactions.postDislikes.eraseById(connection, {
        id: dislike.id,
      });
    }
  );

  // 6. Recreate the dislike for the next tests
  const dislike2 = await api.functional.discussionboard.interactions.postDislikes.post(connection, {
    body: {
      discussionboard_post_id: post.id,
      discussionboard_member_id: ordinaryMember.id,
    }
  });
