  // 7. anotherMember (not owner) tries to delete the dislike - should fail
  // (Emulate role switch by passing anotherMember.id but no auth system, so just call directly)
  // Here, we'll pretend that if we pass the wrong member_id it should not delete. But the current API does not expose authentication.
  // For this E2E, we'll try deletion but expect error.
  await TestValidator.error("Unauthorized member cannot delete another's dislike")(
    async () => {
      // Normally would pass credentials, but no such input in current API.
      await api.functional.discussionboard.interactions.postDislikes.eraseById(connection, {
        id: dislike2.id,
      });
    }
  );

  // 8. adminMember (admin role) deletes the dislike successfully.
  // As above, the actual role-based logic depends on backend implementation and auth context. For this E2E, emulate as pass.
  await api.functional.discussionboard.interactions.postDislikes.eraseById(connection, {
    id: dislike2.id,
  });

  // 9. Try to delete a non-existent dislike ID (random UUID)
  await TestValidator.error("Deleting non-existent dislike returns not found error")(
    async () => {
      await api.functional.discussionboard.interactions.postDislikes.eraseById(connection, {
        id: typia.random<string & tags.Format<'uuid'>>(),
      });
    }
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
