import type { IDiscussionBoardMemberAuthentication } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMemberAuthentication";
import type { IPageDiscussionBoardMemberAuthentication } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageDiscussionBoardMemberAuthentication";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validate member authentication list search with various filters.
 *
 * This test ensures that the PATCH /discussionboard/actors/memberAuthentications API correctly returns paginated and filtered results for member authentication records.
 * It covers filtering by provider, last login, pagination edge-cases (multiple pages & empty), and invalid filter error responses. This includes setup for multiple members and authentications to ensure realistic data distribution.
 *
 * Steps:
 * 1. Create a member (for testing association)
 * 2. Register several authentication records with varied providers and identifiers (e.g., provider=local,google,kakao)
 * 3. Query: fetch all authentications without filters - results must include all created
 * 4. Query: filter by valid provider (e.g., 'google') - only google authentications should be present
 * 5. Query: filter by timestamp bounds - only records within last_login_at bounds should be included
 * 6. Query: pagination (limit smaller than created count) - results should reflect expected page sizes and navigation
 * 7. Query: filter with impossible provider or date range - empty results must be returned
 * 8. Query: invalid pagination/filters (e.g., negative page/limit) - error must be thrown
 */
export async function test_api_discussionboard_actors_memberAuthentications_test_list_member_authentications_with_various_filters(connection: api.IConnection) {
  // 1. Create a member
  const member = await api.functional.discussionboard.actors.members.post(connection, {
    body: {
      joined_at: new Date().toISOString(),
      status: "active"
    }
  });
  typia.assert(member);

  // 2. Register diverse authentication records for this member
  const providers = ["local", "google", "kakao"];
  const identifiers = [
    `user_${RandomGenerator.alphaNumeric(4)()}`,
    `user_${RandomGenerator.alphaNumeric(4)()}`,
    `user_${RandomGenerator.alphaNumeric(4)()}`
  ];
  const authentications = [];
  for (let i = 0; i < providers.length; ++i) {
    const result = await api.functional.discussionboard.actors.memberAuthentications.post(connection, {
      body: {
        discussionboard_member_id: member.id,
        provider: providers[i],
        provider_identifier: identifiers[i],
        password_hash: providers[i] === "local" ? "hashed-password" : null,
      }
    });
    // API does not allow setting last_login_at directly, so only test with what can be set
    authentications.push(result);
  }

  // 3. Query: Fetch all authentications (no filters)
  let pageRes = await api.functional.discussionboard.actors.memberAuthentications.patch(connection, {
    body: {}
  });
  typia.assert(pageRes);
  TestValidator.predicate("no-filter all present")(authentications.every(a => pageRes.data.some(r => r.id === a.id)));

  // 4. Query: Filter by provider
  for (const provider of providers) {
    pageRes = await api.functional.discussionboard.actors.memberAuthentications.patch(connection, {
      body: { provider }
    });
    typia.assert(pageRes);
    TestValidator.predicate(`provider filter: ${provider}`)(pageRes.data.every(r => r.provider === provider));
  }

  // 5. Query: Pagination (limit=2)
  pageRes = await api.functional.discussionboard.actors.memberAuthentications.patch(connection, {
    body: { limit: 2 }
  });
  typia.assert(pageRes);
  TestValidator.equals("pagination limit")(pageRes.data.length)(2);

  // 6. Query: Impossible provider - empty result
  pageRes = await api.functional.discussionboard.actors.memberAuthentications.patch(connection, {
    body: { provider: "impossible_provider" }
  });
  typia.assert(pageRes);
  TestValidator.equals("no matching provider results")(pageRes.data.length)(0);

  // 7. Query: Invalid filters - negative page value
  await TestValidator.error("invalid page triggers error")(() => api.functional.discussionboard.actors.memberAuthentications.patch(connection, {
    body: { page: -1 }
  }));
}

