/**
 * Test creation of discussion board member authentications, covering both unique and duplicate cases, as well as referential integrity errors.
 *
 * This test covers the following:
 * 1. Successful creation of a new authentication record for a valid member
 * 2. Error on duplicate provider/identifier submission for the same member
 * 3. Acceptance of another authentication for the same member/identifier if provider is different
 * 4. Error when attempting authentication creation with a non-existent member ID
 *
 * Business significance: ensures uniqueness, referential integrity, and correct error handling for identity credential storage on the discussion board system.
 *
 * Test Steps:
 * 1. Create a discussion board member for use in the positive/negative authentication cases
 * 2. Register valid authentication for that member (provider = 'local')
 * 3. Attempt duplicate creation for the same provider/identifier (expect error)
 * 4. Register new authentication with another provider but same identifier (should succeed)
 * 5. Attempt authentication creation with a randomly generated non-existent member UUID (expect error)
 */
export async function test_api_discussionboard_test_create_member_authentication_with_valid_and_duplicate_data(
  connection: api.IConnection,
) {
  // 1. Create a new member (prerequisite for auth records)
  const memberReg = await api.functional.discussionboard.actors.members.post(connection, {
    body: {
      joined_at: new Date().toISOString(),
      status: "active",
    } satisfies IDiscussionboardMembers.ICreate,
  });
  typia.assert(memberReg);

  // 2. Create an authentication for this member
  const provider = "local";
  const provider_identifier = RandomGenerator.alphaNumeric(10);
  const password_hash = RandomGenerator.alphaNumeric(32);

  const authCreate = await api.functional.discussionboard.actors.memberAuthentications.post(connection, {
    body: {
      discussionboard_member_id: memberReg.id,
      provider,
      provider_identifier,
      password_hash,
    } satisfies IDiscussionBoardMemberAuthentication.ICreate,
  });
  typia.assert(authCreate);
  TestValidator.equals("discussionboard_member_id matches")(authCreate.discussionboard_member_id)(memberReg.id);
  TestValidator.equals("provider matches")(authCreate.provider)(provider);
  TestValidator.equals("provider_identifier matches")(authCreate.provider_identifier)(provider_identifier);
  TestValidator.equals("password_hash matches")(authCreate.password_hash)(password_hash);

  // 3. Attempt to create duplicate authentication (should fail)
  await TestValidator.error("duplicate provider/identifier should fail")(() =>
    api.functional.discussionboard.actors.memberAuthentications.post(connection, {
      body: {
        discussionboard_member_id: memberReg.id,
        provider,
        provider_identifier,
        password_hash: RandomGenerator.alphaNumeric(32),
      } satisfies IDiscussionBoardMemberAuthentication.ICreate,
    })
  );

  // 4. Create authentication with different provider for same member/identifier
  const anotherProvider = "google";
  const authCreate2 = await api.functional.discussionboard.actors.memberAuthentications.post(connection, {
    body: {
      discussionboard_member_id: memberReg.id,
      provider: anotherProvider,
      provider_identifier,
      password_hash: null,
    } satisfies IDiscussionBoardMemberAuthentication.ICreate,
  });
  typia.assert(authCreate2);
  TestValidator.equals("discussionboard_member_id matches")(authCreate2.discussionboard_member_id)(memberReg.id);
  TestValidator.equals("provider matches")(authCreate2.provider)(anotherProvider);
  TestValidator.equals("provider_identifier matches")(authCreate2.provider_identifier)(provider_identifier);
  TestValidator.equals("password_hash null for google provider")(authCreate2.password_hash)(null);

  // 5. Attempt to create auth for non-existent member (should fail)
  await TestValidator.error("non-existent member uuid fails")(() =>
    api.functional.discussionboard.actors.memberAuthentications.post(connection, {
      body: {
        discussionboard_member_id: typia.random<string & tags.Format<"uuid">>(),
        provider: "local",
        provider_identifier: RandomGenerator.alphaNumeric(10),
        password_hash: RandomGenerator.alphaNumeric(32),
      } satisfies IDiscussionBoardMemberAuthentication.ICreate,
    })
  );
}

