  const deleteResult1 = await api.functional.discussionboard.actors.memberAuthentications.eraseById(connection, { id: auth1.id });
  typia.assert(deleteResult1);
  TestValidator.equals("should succeed")(deleteResult1.success)(true);
  TestValidator.equals("should return deleted id")(deleteResult1.deleted_id)(auth1.id);

  // 4. Attempt to delete again with same ID (should fail)
