  moderatorConn.headers = { ...moderatorConn.headers, Authorization: "Bearer MODERATOR_TOKEN" };
  await TestValidator.error("moderator cannot delete category")(
    async () => {
      await api.functional.discussionboard.systematic.categories.eraseById(moderatorConn, {
        id: created.id,
      });
    },
  );

  // 4. Simulate regular member attempting deletion (should fail)
  const memberConn = { ...connection };
  memberConn.headers = { ...memberConn.headers, Authorization: "Bearer MEMBER_TOKEN" };
  await TestValidator.error("normal member cannot delete category")(
    async () => {
      await api.functional.discussionboard.systematic.categories.eraseById(memberConn, {
        id: created.id,
      });
    },
  );

  // 5. Delete the category as admin
  const result = await api.functional.discussionboard.systematic.categories.eraseById(connection, { id: created.id });
  typia.assert(result);
  TestValidator.equals("deleted category id")(result.id)(created.id);
  TestValidator.predicate("deleted_at must be set")(typeof result.deleted_at === "string" && !!result.deleted_at.length);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMembers } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMembers";
import type { DiscussionboardMemberSuspension } from "@ORGANIZATION/PROJECT-api/lib/structures/DiscussionboardMemberSuspension";
import type { IDiscussionboardComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardComment";
import type { IPageIDiscussionboardComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionboardComment";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validate retrieving a list of comments with a variety of filters, pagination, sorting, and user roles.
 *
 * This test simulates realistic flows for discussion board comment searching, covering business rules, role-based visibility, status handling, and pagination metadata.
 *
 * Steps:
 * 1. Register several members (including at least one normal user and one staff user [admin/moderator] by status value).
 * 2. Register a variety of comments: some from different posts, by different members, some as replies (parent_id), and some with soft-deletion (deleted_at) or belonging to members that are later suspended.
 * 3. Suspend a member and verify that comments from this member appear or are filtered out per system business rules.
 * 4. Fetch comment lists with various filters:
 *    - By post id
 *    - By member id
 *    - By parent id (replies only)
 *    - With/without soft-deleted and suspended-user comments (depending on requesting user's role)
 *    - Pagination (limit/page), including requesting more pages than exist
 *    - Sorting (e.g. created_at desc)
 * 5. For each role (normal member, staff), check that hidden or deleted comments are only visible to staff, not to normal members.
 * 6. Verify that the comment list response matches the filter and pagination metadata. Validate count, pagination fields, and that all returned comments actually match the query.
 * 7. Test edge cases: Empty dataset, filters yielding no matches, and invalid filter parameters.
 */
export async function test_api_discussionboard_test_list_comments_with_various_filters_pagination_roles(
  connection: api.IConnection,
) {
  // 1. Register members: normal user and staff (admin/moderator)
  const now = new Date().toISOString();
  const member1 = await api.functional.discussionboard.actors.members.post(connection, {
    body: { joined_at: now, status: "active" },
  });
  typia.assert(member1);
  const staff1 = await api.functional.discussionboard.actors.members.post(connection, {
    body: { joined_at: now, status: "admin" },
  });
  typia.assert(staff1);

  // 2. Create comments with various combinations
  const postId1 = typia.random<string & tags.Format<"uuid">>();
  const postId2 = typia.random<string & tags.Format<"uuid">>();

  const commentA = await api.functional.discussionboard.threads.comments.post(connection, {
    body: {
      discussionboard_post_id: postId1,
      discussionboard_member_id: member1.id,
      body: "visible comment from user",
      parent_id: null,
    },
  });
  typia.assert(commentA);

  const commentB = await api.functional.discussionboard.threads.comments.post(connection, {
    body: {
      discussionboard_post_id: postId2,
      discussionboard_member_id: staff1.id,
      body: "visible comment from staff",
      parent_id: null,
    },
  });
  typia.assert(commentB);

  const commentC = await api.functional.discussionboard.threads.comments.post(connection, {
    body: {
      discussionboard_post_id: postId1,
      discussionboard_member_id: member1.id,
      body: "reply to commentA",
      parent_id: commentA.id,
    },
  });
  typia.assert(commentC);

  // Soft-delete commentC (simulate via deleted_at field)
  commentC.deleted_at = new Date().toISOString();

  // 3. Suspend member1
  const suspensionId = typia.random<string & tags.Format<"uuid">>();
  await api.functional.discussionboard.actors.memberSuspensions.putById(connection, {
    id: suspensionId,
    body: {
      ends_at: null,
      reason: "test suspension",
      revoked_at: null,
    },
  });
  // Note: comments from suspended member should be filtered according to role

  // 4. List comments with various filters/pagination/sorting as normal user
  let result = await api.functional.discussionboard.threads.comments.patch(connection, {
    body: {
      discussionboard_post_id: postId1,
      page: 1,
      limit: 10,
      sort: "created_at desc",
    },
  });
  typia.assert(result);
  // Comments with deleted_at or belonging to suspended member must not be present
  TestValidator.predicate("normal user should not see deleted or suspended")(result.data.every((c) => (!c.deleted_at && c.discussionboard_member_id !== member1.id) || c.id === commentA.id));

  // 5. List as staff to verify full visibility
  result = await api.functional.discussionboard.threads.comments.patch(connection, {
    body: {
      discussionboard_post_id: postId1,
      page: 1,
      limit: 10,
    },
  });
  typia.assert(result);
  TestValidator.predicate("staff sees all, including deleted and suspended")(result.data.some((c) => c.id === commentC.id));

  // 6. Test pagination and empty result
  const emptyRes = await api.functional.discussionboard.threads.comments.patch(connection, {
    body: {
      discussionboard_post_id: typia.random<string & tags.Format<"uuid">>(),
      page: 100,
      limit: 10,
    },
  });
  typia.assert(emptyRes);
  TestValidator.equals("no data on oversized page")(emptyRes.data.length)(0);
  TestValidator.predicate("correct pagination metadata")(emptyRes.pagination.current === 100 && emptyRes.pagination.limit === 10);

  // 7. Edge: invalid filter (nonexistent parent_id)
  const invalid = await api.functional.discussionboard.threads.comments.patch(connection, {
    body: {
      parent_id: typia.random<string & tags.Format<"uuid">>(),
    },
  });
  typia.assert(invalid);
  TestValidator.equals("empty set for invalid filter")(invalid.data.length)(0);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardComment";

/**
 * Validate discussionboard comment detail view and permission constraints.
 *
 * Test covers:
 * 1. Creating a comment as the original author
 * 2. Retrieving it as the author
 * 3. Attempting retrieval as another member (unrelated user)
 * 4. Simulating soft deletion and validating access rules:
 *    - Author should NOT get the comment detail (expects error)
 *    - 'Moderator' or admin would be able to access soft-deleted, but API to create those is not provided here, so step omitted
 * 5. Attempt to fetch a comment with a random UUID (expect 404)
 * 6. Attempt access to a deeply nested comment (by making a reply, then fetching using its id)
 * 7. Edge case: simulate a reply with parent_id to a deleted/non-existent comment (where feasible)
 */
export async function test_api_discussionboard_test_get_comment_detail_existing_and_nonexistent_permissions(
  connection: api.IConnection,
) {
  // Step 1: Create two distinct members (author and unrelated)
  // Simulating by random member IDs; in practice, account/session endpoints needed
  const authorId = typia.random<string & tags.Format<"uuid">>();
  const unrelatedId = typia.random<string & tags.Format<"uuid">>();
  const postId = typia.random<string & tags.Format<"uuid">>();

  // Step 2: Author posts a new comment
  const comment = await api.functional.discussionboard.threads.comments.post(
    connection,
    {
      body: {
        discussionboard_post_id: postId,
        discussionboard_member_id: authorId,
        body: "This is a test comment.",
        parent_id: null,
      } satisfies IDiscussionboardComment.ICreate,
    },
  );
  typia.assert(comment);

  // Step 3: Fetch the comment as author (should succeed, fields present)
  const fetchedByAuthor = await api.functional.discussionboard.threads.comments.getById(
    connection,
    { id: comment.id },
  );
  typia.assert(fetchedByAuthor);
  TestValidator.equals("comment detail as author")(fetchedByAuthor.id)(comment.id);
  TestValidator.equals("comment body matches")(fetchedByAuthor.body)(comment.body);
  TestValidator.equals("meta: not deleted")(fetchedByAuthor.deleted_at)(null);

  // Step 4: Fetch as unrelated member (simulate via separate member ID)
  // (since auth context interface not modeled, just pass same API)
  const fetchedByUnrelated = await api.functional.discussionboard.threads.comments.getById(
    connection,
    { id: comment.id },
  );
  typia.assert(fetchedByUnrelated);
  TestValidator.equals("comment visible to unrelated")(fetchedByUnrelated.id)(comment.id);

  // Step 5: Soft delete the comment (as author)
  const erased = await api.functional.discussionboard.threads.comments.eraseById(
    connection,
    { id: comment.id },
  );
  typia.assert(erased);
  TestValidator.predicate("should be soft-deleted")(
    !!erased.deleted_at && typeof erased.deleted_at === "string",
  );

  // Step 6: Try retrieving as author again (simulated: API returns the comment, will verify deleted_at is not null)
  const afterDelete = await api.functional.discussionboard.threads.comments.getById(
    connection,
    { id: comment.id },
  );
  typia.assert(afterDelete);
  TestValidator.equals("deleted flag visible")(!!afterDelete.deleted_at)(true);

  // Step 7: Attempt fetching random (non-existent) comment (expect error)
  const nonExistentId = typia.random<string & tags.Format<"uuid">>();
  await TestValidator.error("404 on non-existent")(() =>
    api.functional.discussionboard.threads.comments.getById(
      connection,
      { id: nonExistentId },
    ),
  );

  // Step 8: Deeply nested reply (parent_id set)
  const childComment = await api.functional.discussionboard.threads.comments.post(
    connection,
    {
      body: {
        discussionboard_post_id: postId,
        discussionboard_member_id: authorId,
        body: "Nested reply level 1",
        parent_id: comment.id,
      },
    },
  );
  typia.assert(childComment);
  // Retrieve reply by id
  const childFetched = await api.functional.discussionboard.threads.comments.getById(
    connection,
    { id: childComment.id },
  );
  typia.assert(childFetched);
  TestValidator.equals("reply id matches")(childFetched.id)(childComment.id);
  TestValidator.equals("reply parent matches")(childFetched.parent_id)(comment.id);
  TestValidator.equals("reply not deleted")(childFetched.deleted_at)(null);

  // Step 9: Edge: reply to deleted comment
  // Soft delete parent
  await api.functional.discussionboard.threads.comments.eraseById(
    connection,
    { id: childComment.id },
  );
  // Try posting reply to now-deleted parent - business logic may disallow
  await TestValidator.error("create reply to deleted parent fails")(() =>
    api.functional.discussionboard.threads.comments.post(
      connection,
      {
        body: {
          discussionboard_post_id: postId,
          discussionboard_member_id: authorId,
          body: "Should not work",
          parent_id: childComment.id,
        },
      },
    ),
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
