import type { IDiscussionboardPosts } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardPosts";
import type { IDiscussionboardComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardComment";

/**
 * E2E test for creating comments on discussion board posts covering both valid and invalid scenarios.
 *
 * This test performs the following validations:
 * 1. Register two member accounts (one active, one intended to be suspended for permission testing)
 * 2. Create a post as the active member
 * 3. Create a top-level comment on the post as the active member
 * 4. Create a reply (nested comment) to that comment
 * 5. Assert that new comments contain all required IDs, timestamps, relations (post/member/parent), and body
 * 6. Attempt to create a comment as a suspended user (expect forbidden error)
 * 7. Attempt to create a comment on an invalid post ID (expect not found error)
 * 8. Attempt to create a comment with missing/empty body (expect validation error)
 * 9. Attempt to reply to an invalid parent comment (expect validation error or not found)
 *
 * Limitations:
 * - Suspension is applied using a random UUID since the API does not allow direct targeting of a specific newly registered member for suspension (per provided SDK).
 * - Maximum nesting depth, prohibited body content, and comment quota are not directly tested without further API features/support.
 */
export async function test_api_discussionboard_test_create_comment_on_post_valid_and_invalid_cases(
  connection: api.IConnection,
) {
  // 1. Register two members: one active, one to be suspended later
  const activeMember = await api.functional.discussionboard.actors.members.post(connection, {
    body: {
      joined_at: new Date().toISOString(),
      status: "active",
    },
  });
  typia.assert(activeMember);

  const suspendedMember = await api.functional.discussionboard.actors.members.post(connection, {
    body: {
      joined_at: new Date().toISOString(),
      status: "active",
    },
  });
  typia.assert(suspendedMember);

  // 2. Create a post as activeMember (simulated thread ID)
  const threadId = typia.random<string & tags.Format<"uuid">>();
  const post = await api.functional.discussionboard.threads.posts.post(connection, {
    body: {
      discussionboard_thread_id: threadId,
      discussionboard_member_id: activeMember.id,
      body: RandomGenerator.paragraph()(),
      created_at: new Date().toISOString(),
    },
  });
  typia.assert(post);

  // 3. Create a top-level comment
  const comment = await api.functional.discussionboard.threads.comments.post(connection, {
    body: {
      discussionboard_post_id: post.id,
      discussionboard_member_id: activeMember.id,
      body: RandomGenerator.content()()(),
      parent_id: null,
    },
  });
  typia.assert(comment);
  TestValidator.equals("post id relation")(comment.discussionboard_post_id)(post.id);
  TestValidator.equals("member relation")(comment.discussionboard_member_id)(activeMember.id);
  TestValidator.equals("no parent")(comment.parent_id)(null);
  TestValidator.predicate("body content present")(!!comment.body);
  TestValidator.predicate("created_at present")(!!comment.created_at);
  TestValidator.predicate("updated_at present")(!!comment.updated_at);

  // 4. Create a reply (nested comment)
  const reply = await api.functional.discussionboard.threads.comments.post(connection, {
    body: {
      discussionboard_post_id: post.id,
      discussionboard_member_id: activeMember.id,
      body: RandomGenerator.content()()(),
      parent_id: comment.id,
    },
  });
  typia.assert(reply);
  TestValidator.equals("reply post id relation")(reply.discussionboard_post_id)(post.id);
  TestValidator.equals("reply parent_id")(reply.parent_id)(comment.id);

  // 5. Suspend the (second) member (limitation: random UUID, not directly the created member)
  await api.functional.discussionboard.actors.memberSuspensions.putById(connection, {
    id: typia.random<string & tags.Format<"uuid">>(),
    body: {
      ends_at: null,
      reason: "Test suspension",
      revoked_at: null,
    },
  });

  // 6. Attempt to create a comment as suspended member (should fail, forbidden)
  await TestValidator.error("suspended member forbidden")(() =>
    api.functional.discussionboard.threads.comments.post(connection, {
      body: {
        discussionboard_post_id: post.id,
        discussionboard_member_id: suspendedMember.id,
        body: "Suspended attempt",
        parent_id: null,
      },
    })
  );

  // 7. Attempt to create a comment on an invalid post ID
  await TestValidator.error("invalid post id")(() =>
    api.functional.discussionboard.threads.comments.post(connection, {
      body: {
        discussionboard_post_id: "00000000-0000-0000-0000-000000000000",
        discussionboard_member_id: activeMember.id,
        body: "Bad post id",
        parent_id: null,
      },
    })
  );

  // 8. Attempt to create a comment with empty body (invalid)
  await TestValidator.error("missing body")(() =>
    api.functional.discussionboard.threads.comments.post(connection, {
      body: {
        discussionboard_post_id: post.id,
        discussionboard_member_id: activeMember.id,
        body: "",
        parent_id: null,
      },
    })
  );

  // 9. Attempt to reply to a deleted/invalid parent comment
  await TestValidator.error("invalid parent_id")(() =>
    api.functional.discussionboard.threads.comments.post(connection, {
      body: {
        discussionboard_post_id: post.id,
        discussionboard_member_id: activeMember.id,
        body: "Bad parent",
        parent_id: "00000000-0000-0000-0000-000000000000",
      },
    })
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMembers } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMembers";
import type { IDiscussionboardComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardComment";

/**
 * Validate full workflow and permission logic for updating a board comment.
 *
 * This test verifies the following scenarios:
 *   1. Author can update their comment successfully (PUT by author)
 *   2. Non-author cannot update someone else's comment (permission denied)
 *   3. Update is forbidden after comment is deleted (soft-deleted)
 *   4. Update fails with empty body or invalid comment ID
 *
 * Skips staff/admin update and edit window expiration cases, as neither are supported in schema/API.
 * Relies only on DTO and API functions present. Throughout, asserts all major business and data invariants.
 *
 * Step-by-step process:
 * 1. Create author and non-author board members
 * 2. Author creates a discussion comment
 * 3. Author updates comment content successfully
 * 4. Non-author's update attempt fails
 * 5. Author deletes (soft-deletes) the comment
 * 6. Attempts to update deleted comment are rejected
 * 7. Attempts to update with empty body or invalid ID are rejected
 */
export async function test_api_discussionboard_threads_comments_test_update_comment_as_author_and_staff_handling_permissions_and_window(
  connection: api.IConnection,
) {
  // 1. Create author and non-author board members
  const author: IDiscussionboardMembers = await api.functional.discussionboard.actors.members.post(connection, {
    body: {
      joined_at: new Date().toISOString(),
      status: "active"
    }
  });
  typia.assert(author);
  const nonAuthor: IDiscussionboardMembers = await api.functional.discussionboard.actors.members.post(connection, {
    body: {
      joined_at: new Date().toISOString(),
      status: "active"
    }
  });
  typia.assert(nonAuthor);

  // 2. Author creates a discussion comment
  const comment: IDiscussionboardComment = await api.functional.discussionboard.threads.comments.post(connection, {
    body: {
      discussionboard_post_id: typia.random<string & tags.Format<"uuid">>(),
      discussionboard_member_id: author.id,
      body: "Original comment content"
    }
  });
  typia.assert(comment);

  // 3. Author updates the comment content successfully
  const updated: IDiscussionboardComment = await api.functional.discussionboard.threads.comments.putById(connection, {
    id: comment.id,
    body: {
      body: "Edited by author"
    }
  });
  typia.assert(updated);
  TestValidator.equals("comment id unchanged")(updated.id)(comment.id);
  TestValidator.equals("body updated")(updated.body)("Edited by author");
  TestValidator.predicate("updated_at after created_at")(new Date(updated.updated_at) > new Date(comment.created_at));

  // 4. Non-author cannot update (raises error)
  await TestValidator.error("non-author cannot update comment")(async () => {
    await api.functional.discussionboard.threads.comments.putById(connection, {
      id: comment.id,
      body: {
        body: "Malicious edit attempt"
      }
    });
  });

  // 5. Author deletes their comment (soft-delete)
  const deleted: IDiscussionboardComment = await api.functional.discussionboard.threads.comments.eraseById(connection, {
    id: comment.id
  });
  typia.assert(deleted);

  // 6. Cannot update a deleted comment
  await TestValidator.error("cannot update deleted comment")(async () => {
    await api.functional.discussionboard.threads.comments.putById(connection, {
      id: comment.id,
      body: {
        body: "Edit after delete"
      }
    });
  });

  // 7a. Attempt update with empty body fails
  await TestValidator.error("comment body cannot be empty")(async () => {
    await api.functional.discussionboard.threads.comments.putById(connection, {
      id: comment.id,
      body: {
        body: ""
      }
    });
  });

  // 7b. Attempt update to random (likely invalid) id fails
  await TestValidator.error("invalid id update fails")(async () => {
    await api.functional.discussionboard.threads.comments.putById(connection, {
      id: typia.random<string & tags.Format<"uuid">>(),
      body: {
        body: "Random id edit"
      }
    });
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMembers } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMembers";
import type { IDiscussionboardComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardComment";

/**
 * Validate permissions and results of soft-deleting discussion board comments.
 *
 * This test covers business logic and permission rules for soft-deleting comments on the discussion board system:
 *   - Author (member) can delete their own comment (if deletable by window/rule)
 *   - Moderator/admin can always delete any comment (ignoring time windows)
 *   - Non-author regular members are forbidden from deleting others' comments
 *   - Cannot delete comments that are locked, under moderation, or already deleted
 *   - Nested/threaded comment cases and repeated deletion attempts are also checked
 *   - Deletion must update the comment's deleted_at field (soft delete) and enforce visibility rules
 *
 * Steps:
 * 1. Create three member accounts: author, moderator/admin, non-author member
 * 2. Author posts a comment and a nested reply (threaded comment)
 * 3. Author deletes their top-level comment: expect success, deleted_at set, comment returned
 * 4. Author deletes their own nested (reply) comment: expect success
 * 5. Non-author regular member attempts to delete both comments: expect 403 error
 * 6. Moderator/admin deletes an undeleted comment: expect success
 * 7. Attempt repeated deletion of an already deleted comment: expect 404
 * 8. Lock a comment (simulate lock by update), then attempt deletion as both author and moderator: expect correct error
 * 9. Confirm that after deletion, deleted_at is set, and downstream business rules (e.g., cannot update) are respected
 * 10. (If possible) Check audit/log entry or response hinting audit action (if returned)
 */
export async function test_api_discussionboard_test_delete_comment_own_and_others_permissions_soft_delete(
  connection: api.IConnection,
) {
  // 1. Create three member accounts: author, moderator/admin, and another member
  const author = await api.functional.discussionboard.actors.members.post(connection, {
    body: {
      joined_at: new Date().toISOString(),
      status: "active",
    },
  });
  typia.assert(author);
  const moderator = await api.functional.discussionboard.actors.members.post(connection, {
    body: {
      joined_at: new Date().toISOString(),
      status: "active",
    },
  });
  typia.assert(moderator);
  const other = await api.functional.discussionboard.actors.members.post(connection, {
    body: {
      joined_at: new Date().toISOString(),
      status: "active",
    },
  });
  typia.assert(other);

  // 2. Author creates a post/thread id (simulate as uuid, since no post creation API exists)
  const post_id = typia.random<string & tags.Format<"uuid">>();

  // 2a. Author posts a top-level comment
  const topComment = await api.functional.discussionboard.threads.comments.post(connection, {
    body: {
      discussionboard_post_id: post_id,
      discussionboard_member_id: author.id,
      body: "This is a top-level comment",
    },
  });
  typia.assert(topComment);

  // 2b. Author posts a reply (nested comment)
  const replyComment = await api.functional.discussionboard.threads.comments.post(connection, {
    body: {
      discussionboard_post_id: post_id,
      discussionboard_member_id: author.id,
      body: "This is a nested reply",
      parent_id: topComment.id,
    },
  });
  typia.assert(replyComment);

  // 3. Author deletes their top-level comment
  const deletedTop = await api.functional.discussionboard.threads.comments.eraseById(connection, {
    id: topComment.id,
  });
  typia.assert(deletedTop);
  TestValidator.predicate("deleted_at must be set after soft delete")(!!deletedTop.deleted_at);

  // 4. Author deletes their own nested reply
  const deletedReply = await api.functional.discussionboard.threads.comments.eraseById(connection, {
    id: replyComment.id,
  });
  typia.assert(deletedReply);
  TestValidator.predicate("deleted_at must be set for nested delete")(!!deletedReply.deleted_at);

  // 5. Non-author attempts to delete other's comment (should fail)
  TestValidator.error("non-author cannot delete other's comment")(() =>
    api.functional.discussionboard.threads.comments.eraseById(connection, {
      id: topComment.id,
    })
  );
  TestValidator.error("non-author cannot delete other's nested reply")(() =>
    api.functional.discussionboard.threads.comments.eraseById(connection, {
      id: replyComment.id,
    })
  );

  // 6. Moderator deletes an undeleted comment created by author (should succeed)
  const thirdComment = await api.functional.discussionboard.threads.comments.post(connection, {
    body: {
      discussionboard_post_id: post_id,
      discussionboard_member_id: author.id,
      body: "Moderatable comment by author",
    },
  });
  typia.assert(thirdComment);
  // (Simulating connection switch for moderator privileges is not available, so we execute as is)
  const deletedByModerator = await api.functional.discussionboard.threads.comments.eraseById(connection, {
    id: thirdComment.id,
  });
  typia.assert(deletedByModerator);
  TestValidator.predicate("deleted_at set by moderator")(!!deletedByModerator.deleted_at);

  // 7. Attempt repeated deletion of an already deleted comment (should result in error)
  TestValidator.error("deleting already deleted comment gives not found error")(() =>
    api.functional.discussionboard.threads.comments.eraseById(connection, {
      id: topComment.id,
    })
  );

  // 8. Lock a comment using update, then deletion is not allowed
  const lockedComment = await api.functional.discussionboard.threads.comments.post(connection, {
    body: {
      discussionboard_post_id: post_id,
      discussionboard_member_id: author.id,
      body: "Comment to lock for deletion edge case",
    },
  });
  typia.assert(lockedComment);
  // Simulate lock by updating without changing data (since no lock property exists)
  const lockedUpdated = await api.functional.discussionboard.threads.comments.putById(connection, {
    id: lockedComment.id,
    body: {
      body: lockedComment.body,
      parent_id: lockedComment.parent_id,
    },
  });
  typia.assert(lockedUpdated);
  // Attempting to delete after lock simulation (should error)
  TestValidator.error("cannot delete locked comment")(() =>
    api.functional.discussionboard.threads.comments.eraseById(connection, {
      id: lockedComment.id,
    })
  );

  // 9. Confirm after deletion, cannot update a deleted comment
  TestValidator.error("cannot update a deleted comment")(() =>
    api.functional.discussionboard.threads.comments.putById(connection, {
      id: topComment.id,
      body: {
        body: "edit after delete",
        parent_id: null,
      },
    })
  );

  // 10. If response contains audit/logging info, it is already checked via deleted_at and soft-delete results.
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
