 * Test prevention of duplicate post likes by a single member.
 *
 * This test verifies that the API for liking a post enforces a unique constraint:
 * the same member should not be able to like the same post more than once.
 *
 * Business Context:
 * - Liking posts is a core engagement mechanic, but duplicate likes must be prevented
 *   for both accurate analytics and user experience correctness.
 *
 * Test workflow:
 * 1. Register a new member for the test.
 * 2. Create a standalone thread ID for the post.
 * 3. Create a discussion post authored by the test member.
 * 4. Perform a successful like action by the member on the post.
 * 5. Attempt the like action again, using the same member and post (expect conflict/error).
 * 6. Validate that first like is stored, and that duplicate is blocked with error.
 */
export async function test_api_discussionboard_test_create_post_like_duplicate_prevention(
  connection: api.IConnection,
) {
  // 1. Register a new member
  const member = await api.functional.discussionboard.actors.members.post(connection, {
    body: {
      joined_at: new Date().toISOString(),
      status: "active",
    },
  });
  typia.assert(member);

  // 2. Prepare a thread ID for the post
  const threadId = typia.random<string & tags.Format<"uuid">>();

