  const likePayload = {
    discussionboard_post_id: post.id,
    discussionboard_member_id: member.id,
  } satisfies IDiscussionboardPostLike.ICreate;

  const firstLike = await api.functional.discussionboard.interactions.postLikes.post(connection, {
    body: likePayload,
  });
