import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMembers } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMembers";
import type { IDiscussionboardContentFlag } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardContentFlag";

/**
 * Validate input validation error handling when creating content flags on discussion board posts or comments.
 *
 * This test ensures that invalid requests, such as missing required fields, mutually exclusive post/comment IDs being both present, and improper flag_type values, are properly rejected by the API with validation errors. A valid test member is created as a prerequisite for all cases. Various malformed payloads are then submitted to the content flag creation endpoint. Error responses are checked to confirm correct validation behavior.
 *
 * Process:
 * 1. Create a valid member.
 * 2. Attempt to create a content flag with required field(s) missing.
 * 3. Attempt to create a content flag with both flagged_post_id and flagged_comment_id provided (should be mutually exclusive).
 * 4. Attempt to create a content flag with an invalid flag_type value (e.g., empty string).
 * 5. Attempt to create a content flag with missing auto_flagged.
 * 6. Confirm all requests produce validation errors as expected.
 */
export async function test_api_discussionboard_test_create_content_flag_input_validation_error(
  connection: api.IConnection,
) {
  // 1. Create a valid member (prerequisite)
  const member = await api.functional.discussionboard.actors.members.post(connection, {
    body: {
      joined_at: new Date().toISOString(),
      status: "active",
    },
  });
  typia.assert(member);

  // 2. Missing required flag_type
  await TestValidator.error("missing flag_type should fail")(async () => {
    await api.functional.discussionboard.moderation.contentFlags.post(connection, {
      body: {
        flagged_post_id: typia.random<string & tags.Format<"uuid">>(),
        flagged_by_member_id: member.id,
        // flag_type is missing
        auto_flagged: false,
      },
    });
  });

  // 3. Both flagged_post_id and flagged_comment_id provided
  await TestValidator.error("providing both post and comment ids should fail")(async () => {
    await api.functional.discussionboard.moderation.contentFlags.post(connection, {
      body: {
        flagged_post_id: typia.random<string & tags.Format<"uuid">>(),
        flagged_comment_id: typia.random<string & tags.Format<"uuid">>(),
        flagged_by_member_id: member.id,
        flag_type: "spam",
        auto_flagged: false,
      },
    });
  });

  // 4. Invalid flag_type value (empty string)
  await TestValidator.error("empty flag_type should fail")(async () => {
    await api.functional.discussionboard.moderation.contentFlags.post(connection, {
      body: {
        flagged_post_id: typia.random<string & tags.Format<"uuid">>(),
        flagged_by_member_id: member.id,
        flag_type: "",
        auto_flagged: false,
      },
    });
  });

  // 5. Missing auto_flagged (required field)
  await TestValidator.error("missing auto_flagged should fail")(async () => {
    await api.functional.discussionboard.moderation.contentFlags.post(connection, {
      body: {
        flagged_post_id: typia.random<string & tags.Format<"uuid">>(),
        flagged_by_member_id: member.id,
        flag_type: "spam",
        // auto_flagged is missing
      },
    });
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardPosts } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardPosts";
import type { IDiscussionboardContentFlag } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardContentFlag";

/**
 * Validate that content flag creation fails for unauthenticated or non-member users.
 *
 * Business Context:
 * The content flag endpoint is protected so only authenticated members (or users with sufficient privileges) can create moderation flags. This test ensures that attempts to create flags without being logged in, or by users without appropriate permissions, are correctly rejected by the API, thus enforcing moderation controls and access rights.
 *
 * Test Steps:
 * 1. Create a post using the normal API (simulating a valid post existing in the system).
 * 2. Attempt to create a content flag for the above post **without authentication** (i.e., using a connection object with no or invalid authentication headers).
 * 3. Check that the API denies this action (expecting a 403 Forbidden or equivalent error via TestValidator.error).
 *
 * Note: Only the unauthenticated case is tested due to lack of role/membership simulation in the provided API. If role-based simulation is added to the SDK in future, similar checks for insufficient privilege can be added.
 */
export async function test_api_discussionboard_test_create_content_flag_permission_error_for_non_member(
  connection: api.IConnection,
) {
  // 1. Create a post to ensure there is content to flag. Assume connection is authenticated here.
  const threadId = typia.random<string & tags.Format<"uuid">>();
  const memberId = typia.random<string & tags.Format<"uuid">>();
  const now = new Date().toISOString() as string & tags.Format<"date-time">;
  const post = await api.functional.discussionboard.threads.posts.post(connection, {
    body: {
      discussionboard_thread_id: threadId,
      discussionboard_member_id: memberId,
      body: "Test post for content flag permission check.",
      created_at: now,
    } satisfies IDiscussionboardPosts.ICreate,
  });
  typia.assert(post);

  // 2. Simulate unauthenticated user by stripping auth headers from connection
  const connectionNoAuth: api.IConnection = {
    ...connection,
    headers: {},
  };

  // 3. Attempt to create a content flag while unauthenticated (should fail)
  TestValidator.error("Content flag should not be creatable by non-members")(
    async () => {
      await api.functional.discussionboard.moderation.contentFlags.post(connectionNoAuth, {
        body: {
          flagged_post_id: post.id,
          flagged_comment_id: null,
          flagged_by_member_id: null,
          set_by_moderator_id: null,
          flag_type: "test-flag-type",
          auto_flagged: false,
        } satisfies IDiscussionboardContentFlag.ICreate,
      });
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMembers } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMembers";
import type { IDiscussionboardPosts } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardPosts";
import type { IDiscussionboardContentFlag } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardContentFlag";

/**
 * Validate that a moderator (or admin) can update a content flag (status or type).
 *
 * Business Scenario:
 *   - A normal member creates a post in a thread.
 *   - The post is flagged (by member, moderator, or system) with an initial type (e.g., 'spam').
 *   - A moderator updates the flag record, reclassifying, marking as manual, and assigning themselves as the acting moderator.
 *   - The update must be applied correctly and reflected on the flag object.
 *   - It is expected (though cannot be directly asserted) that such updates are always audit/logged per policy.
 *
 * Steps:
 *   1. Create a normal member account.
 *   2. Create a moderator account (using member API; role distinction is not implemented here but would be in production).
 *   3. Create a post (attached to a synthetic thread ID for testing).
 *   4. Flag that post as 'spam' (member-flagged).
 *   5. Moderator updates the flag to 'abuse,' assigns themselves, and ensures manual (not automated).
 *   6. Assert returned object reflects updates: flag_type, set_by_moderator_id, auto_flagged fields.
 *   7. (Doc) State that audit log is expected though not directly tested in the API response.
 */
export async function test_api_discussionboard_moderation_contentFlags_test_update_content_flag_status_by_moderator(
  connection: api.IConnection,
) {
  // 1. Create a normal member
  const member = await api.functional.discussionboard.actors.members.post(connection, {
    body: {
      joined_at: new Date().toISOString(),
      status: "active",
    } satisfies IDiscussionboardMembers.ICreate,
  });
  typia.assert(member);

  // 2. Create a moderator
  const moderator = await api.functional.discussionboard.actors.members.post(connection, {
    body: {
      joined_at: new Date().toISOString(),
      status: "active",
    } satisfies IDiscussionboardMembers.ICreate,
  });
  typia.assert(moderator);

  // 3. Create a post attached to a synthetic thread
  const threadId = typia.random<string & tags.Format<"uuid">>();
  const post = await api.functional.discussionboard.threads.posts.post(connection, {
    body: {
      discussionboard_thread_id: threadId,
      discussionboard_member_id: member.id,
      body: RandomGenerator.paragraph()(),
      created_at: new Date().toISOString(),
    } satisfies IDiscussionboardPosts.ICreate,
  });
  typia.assert(post);

  // 4. Create a flag on the post, initially by the member
  const initialFlagType = "spam";
  const flag = await api.functional.discussionboard.moderation.contentFlags.post(connection, {
    body: {
      flagged_post_id: post.id,
      flagged_comment_id: null,
      flagged_by_member_id: member.id,
      set_by_moderator_id: null,
      flag_type: initialFlagType,
      auto_flagged: false,
    } satisfies IDiscussionboardContentFlag.ICreate,
  });
  typia.assert(flag);

  // 5. Moderator updates the flag: change type, assign self as moderator, mark as not automated
  const newFlagType = "abuse";
  const updated = await api.functional.discussionboard.moderation.contentFlags.putById(connection, {
    id: flag.id,
    body: {
      flag_type: newFlagType,
      set_by_moderator_id: moderator.id,
      auto_flagged: false,
    } satisfies IDiscussionboardContentFlag.IUpdate,
  });
  typia.assert(updated);

  // 6. Validate changes applied
  TestValidator.equals("flag_type updated")(updated.flag_type)(newFlagType);
  TestValidator.equals("moderator assignment")(updated.set_by_moderator_id)(moderator.id);
  TestValidator.equals("auto_flagged is manual")(updated.auto_flagged)(false);

  // 7. (Doc) Audit logging expected for all updates - not verifiable via API result.
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardContentFlag } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardContentFlag";

/**
 * Validate error handling when updating a content flag with an invalid or non-existent ID.
 *
 * Business context:
 * Updating content moderation flags is restricted and audit-sensitive. Attempting to update 
 * a flag that does not exist or has been deleted should result in a well-defined error such as 404 Not Found.
 *
 * Test steps:
 * 1. Generate a random UUID that is extremely unlikely to exist as a content flag.
 * 2. Attempt to update a flag at this ID using the moderation update endpoint
 *    with a minimal but valid IDiscussionboardContentFlag.IUpdate body.
 * 3. Verify that the API returns an error (preferably 404) indicating that the flag record does not exist.
 * 4. (Negative test) Ensure the response is not a successful update and surfaces correct error handling for non-existent targets.
 *
 * Note: No dependencies or data setup required, as we are purposefully targeting an ID that should not exist. 
 */
export async function test_api_discussionboard_test_update_content_flag_invalid_id_error(
  connection: api.IConnection,
) {
  // 1. Generate a random UUID for a non-existent content flag
  const nonExistentFlagId = typia.random<string & tags.Format<"uuid">>();

  // 2. Construct a minimal valid update payload (no required fields)
  const updatePayload: IDiscussionboardContentFlag.IUpdate = {
    flag_type: "spam", // Using a typical real flag type
  };

  // 3. Attempt to update the non-existent flag
  await TestValidator.error("Should fail updating non-existent content flag")(
    async () => {
      await api.functional.discussionboard.moderation.contentFlags.putById(
        connection,
        {
          id: nonExistentFlagId,
          body: updatePayload,
        },
      );
    },
  );
}

