import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMembers } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMembers";
import type { DiscussionBoardAdmins } from "@ORGANIZATION/PROJECT-api/lib/structures/DiscussionBoardAdmins";
import type { IDiscussionboardPosts } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardPosts";
import type { IDiscussionboardContentFlag } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardContentFlag";

/**
 * E2E test: Soft-delete a content flag as an admin.
 *
 * This test ensures the soft-delete (logical removal) of a moderation content flag from the discussion board.
 * It validates that an admin user can delete a flag, receives a correct deletion result, and all audit fields
 * are present and valid. The flow follows required business logic: user/member creation, admin elevation,
 * content/post creation, flagging, and moderation action by admin.
 *
 * Steps:
 * 1. Create a board member
 * 2. Promote the member to admin (role elevation)
 * 3. Create a post to flag (using the member)
 * 4. Flag the post for moderation (by the member)
 * 5. As admin, soft-delete the flag
 * 6. Validate the API result: correct id, non-empty deleted_at (ISO8601) and success true
 * 7. (SDK does not provide content flag GET API, so post-delete fetch validation cannot be performed)
 */
export async function test_api_discussionboard_moderation_contentFlags_test_delete_content_flag_by_admin(
  connection: api.IConnection,
) {
  // 1. Create a new member
  const memberJoinedAt: string = new Date().toISOString();
  const memberStatus = "active";
  const member = await api.functional.discussionboard.actors.members.post(connection, {
    body: {
      joined_at: memberJoinedAt,
      status: memberStatus,
    },
  });
  typia.assert(member);

  // 2. Promote to admin
  const adminElevationTime = new Date().toISOString();
  const admin = await api.functional.discussionboard.actors.admins.post(connection, {
    body: {
      discussionboard_member_id: member.id,
      elevated_at: adminElevationTime,
    },
  });
  typia.assert(admin);

  // 3. Create a post (to be flagged)
  const threadId = typia.random<string & tags.Format<"uuid">>();
  const postCreatedAt = new Date().toISOString();
  const postBody = "Test post for flagging.";
  const post = await api.functional.discussionboard.threads.posts.post(connection, {
    body: {
      discussionboard_thread_id: threadId,
      discussionboard_member_id: member.id,
      body: postBody,
      created_at: postCreatedAt,
    },
  });
  typia.assert(post);

  // 4. Flag the post (member flags as 'spam')
  const flag = await api.functional.discussionboard.moderation.contentFlags.post(connection, {
    body: {
      flagged_post_id: post.id,
      flagged_comment_id: null,
      flagged_by_member_id: member.id,
      set_by_moderator_id: null,
      flag_type: "spam",
      auto_flagged: false,
    },
  });
  typia.assert(flag);

  // 5. As admin, soft-delete the content flag
  const deletion = await api.functional.discussionboard.moderation.contentFlags.eraseById(connection, {
    id: flag.id,
  });
  typia.assert(deletion);

  // 6. Validate deletion response
  TestValidator.equals("deleted flag id matches")(deletion.id)(flag.id);
  TestValidator.predicate("success true")(deletion.success === true);
  TestValidator.predicate("deleted_at present")(typeof deletion.deleted_at === "string" && deletion.deleted_at.length > 0);
  // No post-delete GET validation possible (endpoint not available)
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMembers } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMembers";
import type { IDiscussionboardContentFlag } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardContentFlag";

/**
 * Test that access control prevents non-admin/moderator users from deleting a content flag.
 *
 * This end-to-end test ensures that deletion of a content flag:
 * - Fails (with 403 Forbidden or similar) for an authenticated regular member (not admin/moderator).
 * - Fails for an unauthenticated (public) user as well.
 *
 * Steps:
 * 1. Register a regular member account.
 * 2. Create a content flag record that will be targeted for attempted deletion.
 * 3. Attempt to delete the flag as the regular member — should receive a permission error.
 * 4. Attempt to delete the flag as an unauthenticated (public) user — should also receive a permission or authentication error.
 *
 * This test validates that only privileged roles (admin/moderator) may delete content flags, and all other attempts are properly rejected by the API.
 */
export async function test_api_discussionboard_moderation_contentFlags_test_delete_content_flag_permission_error_for_non_admin_moderator(
  connection: api.IConnection,
) {
  // 1. Register a regular (non-privileged) member
  const memberInput: IDiscussionboardMembers.ICreate = {
    joined_at: new Date().toISOString() as string & tags.Format<"date-time">,
    status: "active",
  };
  const member = await api.functional.discussionboard.actors.members.post(
    connection,
    { body: memberInput },
  );
  typia.assert(member);

  // 2. Create a content flag as that member (so flag exists for testing)
  const flagInput: IDiscussionboardContentFlag.ICreate = {
    flagged_post_id: typia.random<string & tags.Format<"uuid">>(),
    flagged_comment_id: null,
    flagged_by_member_id: member.id,
    set_by_moderator_id: null,
    flag_type: "spam",
    auto_flagged: false,
  };
  const flag = await api.functional.discussionboard.moderation.contentFlags.post(
    connection,
    { body: flagInput },
  );
  typia.assert(flag);

  // 3. Attempt to delete the flag as the regular member (should fail: forbidden/permission error)
  await TestValidator.error("regular member cannot delete content flag")(async () => {
    await api.functional.discussionboard.moderation.contentFlags.eraseById(
      connection,
      { id: flag.id },
    );
  });

  // 4. Attempt to delete the flag as an unauthenticated/public user (should also fail)
  const publicConnection = { ...connection, headers: { ...connection.headers } };
  delete publicConnection.headers.Authorization;
  await TestValidator.error("public user cannot delete content flag")(async () => {
    await api.functional.discussionboard.moderation.contentFlags.eraseById(
      publicConnection,
      { id: flag.id },
    );
  });
}

