import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMembers } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMembers";
import type { DiscussionBoardAdmins } from "@ORGANIZATION/PROJECT-api/lib/structures/DiscussionBoardAdmins";
import type { IDiscussionboardComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardComment";
import type { IDiscussionboardCommentDislike } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardCommentDislike";
import type { IPageIDiscussionboardCommentDislike } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionboardCommentDislike";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * 다양한 필터 및 페이징 조합에서 댓글 싫어요 리스트 검색 E2E 검증
 *
 * 본 테스트는 다음을 주요 목적으로 한다:
 * - 일반 멤버일 때 자신이 누른 싫어요만 목록으로 보임을 보장
 * - 관리자는 전체를 조회할 수 있고 필터, 페이징, 날짜 지정 등이 정확하게 적용됨을 보장
 * - 잘못된 필터(존재하지 않는 멤버ID, 코멘트ID 등), 데이터 없는 상황, 범위 초과 페이지 요청에 대해 graceful handling 확인
 *
 * 구체 시나리오:
 * 1. 회원 A, B 생성 → B를 admin 으로 승격
 * 2. A, B 각각 적어도 하나씩 여러 개 댓글 작성
 * 3. 서로 교차로 dislike(싫어요) 여러 개 생성 (케이스별 분포)
 * 4. 일반 A→ 자신의 싫어요만 보이는지 다양한 조건/페이징/필터로 검색 반복
 * 5. admin B→ 전체/필터/엣지케이스 등 자유 검색 및 접근권한 확인
 */
export async function test_api_discussionboard_test_list_comment_dislikes_with_various_filters_and_pagination(
  connection: api.IConnection,
) {
  // --- [사전 데이터 준비: 회원 및 댓글/싫어요 생성] ---

  // 1. 회원 2명 생성 (A, B)
  const memberA = await api.functional.discussionboard.actors.members.post(connection, {
    body: {
      joined_at: new Date().toISOString(),
      status: 'active',
    },
  });
  typia.assert(memberA);

  const memberB = await api.functional.discussionboard.actors.members.post(connection, {
    body: {
      joined_at: new Date().toISOString(),
      status: 'active',
    },
  });
  typia.assert(memberB);

  // 편의를 위해 A로그인을 기본으로, 필터 권한 체크 전환 때만 B(admin) context로 스위칭함

  // 2. memberB를 admin 승격
  const adminElevate = await api.functional.discussionboard.actors.admins.post(connection, {
    body: {
      discussionboard_member_id: memberB.id,
      elevated_at: new Date().toISOString(),
    },
  });
  typia.assert(adminElevate);

  // 3. 댓글 여러 개 작성: A/B 각각 post_id 임의로 생성해 2개씩
  const comments: api.IDiscussionboardComment[] = [];
  for (let i = 0; i < 2; ++i) {
    // A가 작성
    const commentA = await api.functional.discussionboard.threads.comments.post(connection, {
      body: {
        discussionboard_post_id: typia.random<string & tags.Format<"uuid">>(),
        discussionboard_member_id: memberA.id,
        body: `memberA-댓글-${i}`,
        parent_id: null,
      },
    });
    typia.assert(commentA);
    comments.push(commentA);

    // B가 작성
    const commentB = await api.functional.discussionboard.threads.comments.post(connection, {
      body: {
        discussionboard_post_id: typia.random<string & tags.Format<"uuid">>(),
        discussionboard_member_id: memberB.id,
        body: `memberB-댓글-${i}`,
        parent_id: null,
      },
    });
    typia.assert(commentB);
    comments.push(commentB);
  }

  // 4. 댓글별로 cross-dislike 분포: A/B가 각자 여러 댓글에 싫어요 (일부 중복, 일부는 A만, 일부는 B만)
  // 총 4개 댓글, 각 댓글마다 최소 1개(본인/상대방), 일부는 둘 다가 싫어요
  const dislikes: api.IDiscussionboardCommentDislike[] = [];
  // 첫번째 댓글: A, 두번째: B, 세번째: A/B 모두, 네번째: 아무도 안 누름(엣지케이스)
  // 댓글 0 (작성자 A) - A만 dislike
  const dislikeA0 = await api.functional.discussionboard.interactions.commentDislikes.post(connection, {
    body: { discussionboard_comment_id: comments[0].id },
  });
  typia.assert(dislikeA0);
  dislikes.push(dislikeA0);
  // 댓글 1 (작성자 B) - B만 dislike
  const dislikeB1 = await api.functional.discussionboard.interactions.commentDislikes.post(connection, {
    body: { discussionboard_comment_id: comments[1].id },
  });
  typia.assert(dislikeB1);
  dislikes.push(dislikeB1);
  // 댓글 2 (작성자 A) - A/B 모두 dislike
  const dislikeA2 = await api.functional.discussionboard.interactions.commentDislikes.post(connection, {
    body: { discussionboard_comment_id: comments[2].id },
  });
  typia.assert(dislikeA2);
  dislikes.push(dislikeA2);
  // (A context로 B도 눌러야 하므로 admin(B) context로 임시 로그인 필요)
  // 일반적으로 access token 기반 계정 전환이면 여기서 admin으로 전환 후 아래 작업. 본 테스트는
  // connection이 member 기반 인증을 실제로 구분하고 있다는 전제하에, context 전환시
  // admin post 이후, 별도 세션 연결이 필요할 수 있음(실제 환경에서는 따로 테스트 프레임워크에서 분리)

  // 댓글 2에 대해 B도 dislike (admin context로)
  // (실제 환경에선 여기에 memberB 세션 연결 필요, 테스트 시에는 connection 재활용)
  const dislikeB2 = await api.functional.discussionboard.interactions.commentDislikes.post(connection, {
    body: { discussionboard_comment_id: comments[2].id },
  });
  typia.assert(dislikeB2);
  dislikes.push(dislikeB2);

  //  --- [Step 1: 일반 회원 A로 dislike 목록 조회 - 권한 테스트] ---
  // (memberA context로 조회한다고 가정)
  // 1) 아무 필터 없이 호출: 내 것만 조회되어야 함
  let page = await api.functional.discussionboard.interactions.commentDislikes.patch(connection, {
    body: {},
  });
  typia.assert(page);
  // member_id가 모두 memberA임을 확인
  for (const d of page.data) {
    TestValidator.equals("내꺼만 조회됨")(d.discussionboard_member_id)(memberA.id);
  }

  // 2) member_id 명시적으로 본인 id로 지정
  page = await api.functional.discussionboard.interactions.commentDislikes.patch(connection, {
    body: { member_id: memberA.id },
  });
  typia.assert(page);
  for (const d of page.data) {
    TestValidator.equals("member_id=본인 지정")(d.discussionboard_member_id)(memberA.id);
  }

  // 3) member_id에 타인(memberB) 지정: 그래도 내꺼만 조회되어야 함
  page = await api.functional.discussionboard.interactions.commentDislikes.patch(connection, {
    body: { member_id: memberB.id },
  });
  typia.assert(page);
  for (const d of page.data) {
    TestValidator.equals("타인 지정해도 내꺼만")(d.discussionboard_member_id)(memberA.id);
  }

  // 4) comment_id에 특정 댓글 지정: memberA가 눌렀던 댓글에만 데이터, 없으면 빈 배열
  page = await api.functional.discussionboard.interactions.commentDislikes.patch(connection, {
    body: { comment_id: comments[0].id },
  });
  typia.assert(page);
  for (const d of page.data) {
    TestValidator.equals("comment_id필터=댓글0")(d.discussionboard_comment_id)(comments[0].id);
    TestValidator.equals("내꺼만")(d.discussionboard_member_id)(memberA.id);
  }

  // 5) paging/limit 등 조합
  page = await api.functional.discussionboard.interactions.commentDislikes.patch(connection, {
    body: { limit: 1, page: 1 },
  });
  typia.assert(page);
  // limit=1로 1개만 나와야 함
  TestValidator.equals("limit=1, page=1만큼만")(page.data.length)(1);

  //  --- [Step 2: admin 권한으로 전체/필터/엣지케이스 테스트] ---
  // (memberB→admin context로 전환하여 전체 및 조합 검증. 실제론 별도 세션/connection 필요할 수 있음)

  // 1) 아무 필터 없이 전체: 전체 dislike 목록
  page = await api.functional.discussionboard.interactions.commentDislikes.patch(connection, {
    body: {},
  });
  typia.assert(page);
  // A, B 모두의 dislike가 나옴
  const allMemberIds = new Set(page.data.map(x => x.discussionboard_member_id));
  TestValidator.predicate("A/B 모두 있음")(
    allMemberIds.has(memberA.id) && allMemberIds.has(memberB.id),
  );

  // 2) member_id, comment_id, 날짜범위(created_after/before)
  // member_id=memberB
  page = await api.functional.discussionboard.interactions.commentDislikes.patch(connection, {
    body: { member_id: memberB.id },
  });
  typia.assert(page);
  for (const d of page.data) {
    TestValidator.equals("admin-member B 필터")(d.discussionboard_member_id)(memberB.id);
  }
  // comment_id=comments[2] (동일한 댓글 A/B 둘이 싫어요 누름)
  page = await api.functional.discussionboard.interactions.commentDislikes.patch(connection, {
    body: { comment_id: comments[2].id },
  });
  typia.assert(page);
  for (const d of page.data) {
    TestValidator.equals("특정 댓글필터")(d.discussionboard_comment_id)(comments[2].id);
  }
  // 날짜 범위 - created_after (싫어요 하나의 created_at을 사용, 그 이후로는 0건 예상)
  const recent = dislikes[dislikes.length - 1].created_at;
  page = await api.functional.discussionboard.interactions.commentDislikes.patch(connection, {
    body: { created_after: recent },
  });
  typia.assert(page);
  TestValidator.equals("created_after 없거나 0건임")(page.data.length)(0);

  // 3) 페이징: limit=2로 1페이지, 2페이지
  page = await api.functional.discussionboard.interactions.commentDislikes.patch(connection, {
    body: { limit: 2, page: 1 },
  });
  typia.assert(page);
  TestValidator.equals("limit=2 페이지1")(page.data.length)(2);
  // 2페이지
  page = await api.functional.discussionboard.interactions.commentDislikes.patch(connection, {
    body: { limit: 2, page: 2 },
  });
  typia.assert(page);
  // 남은 dislikes 개수 체크
  TestValidator.equals("limit=2 페이지2")(page.data.length)(dislikes.length - 2);

  // 4) 존재하지 않는 값, 유효하지 않은 값, 데이터가 비어있는 경우 edge case: 없는 member_id, comment_id, page 범위 초과
  page = await api.functional.discussionboard.interactions.commentDislikes.patch(connection, {
    body: { member_id: typia.random<string & tags.Format<"uuid">>() },
  });
  typia.assert(page);
  TestValidator.equals("없는멤버id=0건")(page.data.length)(0);

  page = await api.functional.discussionboard.interactions.commentDislikes.patch(connection, {
    body: { comment_id: typia.random<string & tags.Format<"uuid">>() },
  });
  typia.assert(page);
  TestValidator.equals("없는코멘트id=0건")(page.data.length)(0);

  page = await api.functional.discussionboard.interactions.commentDislikes.patch(connection, {
    body: { page: 9999 },
  });
  typia.assert(page);
  TestValidator.equals("페이지 초과 데이터=0건")(page.data.length)(0);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMembers } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMembers";
import type { DiscussionBoardAdmins } from "@ORGANIZATION/PROJECT-api/lib/structures/DiscussionBoardAdmins";
import type { IDiscussionboardComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardComment";
import type { IDiscussionboardCommentDislike } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardCommentDislike";

/**
 * E2E test for retrieving a single comment dislike by its ID on the Discussion Board.
 *
 * PURPOSE:
 * Validates that a comment dislike entry can be fetched by its unique identifier, with full field validation and correct permission controls.
 *
 * BUSINESS CONTEXT:
 * This endpoint is essential for viewing the audit record of a dislike event on a comment. The system must ensure that only the record owner, or a user with privileged roles (admin/moderator), can retrieve a given comment dislike, while others are denied access.
 *
 * TEST STEPS:
 * 1. Register two members: one regular user and one (who will become) admin.
 * 2. Promote one member to admin via the admins API.
 * 3. As regular user, create a comment (thread not modeled, but post ID required).
 * 4. As the same regular user, create a dislike for the comment.
 * 5. Fetch the dislike by its ID as the creating user; verify all fields.
 * 6. As another regular user, attempt to fetch the dislike; should receive forbidden or not found error.
 * 7. As admin, fetch the dislike; should succeed and all fields must be correct.
 * 8. Attempt to fetch a dislike with a non-existent ID (random UUID); verify not found error.
 */
export async function test_api_discussionboard_interactions_commentDislikes_getById(
  connection: api.IConnection,
) {
  // 1. Register member A (regular user)
  const memberA = await api.functional.discussionboard.actors.members.post(connection, {
    body: {
      joined_at: new Date().toISOString(),
      status: 'active',
    },
  });
  typia.assert(memberA);

  // 2. Register member B (to be admin)
  const memberB = await api.functional.discussionboard.actors.members.post(connection, {
    body: {
      joined_at: new Date().toISOString(),
      status: 'active',
    },
  });
  typia.assert(memberB);

  // 3. Promote member B to admin
  const admin = await api.functional.discussionboard.actors.admins.post(connection, {
    body: {
      discussionboard_member_id: memberB.id,
      elevated_at: new Date().toISOString(),
    },
  });
  typia.assert(admin);

  // 4. As member A, create a comment on a fake post ID (simulate post with UUID)
  const fakePostId = typia.random<string & tags.Format<'uuid'>>();
  const comment = await api.functional.discussionboard.threads.comments.post(connection, {
    body: {
      discussionboard_post_id: fakePostId,
      discussionboard_member_id: memberA.id,
      body: 'Test comment by member A',
    },
  });
  typia.assert(comment);

  // 5. As member A, create a dislike entry for the comment
  const dislike = await api.functional.discussionboard.interactions.commentDislikes.post(connection, {
    body: {
      discussionboard_comment_id: comment.id,
    },
  });
  typia.assert(dislike);

  // 6. Fetch dislike by ID as member A (should succeed, compare fields)
  const fetchedByOwner = await api.functional.discussionboard.interactions.commentDislikes.getById(connection, { id: dislike.id });
  typia.assert(fetchedByOwner);
  TestValidator.equals('Fetched dislike equals created')(fetchedByOwner)(dislike);

  // 7. Register member C (another regular user)
  const memberC = await api.functional.discussionboard.actors.members.post(connection, {
    body: {
      joined_at: new Date().toISOString(),
      status: 'active',
    },
  });
  typia.assert(memberC);

  // 8. As member C, attempt to fetch the dislike by ID (should fail: forbidden or not found)
  TestValidator.error('Non-owner user cannot fetch another user’s dislike')(
    async () => {
      await api.functional.discussionboard.interactions.commentDislikes.getById(connection, { id: dislike.id });
    },
  );

  // 9. As admin, fetch the dislike by ID (should succeed)
  // (Assume context switch for admin, or direct API call given stateless connection)
  const fetchedByAdmin = await api.functional.discussionboard.interactions.commentDislikes.getById(connection, { id: dislike.id });
  typia.assert(fetchedByAdmin);
  TestValidator.equals('Admin fetch matches original')(fetchedByAdmin)(dislike);

  // 10. Attempt to fetch a dislike record with non-existent ID
  TestValidator.error('Not found when fetching with non-existent ID')(
    async () => {
      await api.functional.discussionboard.interactions.commentDislikes.getById(connection, { id: typia.random<string & tags.Format<'uuid'>>() });
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMembers } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMembers";
import type { IDiscussionBoardMemberSuspension } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMemberSuspension";
import type { IDiscussionboardComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardComment";
import type { IDiscussionboardCommentDislike } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardCommentDislike";

/**
 * Test successful creation of a comment dislike and enforcement of one-dislike-per-member rule.
 *
 * - Validates that an authenticated member can dislike a comment.
 * - Ensures duplicate dislikes (same member/comment) are rejected.
 * - Checks unauthenticated and suspended access restrictions.
 * - Handles error for invalid comment ID.
 * - Assumes audit events are occurring on successful API calls (no direct read/assert).
 *
 * Steps:
 * 1. Register Member #1 (active)
 * 2. Register Member #2 (who will be suspended)
 * 3. Create a test comment as Member #1
 * 4. Member #1 dislikes the comment (success)
 * 5. Try duplicate dislike as Member #1 (should fail)
 * 6. Attempt dislike as unauthenticated user (should fail)
 * 7. Suspend Member #2
 * 8. Try dislike as suspended Member #2 (should fail)
 * 9. Try dislike on invalid comment ID (should fail)
 */
export async function test_api_discussionboard_test_create_comment_dislike_success_and_duplicate_prevention(
  connection: api.IConnection,
) {
  // 1. Register Member #1
  const member1 = await api.functional.discussionboard.actors.members.post(connection, {
    body: {
      joined_at: new Date().toISOString(),
      status: 'active',
    } satisfies IDiscussionboardMembers.ICreate,
  });
  typia.assert(member1);

  // 2. Register Member #2
  const member2 = await api.functional.discussionboard.actors.members.post(connection, {
    body: {
      joined_at: new Date().toISOString(),
      status: 'active',
    } satisfies IDiscussionboardMembers.ICreate,
  });
  typia.assert(member2);

  // 3. Create a comment as Member #1 (simulate post with random UUID)
  const fakePostId = typia.random<string & tags.Format<'uuid'>>();
  const comment = await api.functional.discussionboard.threads.comments.post(connection, {
    body: {
      discussionboard_post_id: fakePostId,
      discussionboard_member_id: member1.id,
      body: 'Test comment for dislike flow.',
      parent_id: null,
    } satisfies IDiscussionboardComment.ICreate,
  });
  typia.assert(comment);

  // 4. Member #1 dislikes the comment
  const dislike1 = await api.functional.discussionboard.interactions.commentDislikes.post(connection, {
    body: { discussionboard_comment_id: comment.id } satisfies IDiscussionboardCommentDislike.ICreate,
  });
  typia.assert(dislike1);
  TestValidator.equals('dislike target comment')(dislike1.discussionboard_comment_id)(comment.id);
  TestValidator.equals('dislike by member1')(dislike1.discussionboard_member_id)(member1.id);

  // 5. Duplicate dislike attempt by Member #1 (should fail)
  await TestValidator.error('duplicate dislike rejected')(() =>
    api.functional.discussionboard.interactions.commentDislikes.post(connection, {
      body: { discussionboard_comment_id: comment.id } satisfies IDiscussionboardCommentDislike.ICreate,
    })
  );

  // 6. Attempt dislike as unauthenticated (clear headers to simulate)
  const unauthConn: api.IConnection = { ...connection, headers: {} };
  await TestValidator.error('unauthenticated cannot dislike')(() =>
    api.functional.discussionboard.interactions.commentDislikes.post(unauthConn, {
      body: { discussionboard_comment_id: comment.id } satisfies IDiscussionboardCommentDislike.ICreate,
    })
  );

  // 7. Suspend Member #2
  const suspension = await api.functional.discussionboard.actors.memberSuspensions.post(connection, {
    body: {
      discussionboard_member_id: member2.id,
      reason: 'Automated test suspension',
      starts_at: new Date().toISOString(),
      ends_at: null,
    } satisfies IDiscussionBoardMemberSuspension.ICreate,
  });
  typia.assert(suspension);

  // 8. Attempt dislike as suspended Member #2 (simulate via header override)
  const suspendedConn: api.IConnection = { ...connection, headers: { ...connection.headers, 'X-Member-ID': member2.id } };
  await TestValidator.error('suspended member cannot dislike')(() =>
    api.functional.discussionboard.interactions.commentDislikes.post(suspendedConn, {
      body: { discussionboard_comment_id: comment.id } satisfies IDiscussionboardCommentDislike.ICreate,
    })
  );

  // 9. Attempt dislike on invalid comment ID
  await TestValidator.error('dislike fails for nonexistent comment')(() =>
    api.functional.discussionboard.interactions.commentDislikes.post(connection, {
      body: { discussionboard_comment_id: typia.random<string & tags.Format<'uuid'>>() } satisfies IDiscussionboardCommentDislike.ICreate,
    })
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMembers } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMembers";
import type { DiscussionBoardAdmins } from "@ORGANIZATION/PROJECT-api/lib/structures/DiscussionBoardAdmins";
import type { IDiscussionboardComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardComment";
import type { IDiscussionboardCommentDislike } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardCommentDislike";

/**
 * Test updating a comment dislike record by both the dislike owner and an admin.
 *
 * This test verifies permission, validation, and correct update logic:
 * 1. A member (owner) can update their own dislike (e.g., to point to a different comment if schema allows).
 * 2. An admin can update any comment dislike record (admin/audit flow).
 * 3. Attempting to update a non-existent dislike returns an error response.
 *
 * Audit log checking is NOT performed due to missing API. Non-owner/non-admin forbidden test is commented for lack of authentication switching.
 *
 * Steps:
 * - Create two members: one will be the dislike owner, the other will later be elevated to admin.
 * - Create at least two comments.
 * - Owner creates a dislike record pointing at the first comment.
 * - Owner updates their dislike to point to the second comment and verifies the change.
 * - The admin user updates the same dislike to point back to the first comment and verifies the change.
 * - Attempt to update a non-existent dislike ID and confirm error response.
 */
export async function test_api_discussionboard_test_update_comment_dislike_by_owner_and_admin(
  connection: api.IConnection,
) {
  // Step 1: Register two members
  const member1 = await api.functional.discussionboard.actors.members.post(connection, {
    body: {
      joined_at: new Date().toISOString(),
      status: "active",
    },
  });
  typia.assert(member1);
  const member2 = await api.functional.discussionboard.actors.members.post(connection, {
    body: {
      joined_at: new Date().toISOString(),
      status: "active",
    },
  });
  typia.assert(member2);

  // Step 2: Create two comments under the same post
  const postId = typia.random<string & tags.Format<"uuid">>();
  const comment1 = await api.functional.discussionboard.threads.comments.post(connection, {
    body: {
      discussionboard_post_id: postId,
      discussionboard_member_id: member1.id,
      body: "First comment body",
    },
  });
  typia.assert(comment1);
  const comment2 = await api.functional.discussionboard.threads.comments.post(connection, {
    body: {
      discussionboard_post_id: postId,
      discussionboard_member_id: member1.id,
      body: "Second comment body",
    },
  });
  typia.assert(comment2);

  // Step 3: Owner creates a comment dislike on the first comment
  const dislike = await api.functional.discussionboard.interactions.commentDislikes.post(connection, {
    body: {
      discussionboard_comment_id: comment1.id,
    },
  });
  typia.assert(dislike);

  // Step 4: Owner updates their dislike to point to the second comment
  const updatedDislikeByOwner = await api.functional.discussionboard.interactions.commentDislikes.putById(connection, {
    id: dislike.id,
    body: {
      discussionboard_comment_id: comment2.id,
    },
  });
  typia.assert(updatedDislikeByOwner);
  TestValidator.equals("dislike updated by owner")(updatedDislikeByOwner.discussionboard_comment_id)(comment2.id);

  // Step 5: Promote member2 to admin role
  const adminRole = await api.functional.discussionboard.actors.admins.post(connection, {
    body: {
      discussionboard_member_id: member2.id,
      elevated_at: new Date().toISOString(),
    },
  });
  typia.assert(adminRole);

  // Step 6: Admin updates the dislike back to the first comment
  const updatedDislikeByAdmin = await api.functional.discussionboard.interactions.commentDislikes.putById(connection, {
    id: dislike.id,
    body: {
