  );

  // Step 4j: Permissions – as unauthenticated (simulate by removing connection.headers.Authorization)
  // [NOTE: This step is a proxy simulation. If the API uses the connection.auth mechanism, clear or omit it.]
  // We'll patch connection to reflect removed auth (deep copy & delete auth header)
  const unauthConn: api.IConnection = { ...connection, headers: { ...connection.headers } };
  if (unauthConn.headers && "Authorization" in unauthConn.headers)
    delete unauthConn.headers.Authorization;
  await TestValidator.error("unauthenticated access gets 403")(
    async () => {
      await api.functional.discussionboard.moderation.moderationLogs.patch(unauthConn, {
        body: {},
      });
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
