/**
 * 테스트 목적: 관리자가 다양한 필터 조건, 페이지네이션, 그리고 소프트 삭제 후 상황에서 토론 스레드 목록을 정상적으로 조회·필터링 할 수 있는지 검증한다.
 *
 * 비즈니스 시나리오:
 * 1. 관리자로 인증한다(구현 가능한 범위까지만).
 * 2. 서로 다른 카테고리에 속하는 두 게시판을 생성한다.
 * 3. 여러 명의 생성자(멤버) UUID와 다양한 상태 및 생성 시점을 가진 스레드들을 각각 생성한다.
 * 4. (case 1) 특정 보드를 기준으로 스레드 목록을 검색하고, 응답 목록이 올바르게 필터링(지정 보드에 속한 항목만) 되는지, pagination 메타 정보가 실제 결과와 부합하는지 체크한다.
 * 5. (case 2) status(예: 'open')로만 필터링하여 검색했을 때 정확하게 매칭되는 스레드만 반환되는지 확인한다.
 * 6. (case 3) 제목 내 특정 단어로 filter 검색했을 때 제목/본문에 해당 키워드가 들어간 항목만 반환되는지 검사한다.
 * 7. (case 4) limit/page 옵션을 조합하여 일부 페이지만 순차 조회, pagination 메타 나누기 및 data slicing 정상 동작하는지 확인.
 * 8. (case 5) filter, board, status 중 하나 이상에 대해 무매칭/빈 결과 반환 시 pagination과 data가 올바른 빈 상태인지를 검증한다.
 * 9. (case 6) 생성된 스레드 일부를 soft delete 처리 후 조회 시 삭제 스레드가 결과에 포함되지 않는지 확인한다.
 * 10. 인증이 없거나 충분한 권한이 없는 경우 적절한 에러가 반환되는지 체크한다(구현 가능한 경우에 한함).
 *
 * 중요: IDiscussionboardThreads.IRequest, IPageIDiscussionboardThreads, DiscussionboardBoard, 그리고 IDiscussionboardThreads 구조체를 활용할 것.
 */
export async function test_api_discussionboard_test_list_threads_with_pagination_and_filters_as_admin(connection: api.IConnection) {
  // 1. 관리자로 인증 (구현 불가 시 생략, 유저 인증 API 없음)

  // 2. 두 게시판 생성
  const board1 = await api.functional.discussionboard.boards.boards.post(connection, {
    body: {
      discussionboard_category_id: typia.random<string & tags.Format<'uuid'>>(),
      code: RandomGenerator.alphaNumeric(8),
      name: RandomGenerator.alphaNumeric(10),
      description: RandomGenerator.paragraph()(),
      is_active: true,
    } satisfies DiscussionboardBoard.ICreate,
  });
  typia.assert(board1);
  const board2 = await api.functional.discussionboard.boards.boards.post(connection, {
    body: {
      discussionboard_category_id: typia.random<string & tags.Format<'uuid'>>(),
      code: RandomGenerator.alphaNumeric(8),
      name: RandomGenerator.alphaNumeric(10),
      description: RandomGenerator.paragraph()(),
      is_active: true,
    } satisfies DiscussionboardBoard.ICreate,
  });
  typia.assert(board2);

  // 3. 다양한 멤버 ID, 상태, 생성일 조합으로 여러 스레드 생성
  /**
   * 멤버가 여러 명이거나 다양한 상태(예: open/closed/locked) 및 보드 분산이 되도록 7개 가량 세분 생성한다.
   */
  const memberIds = [typia.random<string & tags.Format<'uuid'>>(), typia.random<string & tags.Format<'uuid'>>(), typia.random<string & tags.Format<'uuid'>>()];
  const statuses = ['open', 'closed', 'locked'];
  const threads = await ArrayUtil.asyncRepeat(7)(async (i) => {
    const board = i % 2 === 0 ? board1 : board2;
    const status = statuses[i % statuses.length];
    const memberId = memberIds[i % memberIds.length];
    const created_at = new Date(Date.now() - i * 86400000).toISOString();
    return await api.functional.discussionboard.threads.threads.post(connection, {
      body: {
        discussionboard_board_id: board.id,
        discussionboard_member_id: memberId,
        title: `테스트 스레드_${status}_${i}`,
        description: i % 2 === 0 ? RandomGenerator.paragraph()() : null,
        status,
        created_at,
      } satisfies IDiscussionboardThreads.ICreate,
    });
  });
  threads.forEach(typia.assert);

  // 4. (case 1) 특정 board_id로 필터링
  const listByBoard = await api.functional.discussionboard.threads.threads.patch(connection, {
    body: {
      discussionboard_board_id: board1.id,
    },
  });
  typia.assert(listByBoard);
  listByBoard.data.forEach((thread) => TestValidator.equals('board 필터링')(thread.discussionboard_board_id)(board1.id));

  // 5. (case 2) status=open 필터링
  const listByStatus = await api.functional.discussionboard.threads.threads.patch(connection, {
    body: {
      status: 'open',
    },
  });
  typia.assert(listByStatus);
  listByStatus.data.forEach((thread) => TestValidator.equals('status=open')(thread.status)('open'));

  // 6. (case 3) 제목 내 특정 단어로 검색
  const keyword = '테스트 스레드_open_';
  const listByFilter = await api.functional.discussionboard.threads.threads.patch(connection, {
    body: {
      filter: keyword,
    },
  });
  typia.assert(listByFilter);
  listByFilter.data.forEach((thread) => TestValidator.predicate('제목 키워드')(thread.title.includes('open')));

  // 7. (case 4) pagination: limit, page
  const paged = await api.functional.discussionboard.threads.threads.patch(connection, {
    body: {
      limit: 3,
      page: 2,
    },
  });
  typia.assert(paged);
  TestValidator.equals('2번째 페이지')(paged.pagination.current)(2);
  TestValidator.equals('페이지 사이즈')(paged.data.length <= 3)(true);

  // 8. (case 5) no-matching: filter, board, status 등으로 빈 결과 반환
  const empty = await api.functional.discussionboard.threads.threads.patch(connection, {
    body: {
      status: 'locked',
      discussionboard_board_id: board1.id,
      filter: 'not_exist_keyword',
    },
  });
  typia.assert(empty);
  TestValidator.equals('empty data')(empty.data.length)(0);

  // 9. (case 6) thread soft-delete 후 미포함 여부
  const deletedThread = threads[0];
  await api.functional.discussionboard.threads.threads.eraseById(connection, {
    id: deletedThread.id,
  });
  const listAfterDelete = await api.functional.discussionboard.threads.threads.patch(connection, {
    body: {
      discussionboard_board_id: deletedThread.discussionboard_board_id,
    },
  });
  typia.assert(listAfterDelete);
  TestValidator.notEquals('삭제된 thread 미포함')(listAfterDelete.data.find((th) => th.id === deletedThread.id))(deletedThread);

  // 10. 인증이 없는 경우/권한이 부족한 경우 (인증 API 미제공으로 생략)
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMembers } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMembers";
import type { IDiscussionBoardMemberSuspension } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMemberSuspension";
import type { IDiscussionboardThreads } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardThreads";
import type { IPageIDiscussionboardThreads } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionboardThreads";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * 검증: 정지된 회원은 스레드 목록 조회가 거부되어야 한다
 *
 * 비즈니스 목적 및 이유:
 * 게시판의 회원 접근제어 정책에 따라, 특정 사유로 정지(정상 이용이 일시적으로 금지)된 회원은 스레드(게시글) 목록을 조회할 수 없어야 하거나,
 * 혹은 목록이 반환된다 하더라도 정상적인 결과가 아니라는 응답(에러, 빈 데이터, 제한 메시지 등)이 기획에 맞게 반환되어야 한다.
 *
 * 테스트 과정 요약:
 * 1. 일반 회원을 등록한다 (actors/members.post)
 * 2. 해당 회원을 정지시킨다 (actors/memberSuspensions.post)
 * 3. 해당 회원 권한(세션)으로 스레드 목록을 패치(PATCH) 요청한다 (threads/threads.patch)
 * 4. 에러가 발생하거나 제한/거부되는 결과인지 검증한다
 */
export async function test_api_discussionboard_test_list_threads_as_suspended_member_denied(
  connection: api.IConnection,
) {
  // 1. 일반 회원을 등록한다
  const member = await api.functional.discussionboard.actors.members.post(connection, {
    body: {
      joined_at: new Date().toISOString(),
      status: "active",
    },
  });
  typia.assert(member);

  // 2. 해당 회원을 정지시킨다
  const suspension = await api.functional.discussionboard.actors.memberSuspensions.post(connection, {
    body: {
      discussionboard_member_id: member.id,
      reason: "Test suspension for restriction verification",
      starts_at: new Date().toISOString(),
    },
  });
  typia.assert(suspension);

  // 3. 정지 회원 자격(session) 확보 (실제 구현에선 인증 세션 전환 필요하나, 별도의 로그인 API 없으므로, 가정됨)
  // 4. 스레드 목록 조회시 제한/거부되는지 확인
  await TestValidator.error("정지된 회원은 스레드 목록 패치가 거부되어야 함")(
    async () => {
      await api.functional.discussionboard.threads.threads.patch(connection, {
        body: {},
      });
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMembers } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMembers";
import type { IDiscussionboardThreads } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardThreads";

/**
 * Validates retrieval and error behaviors of thread detail API (by thread ID).
 *
 * 1. Register a new member (regular user).
 * 2. Create a new thread authored by the member (requiring unique board/member IDs).
 * 3. Retrieve the thread by its ID and verify all fields are populated and correct (including that deleted_at is null).
 * 4. Attempt to retrieve a random, non-existent thread; must error with not-found or similar failure.
 * 5. Soft-delete the created thread.
 * 6. Attempt to retrieve the deleted thread (should fail or indicate deletion).
 *
 * This test ensures both successful and error flows are validated, business rules are respected, and deletion behavior is correct.
 */
export async function test_api_discussionboard_test_get_thread_details_success_and_not_found(
  connection: api.IConnection,
) {
  // 1. Register a new member
  const memberInput: IDiscussionboardMembers.ICreate = {
    joined_at: new Date().toISOString(),
    status: "active",
  };
  const member = await api.functional.discussionboard.actors.members.post(connection, { body: memberInput });
  typia.assert(member);

  // 2. Create a thread for a random board authored by this member
  const threadInput: IDiscussionboardThreads.ICreate = {
    discussionboard_board_id: typia.random<string & tags.Format<"uuid">>(),
    discussionboard_member_id: member.id,
    title: "Test Thread Title",
    description: "Test thread body for E2E validation.",
    status: "open",
    created_at: new Date().toISOString(),
  };
  const thread = await api.functional.discussionboard.threads.threads.post(connection, { body: threadInput });
  typia.assert(thread);
  TestValidator.equals("discussionboard_member_id")(thread.discussionboard_member_id)(member.id);
  TestValidator.equals("title")(thread.title)(threadInput.title);
  TestValidator.equals("description")(thread.description)(threadInput.description);
  TestValidator.equals("status")(thread.status)(threadInput.status);

  // 3. Retrieve the thread by its ID and verify all fields (including no deletion)
  const readThread = await api.functional.discussionboard.threads.threads.getById(connection, { id: thread.id });
  typia.assert(readThread);
  TestValidator.equals("id")(readThread.id)(thread.id);
  TestValidator.equals("discussionboard_board_id")(readThread.discussionboard_board_id)(threadInput.discussionboard_board_id);
  TestValidator.equals("discussionboard_member_id")(readThread.discussionboard_member_id)(member.id);
  TestValidator.equals("title")(readThread.title)(threadInput.title);
  TestValidator.equals("description")(readThread.description)(threadInput.description);
  TestValidator.equals("status")(readThread.status)(threadInput.status);
  TestValidator.equals("deleted_at")(readThread.deleted_at)(null);

  // 4. Try to fetch a random, non-existent thread (should error)
  await TestValidator.error("Fetching non-existing thread should fail")(
    async () => {
      await api.functional.discussionboard.threads.threads.getById(connection, {
        id: typia.random<string & tags.Format<"uuid">>(),
      });
    },
  );

  // 5. Soft-delete the thread
  const deleted = await api.functional.discussionboard.threads.threads.eraseById(connection, { id: thread.id });
  typia.assert(deleted);
  TestValidator.equals("id")(deleted.id)(thread.id);
  TestValidator.predicate("deleted_at is set")(
    typeof deleted.deleted_at === "string" && deleted.deleted_at.length > 0
  );

  // 6. Attempt to retrieve the soft-deleted thread (should fail)
  await TestValidator.error("Fetching deleted thread should fail")(
    async () => {
      await api.functional.discussionboard.threads.threads.getById(connection, {
        id: thread.id,
      });
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMembers } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMembers";
import type { IDiscussionboardThreads } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardThreads";

/**
 * Validate permission-restricted thread retrieval in various thread visibility and member status scenarios.
 *
 * This test ensures that details of a discussion board thread are retrievable only by members with appropriate permissions, according to the thread's status ('open', 'locked', 'hidden') and the member's account status ('active', 'suspended').
 *
 * Steps:
 * 1. Create four members: one normal active, one moderator (simulated), one admin (simulated), and one suspended. (Since the DTO provides only 'status', moderation/admin distinction is not technically enforceable but included for completeness.)
 * 2. Create a thread as the active member with status 'open'.
 * 3. Retrieve the thread as an active member and verify success.
 * 4. Change the thread status to 'locked'.
 * 5. Attempt to retrieve the locked thread as an active member (expect failure).
 * 6. Change the thread status to 'hidden' and attempt to retrieve it as an active member (failure expected).
 * 7. Attempt to retrieve the thread as a suspended member throughout (always fails).
 * 8. All permitted responses are type asserted. Permission denials are checked with TestValidator.error.
 */
export async function test_api_discussionboard_threads_test_get_thread_details_permission_restrictions(
  connection: api.IConnection,
) {
  // 1. Create four members: normal active, 'moderator', 'admin', and suspended (roles simulated by status label only)
  const now: string = new Date().toISOString();
  const user = await api.functional.discussionboard.actors.members.post(connection, { body: { joined_at: now, status: 'active' } });
  typia.assert(user);
  const moderator = await api.functional.discussionboard.actors.members.post(connection, { body: { joined_at: now, status: 'active' } });
  typia.assert(moderator);
  const admin = await api.functional.discussionboard.actors.members.post(connection, { body: { joined_at: now, status: 'active' } });
  typia.assert(admin);
  const suspended = await api.functional.discussionboard.actors.members.post(connection, { body: { joined_at: now, status: 'suspended' } });
  typia.assert(suspended);

  // 2. Create a thread as the active normal member
  const boardId = typia.random<string & tags.Format<'uuid'>>();
  const thread = await api.functional.discussionboard.threads.threads.post(connection, {
    body: {
      discussionboard_board_id: boardId,
      discussionboard_member_id: user.id,
      title: RandomGenerator.paragraph()(10),
      description: RandomGenerator.paragraph()(40),
      status: 'open',
      created_at: now,
    },
  });
  typia.assert(thread);

  // 3. Retrieve thread as active user (should succeed)
  const threadByUser = await api.functional.discussionboard.threads.threads.getById(connection, {
    id: thread.id,
  });
  typia.assert(threadByUser);
  TestValidator.equals('Open thread access allowed as active')(threadByUser.status)('open');

  // 4. Lock the thread (status: 'locked')
  const lockTime = new Date().toISOString();
  const lockedThread = await api.functional.discussionboard.threads.threads.putById(connection, {
    id: thread.id,
    body: {
      status: 'locked',
      updated_at: lockTime,
    },
  });
  typia.assert(lockedThread);
  TestValidator.equals('Thread is now locked')(lockedThread.status)('locked');

  // 5. Try to access locked thread as active user (should fail)
  await TestValidator.error('Active user cannot access locked thread')(
    () => api.functional.discussionboard.threads.threads.getById(connection, {
      id: thread.id,
    })
  );

  // 6. Hide the thread (status: 'hidden')
  const hiddenTime = new Date().toISOString();
  const hiddenThread = await api.functional.discussionboard.threads.threads.putById(connection, {
    id: thread.id,
    body: {
      status: 'hidden',
      updated_at: hiddenTime,
    },
  });
  typia.assert(hiddenThread);
  TestValidator.equals('Thread is now hidden')(hiddenThread.status)('hidden');

  // 7. Try to access hidden thread as active user (should fail)
  await TestValidator.error('Active user cannot access hidden thread')(
    () => api.functional.discussionboard.threads.threads.getById(connection, {
      id: thread.id,
    })
  );

  // 8. Try to access thread as suspended member (should always fail; simulate by description as status is set at creation only)
  await TestValidator.error('Suspended user cannot access any thread')(
    () => api.functional.discussionboard.threads.threads.getById(connection, {
      id: thread.id,
    })
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMembers } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMembers";
import type { IDiscussionBoardMemberSuspension } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMemberSuspension";
import type { DiscussionboardBoard } from "@ORGANIZATION/PROJECT-api/lib/structures/DiscussionboardBoard";
import type { IDiscussionboardThreads } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardThreads";

/**
 * Validate creation of discussion threads by authenticated members, including business rules and proper error handling.
 *
 * This test simulates realistic scenarios for thread creation:
 * 1. Register a member for authorship
 * 2. Register a board with a valid (fake) category
 * 3. Create a thread as the member, providing all fields
 * 4. Validate returned thread matches request/body
 * 5. Attempt thread creation with missing required fields, asserting error
 * 6. Attempt thread creation using invalid/nonexistent member/board UUIDs
 * 7. Register a member, suspend them, then validate thread creation fails
 *
 * All API calls use only the functions and DTOs provided. Only runtime business/validation errors are tested, no type-level (compile-time) checks.
 */
export async function test_api_discussionboard_test_create_thread_success_and_validation_errors(
  connection: api.IConnection,
) {
  // 1. Register a valid, active member (thread author)
  const member = await api.functional.discussionboard.actors.members.post(connection, {
    body: {
      joined_at: new Date().toISOString(),
      status: "active",
    } satisfies IDiscussionboardMembers.ICreate,
  });
  typia.assert(member);

  // 2. Register a board (requires a category, so use random/fake UUID for demo)
  const fakeCategoryId = typia.random<string & tags.Format<"uuid">>();
  const board = await api.functional.discussionboard.boards.boards.post(connection, {
    body: {
      discussionboard_category_id: fakeCategoryId,
      code: RandomGenerator.alphabets(8),
      name: RandomGenerator.alphabets(10),
      description: RandomGenerator.paragraph()(),
      is_active: true,
    } satisfies DiscussionboardBoard.ICreate,
  });
  typia.assert(board);

  // 3. Create a thread (all required + optional description)
  const threadInput: IDiscussionboardThreads.ICreate = {
    discussionboard_board_id: board.id,
    discussionboard_member_id: member.id,
    title: RandomGenerator.paragraph()(),
    description: RandomGenerator.content()()(),
    status: "open",
    created_at: new Date().toISOString(),
  };
  const thread = await api.functional.discussionboard.threads.threads.post(connection, {
    body: threadInput,
  });
  typia.assert(thread);
  TestValidator.equals("board id matches")(thread.discussionboard_board_id)(threadInput.discussionboard_board_id);
  TestValidator.equals("member id matches")(thread.discussionboard_member_id)(threadInput.discussionboard_member_id);
  TestValidator.equals("title matches")(thread.title)(threadInput.title);
  TestValidator.equals("description matches")(thread.description)(threadInput.description);
  TestValidator.equals("status matches")(thread.status)(threadInput.status);

  // 4. Attempt thread creation with missing required field 'title' (runtime error expected)
  const missingTitle: any = { ...threadInput };
  delete missingTitle.title;
  await TestValidator.error("missing required field: title")(
    async () =>
      await api.functional.discussionboard.threads.threads.post(connection, {
        body: missingTitle as IDiscussionboardThreads.ICreate,
      })
  );

  // 5. Attempt creation with invalid/nonexistent board id
  const invalidBoardInput = { ...threadInput, discussionboard_board_id: typia.random<string & tags.Format<"uuid">>() };
  await TestValidator.error("invalid/nonexistent board id")(
    async () =>
      await api.functional.discussionboard.threads.threads.post(connection, {
        body: invalidBoardInput,
      })
  );

  // 6. Attempt creation with invalid/nonexistent member id
  const invalidMemberInput = { ...threadInput, discussionboard_member_id: typia.random<string & tags.Format<"uuid">>() };
  await TestValidator.error("invalid/nonexistent member id")(
    async () =>
      await api.functional.discussionboard.threads.threads.post(connection, {
        body: invalidMemberInput,
      })
  );

  // 7. Register new member, suspend, attempt to create thread (should fail)
  const suspendedMember = await api.functional.discussionboard.actors.members.post(connection, {
    body: {
      joined_at: new Date().toISOString(),
      status: "active",
    } satisfies IDiscussionboardMembers.ICreate,
  });
  typia.assert(suspendedMember);
  const suspension = await api.functional.discussionboard.actors.memberSuspensions.post(connection, {
    body: {
      discussionboard_member_id: suspendedMember.id,
      issued_by_moderator_id: null,
      issued_by_admin_id: null,
      reason: "Rule violation",
      starts_at: new Date().toISOString(),
      ends_at: null,
    } satisfies IDiscussionBoardMemberSuspension.ICreate,
  });
  typia.assert(suspension);
  // attempt thread creation as suspended member
  const failSuspendedInput = {
    ...threadInput,
    discussionboard_member_id: suspendedMember.id,
    title: RandomGenerator.paragraph()(),
  };
  await TestValidator.error("creation by suspended member fails")(
    async () =>
      await api.functional.discussionboard.threads.threads.post(connection, {
        body: failSuspendedInput,
      })
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMembers } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMembers";
import type { DiscussionboardBoard } from "@ORGANIZATION/PROJECT-api/lib/structures/DiscussionboardBoard";
import type { IDiscussionboardThreads } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardThreads";

/**
 * Validate that threads within the same board cannot share the same title.
 *
 * This E2E test ensures that the API correctly enforces the uniqueness
 * constraint on thread titles per board. It follows these steps:
 *
