import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMembers } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMembers";
import type { IDiscussionboardNotification } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardNotification";
import type { IPageDiscussionboardNotification } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageDiscussionboardNotification";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validate listing notifications for an authenticated discussion board member with pagination and filtering.
 *
 * This test covers the correct functionality of fetching notifications for a single, authenticated member,
 * checking that filtering by notification type and read/unread status works, and that only notifications belonging
 * to the logged-in member are returned. The test also validates pagination metadata in the response.
 *
 * Steps:
 * 1. Register a new member (to serve as the owner of notifications).
 * 2. Create several notifications for this member. Use different types and delivered_at timestamps.
 * 3. Issue a notification listing request as this member with a limit (e.g., 2), and a filter for type.
 * 4. Assert that only notifications for this member are returned, of the filtered type, and that the returned list respects the limit.
 * 5. Check that pagination metadata reflects the number of records, number of pages, and limit.
 * 6. Edge: Also create notifications for a different member, and assert these are not included in results for the original member.
 * 7. Optionally, test read/unread filtering by marking a notification as read, then filtering accordingly.
 */
export async function test_api_discussionboard_test_list_notifications_with_valid_member_and_pagination(
  connection: api.IConnection,
) {
  // 1. Register new member (notification owner)
  const member = await api.functional.discussionboard.actors.members.post(connection, {
    body: {
      joined_at: new Date().toISOString(),
      status: "active",
    },
  });
  typia.assert(member);

  // 2. Create a different extra member (for edge case isolation)
  const otherMember = await api.functional.discussionboard.actors.members.post(connection, {
    body: {
      joined_at: new Date().toISOString(),
      status: "active",
    },
  });
  typia.assert(otherMember);

  // 3. Create notifications for member. Use two types.
  const notifications = [
    await api.functional.discussionboard.notifications.notifications.post(connection, {
      body: {
        discussionboard_member_id: member.id,
        type: "reply",
        title: "New reply to your post",
        body: "Someone replied to your thread.",
        delivered_at: new Date().toISOString(),
      },
    }),
    await api.functional.discussionboard.notifications.notifications.post(connection, {
      body: {
        discussionboard_member_id: member.id,
        type: "reply",
        title: "You were replied to again",
        body: "Different reply notification.",
        delivered_at: new Date(Date.now() - 10000).toISOString(),
      },
    }),
    await api.functional.discussionboard.notifications.notifications.post(connection, {
      body: {
        discussionboard_member_id: member.id,
        type: "announcement",
        title: "Announcement posted",
        body: "There is a new announcement.",
        delivered_at: new Date(Date.now() - 20000).toISOString(),
      },
    }),
  ];
  notifications.forEach(typia.assert);

  // 4. Create notifications for other member
  const otherNotification = await api.functional.discussionboard.notifications.notifications.post(connection, {
    body: {
      discussionboard_member_id: otherMember.id,
      type: "reply",
      title: "Irrelevant notification",
      body: "Should not appear in original member results.",
      delivered_at: new Date().toISOString(),
    },
  });
  typia.assert(otherNotification);

  // 5. List notifications for member, filter by type 'reply', limit 2
  const pageResult = await api.functional.discussionboard.notifications.notifications.patch(connection, {
    body: {
      page: 1,
      limit: 2,
      type: "reply",
      read: null,
      delivered_from: null,
      delivered_to: null,
    },
  });
  typia.assert(pageResult);

  // 6. Assert that all notifications belong to the correct member and are of the correct type
  pageResult.data.forEach((notif) => {
    TestValidator.equals("discussionboard_member_id matches")(notif.discussionboard_member_id)(member.id);
    TestValidator.equals("type is reply")(notif.type)("reply");
  });
  // 7. Assert limit and pagination metadata
  TestValidator.equals("limit matches")(pageResult.pagination.limit)(2);
  TestValidator.equals("page matches")(pageResult.pagination.current)(1);
  // Should not exceed the total number of expected notifications of type 'reply'
  const expectedCount = notifications.filter(n => n.type === "reply").length;
  TestValidator.predicate("returned records <= expected replies")(pageResult.data.length <= expectedCount);
  TestValidator.predicate("pagination records correct")(pageResult.pagination.records >= pageResult.data.length);

  // 8. (Optional) Pagination edge: If there are more 'reply' notifications than limit, page count > 1
  if (expectedCount > 2) {
    TestValidator.predicate("multiple pages for replies")(pageResult.pagination.pages > 1);
  }

  // 9. (Optional) Advanced: If mark-as-read supported, set up read filtering (not possible with current endpoints/types)
}

