/**
 * Validate fetching notification details by ID for a valid member.
 *
 * This test ensures that when a member is registered and a notification is created for them, retrieving that notification by ID returns the correct details. It verifies the API includes all fields as per the notification schema, including delivery and read status fields.
 *
 * Steps:
 * 1. Create a discussion board member.
 * 2. Create a notification targeted at that member.
 * 3. Fetch the notification by its ID as the member.
 * 4. Validate that the returned notification data matches the created notification (recipient, type, title, body, url, delivered_at), and that delivery/read status fields are included.
 */
export async function test_api_discussionboard_notifications_test_get_notification_detail_for_valid_member(
  connection: api.IConnection,
) {
  // 1. Create a member
  const member = await api.functional.discussionboard.actors.members.post(connection, {
    body: {
      joined_at: new Date().toISOString(),
      status: "active",
    } satisfies IDiscussionboardMembers.ICreate,
  });
  typia.assert(member);

  // 2. Create a notification for the member
  const notificationInput = {
    discussionboard_member_id: member.id,
    type: "announcement",
    title: "Test notification title",
    body: "Test notification body text for member notification detail API test.",
    url: "https://example.com/notification/detail",
    delivered_at: new Date().toISOString(),
  } satisfies IDiscussionboardNotification.ICreate;
  const notification = await api.functional.discussionboard.notifications.notifications.post(connection, {
    body: notificationInput,
  });
  typia.assert(notification);

  // 3. Fetch the notification by ID
  const fetched = await api.functional.discussionboard.notifications.notifications.getById(connection, {
    id: notification.id,
  });
  typia.assert(fetched);

  // 4. Validate returned data matches original input and includes all fields
  TestValidator.equals("recipient matches")(fetched.discussionboard_member_id)(notificationInput.discussionboard_member_id);
  TestValidator.equals("type matches")(fetched.type)(notificationInput.type);
  TestValidator.equals("title matches")(fetched.title)(notificationInput.title);
