/**
 * E2E test for soft-delete of a board announcement with access control and error handling.
 *
 * Validates the following workflow:
 * 1. Create a board announcement as admin/moderator (satisfies business privilege)
 * 2. Soft-delete the announcement (logical deletion, not physical removal)
 * 3. Assert the deleted announcement's deleted_at is set (data preserved for compliance)
 * 4. Attempt duplicate delete (already deleted) and expect error
 * 5. Attempt to delete a non-existent announcement and expect error
 *
 * Note: Role-based permission switching and unauthenticated access cases are omitted due to lack of authentication/user APIs in provided materials.
 */
export async function test_api_discussionboard_test_delete_board_announcement_with_soft_delete_and_access_control(
  connection: api.IConnection,
) {
  // 1. As admin/moderator, create a board announcement
  const announcement = await api.functional.discussionboard.boards.boardAnnouncements.post(connection, {
    body: typia.random<IDiscussionboardBoardAnnouncements.ICreate>(),
  });
  typia.assert(announcement);

  // 2. Soft-delete as admin/moderator
  const deleted = await api.functional.discussionboard.boards.boardAnnouncements.eraseById(connection, { id: announcement.id });
  typia.assert(deleted);
  TestValidator.equals("deleted id matches")(deleted.id)(announcement.id);
  TestValidator.predicate("deleted_at is set")(typeof deleted.deleted_at === "string" && deleted.deleted_at.length > 0);

  // 3. Attempt duplicate delete should error (already deleted)
