import type { IOperationStatus } from "@ORGANIZATION/PROJECT-api/lib/structures/IOperationStatus";

/**
 * Validate the API behavior when listing topic tags on an empty system.
 *
 * This test ensures that after deleting all topic tags, a request to list topic tags (with no search filters) returns:
 *   - An empty tag array
 *   - Valid pagination metadata (current page, limit, records, pages)
 *
 * This verifies edge case handling for clients when there are no tags present in the system. It simulates this by listing and deleting all tags (if any), then checking the list API after ensuring all tags are erased.
 *
 * Steps:
 * 1. List all topic tags (broad filter, page 1, limit 100)
 * 2. For each topic tag found, delete it using eraseById
 * 3. List all topic tags again
 * 4. Assert that returned array is empty and pagination reflects no records
 */
export async function test_api_discussionboard_boards_topicTags_patch_empty_when_no_tags_exist(
  connection: api.IConnection,
) {
  // 1. Initial list - find all tags
  const firstPage = await api.functional.discussionboard.boards.topicTags.patch(connection, {
    body: {
      filter: "",
      is_active: null,
      page: 1,
      limit: 100,
    },
  });
  typia.assert(firstPage);

  // 2. Delete all tags (if any)
  for (const tag of firstPage.data) {
    const del = await api.functional.discussionboard.boards.topicTags.eraseById(connection, {
      id: tag.id,
    });
    typia.assert(del);
    TestValidator.equals("delete success")(del.success)(true);
  }

  // 3. List again - should be empty
  const emptyPage = await api.functional.discussionboard.boards.topicTags.patch(connection, {
    body: {
      filter: "",
      is_active: null,
      page: 1,
      limit: 100,
    },
  });
  typia.assert(emptyPage);

  // 4. Validate empty list and zero records
  TestValidator.equals("No topic tags data array")(emptyPage.data)([]);
  TestValidator.equals("pagination.records is 0")(emptyPage.pagination.records)(0);
  TestValidator.equals(
    "pagination.pages on empty should be 0",
  )(emptyPage.pagination.pages)(0);
}

