    body: input,
  });
  typia.assert(created);

  // 2. 생성된 ID로 상세 정보 조회
  const detail: DiscussionBoardTopicTag = await api.functional.discussionboard.boards.topicTags.getById(connection, {
    id: created.id,
  });
