  TestValidator.equals("topic tag ID 일치")(detail.id)(created.id);
  TestValidator.equals("tag name 일치")(detail.name)(input.name);
  TestValidator.equals("활성화 상태 일치")(detail.is_active)(input.is_active);
  TestValidator.predicate("created_at timestamp 형식 및 존재 확인")(typeof detail.created_at === "string" && detail.created_at.length > 0);
  TestValidator.predicate("updated_at timestamp 형식 및 존재 확인")(typeof detail.updated_at === "string" && detail.updated_at.length > 0);
}

