/**
 * Test successful update of a topic tag's properties (name, is_active).
 *
 * This test verifies that when a topic tag exists, its properties can be updated successfully using the update endpoint, and that changes are correctly reflected when the updated record is retrieved. The scenario covers the primary positive case where all inputs are valid and permissions are sufficient. It also validates the business requirement that topic tags can be renamed and their activation status changed.
 *
 * Steps:
 * 1. Create a new topic tag (using the POST endpoint) to ensure controlled test data.
 * 2. Update this tag using the PUT endpoint, changing both 'name' and 'is_active'.
 * 3. Validate that the PUT response includes the correct updated fields and that the record ID remains unchanged.
 * 4. Optionally, query the detail of the tag to confirm the persisted changes (if supported by available endpoints—skip if not present).
 */
export async function test_api_discussionboard_boards_topicTags_test_update_topic_tag_success(
  connection: api.IConnection,
) {
  // 1. Create an initial topic tag.
  const initialName = `tag-${RandomGenerator.alphaNumeric(8)}`;
  const tag = await api.functional.discussionboard.boards.topicTags.post(connection, {
    body: {
      name: initialName,
      is_active: true,
    } satisfies DiscussionBoardTopicTag.ICreate,
  });
  typia.assert(tag);

  // 2. Update this tag's name and is_active status.
  const updatedName = `${initialName}-upd`;
  const updateBody = {
    name: updatedName,
    is_active: false,
