import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMembers } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMembers";
import type { DiscussionBoardAdmins } from "@ORGANIZATION/PROJECT-api/lib/structures/DiscussionBoardAdmins";
import type { IDiscussionboardModerationLog } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardModerationLog";

/**
 * 관리자 또는 운영자의 moderation log 생성 및 권한/입력 검증 테스트
 *
 * 이 테스트는 다음 사항을 검증합니다:
 * 1. 신규 회원을 등록 후 해당 회원을 관리자로 승격, 정상적인 moderation log를 생성할 수 있다.
 * 2. 생성된 moderation log의 moderator_id, action_type, action_details 등 주요 필드가 입력값과 일치함을 확인한다.
 * 3. 권한이 없는 일반 회원이 moderation log 생성 시도시 403 Forbidden 에러가 발생한다.
 * 4. 필수 필드(moderator_id/action_type 등)가 누락된 경우 400 Bad Request가 발생한다.
 *
 * 참고: moderation log listing API가 제공되지 않아, 생성한 로그의 목록 반영 여부는 별도 검증하지 않음.
 *
 * 테스트 시나리오
 * 1. 회원 가입, 2. 관리자 승격, 3. 정상 moderation log 생성, 4. 응답 유효성 검증
 * 5. 권한 없는 사용자 시도(403), 6. 필수값 누락(400)에 대한 유효성 검증
 */
export async function test_api_discussionboard_test_create_moderation_log_as_admin_or_moderator(
  connection: api.IConnection,
) {
  // 1. 신규 회원 가입
  const member = await api.functional.discussionboard.actors.members.post(
    connection,
    {
      body: {
        joined_at: new Date().toISOString(),
        status: "active",
      },
    },
  );
  typia.assert(member);

  // 2. 관리자 승격
  const admin = await api.functional.discussionboard.actors.admins.post(
    connection,
    {
      body: {
        discussionboard_member_id: member.id,
        elevated_at: new Date().toISOString(),
      },
    },
  );
  typia.assert(admin);

  // 3. 관리자로 moderation log 저장
  const actionType = "delete_post";
  const logInput = {
    moderator_id: member.id,
    action_type: actionType,
    action_details: "게시글 삭제 처리",
  } satisfies IDiscussionboardModerationLog.ICreate;
  const logOutput = await api.functional.discussionboard.moderation.moderationLogs.post(
    connection,
    { body: logInput },
  );
  typia.assert(logOutput);
  TestValidator.equals("moderator_id matches")(logOutput.moderator_id)(logInput.moderator_id);
  TestValidator.equals("action_type matches")(logOutput.action_type)(logInput.action_type);
  TestValidator.equals("action_details matches")(logOutput.action_details)(logInput.action_details);

  // 4. 권한 없는 일반 회원이 moderation log를 생성하려 할 때: 403 Forbidden
  const member2 = await api.functional.discussionboard.actors.members.post(
    connection,
    {
      body: {
        joined_at: new Date().toISOString(),
        status: "active",
      },
    },
  );
  typia.assert(member2);
  TestValidator.error("member cannot create log")(async () => {
    await api.functional.discussionboard.moderation.moderationLogs.post(
      connection,
      {
        body: {
          moderator_id: member2.id,
          action_type: "delete_post",
        },
      },
    );
  });

  // 5. 필수 input 필드(moderator_id) 누락 → 400 Bad Request
  TestValidator.error("필수 moderator_id 누락시 400")(() => {
    // @ts-expect-error: 타입 시스템에서 막히지만, 런타임선 400 검증
    return api.functional.discussionboard.moderation.moderationLogs.post(
      connection,
      {
        body: {
          action_type: "delete_post",
        },
      },
    );
  });

  // 6. action_type 누락 → 400 Bad Request
  TestValidator.error("필수 action_type 누락시 400")(() => {
    // @ts-expect-error: 타입 시스템에서 막히지만, 런타임선 400 검증
    return api.functional.discussionboard.moderation.moderationLogs.post(
      connection,
      {
        body: {
          moderator_id: member.id,
        },
      },
    );
  });
}

