 * This test ensures that the PATCH /discussionboard/actors/memberAuthentications API correctly returns paginated and filtered results for member authentication records.
 * It covers filtering by provider, last login, pagination edge-cases (multiple pages & empty), and invalid filter error responses. This includes setup for multiple members and authentications to ensure realistic data distribution.
 *
 * Steps:
 * 1. Create a member (for testing association)
 * 2. Register several authentication records with varied providers and identifiers (e.g., provider=local,google,kakao)
 * 3. Query: fetch all authentications without filters - results must include all created
 * 4. Query: filter by valid provider (e.g., 'google') - only google authentications should be present
 * 5. Query: filter by timestamp bounds - only records within last_login_at bounds should be included
 * 6. Query: pagination (limit smaller than created count) - results should reflect expected page sizes and navigation
 * 7. Query: filter with impossible provider or date range - empty results must be returned
 * 8. Query: invalid pagination/filters (e.g., negative page/limit) - error must be thrown
 */
export async function test_api_discussionboard_actors_memberAuthentications_test_list_member_authentications_with_various_filters(connection: api.IConnection) {
  // 1. Create a member
  const member = await api.functional.discussionboard.actors.members.post(connection, {
    body: {
      joined_at: new Date().toISOString(),
      status: "active"
    }
  });
  typia.assert(member);

  // 2. Register diverse authentication records for this member
  const providers = ["local", "google", "kakao"];
  const identifiers = [
    `user_${RandomGenerator.alphaNumeric(4)}`,
    `user_${RandomGenerator.alphaNumeric(4)}`,
    `user_${RandomGenerator.alphaNumeric(4)}`
  ];
  const authentications = [];
  for (let i = 0; i < providers.length; ++i) {
    const result = await api.functional.discussionboard.actors.memberAuthentications.post(connection, {
      body: {
        discussionboard_member_id: member.id,
        provider: providers[i],
        provider_identifier: identifiers[i],
        password_hash: providers[i] === "local" ? "hashed-password" : null,
      }
    });
    // API does not allow setting last_login_at directly, so only test with what can be set
    authentications.push(result);
  }

  // 3. Query: Fetch all authentications (no filters)
  let pageRes = await api.functional.discussionboard.actors.memberAuthentications.patch(connection, {
    body: {}
  });
  typia.assert(pageRes);
  TestValidator.predicate("no-filter all present")(authentications.every(a => pageRes.data.some(r => r.id === a.id)));

  // 4. Query: Filter by provider
  for (const provider of providers) {
    pageRes = await api.functional.discussionboard.actors.memberAuthentications.patch(connection, {
      body: { provider }
    });
    typia.assert(pageRes);
    TestValidator.predicate(`provider filter: ${provider}`)(pageRes.data.every(r => r.provider === provider));
  }

  // 5. Query: Pagination (limit=2)
  pageRes = await api.functional.discussionboard.actors.memberAuthentications.patch(connection, {
    body: { limit: 2 }
  });
  typia.assert(pageRes);
  TestValidator.equals("pagination limit")(pageRes.data.length)(2);

  // 6. Query: Impossible provider - empty result
  pageRes = await api.functional.discussionboard.actors.memberAuthentications.patch(connection, {
    body: { provider: "impossible_provider" }
  });
  typia.assert(pageRes);
  TestValidator.equals("no matching provider results")(pageRes.data.length)(0);

  // 7. Query: Invalid filters - negative page value
  await TestValidator.error("invalid page triggers error")(() => api.functional.discussionboard.actors.memberAuthentications.patch(connection, {
    body: { page: -1 }
  }));
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardChannel } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardChannel";
import type { IDiscussionboardCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardCategory";

/**
 * Test category updating workflow including validation in the discussion board system.
 *
 * - Tests success and business rule errors for category update API.
 *
 * 1. Create a channel (required for foreign key)
 * 2. Create two categories in the same channel (will test duplicate code constraint)
 * 3. Update the first category’s name, code, enabled state, and parent (success)
 * 4. Verify attributes updated on return value
 * 5. Try updating that first category’s code to the second category's current code; check for error (code must be unique per channel)
 * 6. Attempt to update immutable fields (e.g., discussionboard_channel_id, or created_at) and verify rejection
 */
export async function test_api_discussionboard_test_update_category_details_success_and_validation(
  connection: api.IConnection,
) {
  // Step 1: Create a channel
  const channel = await api.functional.discussionboard.systematic.channels.post(connection, {
    body: {
      code: RandomGenerator.alphaNumeric(4),
      name: RandomGenerator.name(),
      description: RandomGenerator.paragraph()(),
      enabled: true,
    } satisfies IDiscussionboardChannel.ICreate,
  });
  typia.assert(channel);

  // Step 2: Create two categories for duplicate code check and for update target
  const catA = await api.functional.discussionboard.systematic.categories.post(connection, {
    body: {
      discussionboard_channel_id: channel.id,
      parent_id: null,
      code: RandomGenerator.alphaNumeric(5),
      name: RandomGenerator.paragraph()(),
      description: RandomGenerator.paragraph()(),
      enabled: true,
    } satisfies IDiscussionboardCategory.ICreate,
  });
  typia.assert(catA);

  const catB = await api.functional.discussionboard.systematic.categories.post(connection, {
    body: {
      discussionboard_channel_id: channel.id,
      parent_id: null,
      code: RandomGenerator.alphaNumeric(5),
      name: RandomGenerator.paragraph()(),
      description: RandomGenerator.paragraph()(),
      enabled: true,
    } satisfies IDiscussionboardCategory.ICreate,
  });
  typia.assert(catB);

  // Step 3: Update catA
  const newName = RandomGenerator.name();
  const newCode = RandomGenerator.alphaNumeric(5);
  const updated = await api.functional.discussionboard.systematic.categories.putById(connection, {
    id: catA.id,
    body: {
      name: newName,
      code: newCode,
      parent_id: catB.id,
      enabled: false,
      description: "Updated description",
    } satisfies IDiscussionboardCategory.IUpdate,
  });
  typia.assert(updated);
  TestValidator.equals("category name updated")(updated.name)(newName);
  TestValidator.equals("category code updated")(updated.code)(newCode);
  TestValidator.equals("parent updated")(updated.parent_id)(catB.id);
  TestValidator.equals("enabled updated")(updated.enabled)(false);
  TestValidator.equals("description updated")(updated.description)("Updated description");

  // Step 4: Duplicate code check
  await TestValidator.error("duplicate category code within same channel should fail")(
    async () => {
      await api.functional.discussionboard.systematic.categories.putById(connection, {
        id: catA.id,
        body: {
          code: catB.code,
        } satisfies IDiscussionboardCategory.IUpdate,
      });
    },
  );

  // Step 5: Attempt to update immutable fields - e.g., discussionboard_channel_id (should not update)
  await TestValidator.error("cannot update immutable field: discussionboard_channel_id")(
    async () => {
      await api.functional.discussionboard.systematic.categories.putById(connection, {
        id: catA.id,
        body: {
          // @ts-expect-error: Property does not exist on IDiscussionboardCategory.IUpdate
          // discussionboard_channel_id: channel.id,
          name: RandomGenerator.name(),
        } as any,
      });
    },
  );
}

