import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardSettings } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardSettings";

/**
 * 비관리자 사용자가 시스템 설정을 수정할 수 없는지 검증합니다.
 *
 * 시스템 설정은 관리자 권한이 필요한 엔드포인트로, 일반 회원이 직접 접근하거나 필드 값을 갱신 시도 시
 * 명확히 권한 거부(permisson denied) 에러가 발생해야 하며, 실제 데이터가 변경되지 않아야 합니다.
 *
 * 테스트 흐름:
 * 1. (관리자 권한으로) 시스템 설정을 생성한다.
 * 2. (비관리자/일반회원 권한으로 전환한 상태에서) 시스템 설정을 PUT 엔드포인트로 갱신 시도한다.
 *    - value, description 등 아무 필드 하나 이상(전체)을 변경
 * 3. 요청이 권한 부족(Permission Denied) 오류로 실패해야 한다.
 * 4. (권한 있는 계정으로 재진입) 설정의 값이 실제로 변경되지 않았는지 확인한다. (GET/read API 미제공 시 생략)
 */
export async function test_api_discussionboard_test_update_setting_without_admin_permission_should_fail(
  connection: api.IConnection,
) {
  // 1. (관리자 권한) 시스템 설정 생성
  const createDto = {
    key: RandomGenerator.alphaNumeric(10),
    value: RandomGenerator.alphaNumeric(12),
    description: "테스트용 설정 설명",
  } satisfies IDiscussionboardSettings.ICreate;
  const created = await api.functional.discussionboard.systematic.settings.post(connection, { body: createDto });
  typia.assert(created);

  // 2. 비관리자 connection 준비
  // 실제로 일반 회원 권한을 가진 connection을 발급/스위칭하는 로직이 필요합니다.
  // 예시에서는 memberConnection이라는 별도 connection 객체가 생성된다고 가정합니다.
  // (테스트 인프라에서 회원 가입 및 인증 시스템이 있고, 그 결과 memberConnection을 얻을 수 있어야 함)
  // 아래 코드는 해당 memberConnection이 이미 준비된 것으로 간주하고 예시를 작성합니다.
  // 만약 일반회원 connection 생성이 불가하면 이 부분은 실제 실행시 동작하지 않을 수 있습니다.

  // 3. 비관리자 권한으로 수정 시도 => 권한 거부 에러 발생해야 함
  await TestValidator.error("비관리자는 시스템 설정을 수정할 수 없어야 함")(
    async () => {
      await api.functional.discussionboard.systematic.settings.putById(
        memberConnection, // (비관리자 connection, 테스트 인프라에서 제공 필요)
        {
          id: created.id,
          body: {
            value: "FORBIDDEN_UPDATE",
            description: "비관리자 수정시도",
          } satisfies IDiscussionboardSettings.IUpdate,
        },
      );
    },
  );

  // 4. (관리자 connection으로 복귀 후 실제 변경 없는지 확인) Get API 미제공으로 생략
}

