import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { DiscussionBoardTopicTag } from "@ORGANIZATION/PROJECT-api/lib/structures/DiscussionBoardTopicTag";

/**
 * 테스트 목적:
 * - 토픽 태그 업데이트 API에 잘못된 데이터(빈 name, 잘못된 타입, 필수 필드 누락 등)를 공급하고, 이로 인해 발생하는 유효성 검사(Validation) 오류를 검증한다.
 *
 * 테스트 흐름:
 * 1. 선행 조건으로 정상적인 토픽 태그 레코드를 생성한다.
 * 2. 다양한 잘못된 IUpdate payload를 구성하고 각 케이스에 대해 업데이트 API 호출 시 Validation Error가 발생하는지 확인한다.
 *   - name: 빈 문자열, is_active: 정상 값
 *   - name: 정상 값, is_active: string 등 잘못된 타입
 *   - name: 누락 (is_active만 보냄)
 *   - is_active: 누락 (name만 보냄)
 *   - 완전히 다른 타입, 혹은 둘 다 누락 (빈 객체)
 * 3. 각 잘못된 payload 제출시, 에러(400/BAD_REQUEST 또는 422/Unprocessable Entity 등)가 발생하는지 TestValidator.error로 검증한다.
 *
 * 검증 포인트:
 * - 올바르지 않은 데이터로는 토픽 태그 수정이 성공하지 않고, API에서 적절한 Validation 에러가 발생한다.
 */
export async function test_api_discussionboard_boards_topicTags_test_update_topic_tag_invalid_input_data(
  connection: api.IConnection,
) {
  // 1. 테스트용 topic 태그를 정상적으로 생성한다.
  const createdTag = await api.functional.discussionboard.boards.topicTags.post(connection, {
    body: {
      name: RandomGenerator.alphaNumeric(10),
      is_active: true,
    },
  });
  typia.assert(createdTag);

  // 2. validation 에러를 유발할 invalid payload 케이스 정의
  const invalidPayloads: Array<Partial<DiscussionBoardTopicTag.IUpdate> | any> = [
    { name: "", is_active: true },       // 빈 name
    { name: RandomGenerator.name(), is_active: "yes" }, // is_active가 string
    { is_active: false },                 // name 누락
    { name: RandomGenerator.name() },     // is_active 누락
    {},                                   // 모든 필드 누락
  ];

  // 3. 각 invalid payload에 대해 ValidationError 발생 검증
  for (const body of invalidPayloads) {
    // 일부 intentionally invalid object는 타입 오류 발생, e2e에서는 실제 Rest API로 제출하면 validation error 발생을 검증하는 목적
    // 실제 프로덕션 코드에서는 사용하지 말 것
    // @ts-expect-error: intentionally invalid for e2e
    await TestValidator.error("validate invalid tag update payload")(
      () => api.functional.discussionboard.boards.topicTags.putById(connection, {
        id: createdTag.id,
        body: body,
      })
    );
  }
}

