import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMembers } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMembers";
import type { DiscussionBoardAdmins } from "@ORGANIZATION/PROJECT-api/lib/structures/DiscussionBoardAdmins";
import type { IDiscussionboardMemberNotificationSettings } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMemberNotificationSettings";
import type { IPageDiscussionboardMemberNotificationSettings } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageDiscussionboardMemberNotificationSettings";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { discussionboardMemberNotificationSettings } from "@ORGANIZATION/PROJECT-api/lib/structures/discussionboardMemberNotificationSettings";

/**
 * Validates admin listing, filtering, and pagination of member notification settings.
 *
 * - Ensures multiple members exist and have notification settings with various flag combinations.
 * - Assigns admin role to an account to enable admin-level listing.
 * - Checks that listing API (PATCH /discussionboard/notifications/memberNotificationSettings) supports:
 *   - Filtering by member ID
 *   - Filtering by notification type enabled status
 *   - Pagination: page and limit
 *   - That returned entries all match filter criteria, and pagination metadata is correct.
 *
 * Steps:
 * 1. Create multiple members (at least 3 for variety).
 * 2. For each member, create a notification setting record with distinct combinations of notification booleans.
 * 3. Assign admin privileges to one member (the 'admin').
 * 4. As admin, list notification settings:
 *    a. Filter by a specific member_id and verify only that member’s setting is present.
 *    b. Filter for a type=enabled flag (e.g. in_app_enabled=true), verify only matching records are returned.
 *    c. Paginate: use limit=2, page=2, verify pagination metadata and that results align with expectations.
 */
export async function test_api_discussionboard_test_list_member_notification_settings_as_admin_with_filters(
  connection: api.IConnection,
) {
  // 1. Create members
  const members: IDiscussionboardMembers[] = await ArrayUtil.asyncRepeat(3)(async (i: number) => {
    const statusOptions = ["active", "pending", "suspended"];
    const member = await api.functional.discussionboard.actors.members.post(connection, {
      body: {
        joined_at: new Date(Date.now() - 10000 * (i + 1)).toISOString(),
        status: statusOptions[i % statusOptions.length],
      },
    });
    typia.assert(member);
    return member;
  });

  // 2. Create notification settings with distinct flag combinations
  const flagCombos: Array<Omit<IDiscussionboardMemberNotificationSettings.ICreate, "discussionboard_member_id">> = [
    {
      in_app_enabled: true,
      email_enabled: false,
      reply_notification_enabled: true,
      mention_notification_enabled: false,
      moderation_notification_enabled: true,
      announcement_notification_enabled: false,
    },
    {
      in_app_enabled: false,
      email_enabled: true,
      reply_notification_enabled: false,
      mention_notification_enabled: true,
      moderation_notification_enabled: false,
      announcement_notification_enabled: true,
    },
    {
      in_app_enabled: true,
      email_enabled: true,
      reply_notification_enabled: false,
      mention_notification_enabled: true,
      moderation_notification_enabled: true,
      announcement_notification_enabled: true,
    },
  ];
  const settings: IDiscussionboardMemberNotificationSettings[] = await ArrayUtil.asyncMap(members)(async (m: IDiscussionboardMembers, i: number) => {
    const body: IDiscussionboardMemberNotificationSettings.ICreate = {
      discussionboard_member_id: m.id,
      ...flagCombos[i % flagCombos.length],
    };
    const setting = await api.functional.discussionboard.notifications.memberNotificationSettings.post(connection, { body });
    typia.assert(setting);
    return setting;
  });

  // 3. Assign admin rights to member[0]
  const admin: IDiscussionboardMembers = members[0];
  const adminAssign = await api.functional.discussionboard.actors.admins.post(connection, {
    body: {
      discussionboard_member_id: admin.id,
      elevated_at: new Date().toISOString(),
    },
  });
  typia.assert(adminAssign);

  // 4a. Admin: list settings, filter by member_id
  const byMemberId: IPageDiscussionboardMemberNotificationSettings = await api.functional.discussionboard.notifications.memberNotificationSettings.patch(connection, {
    body: { discussionboard_member_id: members[1].id },
  });
  typia.assert(byMemberId);
  TestValidator.equals("filter by member id")(byMemberId.data.length)(1);
  TestValidator.equals("member id matches")(byMemberId.data[0].discussionboard_member_id)(members[1].id);

  // 4b. Filter for in_app_enabled=true, should get all settings whose in_app_enabled is true
  const byInAppEnabled: IPageDiscussionboardMemberNotificationSettings = await api.functional.discussionboard.notifications.memberNotificationSettings.patch(connection, {
    body: { in_app_enabled: true },
  });
  typia.assert(byInAppEnabled);
  TestValidator.predicate("all in_app_enabled")(byInAppEnabled.data.every((x: discussionboardMemberNotificationSettings) => x.in_app_enabled === true));

  // 4c. Pagination: limit=2, page=2 (should return the 3rd record if present)
  const paged: IPageDiscussionboardMemberNotificationSettings = await api.functional.discussionboard.notifications.memberNotificationSettings.patch(connection, {
    body: { page: 2, limit: 2 },
  });
  typia.assert(paged);
  TestValidator.equals("page is 2")(paged.pagination.current)(2);
  TestValidator.equals("limit is 2")(paged.pagination.limit)(2);
  // The third element should be alone on page 2 if total is 3
  if (settings.length === 3) {
    TestValidator.equals("one record on page 2")(paged.data.length)(1);
  }
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMembers } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMembers";
import type { DiscussionBoardAdmins } from "@ORGANIZATION/PROJECT-api/lib/structures/DiscussionBoardAdmins";
import type { IDiscussionboardModerationLog } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardModerationLog";

/**
 * Validate privileges and error handling when retrieving a specific moderation log entry by ID.
 *
 * This test verifies proper permission enforcement, error returns, and audit data accuracy.
 * It covers all major edge cases, from success as admin to expected denials for unauthorized or unauthenticated reads and missing resources.
 *
 * Step-by-step breakdown:
 * 1. Register a new discussion board member (to be promoted).
 * 2. Promote the member to admin, making them eligible for privileged moderation log read.
 * 3. As admin, create a moderation log entry (e.g., action_type='suspend_user').
 * 4. Fetch the created moderation log entry by ID as the admin. Assert the returned object matches what was written.
 * 5. As admin, attempt to fetch a non-existent moderation log ID (random UUID). Assert a 404 not found error.
 * 6. As a regular member (not admin), attempt to fetch the valid moderation log entry by ID and assert 403 forbidden error.
 * 7. As an unauthenticated client, attempt to fetch the valid moderation log entry by ID and assert 403 forbidden error.
 */
export async function test_api_discussionboard_test_get_moderation_log_detail_valid_and_invalid_id(connection: api.IConnection) {
  // 1. Register new member to promote to admin
  const adminMember = await api.functional.discussionboard.actors.members.post(connection, {
    body: {
      joined_at: new Date().toISOString(),
      status: 'active',
    },
  });
  typia.assert(adminMember);

  // 2. Promote member to admin
  const adminAssignment = await api.functional.discussionboard.actors.admins.post(connection, {
    body: {
      discussionboard_member_id: adminMember.id,
      elevated_at: new Date().toISOString(),
    },
  });
  typia.assert(adminAssignment);

  // 3. Create a moderation log entry as admin
  const moderationLog = await api.functional.discussionboard.moderation.moderationLogs.post(connection, {
    body: {
      moderator_id: adminMember.id,
      action_type: 'suspend_user',
      // For this test no related target entities
      action_details: 'User suspended for violating guidelines',
    },
  });
  typia.assert(moderationLog);

  // 4. Fetch the created moderation log by ID as admin
  const fetchedLog = await api.functional.discussionboard.moderation.moderationLogs.getById(connection, {
    id: moderationLog.id,
  });
  typia.assert(fetchedLog);
  TestValidator.equals('moderation log id matches')(fetchedLog.id)(moderationLog.id);

  // 5. As admin, attempt to fetch a moderation log with a non-existent (random) id (should 404)
  await TestValidator.error('404 when fetching nonexistent moderation log')(async () => {
    await api.functional.discussionboard.moderation.moderationLogs.getById(connection, {
      id: typia.random<string & tags.Format<'uuid'>>(),
    });
  });

  // 6. Register a regular (non-admin) member
  const regularMember = await api.functional.discussionboard.actors.members.post(connection, {
    body: {
      joined_at: new Date().toISOString(),
      status: 'active',
    }
  });
  typia.assert(regularMember);

  // Simulate acting as regular member (no admin rights)
  await TestValidator.error('403 for regular member fetching moderation log')(async () => {
    await api.functional.discussionboard.moderation.moderationLogs.getById(connection, {
      id: moderationLog.id,
    });
  });

  // 7. Simulate unauthenticated access by stripping Authorization header
  const unauthConnection = {
    ...connection,
    headers: {
      ...connection.headers,
      Authorization: undefined,
    },
  };
  await TestValidator.error('403 for unauthenticated fetch moderation log')(async () => {
    await api.functional.discussionboard.moderation.moderationLogs.getById(unauthConnection, {
      id: moderationLog.id,
    });
  });
}

event.think_again_with_compile_error:
The compilation error is: Argument of type '{ headers: { Authorization: undefined; }; host: string; ... }' is not assignable to parameter of type 'IConnection<object | undefined>'.

This is because I attempted to simulate an unauthenticated request by setting Authorization: undefined in the connection.headers object. However, the type for IConnection (from @nestia/fetcher) expects headers.Authorization to be a string if present, and omitting it is the correct way to simulate no authentication. Setting it to undefined is not permitted by the IConnection typing.

So instead of setting { Authorization: undefined } on the headers object, I must simply omit the Authorization property altogether in the unauthenticated case. The corrected code should clone the existing headers except for Authorization, e.g.,
const unauthConnection = {
  ...connection,
  headers: Object.fromEntries(Object.entries(connection.headers ?? {}).filter(([k]) => k !== "Authorization")),
};

This will create a connection without the Authorization field, properly simulating an unauthenticated request according to the type definition.

