  // 댓글 0 (작성자 A) - A만 dislike
  const dislikeA0 = await api.functional.discussionboard.interactions.commentDislikes.post(connection, {
    body: { discussionboard_comment_id: comments[0].id },
  });
  typia.assert(dislikeA0);
  dislikes.push(dislikeA0);
  // 댓글 1 (작성자 B) - B만 dislike
  const dislikeB1 = await api.functional.discussionboard.interactions.commentDislikes.post(connection, {
    body: { discussionboard_comment_id: comments[1].id },
  });
  typia.assert(dislikeB1);
  dislikes.push(dislikeB1);
  // 댓글 2 (작성자 A) - A/B 모두 dislike
  const dislikeA2 = await api.functional.discussionboard.interactions.commentDislikes.post(connection, {
    body: { discussionboard_comment_id: comments[2].id },
  });
  typia.assert(dislikeA2);
  dislikes.push(dislikeA2);
