import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMembers } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMembers";
import type { IDiscussionboardContentFlag } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardContentFlag";

/**
 * Validate input validation error handling when creating content flags on discussion board posts or comments.
 *
 * This test ensures that invalid requests, such as missing required fields, mutually exclusive post/comment IDs being both present, and improper flag_type values, are properly rejected by the API with validation errors. A valid test member is created as a prerequisite for all cases. Various malformed payloads are then submitted to the content flag creation endpoint. Error responses are checked to confirm correct validation behavior.
 *
 * Process:
 * 1. Create a valid member.
 * 2. Attempt to create a content flag with required field(s) missing.
 * 3. Attempt to create a content flag with both flagged_post_id and flagged_comment_id provided (should be mutually exclusive).
 * 4. Attempt to create a content flag with an invalid flag_type value (e.g., empty string).
 * 5. Attempt to create a content flag with missing auto_flagged.
 * 6. Confirm all requests produce validation errors as expected.
 */
export async function test_api_discussionboard_test_create_content_flag_input_validation_error(
  connection: api.IConnection,
) {
  // 1. Create a valid member (prerequisite)
  const member = await api.functional.discussionboard.actors.members.post(connection, {
    body: {
      joined_at: new Date().toISOString(),
      status: "active",
    },
  });
  typia.assert(member);

  // 2. Missing required flag_type
  await TestValidator.error("missing flag_type should fail")(async () => {
    await api.functional.discussionboard.moderation.contentFlags.post(connection, {
      body: {
        flagged_post_id: typia.random<string & tags.Format<"uuid">>(),
        flagged_by_member_id: member.id,
        // flag_type is missing
        auto_flagged: false,
      },
    });
  });

  // 3. Both flagged_post_id and flagged_comment_id provided
  await TestValidator.error("providing both post and comment ids should fail")(async () => {
    await api.functional.discussionboard.moderation.contentFlags.post(connection, {
      body: {
        flagged_post_id: typia.random<string & tags.Format<"uuid">>(),
        flagged_comment_id: typia.random<string & tags.Format<"uuid">>(),
        flagged_by_member_id: member.id,
        flag_type: "spam",
        auto_flagged: false,
      },
    });
  });

  // 4. Invalid flag_type value (empty string)
  await TestValidator.error("empty flag_type should fail")(async () => {
    await api.functional.discussionboard.moderation.contentFlags.post(connection, {
      body: {
        flagged_post_id: typia.random<string & tags.Format<"uuid">>(),
        flagged_by_member_id: member.id,
        flag_type: "",
        auto_flagged: false,
      },
    });
  });

  // 5. Missing auto_flagged (required field)
  await TestValidator.error("missing auto_flagged should fail")(async () => {
    await api.functional.discussionboard.moderation.contentFlags.post(connection, {
      body: {
        flagged_post_id: typia.random<string & tags.Format<"uuid">>(),
        flagged_by_member_id: member.id,
        flag_type: "spam",
        // auto_flagged is missing
      },
    });
  });
}

