import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { DiscussionBoardAdmins } from "@ORGANIZATION/PROJECT-api/lib/structures/DiscussionBoardAdmins";
import type { DiscussionboardBoard } from "@ORGANIZATION/PROJECT-api/lib/structures/DiscussionboardBoard";
import type { IDiscussionboardBoardAnnouncements } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardBoardAnnouncements";

/**
 * Validate creation of board announcements under various scenarios:
 *  - Normal authorized case
 *  - Input validation (missing required fields)
 *  - Single pinned announcement per board enforcement
 *  - Admin-only creation restriction
 *
 * This ensures the board announcement endpoint enforces RBAC,
 * validates essential properties, and respects the single-pin business rule.
 *
 * Steps:
 * 1. Create an admin assignment (for privilege).
 * 2. Create a board to attach announcements to.
 * 3. As admin: create a valid announcement (required fields/pinned).
 * 4. Negative tests:
 *    a) Missing title (should fail)
 *    b) Missing board ID (should fail)
 *    c) Try duplicate pinned announcement on same board (should fail)
 *    d) Use non-admin to create announcement (should fail)
 */
export async function test_api_discussionboard_test_create_board_announcement_with_valid_and_invalid_data(
  connection: api.IConnection,
) {
  // 1. Create an admin user assignment (simulate member role elevation)
  const admin_member_id = typia.random<string & tags.Format<"uuid">>();
  const elevated_at = new Date().toISOString();
  const admin = await api.functional.discussionboard.actors.admins.post(connection, {
    body: {
      discussionboard_member_id: admin_member_id,
      elevated_at,
    },
  });
  typia.assert(admin);

  // 2. Create a board to post announcements to
  const board = await api.functional.discussionboard.boards.boards.post(connection, {
    body: {
      discussionboard_category_id: typia.random<string & tags.Format<"uuid">>(),
      code: RandomGenerator.alphabets(8),
      name: RandomGenerator.alphabets(12),
      description: RandomGenerator.paragraph()(),
      is_active: true,
    },
  });
  typia.assert(board);

  // 3. As admin, create a valid board announcement (should succeed)
  const announcement = await api.functional.discussionboard.boards.boardAnnouncements.post(connection, {
    body: {
      discussionboard_board_id: board.id,
      published_by_admin_id: admin.id,
      title: RandomGenerator.paragraph()(),
      body: RandomGenerator.content()()(),
      is_pinned: true,
    },
  });
  typia.assert(announcement);
  TestValidator.equals("announcement board matches")(announcement.discussionboard_board_id)(board.id);
  TestValidator.equals("publisher matches")(announcement.published_by_admin_id)(admin.id);
  TestValidator.equals("pin flag matches")(announcement.is_pinned)(true);

  // 4a. Negative: Missing required title (should fail)
  await TestValidator.error("missing title should fail")(async () => {
    // @ts-expect-error Intentional: omit required title field
    await api.functional.discussionboard.boards.boardAnnouncements.post(connection, {
      body: {
        discussionboard_board_id: board.id,
        published_by_admin_id: admin.id,
        // title omitted
        body: RandomGenerator.content()()(),
        is_pinned: false,
      } as any,
    });
  });

  // 4b. Negative: Missing required board ID (should fail)
  await TestValidator.error("missing board id should fail")(async () => {
    // @ts-expect-error Intentional: omit required board ID
    await api.functional.discussionboard.boards.boardAnnouncements.post(connection, {
      body: {
        // discussionboard_board_id omitted
        published_by_admin_id: admin.id,
        title: RandomGenerator.paragraph()(),
        body: RandomGenerator.content()()(),
        is_pinned: false,
      } as any,
    });
  });

  // 4c. Negative: Duplicate pinned announcement for same board (should fail if two pin=true)
  await TestValidator.error("duplicate pinned per board fails")(async () => {
    await api.functional.discussionboard.boards.boardAnnouncements.post(connection, {
      body: {
        discussionboard_board_id: board.id,
        published_by_admin_id: admin.id,
        title: RandomGenerator.paragraph()(),
        body: RandomGenerator.content()()(),
        is_pinned: true,
      },
    });
  });

  // 4d. Negative: Use a non-admin user to create announcement (should fail)
  const non_admin_id = typia.random<string & tags.Format<"uuid">>();
  await TestValidator.error("non-admin forbidden")(async () => {
    await api.functional.discussionboard.boards.boardAnnouncements.post(connection, {
      body: {
        discussionboard_board_id: board.id,
        published_by_admin_id: non_admin_id,
        title: RandomGenerator.paragraph()(),
        body: RandomGenerator.content()()(),
        is_pinned: false,
      },
    });
  });
}

