import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMembers } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMembers";
import type { DiscussionboardBoard } from "@ORGANIZATION/PROJECT-api/lib/structures/DiscussionboardBoard";
import type { DiscussionBoardBoardTopic } from "@ORGANIZATION/PROJECT-api/lib/structures/DiscussionBoardBoardTopic";

/**
 * 게시판 토픽 수정 권한 에러 케이스 검증
 *
 * [시나리오]
 * - 게시판 주제(토픽)의 생성자가 아닌 회원(intruder) 또는 인증되지 않은 사용자가
 *   해당 토픽의 수정을 시도할 경우 운영 정책에 따라 권한 거부(forbidden)가 발생해야 함을 보장합니다.
 * - 실제로 데이터는 변경되지 않아야 하며, 시스템의 보안적 신뢰성을 담보합니다.
 *
 * [비즈니스/보안 흐름]
 * 1. 게시판(discussionboard_board) 생성
 * 2. 첫 번째 회원(owner) 생성
 * 3. owner가 해당 게시판에 주제(topic) 생성
 * 4. 두 번째 회원(intruder) 생성(서로 다른 사용자인지 분명하게 설정)
 * 5. intruder가 owner의 topic에 대해 PUT(수정) 시도 → 반드시 권한오류(403 등) 발생해야 함
 * 6. 인증되지 않은 connection(로그아웃 등)으로 topic PUT 시도 → 권한오류(403 등) 발생해야 함
 * 7. 실제 토픽 내용이 변경되지 않았음을 별도 조회 API 등으로 최종 검증(여기선 주석 안내)
 */
export async function test_api_discussionboard_test_update_board_topic_unauthorized_access(
  connection: api.IConnection,
) {
  // 1. 게시판 생성
  const board = await api.functional.discussionboard.boards.boards.post(connection, {
    body: {
      discussionboard_category_id: typia.random<string & tags.Format<"uuid">>(),
      code: RandomGenerator.alphabets(8),
      name: RandomGenerator.alphabets(10),
      is_active: true,
    },
  });
  typia.assert(board);

  // 2. owner(토픽 소유자) 회원 생성
  const owner = await api.functional.discussionboard.actors.members.post(connection, {
    body: {
      joined_at: new Date().toISOString(),
      status: "active",
    },
  });
  typia.assert(owner);

  // 3. owner가 게시판 주제(토픽) 생성
  const topic = await api.functional.discussionboard.boards.boardTopics.post(connection, {
    body: {
      discussionboard_board_id: board.id,
      code: RandomGenerator.alphabets(6),
      title: RandomGenerator.alphabets(12),
      created_by_member_id: owner.id,
    },
  });
  typia.assert(topic);

  // 4. intruder(권한 없는 회원) 생성
  const intruder = await api.functional.discussionboard.actors.members.post(connection, {
    body: {
      joined_at: new Date().toISOString(),
      status: "active",
    },
  });
  typia.assert(intruder);

