  const outOfRange = await api.functional.discussionboard.interactions.commentLikes.patch(connection, {
    body: {
      page: 999,
      limit: 20,
    },
  });
  typia.assert(outOfRange);
  TestValidator.equals('empty page')(outOfRange.data.length)(0);

