  TestValidator.equals("page 1 number")(page1.pagination.current)(1);
  TestValidator.equals("page 2 number")(page2.pagination.current)(2);
  TestValidator.equals("per page limit")(page1.pagination.limit)(2);

  // 3.g Combination filter
  const combo = await api.functional.discussionboard.actors.memberSuspensions.patch(connection, {
    body: {
      discussionboard_member_id: members[0].id,
      issued_by_moderator_id: moderatorId,
    },
  });
  typia.assert(combo);
  TestValidator.predicate("combo")(combo.data.every(x => x.discussionboard_member_id === members[0].id && x.issued_by_moderator_id === moderatorId));

  // 3.h Edge case: no results
  const none = await api.functional.discussionboard.actors.memberSuspensions.patch(connection, {
    body: {
      discussionboard_member_id: typia.random<string & tags.Format<"uuid">>(),
    },
  });
  typia.assert(none);
  TestValidator.equals("empty array for no hits")(none.data.length)(0);

  // 4. Unauthorized access returns 403
  await TestValidator.error("unauthorized result should fail")(
    async () => {
      // Simulate public/non-privileged: probably modifying the connection context or omitting tokens
      // Here, just call as is; in real scenario update connection to unauthenticated.
      await api.functional.discussionboard.actors.memberSuspensions.patch(
        { ...connection, headers: {} },
        { body: {} },
      );
    },
  );
}

