import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMembers } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMembers";
import type { IDiscussionBoardMemberSuspension } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMemberSuspension";
import type { IPageDiscussionBoardMemberSuspension } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageDiscussionBoardMemberSuspension";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validate the listing and filtering of member suspensions with full pagination and access control.
 *
 * This scenario ensures the suspension listing API works for a variety of filter and pagination edge cases:
 * - Suspension records exist for multiple members, both active and non-active.
 * - Some suspensions are issued by admin, others by moderator.
 * - Filter and pagination parameters behave as expected, covering member, issuer, status, and date ranges.
 * - Unauthorized access (as a public/non-privileged user) is rejected with 403.
 *
 * Steps:
 * 1. Create several members (at least 4) to allow for cross-member filtration and some that are unsuspended, some suspended.
 * 2. For each privileged role (simulate moderator/admin), create suspensions for a subset of members:
 *    a. At least one suspension issued by a moderator.
 *    b. At least one issued by an admin.
 *    c. At least one active, one revoked/expired or null ends_at for perpetual.
 * 3. As a privileged (moderator or admin) account, retrieve suspensions
 *    - List all (no filters): Validate paginated format, record count >= seeded suspensions.
 *    - Filter by discussionboard_member_id: Only suspensions for that member included.
 *    - Filter by issued_by_moderator_id and issued_by_admin_id: Results contain only matching issuer.
 *    - Filter by status (active, revoked, expired, any): Each returns only corresponding status.
 *    - Filter by time window (starts_at_from/to, ends_at_from/to): Results are date-restricted.
 *    - Pagination: Use small limit, verify division across pages and navigation (page > 1 returns correct subset, page out of range is empty).
 *    - Combination filters: e.g., issuer+status+date.
 *    - Edge filter: where no results (should get empty data array, correct pagination).
 * 4. Attempt to retrieve as unauthorized (simulate public): Should get 403 (TestValidator.error).
 */
export async function test_api_discussionboard_test_list_member_suspensions_with_filters_and_pagination(
  connection: api.IConnection,
) {
  // 1. Create members
  const members = await ArrayUtil.asyncRepeat(4)(async () => {
    const member = await api.functional.discussionboard.actors.members.post(connection, {
      body: {
        joined_at: new Date().toISOString(),
        status: "active",
      },
    });
    typia.assert(member);
    return member;
  });

  // 2. Seed suspensions with diverse issuers, statuses, and times
  const [moderatorId, adminId] = [
    typia.random<string & tags.Format<"uuid">>(),
    typia.random<string & tags.Format<"uuid">>(),
  ];
  const now = new Date();
  const suspensions = [
    // Issued by moderator - active
    await api.functional.discussionboard.actors.memberSuspensions.post(connection, {
      body: {
        discussionboard_member_id: members[0].id,
        issued_by_moderator_id: moderatorId,
        reason: "Moderator active suspension",
        starts_at: new Date(now.getTime() - 1000 * 60 * 60).toISOString(),
        ends_at: new Date(now.getTime() + 1000 * 60 * 60).toISOString(),
      },
    }),
    // Issued by admin - expired
    await api.functional.discussionboard.actors.memberSuspensions.post(connection, {
      body: {
        discussionboard_member_id: members[1].id,
        issued_by_admin_id: adminId,
        reason: "Admin expired suspension",
        starts_at: new Date(now.getTime() - 1000 * 60 * 60 * 3).toISOString(),
        ends_at: new Date(now.getTime() - 1000 * 60 * 30).toISOString(),
      },
    }),
    // Issued by moderator - revoked
    await api.functional.discussionboard.actors.memberSuspensions.post(connection, {
      body: {
        discussionboard_member_id: members[2].id,
        issued_by_moderator_id: moderatorId,
        reason: "Moderator revoked suspension",
        starts_at: new Date(now.getTime() - 1000 * 60 * 60 * 4).toISOString(),
        ends_at: new Date(now.getTime() + 1000 * 60 * 60).toISOString(),
        // simulate revoked
        // After API call, PATCH to set revoked_at if such API exists; here, just create as normal.
      },
    }),
    // Admin, perpetual
    await api.functional.discussionboard.actors.memberSuspensions.post(connection, {
      body: {
        discussionboard_member_id: members[3].id,
        issued_by_admin_id: adminId,
        reason: "Admin permanent suspension",
        starts_at: now.toISOString(),
        ends_at: null,
      },
    }),
  ];
  suspensions.forEach(x => typia.assert(x));

  // 3.a List all
  const pageResAll = await api.functional.discussionboard.actors.memberSuspensions.patch(connection, {
    body: {},
  });
  typia.assert(pageResAll);
  TestValidator.predicate("count >= seeded suspensions")(pageResAll.data.length >= suspensions.length);

  // 3.b Filter by member
  for (const member of members) {
    const res = await api.functional.discussionboard.actors.memberSuspensions.patch(connection, {
      body: { discussionboard_member_id: member.id },
    });
    typia.assert(res);
    TestValidator.predicate("filtered by member matches")(res.data.every(x => x.discussionboard_member_id === member.id));
  }

  // 3.c Filter by issuer (moderator, admin)
  const byMod = await api.functional.discussionboard.actors.memberSuspensions.patch(connection, {
    body: { issued_by_moderator_id: moderatorId },
  });
  typia.assert(byMod);
  TestValidator.predicate("by moderator only")(byMod.data.every(x => x.issued_by_moderator_id === moderatorId));

  const byAdmin = await api.functional.discussionboard.actors.memberSuspensions.patch(connection, {
    body: { issued_by_admin_id: adminId },
  });
  typia.assert(byAdmin);
  TestValidator.predicate("by admin only")(byAdmin.data.every(x => x.issued_by_admin_id === adminId));

  // 3.d Status (active, revoked, expired, any)
  const statuses: ("active" | "revoked" | "expired" | "any")[] = [
    "active",
    "revoked",
    "expired",
    "any",
  ];
  for (const status of statuses) {
    const byStatus = await api.functional.discussionboard.actors.memberSuspensions.patch(connection, {
      body: { status },
    });
    typia.assert(byStatus);
    TestValidator.predicate(`all status=${status}`)(byStatus.data.every(rec => status === "any" || rec.ends_at == null || rec.starts_at != null));
  }

  // 3.e Date windows
  const startsWindow = await api.functional.discussionboard.actors.memberSuspensions.patch(connection, {
    body: { starts_at_from: new Date(now.getTime() - 3600 * 1000 * 2).toISOString(), starts_at_to: now.toISOString() },
  });
  typia.assert(startsWindow);
  TestValidator.predicate("starts in window")(startsWindow.data.every(r => r.starts_at >= startsWindow.data[0].starts_at));

  // 3.f Pagination
  const page1 = await api.functional.discussionboard.actors.memberSuspensions.patch(connection, { body: { page: 1, limit: 2 } });
  const page2 = await api.functional.discussionboard.actors.memberSuspensions.patch(connection, { body: { page: 2, limit: 2 } });
  typia.assert(page1); typia.assert(page2);
  TestValidator.equals("page 1 number")(page1.pagination.current)(1);
  TestValidator.equals("page 2 number")(page2.pagination.current)(2);
  TestValidator.equals("per page limit")(page1.pagination.limit)(2);

  // 3.g Combination filter
  const combo = await api.functional.discussionboard.actors.memberSuspensions.patch(connection, {
    body: {
      discussionboard_member_id: members[0].id,
      issued_by_moderator_id: moderatorId,
    },
  });
  typia.assert(combo);
  TestValidator.predicate("combo")(combo.data.every(x => x.discussionboard_member_id === members[0].id && x.issued_by_moderator_id === moderatorId));

  // 3.h Edge case: no results
  const none = await api.functional.discussionboard.actors.memberSuspensions.patch(connection, {
    body: {
      discussionboard_member_id: typia.random<string & tags.Format<"uuid">>(),
    },
  });
  typia.assert(none);
  TestValidator.equals("empty array for no hits")(none.data.length)(0);

  // 4. Unauthorized access returns 403
  await TestValidator.error("unauthorized result should fail")(
    async () => {
      // Simulate public/non-privileged: probably modifying the connection context or omitting tokens
      // Here, just call as is; in real scenario update connection to unauthenticated.
      await api.functional.discussionboard.actors.memberSuspensions.patch(
        { ...connection, headers: {} },
        { body: {} },
      );
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMembers } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMembers";
import type { DiscussionBoardAdmins } from "@ORGANIZATION/PROJECT-api/lib/structures/DiscussionBoardAdmins";
import type { IDiscussionboardModerationLog } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardModerationLog";
import type { IPageDiscussionboardModerationLog } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageDiscussionboardModerationLog";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validate paginated/filtered retrieval of moderation logs as admin.
 *
 * This test validates that admin users can search moderation logs using all supported filters and that pagination and permission rules are enforced.
 *
 * Steps:
 * 1. Create a base member (will serve as moderator/admin)
 * 2. Promote member to admin
 * 3. Create multiple moderation log entries with varied action_types and targets using the admin
 * 4. Retrieve logs using different filters:
 *    a. By moderator_id
 *    b. By action_type
 *    c. By entity type/id
 *    d. By date range
 *    e. Combined filters
 *    f. Pagination (limit/page)
 *    g. Query with no matches
 *    h. Malformed filter (invalid UUID)
 *    i. Excessive page/limit
 *    j. Permissions: regular member or unauthenticated user forbidden
 */
export async function test_api_discussionboard_test_list_moderation_logs_with_filters_and_pagination(
  connection: api.IConnection,
) {
  // Step 1: Create a base member user
  const member: IDiscussionboardMembers =
    await api.functional.discussionboard.actors.members.post(connection, {
      body: {
        joined_at: new Date().toISOString() as string & tags.Format<"date-time">,
        status: "active",
      } satisfies IDiscussionboardMembers.ICreate,
    });
  typia.assert(member);

  // Step 2: Promote the member to admin
  const adminAssignment: DiscussionBoardAdmins =
    await api.functional.discussionboard.actors.admins.post(connection, {
      body: {
        discussionboard_member_id: member.id,
        elevated_at: new Date().toISOString() as string & tags.Format<"date-time">,
      } satisfies DiscussionBoardAdmins.ICreate,
    });
  typia.assert(adminAssignment);

  // Step 3: Create multiple moderation log entries with varied action_types, targets, and timestamps
  const actionTypes = ["delete_post", "warn_user", "suspend_member"];
  const logEntries: IDiscussionboardModerationLog[] = [];
  for (let i = 0; i < 6; ++i) {
    const type = actionTypes[i % actionTypes.length];
    const isEven = i % 2 === 0;
    const log: IDiscussionboardModerationLog =
      await api.functional.discussionboard.moderation.moderationLogs.post(connection, {
        body: {
          moderator_id: member.id,
          action_type: type,
          target_member_id: isEven ? member.id : undefined,
          target_post_id: isEven ? typia.random<string & tags.Format<"uuid">>() : undefined,
          target_comment_id: isEven ? typia.random<string & tags.Format<"uuid">>() : undefined,
          action_details: `Log entry #${i} - ${type}`,
        } satisfies IDiscussionboardModerationLog.ICreate,
      });
    typia.assert(log);
    logEntries.push(log);
    // Space logs apart by 1 minute
    await new Promise((resolve) => setTimeout(resolve, 10)); // Not real time, but in reality would set ISO string differently
  }

  // Helper: Earliest/Latest log timestamps
  const timestamps = logEntries.map((l) => l.created_at).sort();
  const firstTimestamp = timestamps[0];
  const lastTimestamp = timestamps[timestamps.length - 1];

  // Step 4a: Filter by moderator_id
  {
    const output = await api.functional.discussionboard.moderation.moderationLogs.patch(connection, {
      body: {
        moderator_id: member.id,
      } satisfies IDiscussionboardModerationLog.IRequest,
    });
    typia.assert(output);
    TestValidator.equals("all logs by moderator id")(output.data.every((l) => l.moderator_id === member.id))(true);
  }

  // Step 4b: Filter by action_type
  {
    const actionType = "warn_user";
    const expected = logEntries.filter((l) => l.action_type === actionType);
    const output = await api.functional.discussionboard.moderation.moderationLogs.patch(connection, {
      body: {
        action_type: actionType,
      } satisfies IDiscussionboardModerationLog.IRequest,
    });
    typia.assert(output);
    TestValidator.equals("correct action_type count")(output.data.length)(expected.length);
    TestValidator.equals("all logs with action_type warn_user")(output.data.every((l) => l.action_type === actionType))(true);
  }

  // Step 4c: Filter by entity type/id (target_member_id)
  {
    const id = member.id;
    const expected = logEntries.filter((l) => l.target_member_id === id);
    const output = await api.functional.discussionboard.moderation.moderationLogs.patch(connection, {
      body: {
        target_id: id,
        target_type: "member",
      } satisfies IDiscussionboardModerationLog.IRequest,
    });
    typia.assert(output);
    TestValidator.equals("all by target_member_id")(output.data.every((l) => l.target_member_id === id))(true);
    TestValidator.equals("target_type set")(output.data.every((l) => l.target_member_id !== undefined))(true);
  }

  // Step 4d: Filter by date range
  {
    // We'll filter for only the logs created at/after the first, before the last
    const expected = logEntries.filter((l) => l.created_at >= firstTimestamp && l.created_at <= lastTimestamp);
    const output = await api.functional.discussionboard.moderation.moderationLogs.patch(connection, {
      body: {
        from: firstTimestamp as string & tags.Format<"date-time">,
        to: lastTimestamp as string & tags.Format<"date-time">,
      } satisfies IDiscussionboardModerationLog.IRequest,
    });
    typia.assert(output);
    TestValidator.equals("date range all in")(output.data.every((l) => l.created_at >= firstTimestamp && l.created_at <= lastTimestamp))(true);
    TestValidator.equals("count equals range")(output.data.length)(expected.length);
  }

  // Step 4e: Combined filters (moderator_id + action_type)
  {
    const actionType = "delete_post";
    const expected = logEntries.filter((l) => l.moderator_id === member.id && l.action_type === actionType);
    const output = await api.functional.discussionboard.moderation.moderationLogs.patch(connection, {
      body: {
        moderator_id: member.id,
        action_type: actionType,
      } satisfies IDiscussionboardModerationLog.IRequest,
    });
    typia.assert(output);
    TestValidator.equals("combined filter moderator + action")(output.data.length)(expected.length);
  }

  // Step 4f: Pagination test (limit/page)
  {
    const limit = 2;
    const outputPage1 = await api.functional.discussionboard.moderation.moderationLogs.patch(connection, {
      body: {
        limit,
        page: 1,
      } satisfies IDiscussionboardModerationLog.IRequest,
    });
    typia.assert(outputPage1);
    TestValidator.equals("pagination limit applies")(outputPage1.data.length <= limit)(true);
    TestValidator.equals("pagination page correct")(outputPage1.pagination.current)(1);

    const outputPage2 = await api.functional.discussionboard.moderation.moderationLogs.patch(connection, {
      body: {
        limit,
        page: 2,
      } satisfies IDiscussionboardModerationLog.IRequest,
    });
    typia.assert(outputPage2);
    TestValidator.equals("page 2 offset")(outputPage2.pagination.current)(2);
    TestValidator.equals("data no overlap")(outputPage1.data.every((a) => !outputPage2.data.map((b) => b.id).includes(a.id)))(true);
  }

  // Step 4g: Query with no matching filters (use fake UUID)
  {
    const noMatchUUID = typia.random<string & tags.Format<"uuid">>();
    const output = await api.functional.discussionboard.moderation.moderationLogs.patch(connection, {
      body: {
        moderator_id: noMatchUUID,
      } satisfies IDiscussionboardModerationLog.IRequest,
    });
    typia.assert(output);
    TestValidator.equals("empty set returns for no matches")(output.data.length)(0);
    TestValidator.equals("pagination meta present")(typeof output.pagination.current === "number")(true);
  }

  // Step 4h: Malformed filter (invalid UUID)
  await TestValidator.error("malformed UUID in filter returns error")(async () => {
    await api.functional.discussionboard.moderation.moderationLogs.patch(connection, {
      body: {
        moderator_id: "not-a-uuid-123" as string & tags.Format<"uuid">,
      } satisfies IDiscussionboardModerationLog.IRequest,
    });
  });

  // Step 4i: Excessive paging (limit > 1000, which should be rejected by server business rules)
  await TestValidator.error("over-limit on page size returns error")(async () => {
    await api.functional.discussionboard.moderation.moderationLogs.patch(connection, {
      body: {
        limit: 100000 as number & tags.Type<"int32">,
      } satisfies IDiscussionboardModerationLog.IRequest,
    });
  });

  // Step 4j: Permissions – as regular member should be forbidden
  // Note: Our system has no explicit login endpoint, so we simulate as member (no admin promotion)
  const member2: IDiscussionboardMembers =
    await api.functional.discussionboard.actors.members.post(connection, {
      body: {
        joined_at: new Date().toISOString() as string & tags.Format<"date-time">,
        status: "active",
      } satisfies IDiscussionboardMembers.ICreate,
    });
  typia.assert(member2);
  await TestValidator.error("non-admin member gets 403")(
    async () => {
      // No privilege promotion for member2
      await api.functional.discussionboard.moderation.moderationLogs.patch(connection, {
        body: {},
      });
    },
  );

  // Step 4j: Permissions – as unauthenticated (simulate by removing connection.headers.Authorization)
  // [NOTE: This step is a proxy simulation. If the API uses the connection.auth mechanism, clear or omit it.]
  // We'll patch connection to reflect removed auth (deep copy & delete auth header)
  const unauthConn: api.IConnection = { ...connection, headers: { ...connection.headers } };
  if (unauthConn.headers && "Authorization" in unauthConn.headers)
    delete unauthConn.headers.Authorization;
  await TestValidator.error("unauthenticated access gets 403")(
    async () => {
      await api.functional.discussionboard.moderation.moderationLogs.patch(unauthConn, {
        body: {},
      });
    },
  );
}

