import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardPosts } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardPosts";
import type { IDiscussionboardPostReport } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardPostReport";
import type { IPageDiscussionboardPostReport } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageDiscussionboardPostReport";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Test listing and searching DiscussionBoard post reports with filters and pagination (admin/moderator only).
 *
 * Validates the following business logic:
 * - Ability to list post abuse reports using various filters (reporter, post, date, reason, sorting, paging)
 * - Permission enforcement (admin/moderator allowed, regular members denied)
 * - Pagination and sorting metadata correctness
 * - Returned data matches the filter used in query
 *
 * Steps:
 * 1. Create two members and two threads (simulate via random UUIDs)
 * 2. Each member creates at least one post in a thread
 * 3. Create two more members who will file reports (simulate reporting members)
 * 4. Each reporting member files several reports with distinct reasons, for various posts, and with spread out created_at dates
 * 5. As an admin/moderator (simulate, e.g. no explicit API: assume connection is privileged), search using various filters:
 *    - by reporting_member_id
 *    - by post_id
 *    - by created_after/created_before
 *    - by reason_search
 *    - with pagination (page/limit)
 *    - with sorting (asc/desc, sort_key)
 * 6. For each query, assert the data and metadata are consistent with the expected logic
 * 7. As a regular member (simulate demotion by using their connection), assert search call is forbidden (permission error)
 *
 * Notes:
 * - Uses typia.random and TestValidator functions for random data and assertions
 * - Test focuses on core filters, sort and error/permission coverage
 */
export async function test_api_discussionboard_test_list_post_reports_with_various_filters_and_pagination(connection: api.IConnection) {
  // --- SETUP PHASE ---
  // Simulate member and thread/post identities
  const member1_id = typia.random<string & tags.Format<"uuid">>();
  const member2_id = typia.random<string & tags.Format<"uuid">>();
  const reporting_member1_id = typia.random<string & tags.Format<"uuid">>();
  const reporting_member2_id = typia.random<string & tags.Format<"uuid">>();
  const thread1_id = typia.random<string & tags.Format<"uuid">>();
  const thread2_id = typia.random<string & tags.Format<"uuid">>();

  // Create posts (target posts for reports)
  const post1 = await api.functional.discussionboard.threads.posts.post(connection, {
    body: {
      discussionboard_thread_id: thread1_id,
      discussionboard_member_id: member1_id,
      body: RandomGenerator.content()()(),
      created_at: new Date("2025-01-01T10:00:00.000Z").toISOString(),
    } satisfies IDiscussionboardPosts.ICreate,
  });
  typia.assert(post1);

  const post2 = await api.functional.discussionboard.threads.posts.post(connection, {
    body: {
      discussionboard_thread_id: thread2_id,
      discussionboard_member_id: member2_id,
      body: RandomGenerator.content()()(),
      created_at: new Date("2025-01-05T12:00:00.000Z").toISOString(),
    } satisfies IDiscussionboardPosts.ICreate,
  });
  typia.assert(post2);

  // Create post3 in thread1 by member2
  const post3 = await api.functional.discussionboard.threads.posts.post(connection, {
    body: {
      discussionboard_thread_id: thread1_id,
      discussionboard_member_id: member2_id,
      body: RandomGenerator.content()()(),
      created_at: new Date("2025-01-03T16:00:00.000Z").toISOString(),
    } satisfies IDiscussionboardPosts.ICreate,
  });
  typia.assert(post3);

  // --- REPORTING PHASE ---
  // Two independent reporting members
  // For each, file multiple reports across different posts, with distinct reasons and dates

  // List of Report objects for reference (to use for search validation)
  const reports: IDiscussionboardPostReport[] = [];
  const base_reasons = ["Spam", "Offensive language", "Harassment", "Irrelevant"];
  const reportTimes = [
    "2025-01-10T13:20:00.000Z",
    "2025-01-14T09:15:00.000Z",
    "2025-01-16T17:55:00.000Z",
    "2025-01-20T11:05:00.000Z",
  ];

  // (simulate as reporting_member1: reports post1, post2)
  for (let i = 0; i < 2; ++i) {
    const report = await api.functional.discussionboard.interactions.postReports.post(connection, {
      body: {
        discussionboard_post_id: i === 0 ? post1.id : post2.id,
        reason: base_reasons[i],
      } satisfies IDiscussionboardPostReport.ICreate,
    });
    typia.assert(report);
    // Overwrite created_at for search test variety
    report.created_at = reportTimes[i];
    report.discussionboard_member_id = reporting_member1_id;
    reports.push(report);
  }
  // (simulate as reporting_member2: report post2, post3)
  for (let i = 2; i < 4; ++i) {
    const report = await api.functional.discussionboard.interactions.postReports.post(connection, {
      body: {
        discussionboard_post_id: i === 2 ? post2.id : post3.id,
        reason: base_reasons[i],
      } satisfies IDiscussionboardPostReport.ICreate,
    });
    typia.assert(report);
    report.created_at = reportTimes[i];
    report.discussionboard_member_id = reporting_member2_id;
    reports.push(report);
  }

  // --- SEARCH PHASE ---
  // As admin/moderator: test various searches and verify accuracy by filter

  // 1. Filter by reporting_member_id (reporting_member1)
  const output1 = await api.functional.discussionboard.interactions.postReports.patch(connection, {
    body: {
      reporting_member_id: reporting_member1_id,
    } satisfies IDiscussionboardPostReport.IRequest,
  });
  typia.assert(output1);
  for (const r of output1.data)
    TestValidator.equals("Filter by reporting_member_id")(r.discussionboard_member_id)(reporting_member1_id);

  // 2. Filter by post_id (post2)
  const output2 = await api.functional.discussionboard.interactions.postReports.patch(connection, {
    body: {
      post_id: post2.id,
    } satisfies IDiscussionboardPostReport.IRequest,
  });
  typia.assert(output2);
  for (const r of output2.data)
    TestValidator.equals("Filter by post_id")(r.discussionboard_post_id)(post2.id);

  // 3. Filter by created_after/created_before (time window between reportTimes[1] and reportTimes[3])
  const output3 = await api.functional.discussionboard.interactions.postReports.patch(connection, {
    body: {
      created_after: reportTimes[1],
      created_before: reportTimes[3],
    } satisfies IDiscussionboardPostReport.IRequest,
  });
  typia.assert(output3);
  for (const r of output3.data)
    TestValidator.predicate("created_at in range")(r.created_at >= reportTimes[1] && r.created_at <= reportTimes[3]);

  // 4. Filter by reason_search ("Spam")
  const output4 = await api.functional.discussionboard.interactions.postReports.patch(connection, {
    body: {
      reason_search: "Spam",
    } satisfies IDiscussionboardPostReport.IRequest,
  });
  typia.assert(output4);
  for (const r of output4.data)
    TestValidator.predicate("reason_search contains keyword")(r.reason.includes("Spam"));

  // 5. Pagination: page/limit (limit=2)
  const output5 = await api.functional.discussionboard.interactions.postReports.patch(connection, {
    body: {
      limit: 2 as number & tags.Type<"int32"> & tags.Default<20> & tags.Minimum<1> & tags.Maximum<100>,
      page: 1 as number & tags.Type<"int32"> & tags.Default<1> & tags.Minimum<1>,
    } satisfies IDiscussionboardPostReport.IRequest,
  });
  typia.assert(output5);
  TestValidator.predicate("limit is respected")(output5.data.length <= 2);
  TestValidator.equals("pagination page")(output5.pagination.current)(1);

  // 6. Sorting: sort_key and sort_order (asc by created_at)
  const output6 = await api.functional.discussionboard.interactions.postReports.patch(connection, {
    body: {
      sort_key: "created_at",
      sort_order: "asc",
    } satisfies IDiscussionboardPostReport.IRequest,
  });
  typia.assert(output6);
  let last = "";
  for (const r of output6.data) {
    if (last && r.created_at < last)
      throw new Error("Sorting ascending not respected");
    last = r.created_at;
  }

  // --- PERMISSION TEST (NEGATIVE CASE) ---
  // Simulate regular member context (e.g. switch connection headers if possible)
  // In this stub, we simply expect a permission error on patch with a member's id
  await TestValidator.error("regular member forbidden")(() =>
    api.functional.discussionboard.interactions.postReports.patch(connection, {
      body: {
        reporting_member_id: reporting_member1_id,
      } satisfies IDiscussionboardPostReport.IRequest,
    })
  );
}

