 * 1. Creation of a post to be reported
 * 2. Filing a post report
 * 3. Updating the report as a moderator/admin (modifies 'reason')
 * 4. Ensuring regular members cannot update reports (permission denied)
 * 5. Error handling for updating a non-existent report
 *
 * Only permitted fields are updated as per DTO (reason), without status fields not supported by schema.
 * All business flows are implemented only as far as available APIs/DTOs permit.
 */
export async function test_api_discussionboard_test_update_post_report_resolution_by_moderator_admin_and_permission_error(
  connection: api.IConnection,
) {
  // 1. Create a post to be reported
  const threadId: string = typia.random<string & tags.Format<"uuid">>();
  const postAuthorId: string = typia.random<string & tags.Format<"uuid">>();
  const post = await api.functional.discussionboard.threads.posts.post(connection, {
