 *
 * 1. Register a new member via the registration API (with valid joined_at and status), saving the returned member id for future use.
 * 2. Create a member profile for this member, populating all valid fields (display_name, bio, avatar_uri, website, location) and verifying the profile is created as expected.
 * 3. Attempt to create another profile for the same member, verifying the API enforces the uniqueness (1:1) constraint and rejects duplicates.
 * 4. Attempt to create a profile omitting the required discussionboard_member_id and verify that a runtime error occurs (only runtime, not TypeScript error).
 * 5. Attempt to create a profile with malformed avatar_uri/website (invalid URI/URL) and assert that validation errors result.
 * 6. Non-owner or banned member simulation is omitted, as there is no supported API for that in provided materials.
 *
 * All API interactions use provided SDK functions and DTOs, with typia.assert and TestValidator assertions to validate correctness. All steps are explained inline.
 */
export async function test_api_discussionboard_test_create_member_profile_valid_and_uniqueness(
  connection: api.IConnection,
) {
  // 1. Register a new member
  const member = await api.functional.discussionboard.actors.members.post(connection, {
    body: {
      joined_at: new Date().toISOString(),
      status: "active",
    } satisfies IDiscussionboardMembers.ICreate,
  });
  typia.assert(member);

  // 2. Create a profile for the new member with all valid fields
  const profileInput: IDiscussionBoardMemberProfile.ICreate = {
    discussionboard_member_id: member.id,
    display_name: "Test User",
    bio: "Enthusiastic member of the discussion board!",
    avatar_uri: "https://cdn.test.com/avatar/1234.png",
    website: "https://test-user.homepage.com",
    location: "Seoul, Korea",
  };
  const profile = await api.functional.discussionboard.actors.memberProfiles.post(connection, {
    body: profileInput,
  });
  typia.assert(profile);
  TestValidator.equals("discussionboard_member_id matches")(profile.discussionboard_member_id)(profileInput.discussionboard_member_id);
  TestValidator.equals("display_name matches")(profile.display_name)(profileInput.display_name);
  TestValidator.equals("bio matches")(profile.bio)(profileInput.bio);
  TestValidator.equals("avatar_uri matches")(profile.avatar_uri)(profileInput.avatar_uri);
  TestValidator.equals("website matches")(profile.website)(profileInput.website);
  TestValidator.equals("location matches")(profile.location)(profileInput.location);
  TestValidator.predicate("profile id is not empty")((typeof profile.id === "string") && profile.id.length > 0);

  // 3. Attempt to create another profile for the same member (should fail: uniqueness constraint)
  await TestValidator.error("unique member-profile constraint enforced")(() =>
    api.functional.discussionboard.actors.memberProfiles.post(connection, {
      body: profileInput,
