  // 4. Attempt to create a profile with missing required discussionboard_member_id (should produce runtime error)
  const invalidProfileMissingMemberId = { ...profileInput };
  // eslint-disable-next-line @typescript-eslint/ban-ts-comment
  // @ts-expect-error
  delete invalidProfileMissingMemberId.discussionboard_member_id;
  await TestValidator.error("missing required member id should fail at runtime")(() =>
    // @ts-ignore
    api.functional.discussionboard.actors.memberProfiles.post(connection, {
      body: invalidProfileMissingMemberId,
    })
  );

  // 5. Attempt to create a profile with invalid URI fields (malformed avatar_uri and website)
  const invalidProfileBadUris: IDiscussionBoardMemberProfile.ICreate = {
    ...profileInput,
    avatar_uri: "not-a-valid-uri",
