/**
 * E2E test for updating a member profile by various roles and validating business rules.
 *
 * This test verifies the correctness and access control of the update endpoint for member profiles. It covers:
 *
 * 1. Profile owner successfully updates profile fields (display name, bio, avatar URI, website, location) and sees changes reflected.
 * 2. Unrelated member attempts update and receives 403 forbidden.
 * 3. Updating non-existent profile returns 404.
 * 4. Invalid data (empty display name, invalid website) returns error.
 * 5. Soft-delete and deleted-member scenarios are omitted due to unavailable API fields.
 *
 * Steps:
 * 1. Register a new member (owner)
 * 2. Create a member profile for that member
 * 3. Update profile as owner and verify changes
 * 4. Register another member and attempt forbidden update
 * 5. Attempt update of non-existent profile
 * 6. Attempt update with invalid website URL
 * 7. Attempt update with empty display_name
 */
export async function test_api_discussionboard_test_update_member_profile_owner_and_admin_verification(
  connection: api.IConnection,
) {
  // 1. Register a new member (profile owner)
  const owner = await api.functional.discussionboard.actors.members.post(connection, {
    body: {
      joined_at: new Date().toISOString(),
      status: "active",
    },
  });
  typia.assert(owner);

  // 2. Create a profile for the owner
  const profile = await api.functional.discussionboard.actors.memberProfiles.post(connection, {
    body: {
      discussionboard_member_id: owner.id,
      display_name: "Original Name",
      bio: "Initial owner bio.",
      avatar_uri: null,
      website: null,
      location: "Seoul",
    },
  });
  typia.assert(profile);

  // 3. Update profile as owner
  const updateBody = {
    display_name: "Updated Display Name",
    bio: "Updated profile bio.",
    avatar_uri: "https://cdn.wrtnlabs.com/avatar/test-owner.png",
    website: "https://www.wrtnlabs.com",
    location: "Busan",
  } satisfies IDiscussionBoardMemberProfile.IUpdate;
  const updated = await api.functional.discussionboard.actors.memberProfiles.putById(connection, {
    id: profile.id,
    body: updateBody,
  });
  typia.assert(updated);
  TestValidator.equals("display_name updated")(updated.display_name)(updateBody.display_name);
  TestValidator.equals("bio updated")(updated.bio)(updateBody.bio);
  TestValidator.equals("avatar_uri updated")(updated.avatar_uri)(updateBody.avatar_uri);
  TestValidator.equals("website updated")(updated.website)(updateBody.website);
  TestValidator.equals("location updated")(updated.location)(updateBody.location);

  // 4. Register unrelated member
  const stranger = await api.functional.discussionboard.actors.members.post(connection, {
    body: {
      joined_at: new Date().toISOString(),
      status: "active",
    },
  });
  typia.assert(stranger);

  // 5. Attempt forbidden update as unrelated member
  TestValidator.error("forbidden: unrelated member cannot update profile")(async () => {
    await api.functional.discussionboard.actors.memberProfiles.putById(connection, {
      id: profile.id,
      body: {
        display_name: "Evil Update",
        bio: "Hacked bio.",
        avatar_uri: null,
        website: null,
        location: null,
      },
    });
  });

  // 6. Attempt update of non-existent profile
  TestValidator.error("not found: update non-existent profile")(async () => {
    await api.functional.discussionboard.actors.memberProfiles.putById(connection, {
      id: typia.random<string & tags.Format<"uuid">>(),
      body: updateBody,
    });
  });

  // 7. Attempt update with invalid website
  TestValidator.error("invalid website url")(async () => {
    await api.functional.discussionboard.actors.memberProfiles.putById(connection, {
      id: profile.id,
      body: {
        ...updateBody,
        website: "not-a-valid-url",
      },
    });
  });

  // 8. Attempt update with empty display_name
  TestValidator.error("invalid: display_name empty")(async () => {
    await api.functional.discussionboard.actors.memberProfiles.putById(connection, {
      id: profile.id,
      body: {
        ...updateBody,
        display_name: "",
      },
    });
  });

  // Soft-delete and deleted-member validation is omitted due to lack of such API fields and controls.
}

