/**
 * Validate permission, business rules, and data cleanup for soft-deleting DiscussionBoard member profiles.
 *
 * Business context:
 * Profiles in the DiscussionBoard system are user-customizable entities linked 1:1 with a member account, and may be removed under data protection principles. Only the profile owner or an administrator is allowed to delete a profile. Deletion may be a soft-delete (hiding the profile) as required for GDPR and audit compliance, and must not (accidentally) remove the core member account data. Correct permissions and status codes are required for each scenario.
 *
 * Test procedure step-by-step:
 * 1. Register a member (A), create their profile, and validate success.
 * 2. Delete the profile as its owner and confirm the profile record is no longer accessible (status/deleted and not found on GET or in profile lists).
 * 3. Register a second member (B) and ensure they cannot delete A's profile (should receive 403 Forbidden or similar error).
 * 4. Register an admin member (with elevated permissions), and as admin, delete a new member's profile (C) and confirm succeeds, cleanup as per business rules.
 * 5. Attempt to delete an already deleted or non-existent profile, expecting a suitable error (e.g., 404 Not Found or idempotent no-op with clear status).
 * 6. Confirm that deleting a profile does not affect the underlying member's data (member entity remains accessible).
 */
export async function test_api_discussionboard_test_delete_member_profile_permission_and_data_cleanup(
  connection: api.IConnection,
) {
  // 1. Register Member A
  const memberA = await api.functional.discussionboard.actors.members.post(connection, {
    body: {
      joined_at: new Date().toISOString(),
      status: "active",
    },
  });
  typia.assert(memberA);

  // 1b. Create profile for Member A
  const profileA = await api.functional.discussionboard.actors.memberProfiles.post(connection, {
    body: {
      discussionboard_member_id: memberA.id,
      display_name: RandomGenerator.name(),
      bio: RandomGenerator.content()()(),
      avatar_uri: null,
      website: null,
      location: null,
