import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardAuditLogs } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardAuditLogs";
import type { DiscussionBoardAdmins } from "@ORGANIZATION/PROJECT-api/lib/structures/DiscussionBoardAdmins";

/**
 * 감사 로그 레코드 수정 (Systematic Audit Log Update by Admin)
 *
 * 관리자 권한에서 감사 로그(action, details 등)를 수정하면 해당 값들이 정상 반영되는지 검증한다.
 * 수정 시 id, created_at, actor_id 등 불변 필드는 변경되지 않아야 하며, 실제로 변경된 내용은 update 결과에 반영된다.
 *
 * [진행 절차]
 * 1. 테스트용 멤버 UUID를 신규 생성해 관리자로 승격
 * 2. 해당 관리자 UUID로 감사 로그 (audit log) 레코드 직접 생성
 * 3. PUT update로 action/details를 변경
 * 4. 반환값에 변경사항 반영 및 불변 필드 불변성 검증
 *
 * 요구사항: 관리자 권한 없이는 update 불가 (의존성 1번),
 *            감사 로그 원본 자체가 있어야 함 (의존성 2번)
 *            - 각 단계별 typia.assert와 TestValidator 검증 필수
 */
export async function test_api_discussionboard_systematic_auditLogs_putById(
  connection: api.IConnection,
) {
  // 1. 테스트용 멤버를 관리자로 승격
  const adminMemberId = typia.random<string & tags.Format<"uuid">>();
  const elevatedAt = new Date().toISOString();
  const adminRecord = await api.functional.discussionboard.actors.admins.post(connection, {
    body: {
      discussionboard_member_id: adminMemberId,
      elevated_at: elevatedAt,
    },
  });
  typia.assert(adminRecord);

  // 2. 감사 로그 생성 (admin UUID 필수)
  const initialLogAction = "SETTING_UPDATE";
  const initialDetails = "Initial quota set to 150";
  const initialTargetTable = "users";
  const initialTargetId = typia.random<string & tags.Format<"uuid">>();
  const auditLog = await api.functional.discussionboard.systematic.auditLogs.post(connection, {
    body: {
      action: initialLogAction,
      actor_id: adminMemberId,
      target_table: initialTargetTable,
      target_id: initialTargetId,
      details: initialDetails,
    },
  });
  typia.assert(auditLog);

  // 3. 감사 로그 update (PUT): action, details 값 수정
  const updatedAction = "SETTING_UPDATE_CORRECTION";
  const updatedDetails = "Changed quota from 150 back to 100 (compliance restore).";
  const updatedAuditLog = await api.functional.discussionboard.systematic.auditLogs.putById(connection, {
    id: auditLog.id,
    body: {
      action: updatedAction,
      target_table: auditLog.target_table,
      target_id: auditLog.target_id,
      details: updatedDetails,
    },
  });
  typia.assert(updatedAuditLog);

  // 4. 결과 검증: 수정된 필드 및 불변 필드 체크
  TestValidator.equals("action updated")(updatedAuditLog.action)(updatedAction);
  TestValidator.equals("details updated")(updatedAuditLog.details)(updatedDetails);
  TestValidator.equals("불변 id")(updatedAuditLog.id)(auditLog.id);
  TestValidator.equals("불변 created_at")(updatedAuditLog.created_at)(auditLog.created_at);
  TestValidator.equals("불변 actor_id")(updatedAuditLog.actor_id)(auditLog.actor_id);
}

