import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardAuditLogs } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardAuditLogs";
import type { DiscussionBoardAdmins } from "@ORGANIZATION/PROJECT-api/lib/structures/DiscussionBoardAdmins";

/**
 * 감사 로그 레코드 삭제(관리자 권한) E2E 시나리오 검증
 *
 * 이 테스트는 시스템 관리자(Admin) 계정이 특정 감사 로그(audit log) 레코드를 정상적으로 삭제(eraseById)할 수 있는지, 그리고 삭제된 결과 레코드가 반환되는지 검증합니다. 실제 운영 환경에서는 감사 로그 삭제 행위가 다시 메타 로그로 이중 기록되지만,
 * 해당 로깅 이력을 직접 조회하는 별도 API는 제공되지 않으므로, 본 테스트에서는 생성-삭제 사이클 및 반환값의 일관성만 검증합니다.
 *
 * 절차:
 * 1. 테스트 멤버 UUID 생성
 * 2. 해당 멤버를 DiscussionBoardAdmins에 관리자 승격
 * 3. 생성된 admin uuid로 감사 로그(Issue) 레코드 직접 생성
 * 4. 해당 감사 로그 id로 eraseById(삭제) API 호출
 * 5. 반환된 삭제 레코드의 주요 필드 및 id 일치 검증
 */
export async function test_api_discussionboard_systematic_auditLogs_eraseById_test_delete_audit_log_success_by_admin(
  connection: api.IConnection,
) {
  // 1. 테스트 멤버 UUID (가상)
  const memberId: string = typia.random<string & tags.Format<"uuid">>();

  // 2. 관리자 승격 (DiscussionBoardAdmins)
  const elevated_at: string = new Date().toISOString();
  const admin = await api.functional.discussionboard.actors.admins.post(connection, {
    body: {
      discussionboard_member_id: memberId,
      elevated_at,
    } satisfies DiscussionBoardAdmins.ICreate,
  });
  typia.assert(admin);
  TestValidator.equals("admin-member id 일치")(admin.discussionboard_member_id)(memberId);

  // 3. 감사 로그 직접 생성 (actor_id = admin)
  const auditLogCreate: IDiscussionboardAuditLogs.ICreate = {
    action: "TEST_DELETE",
    actor_id: memberId,
    target_table: "audit_test",
    target_id: typia.random<string & tags.Format<"uuid">>(),
    details: "E2E 테스트: 감사 로그 삭제 정상 흐름 검증",
  };
  const auditLog = await api.functional.discussionboard.systematic.auditLogs.post(connection, {
    body: auditLogCreate,
  });
  typia.assert(auditLog);
  TestValidator.equals("issue action 코드")(auditLog.action)(auditLogCreate.action);
  TestValidator.equals("actor_id")(auditLog.actor_id)(memberId);

  // 4. 감사 로그 삭제 by id (관리자)
  const deleted = await api.functional.discussionboard.systematic.auditLogs.eraseById(connection, {
    id: auditLog.id,
  });
  typia.assert(deleted);
  TestValidator.equals("삭제된 감사로그 id")(deleted.id)(auditLog.id);
  TestValidator.equals("삭제된 actor")(deleted.actor_id)(auditLog.actor_id);
  TestValidator.equals("삭제 action 코드")(deleted.action)(auditLog.action);
}

