  });
  typia.assert(listByCode);
  TestValidator.predicate('code filter valid')(
    listByCode.data.length === 1 && listByCode.data[0].code === 'ECON'
  );

  // 5. List boards filter by name (partial matches may/may not be supported)
  const listByName = await api.functional.discussionboard.boards.boards.patch(connection, {
    body: { name: 'Politics Board' } as any,
  });
  typia.assert(listByName);
  TestValidator.predicate('name filter valid')(
    listByName.data.length === 1 && listByName.data[0].name === 'Politics Board'
  );

  // 6. List boards filter by is_active
  const listActive = await api.functional.discussionboard.boards.boards.patch(connection, {
    body: { is_active: true } as any,
  });
  typia.assert(listActive);
  TestValidator.predicate('is_active filter only active')(
    listActive.data.every(b => b.is_active === true)
  );

  // 7. Test pagination: limit to 2 per page
  const pagedBoardsPage1 = await api.functional.discussionboard.boards.boards.patch(connection, {
    body: { limit: 2, page: 1 } as any,
  });
  typia.assert(pagedBoardsPage1);
  TestValidator.equals('pagination per page')(
    pagedBoardsPage1.data.length
  )(2);
  TestValidator.equals('pagination records')(
    pagedBoardsPage1.pagination.records
  )(boards.length);

  const pagedBoardsPage2 = await api.functional.discussionboard.boards.boards.patch(connection, {
    body: { limit: 2, page: 2 } as any,
  });
  typia.assert(pagedBoardsPage2);
  TestValidator.equals('pagination page 2 count')(
    pagedBoardsPage2.data.length
  )(boards.length - 2);

