  const noResult = await api.functional.discussionboard.boards.boards.patch(connection, {
    body: { code: 'NONEXISTENT' } as any,
  });
  typia.assert(noResult);
  TestValidator.equals('empty result')(
    noResult.data.length
  )(0);
  TestValidator.equals('pagination records 0')(
    noResult.pagination.records
  )(0);

  // 9. Out-of-bounds page
  const obPage = await api.functional.discussionboard.boards.boards.patch(connection, {
    body: { limit: 2, page: 100 } as any,
  });
  typia.assert(obPage);
  TestValidator.equals('out of bounds data empty')(
    obPage.data.length
  )(0);
}

