  TestValidator.equals("discussionboard_category_id matches")(fetched.discussionboard_category_id)(created.discussionboard_category_id);
  TestValidator.equals("code matches")(fetched.code)(created.code);
  TestValidator.equals("name matches")(fetched.name)(created.name);
