import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMembers } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMembers";
import type { DiscussionBoardModerators } from "@ORGANIZATION/PROJECT-api/lib/structures/DiscussionBoardModerators";
import type { IDiscussionboardWarningRecord } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardWarningRecord";
import type { IPageIDiscussionboardWarningRecord } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionboardWarningRecord";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * 다양한 필터와 페이지네이션, 접근 권한 시나리오를 포괄적으로 검증하는 경고 레코드 리스트 E2E 테스트
 *
 * - 커뮤니티 경고 레코드 관리의 각종 필터(warned_member_id, issued_by_moderator_id, date range),
 *   페이지네이션(page/limit) 및 조합, 엣지 케이스(빈 결과, 잘못된 uuid, 페이지 범위 초과 등)와
 *   접근 제어(모더레이터/일반멤버 권한 차이)를 검증하는 E2E 테스트입니다.
 * - connection 객체 기반의 인증정보(권한)를 시험하는 부분은 실제 authentication 방식에 맞춰 구현 필요
 *
 * [테스트 절차]
 * 1. 멤버1, 멤버2 생성 후 멤버1을 운영자로 승격
 * 2. 멤버1이 멤버2 및 자기 자신에게 각각 경고를 여러 건 발행
 * 3. 다양한 필터 조건(warned_member_id, issued_by_moderator_id, created_after, created_before, page, limit 등)으로 목록 조회 & 데이터 일치성 체크
 * 4. 빈 결과/잘못된 uuid/비권한자의 접근 등 예외/경계 상황 확인
 */
export async function test_api_discussionboard_test_list_warning_records_with_various_filters_and_pagination(
  connection: api.IConnection,
) {
  // 1. 멤버1 생성
  const member1 = await api.functional.discussionboard.actors.members.post(connection, {
    body: {
      joined_at: new Date(Date.now() - 5 * 24 * 60 * 60 * 1000).toISOString(), // 5일 전
      status: "active",
    },
  });
  typia.assert(member1);

  // 2. 멤버2 생성
  const member2 = await api.functional.discussionboard.actors.members.post(connection, {
    body: {
      joined_at: new Date(Date.now() - 4 * 24 * 60 * 60 * 1000).toISOString(), // 4일 전
      status: "active",
    },
  });
  typia.assert(member2);

  // 3. 멤버1 운영자(Moderator)로 승격
  const moderator = await api.functional.discussionboard.actors.moderators.post(connection, {
    body: {
      discussionboard_member_id: member1.id,
      promoted_at: new Date(Date.now() - 3 * 24 * 60 * 60 * 1000).toISOString(),
    },
  });
  typia.assert(moderator);

  // 4. 경고 기록 생성: 멤버2에게 2건, 멤버1에게 1건 (발행자 모두 멤버1)
  const warning1 = await api.functional.discussionboard.moderation.warningRecords.post(connection, {
    body: {
      warned_member_id: member2.id,
      issued_by_moderator_id: moderator.discussionboard_member_id,
      reason: "스팸 링크 게시 (3일 전)",
    },
  });
  typia.assert(warning1);

  const warning2 = await api.functional.discussionboard.moderation.warningRecords.post(connection, {
    body: {
      warned_member_id: member2.id,
      issued_by_moderator_id: moderator.discussionboard_member_id,
      reason: "욕설 사용 (2일 전)",
    },
  });
  typia.assert(warning2);

  const warning3 = await api.functional.discussionboard.moderation.warningRecords.post(connection, {
    body: {
      warned_member_id: member1.id,
      issued_by_moderator_id: moderator.discussionboard_member_id,
      reason: "운영자 규칙 위반 (1일 전)",
    },
  });
  typia.assert(warning3);

  // 5-1. warned_member_id 필터
  const pageRes1 = await api.functional.discussionboard.moderation.warningRecords.patch(connection, {
    body: {
      warned_member_id: member2.id,
      page: 1,
      limit: 10,
    },
  });
  typia.assert(pageRes1);
  pageRes1.data.forEach(w => {
    TestValidator.equals("warned_member_id 매치")(w.warned_member_id)(member2.id);
  });
  TestValidator.predicate("2건 반환")(pageRes1.data.length === 2);

  // 5-2. issued_by_moderator_id로 필터
  const pageRes2 = await api.functional.discussionboard.moderation.warningRecords.patch(connection, {
    body: {
      issued_by_moderator_id: moderator.discussionboard_member_id,
      limit: 10,
    },
  });
  typia.assert(pageRes2);
  pageRes2.data.forEach(w => {
    TestValidator.equals("발행자 일치")(w.issued_by_moderator_id)(moderator.discussionboard_member_id);
  });
  TestValidator.predicate("3건 반환")(pageRes2.data.length === 3);

  // 5-3. created_after/created_before 범위 내만 필터 (warning2, warning3 구간)
  const createdAfter = new Date(Date.now() - 2.5 * 24 * 60 * 60 * 1000).toISOString();
