      created_after: createdAfter,
      created_before: createdBefore,
      limit: 10,
    },
  });
  typia.assert(pageRes3);
  pageRes3.data.forEach(w => {
    TestValidator.predicate("범위 내 created_at인지")(
      w.created_at >= createdAfter && w.created_at <= createdBefore,
    );
  });

  // 5-4. 페이지네이션 (limit=1) 두번째 페이지
  const pageRes4 = await api.functional.discussionboard.moderation.warningRecords.patch(connection, {
