  const pageRes5 = await api.functional.discussionboard.moderation.warningRecords.patch(connection, {
    body: {
      warned_member_id: typia.random<string & tags.Format<"uuid">>(),
      page: 1,
      limit: 5,
    },
  });
  typia.assert(pageRes5);
  TestValidator.equals("빈 결과 반환")(pageRes5.data.length)(0);

  // 7. 잘못된 uuid 포맷 -> 에러 발생
  await TestValidator.error("warned_member_id 잘못된 uuid 포맷은 에러")(async () => {
    await api.functional.discussionboard.moderation.warningRecords.patch(connection, {
      body: {
        warned_member_id: "NOT_UUID",
      },
    });
  });

  // 8. 권한 없는 멤버(멤버2)가 접근 시 권한 에러
  await TestValidator.error("일반 멤버는 접근 금지")(async () => {
    // 실제 환경에서는 connection에 멤버2의 인증정보를 세팅해야 함 (여기선 connection 객체를 그대로 사용)
    await api.functional.discussionboard.moderation.warningRecords.patch(connection, {
      body: {
        limit: 5,
      },
    });
  });
}

