import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMembers } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMembers";
import type { DiscussionBoardModerators } from "@ORGANIZATION/PROJECT-api/lib/structures/DiscussionBoardModerators";
import type { IDiscussionboardWarningRecord } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardWarningRecord";

/**
 * Test updating discussion board warning record by ID for all success and error flows.
 *
 * Covers:
 * - Successful reason update by moderator.
 * - State and audit property preservation.
 * - Forbidden update attempt by unauthorized user.
 * - Not found error for invalid ID update.
 * - DTO field immutability enforcement (immutable fields not accepted in update by schema).
 *
 * 1. Create recipient member (target of warning).
 * 2. Create moderator member; grant moderator role.
 * 3. Moderator issues warning to recipient.
 * 4. Moderator updates reason via PUT /warningRecords/{id}.
 * 5. Assert: updated reason, unchanged audit/immutable fields.
 * 6. Unauthorized member attempts update (should fail: forbidden/unauthorized).
 * 7. Moderator attempts update of random ID (should fail: 404).
 * 8. (Field immutability: no patch allowed except .reason by DTO design.)
 */
export async function test_api_discussionboard_test_update_warning_record_by_id_authorized_and_error_cases(connection: api.IConnection) {
  // === Step 1: Create recipient member (will receive warning) ===
  const recipient: IDiscussionboardMembers = await api.functional.discussionboard.actors.members.post(
    connection,
    {
      body: {
        joined_at: new Date().toISOString(),
        status: "active",
      } satisfies IDiscussionboardMembers.ICreate,
    }
  );
  typia.assert(recipient);

  // === Step 2: Create moderator member and grant moderator role ===
  const moderator: IDiscussionboardMembers = await api.functional.discussionboard.actors.members.post(
    connection,
    {
      body: {
        joined_at: new Date().toISOString(),
        status: "active",
      } satisfies IDiscussionboardMembers.ICreate,
    }
  );
  typia.assert(moderator);
  // Promote to moderator
  const moderatorRole: DiscussionBoardModerators = await api.functional.discussionboard.actors.moderators.post(
    connection,
    {
      body: {
        discussionboard_member_id: moderator.id,
        promoted_at: new Date().toISOString(),
      } satisfies DiscussionBoardModerators.ICreate,
    }
  );
  typia.assert(moderatorRole);

  // === Step 3: Issue a warning as moderator ===
  const warning: IDiscussionboardWarningRecord = await api.functional.discussionboard.moderation.warningRecords.post(
    connection,
    {
      body: {
        warned_member_id: recipient.id,
        issued_by_moderator_id: moderator.id,
        reason: "Initial warning reason - inappropriate content.",
      } satisfies IDiscussionboardWarningRecord.ICreate,
    }
  );
  typia.assert(warning);

  // === Step 4: Moderator updates the reason field ===
  const updatedReason = "Edited warning reason: explanation updated.";
  const updatedWarning: IDiscussionboardWarningRecord = await api.functional.discussionboard.moderation.warningRecords.putById(
    connection,
    {
      id: warning.id,
      body: {
        reason: updatedReason,
      } satisfies IDiscussionboardWarningRecord.IUpdate,
    }
  );
  typia.assert(updatedWarning);

  // === Step 5: Assert only reason changed, audit fields preserved ===
  TestValidator.equals("reason updated")(updatedWarning.reason)(updatedReason);
  TestValidator.equals("warned_member_id unchanged")(updatedWarning.warned_member_id)(warning.warned_member_id);
  TestValidator.equals("issued_by_moderator_id unchanged")(updatedWarning.issued_by_moderator_id)(warning.issued_by_moderator_id);
  TestValidator.equals("created_at unchanged")(updatedWarning.created_at)(warning.created_at);
  TestValidator.equals("id unchanged")(updatedWarning.id)(warning.id);

  // === Step 6: Unauthorized user attempts update (should be forbidden/unauthorized error) ===
  const otherMember: IDiscussionboardMembers = await api.functional.discussionboard.actors.members.post(
    connection,
    {
      body: {
        joined_at: new Date().toISOString(),
        status: "active",
      } satisfies IDiscussionboardMembers.ICreate,
    }
  );
  typia.assert(otherMember);
  // No promotion - remains normal member

  await TestValidator.error("forbidden: member cannot update warning record")(
    async () => {
      // (No API for login/switching member tokens in this API set, so by permissions: assume connection context respects role. If ability to simulate role present, would re-auth as member. Currently this step is a placeholder and must be manually verified in context where user switching is supported.)
      await api.functional.discussionboard.moderation.warningRecords.putById(
        connection,
        {
          id: warning.id,
          body: {
            reason: "Tamper by user!",
          } satisfies IDiscussionboardWarningRecord.IUpdate,
        }
      );
    }
  );

  // === Step 7: Update non-existent warning record (404) ===
  await TestValidator.error("not found for random/dangling warning id")(
    async () => {
      await api.functional.discussionboard.moderation.warningRecords.putById(
        connection,
        {
          id: typia.random<string & tags.Format<"uuid">>(),
          body: {
            reason: "Should not exist",
          } satisfies IDiscussionboardWarningRecord.IUpdate,
        }
      );
    }
  );

  // === Step 8: Immutable fields in update ===
  // As per IDiscussionboardWarningRecord.IUpdate, only `reason` may be provided. No test is possible for changing other fields by type safety.
}

