  //  (Assume real token switching per user in real E2E, not shown here)
  await TestValidator.error("unauthorized deletion should fail")(() =>
    api.functional.discussionboard.threads.commentReplies.eraseById(connection, {
      id: replyMapping.id
    })
  );

  // -----
  // Case 3: Owner tries to delete already deleted mapping (should fail or demonstrate idempotency)
  await TestValidator.error("repeat deletion should fail or be idempotent")(() =>
    api.functional.discussionboard.threads.commentReplies.eraseById(connection, {
      id: replyMapping.id
    })
  );

  // -----
  // Case 4: Delete random non-existing mapping ID (404 expected)
  await TestValidator.error("delete non existent mapping yields 404")(() =>
    api.functional.discussionboard.threads.commentReplies.eraseById(connection, {
