/**
 * Test retrieving a tag proposal by its unique ID (valid and invalid cases).
 *
 * This test validates the retrieval of tag proposals via their unique IDs, ensuring that:
 * - Tag proposals can be successfully fetched if the ID is valid
 * - Error is thrown for non-existent proposal IDs (not found handling)
 *
 * Business context:
 * Tag proposals represent suggestions by registered members for new forum tags. Only members can create such proposals, and each proposal is uniquely identified by a UUID. Fetching by ID is a key part of moderation and member UI flows.
 *
 * Workflow:
 * 1. Register two members (simulates two users)
 * 2. Each member submits a tag proposal using their member ID
 * 3. Retrieve each proposal by its unique ID and verify all returned properties match the expected values
 * 4. Attempt to retrieve a proposal by a random (non-existent) UUID and assert that a not found error is thrown
 */
export async function test_api_discussionboard_test_get_tag_proposal_by_valid_and_invalid_id(
  connection: api.IConnection,
) {
  // 1. Register two members
  const member1 = await api.functional.discussionboard.actors.members.post(connection, {
    body: {
      joined_at: new Date().toISOString(),
      status: "active",
    } satisfies IDiscussionboardMembers.ICreate,
  });
  typia.assert(member1);

  const member2 = await api.functional.discussionboard.actors.members.post(connection, {
    body: {
      joined_at: new Date().toISOString(),
      status: "active",
    } satisfies IDiscussionboardMembers.ICreate,
  });
  typia.assert(member2);

  // 2. Each member submits a tag proposal
  const tag1 = RandomGenerator.alphabets(8);
  const proposal1 = await api.functional.discussionboard.interactions.tagProposals.post(connection, {
    body: {
      discussionboard_member_id: member1.id,
      proposed_tag: tag1,
    } satisfies IDiscussionboardTagProposal.ICreate,
  });
  typia.assert(proposal1);

  const tag2 = RandomGenerator.alphabets(8);
  const proposal2 = await api.functional.discussionboard.interactions.tagProposals.post(connection, {
    body: {
      discussionboard_member_id: member2.id,
      proposed_tag: tag2,
    } satisfies IDiscussionboardTagProposal.ICreate,
  });
  typia.assert(proposal2);

  // 3. Retrieve each proposal by valid ID and verify all returned data
  const fetched1 = await api.functional.discussionboard.interactions.tagProposals.getById(connection, { id: proposal1.id });
  typia.assert(fetched1);
  TestValidator.equals("proposal1 same id")(fetched1.id)(proposal1.id);
  TestValidator.equals("proposal1 tag")(fetched1.proposed_tag)(proposal1.proposed_tag);
  TestValidator.equals("proposal1 member")(fetched1.discussionboard_member_id)(member1.id);

  const fetched2 = await api.functional.discussionboard.interactions.tagProposals.getById(connection, { id: proposal2.id });
  typia.assert(fetched2);
  TestValidator.equals("proposal2 same id")(fetched2.id)(proposal2.id);
  TestValidator.equals("proposal2 tag")(fetched2.proposed_tag)(proposal2.proposed_tag);
  TestValidator.equals("proposal2 member")(fetched2.discussionboard_member_id)(member2.id);

  // 4. Try retrieving a proposal by a random UUID (should result in error)
  const nonExistentId = typia.random<string & tags.Format<"uuid">>();
  TestValidator.error("not found for non-existent proposal id")(
    async () => {
      await api.functional.discussionboard.interactions.tagProposals.getById(connection, { id: nonExistentId });
    },
  );
}

