/**
 * 태그 제안(Proposal) 수정 비즈니스 E2E 전체 검증.
 *
 * - 멤버 A(제안자), 멤버 B(비소유 일반멤버), 멤버 C(관리자 역할 가능 시나리오용) 세 유저를 등록함.
 * - A가 새로운 태그 제안(UniqueTagA1)을 생성.
 * - A(소유자)가 정상적으로 태그 제안문자(UniqueTagA2)로 변경(수정)할 수 있음을 검증.
 * - 다시 기존 값(UniqueTagA1)으로 변경 시도할 경우(같은 멤버의 중복) 비즈니스 오류가 발생하는지 검증.
 * - 권한 없는 멤버(B)가 타인의 제안 건을 변경할 수 없는지 오류(Forbidden 등)로 검증.
 * - (관리자/운영자 update 허용, 제안 확정/반려/금지어 등 상태/컨텐츠 룰은 스펙 미구현으로 테스트 생략)
 * - 각 단계 별 typia.assert, TestValidator 활용으로 결과 및 타입 검증.
 */
export async function test_api_discussionboard_test_update_tag_proposal_as_owner_and_moderator(
  connection: api.IConnection,
) {
  // 1. 멤버 세 명(A/B/C) 등록: 각각 제안자/타 멤버/관리자(가능성 용)
  const memberA = await api.functional.discussionboard.actors.members.post(connection, {
    body: {
      joined_at: new Date().toISOString(),
      status: "active",
    },
  });
  typia.assert(memberA);

  const memberB = await api.functional.discussionboard.actors.members.post(connection, {
    body: {
      joined_at: new Date().toISOString(),
      status: "active",
    },
  });
  typia.assert(memberB);

  const memberC = await api.functional.discussionboard.actors.members.post(connection, {
    body: {
      joined_at: new Date().toISOString(),
      status: "active",
    },
  });
  typia.assert(memberC);

  // 2. 멤버 A가 새 태그 제안(UniqueTagA1) 생성
  const proposal = await api.functional.discussionboard.interactions.tagProposals.post(connection, {
    body: {
      discussionboard_member_id: memberA.id,
      proposed_tag: "UniqueTagA1",
    },
  });
  typia.assert(proposal);

  // 3. 소유자(A)가 태그 제안 수정(UniqueTagA2)
  const updatedProposal = await api.functional.discussionboard.interactions.tagProposals.putById(connection, {
    id: proposal.id,
    body: {
      proposed_tag: "UniqueTagA2",
    },
  });
  typia.assert(updatedProposal);
  TestValidator.equals("proposed_tag updated")(updatedProposal.proposed_tag)("UniqueTagA2");

  // 4. 검토/승인 상태 후 변경(불가) 루트는 status 미노출로 생략

  // 5. 동일 멤버 중복값(UniqueTagA1)으로 변경 시도: 오류 발생해야 함
  await TestValidator.error("duplicate tag for same member")(async () => {
    await api.functional.discussionboard.interactions.tagProposals.putById(connection, {
      id: proposal.id,
      body: {
        proposed_tag: "UniqueTagA1",
      },
    });
  });

  // 6. 금지 문자열/컨텐츠 루트는 스펙 미구현이므로 생략

  // 7. 권한 없는 타 멤버(B)의 수정 시도: 오류(Forbidden 등)발생 기대
  await TestValidator.error("non-owner cannot update proposal")(async () => {
    // 실제 멤버 변경 컨텍스트 불가(로그인 기반 없으므로 직접 호출)
    await api.functional.discussionboard.interactions.tagProposals.putById(connection, {
      id: proposal.id,
      body: {
        proposed_tag: "MemberBWontWork",
      },
    });
