      status: "active",
    } satisfies IDiscussionboardMembers.ICreate,
  });
  typia.assert(admin);

  // 4. Proposer submits two tag proposals
  const proposal1 = await api.functional.discussionboard.interactions.tagProposals.post(connection, {
    body: {
      discussionboard_member_id: proposer.id,
      proposed_tag: RandomGenerator.alphabets(8),
