import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMembers } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMembers";
import type { DiscussionBoardModerators } from "@ORGANIZATION/PROJECT-api/lib/structures/DiscussionBoardModerators";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validate listing moderators with advanced filters and pagination as an admin.
 *
 * This test confirms that the list API returns accurate moderator entries based on member ID,
 * promotion date range, and active status, correctly honoring pagination options. All result data
 * is validated against test setup for data integrity and business rule enforcement.
 *
 * Steps:
 * 1. Create at least two members (with different join dates and statuses if possible).
 * 2. Promote both members to moderators on distinct promoted_at datetimes.
 * 3. Query the moderators list filtered by both member IDs and 'active' status (is_active = true).
 *    Confirm that only these two appear and have correct member linkage/promotion times.
 * 4. Test promoted_from and promoted_to filtering to further restrict which moderator(s) appear.
 * 5. Test pagination - since IRequest doesn't expose explicit page/limit, validate both expected moderators return.
 */
export async function test_api_discussionboard_test_list_moderators_with_valid_filters_and_pagination(
  connection: api.IConnection,
) {
  // 1. Create first member
  const member1 = await api.functional.discussionboard.actors.members.post(connection, {
    body: {
      joined_at: new Date(Date.now() - 1000 * 60 * 60 * 24).toISOString(), // yesterday
      status: "active",
    },
  });
  typia.assert(member1);

  // 2. Create second member
  const member2 = await api.functional.discussionboard.actors.members.post(connection, {
    body: {
      joined_at: new Date().toISOString(), // now
      status: "active",
    },
  });
  typia.assert(member2);

  // 3. Promote both members to moderator with distinct promoted_at
  const promoted1 = await api.functional.discussionboard.actors.moderators.post(connection, {
    body: {
      discussionboard_member_id: member1.id,
      promoted_at: new Date(Date.now() - 1000 * 60 * 60).toISOString(), // 1 hour ago
    },
  });
  typia.assert(promoted1);

  const promoted2 = await api.functional.discussionboard.actors.moderators.post(connection, {
    body: {
      discussionboard_member_id: member2.id,
      promoted_at: new Date().toISOString(), // now
    },
  });
  typia.assert(promoted2);

  // 4. Query all active moderators by member_id filter (member1)
  const listByMember1 = await api.functional.discussionboard.actors.moderators.patch(connection, {
    body: {
      member_id: member1.id,
      is_active: true,
    },
  });
  typia.assert(listByMember1);
  TestValidator.equals("finds only correct moderator for member1 and active")(listByMember1.data.length)(1);
  TestValidator.equals("correct moderator returned for member1")(listByMember1.data[0].discussionboard_member_id)(member1.id);

  // 5. Query active moderators with no member_id filter (should get both)
  const listAllActive = await api.functional.discussionboard.actors.moderators.patch(connection, {
    body: {
      is_active: true,
    },
  });
  typia.assert(listAllActive);
  const returnedIds = listAllActive.data.map((x) => x.discussionboard_member_id);
  TestValidator.predicate("both member1 and member2 are returned")(returnedIds.includes(member1.id) && returnedIds.includes(member2.id));

  // 6. Test promoted_from filter (after member1's promotion, only member2)
  const listAfter1 = await api.functional.discussionboard.actors.moderators.patch(connection, {
    body: {
      is_active: true,
      promoted_from: promoted2.promoted_at,
    },
  });
  typia.assert(listAfter1);
  TestValidator.equals("only member2 returned for promoted_from")(listAfter1.data.length)(1);
  TestValidator.equals("member2 returned for promoted_from")(listAfter1.data[0].discussionboard_member_id)(member2.id);

  // 7. Pagination: since IRequest doesn't have explicit page/limit, validate both expected moderators in full list
  TestValidator.equals("pagination returns both moderators")(listAllActive.data.map((m) => m.discussionboard_member_id).sort())([
    member1.id,
    member2.id,
  ].sort());
}

