import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * 시스템 설정 목록 조회 권한 통제 테스트 (비관리자 접근 차단)
 *
 * - 목적: 관리자 권한이 없는 일반 사용자가 시스템 설정 목록을 조회하려 할 때 접근이 차단되는지 확인한다.
 * - 배경: 시스템 전체 설정(discussionboard_settings)은 오직 관리자만 접근, 검색, 조회할 수 있어야 하며, 인증 상태이거나 비관리자 계정으로 접근 시에는 반드시 권한 오류(Forbidden 또는 Permission Denied)가 발생해야 한다.
 * - 상세 절차:
 *   1. 별도의 인증/권한 상승 없이 임의(비관리자) 연결 객체(connection)로 시스템 설정 목록 조회 API를 PATCH로 요청한다.
 *      - body는 랜덤하게 구성한다(검색어/필터/페이징 등은 랜덤, 본질은 권한 체크).
 *   2. Forbidden/Permission Denied와 같은 권한 거부 런타임 에러가 발생하는지 TestValidator.error()로 검증한다.
 * - 기대 결과: 권한이 없는 사용자는 절대 시스템 설정 목록을 조회할 수 없으며, 적합한 권한 오류가 발생해야 한다. 잘못된 인증/권한 상태에서는 목록 데이터가 절대 반환되어선 안 된다.
 */
export async function test_api_discussionboard_test_list_settings_without_permission_should_fail(connection: api.IConnection) {
  // 1. 비관리자/권한없는 상태에서 시스템 설정 목록 PATCH 수행 → 권한 에러 발생 검증
  await TestValidator.error("Should throw forbidden when non-admin tries to list system settings")(
    async () => {
      await api.functional.discussionboard.systematic.settings.patch(connection, {
        body: typia.random<IDiscussionboardSetting.IRequest>(),
      });
    }
  );
}

