import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMembers } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMembers";
import type { IDiscussionboardThreads } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardThreads";
import type { IDiscussionboardPosts } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardPosts";
import type { IDiscussionboardPostDislike } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardPostDislike";
import type { IPageIDiscussionboardPostDislike } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionboardPostDislike";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * 다양한 필터, 페이지네이션, 권한 제약을 테스트하는 post dislikes 조회 E2E.
 *
 * - 여러 멤버와 여러 게시글을 사전 생성하고,
 * - 여러 멤버들이 다양한 포스트에 dislike를 남긴다.
 * - 이후 PATCH(postDislikes) 엔드포인트로
 *   · post id, member id, 날짜 범위, 페이지/limit 등 다양한 필터로 검색/검증
 * - 응답 데이터의 정합성과 필터링 반영 여부, 기본 정렬, 페이지네이션 동작, 
 *   (권한별 민감정보 노출 제한 또는 오류 케이스는 실제 상황에 따라 skip 또는 error 테스트 가능)
 *
 * 1. 멤버 3명 생성 (A/B/C)
 * 2. Thread 2개, Post 3개 생성 (멤버 소유 분산)
 * 3. 여러 멤버가 여러 포스트 dislike
 * 4. PATCH(postDislikes)로
 *    - 포스트 id로 필터
 *    - 멤버 id로 필터
 *    - created_at 범위
 *    - 페이지네이션/limit
 * 5. (옵션) 비권한자 접근 제한 또는 정보 제한 테스트
 */
export async function test_api_discussionboard_test_list_post_dislikes_with_various_filters_and_pagination(
  connection: api.IConnection,
) {
  // 1. 멤버 생성 (A/B/C)
  const now = new Date();
  const members = await Promise.all([
    api.functional.discussionboard.actors.members.post(connection, {
      body: {
        joined_at: now.toISOString(),
        status: "active",
      },
    }),
    api.functional.discussionboard.actors.members.post(connection, {
      body: {
        joined_at: now.toISOString(),
        status: "active",
      },
    }),
    api.functional.discussionboard.actors.members.post(connection, {
      body: {
        joined_at: now.toISOString(),
        status: "active",
      },
    }),
  ]);
  typia.assert(members[0]);
  typia.assert(members[1]);
  typia.assert(members[2]);

  // 2. Thread 2개, Post 3개 생성
  const boardId = typia.random<string & tags.Format<"uuid">>();
  const threads = await Promise.all([
    api.functional.discussionboard.threads.threads.post(connection, {
      body: {
        discussionboard_board_id: boardId,
        discussionboard_member_id: members[0].id,
        title: "Thread 1 by A",
        status: "open",
        created_at: now.toISOString(),
      },
    }),
    api.functional.discussionboard.threads.threads.post(connection, {
      body: {
        discussionboard_board_id: boardId,
        discussionboard_member_id: members[1].id,
        title: "Thread 2 by B",
        status: "open",
        created_at: now.toISOString(),
      },
    }),
  ]);
  typia.assert(threads[0]);
  typia.assert(threads[1]);

  const posts = await Promise.all([
    api.functional.discussionboard.threads.posts.post(connection, {
      body: {
        discussionboard_thread_id: threads[0].id,
        discussionboard_member_id: members[0].id,
        body: "Post 1 in Thread 1 (A)",
        created_at: now.toISOString(),
      },
    }),
    api.functional.discussionboard.threads.posts.post(connection, {
      body: {
        discussionboard_thread_id: threads[0].id,
        discussionboard_member_id: members[0].id,
        body: "Post 2 in Thread 1 (A)",
        created_at: now.toISOString(),
      },
    }),
    api.functional.discussionboard.threads.posts.post(connection, {
      body: {
        discussionboard_thread_id: threads[1].id,
        discussionboard_member_id: members[1].id,
        body: "Post 3 in Thread 2 (B)",
        created_at: now.toISOString(),
      },
    }),
  ]);
  typia.assert(posts[0]);
  typia.assert(posts[1]);
  typia.assert(posts[2]);

  // 3. 여러 멤버가 여러 포스트 dislike 생성
  const dislikes = [
    await api.functional.discussionboard.interactions.postDislikes.post(connection, {
      body: {
        discussionboard_post_id: posts[0].id,
        discussionboard_member_id: members[0].id,
      },
    }),
    await api.functional.discussionboard.interactions.postDislikes.post(connection, {
      body: {
        discussionboard_post_id: posts[1].id,
        discussionboard_member_id: members[1].id,
      },
    }),
    await api.functional.discussionboard.interactions.postDislikes.post(connection, {
      body: {
        discussionboard_post_id: posts[0].id,
        discussionboard_member_id: members[2].id,
      },
    }),
    await api.functional.discussionboard.interactions.postDislikes.post(connection, {
      body: {
        discussionboard_post_id: posts[2].id,
        discussionboard_member_id: members[2].id,
      },
    }),
  ];
  dislikes.forEach((d) => typia.assert(d));

  // 4. PATCH - 포스트 id로 필터링
  const resByPost = await api.functional.discussionboard.interactions.postDislikes.patch(connection, {
    body: { discussionboard_post_id: posts[0].id },
  });
  typia.assert(resByPost);
  TestValidator.predicate("post 0 dislikes만 포함 여부")(
    resByPost.data.every((d) => d.discussionboard_post_id === posts[0].id)
  );

  // PATCH - 멤버 id로 필터링
  const resByMember = await api.functional.discussionboard.interactions.postDislikes.patch(connection, {
    body: { discussionboard_member_id: members[2].id },
  });
  typia.assert(resByMember);
  TestValidator.predicate("member 2 dislikes만 포함 여부")(
    resByMember.data.every((d) => d.discussionboard_member_id === members[2].id)
  );

  // PATCH - 날짜(from, to) 범위 (now시점만 모두 포함)
  const isoNow = now.toISOString();
  const resByDate = await api.functional.discussionboard.interactions.postDislikes.patch(connection, {
    body: {
      from_created_at: isoNow,
      to_created_at: isoNow,
    },
  });
  typia.assert(resByDate);
  TestValidator.predicate("created_at=now만 filter")(
    resByDate.data.every((d) => d.created_at === isoNow)
  );

  // PATCH - 페이지네이션(페이지/limit)
  const resPage1 = await api.functional.discussionboard.interactions.postDislikes.patch(connection, {
    body: { limit: 2, page: 1 },
  });
  typia.assert(resPage1);
  TestValidator.equals("1페이지, 2limit 길이 확인")(resPage1.data.length)(2);
  TestValidator.equals("1페이지 current 필드 확인")(resPage1.pagination.current)(1);

  const resPage2 = await api.functional.discussionboard.interactions.postDislikes.patch(connection, {
    body: { limit: 2, page: 2 },
  });
  typia.assert(resPage2);
  TestValidator.equals("2페이지, 2limit 길이 확인")(resPage2.data.length)(2);
  TestValidator.equals("2페이지 current 필드 확인")(resPage2.pagination.current)(2);

  // 5. (옵션) 권한 없는 일반/비권한자 접근 제한 시나리오 (API 지원시)
  // 실제로 정보 제한/예외 발생 시 TestValidator.error 등으로 검증 가능
}

