/**
 * Validate successful creation of a post dislike and duplicate prevention.
 *
 * This test simulates a member who dislikes a post for the first time, then attempts to dislike the same post again.
 * The first action should succeed and the API should return a valid dislike entity.
 * The second action should be rejected due to the unique constraint that a member cannot dislike the same post twice.
 *
 * Test Steps:
 * 1. Register a member (the actor giving the dislike).
 * 2. Create a dummy thread (as post container).
 * 3. Create a post in that thread (target for the dislike).
 * 4. Have the member issue a dislike (should succeed).
 * 5. Attempt to dislike the same post again with this member (should fail due to uniqueness rule).
 */
export async function test_api_discussionboard_test_create_post_dislike_successful_and_duplicate_prevention(
  connection: api.IConnection,
) {
  // 1. Register the member who will dislike the post
  const member = await api.functional.discussionboard.actors.members.post(connection, {
    body: {
      joined_at: new Date().toISOString(),
      status: "active",
    },
  });
  typia.assert(member);

  // 2. Create a dummy thread as context for the post
  const thread = await api.functional.discussionboard.threads.threads.post(connection, {
    body: {
      discussionboard_board_id: typia.random<string & tags.Format<"uuid">>(),
      discussionboard_member_id: member.id,
      title: RandomGenerator.paragraph()(2),
      description: RandomGenerator.paragraph()(4),
      status: "open",
      created_at: new Date().toISOString(),
    },
  });
  typia.assert(thread);

  // 3. Create a post in the dummy thread
  const post = await api.functional.discussionboard.threads.posts.post(connection, {
    body: {
      discussionboard_thread_id: thread.id,
      discussionboard_member_id: member.id,
      body: RandomGenerator.content()(1)(),
      created_at: new Date().toISOString(),
    },
  });
  typia.assert(post);

  // 4. Member expresses initial dislike (should succeed)
  const dislike = await api.functional.discussionboard.interactions.postDislikes.post(connection, {
    body: {
      discussionboard_post_id: post.id,
      discussionboard_member_id: member.id,
    },
  });
  typia.assert(dislike);
  TestValidator.equals("member ID")(dislike.discussionboard_member_id)(member.id);
  TestValidator.equals("post ID")(dislike.discussionboard_post_id)(post.id);

  // 5. Attempt to dislike the same post again (should fail because of unique constraint)
  await TestValidator.error("duplicate dislike rejected")(
    async () => {
      await api.functional.discussionboard.interactions.postDislikes.post(connection, {
        body: {
          discussionboard_post_id: post.id,
          discussionboard_member_id: member.id,
        },
      });
    },
  );
}

