import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMembers } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMembers";
import type { IDiscussionBoardMemberAuthentication } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMemberAuthentication";

/**
 * Validate the deletion of a member authentication record (credential) by unique ID.
 *
 * This test covers multiple business scenarios:
 *
 * 1. Successfully soft-deleting an authentication record as its owner.
 * 2. Ensuring an error is returned when deleting as a different user with insufficient privileges.
 * 3. Using a non-existent authentication record ID returns an appropriate not found error.
 *
 * Pre-requisites:
 * - A member must be created for ownership and privilege testing.
 * - At least one authentication record must be created against the member created above.
 *
 * Steps:
 * 1. Register a member (obtain member_id)
 * 2. Register an authentication method with that member_id (obtain auth_id)
 * 3. Delete the authentication as owner (should succeed, audit log implied)
 * 4. Attempt to delete again with the same ID (should fail, not found)
 * 5. Register a second member and authentication (auth_id2, different member)
 * 6. Try to delete auth_id2 as the original member (should fail, insufficient privileges)
 * 7. Try deleting random (non-existent) auth_id (should fail, not found)
 *
 * Each step involving deletion must validate response for compliance with the IDeleteResult schema and check for appropriate success or error state.
 */
export async function test_api_discussionboard_test_delete_member_authentication_success_and_permission_denied(
  connection: api.IConnection,
) {
  // 1. Register member #1
  const member1 = await api.functional.discussionboard.actors.members.post(connection, {
    body: {
      joined_at: new Date().toISOString(),
      status: "active"
    } satisfies IDiscussionboardMembers.ICreate,
  });
  typia.assert(member1);

  // 2. Register authentication for member #1
  const auth1 = await api.functional.discussionboard.actors.memberAuthentications.post(connection, {
    body: {
      discussionboard_member_id: member1.id,
      provider: "local",
      provider_identifier: RandomGenerator.alphaNumeric(10),
      password_hash: RandomGenerator.alphaNumeric(40)
    } satisfies IDiscussionBoardMemberAuthentication.ICreate,
  });
  typia.assert(auth1);

