import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardChannel } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardChannel";
import type { IDiscussionboardCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardCategory";
import type { IPageIDiscussionboardCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionboardCategory";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validates paginated, filtered retrieval of discussion board categories.
 *
 * 이 테스트는 다음을 검증합니다:
 * - 복수의 channel 및 각 카테고리(상태·계층) 데이터를 세팅
 * - channel별, enabled 여부, parent_id, 이름/코드/설명 부분검색, pagination 등 다양한 조합 필터에 대해 정상적으로 결과 반환 및 정확한 카운트/페이지네이션이 작동하는지
 * - 삭제(soft-delete)는 delete 엔드포인트가 없으므로 미검증
 *
 * [구현 단계]
 * 1. channel 2개 생성
 * 2. 각 channel 하위로 enabled/disabled, parent-child(계층) 등 다양한 카테고리 생성
 * 3. 필터별(PATCH) 결과 검증:
 *   - discussionboard_channel_id
 *   - enabled
 *   - parent_id
 *   - search(부분검색)
 *   - limit, page(pagination)
 *   - (soft-delete, untested)
 */
export async function test_api_discussionboard_test_list_categories_with_various_filters_pagination(
  connection: api.IConnection,
) {
  // 1. 채널 2개 생성 (각각 고유 코드와 표시명)
  const channel1 = await api.functional.discussionboard.systematic.channels.post(connection, {
    body: {
      code: RandomGenerator.alphaNumeric(8),
      name: RandomGenerator.alphabets(10),
      enabled: true,
      description: RandomGenerator.paragraph()(),
    } satisfies IDiscussionboardChannel.ICreate,
  });
  typia.assert(channel1);

  const channel2 = await api.functional.discussionboard.systematic.channels.post(connection, {
    body: {
      code: RandomGenerator.alphaNumeric(8),
      name: RandomGenerator.alphabets(10),
      enabled: false,
      description: RandomGenerator.paragraph()(),
    } satisfies IDiscussionboardChannel.ICreate,
  });
  typia.assert(channel2);

  // 2. channel1: enabled 루트, disabled 루트, enabled 자식
  const cat1_root_enabled = await api.functional.discussionboard.systematic.categories.post(connection, {
    body: {
      discussionboard_channel_id: channel1.id,
      code: RandomGenerator.alphaNumeric(6),
      name: "Root Enabled 1",
      enabled: true,
      description: "Root enabled in channel1"
    } satisfies IDiscussionboardCategory.ICreate,
  });
  typia.assert(cat1_root_enabled);
  const cat1_root_disabled = await api.functional.discussionboard.systematic.categories.post(connection, {
    body: {
      discussionboard_channel_id: channel1.id,
      code: RandomGenerator.alphaNumeric(6),
      name: "Root Disabled 1",
      enabled: false,
      description: "Root disabled in channel1"
    } satisfies IDiscussionboardCategory.ICreate,
  });
  typia.assert(cat1_root_disabled);
  const cat1_child_enabled = await api.functional.discussionboard.systematic.categories.post(connection, {
    body: {
      discussionboard_channel_id: channel1.id,
      parent_id: cat1_root_enabled.id,
      code: RandomGenerator.alphaNumeric(6),
      name: "Child Enabled 1",
      enabled: true,
      description: "Child of root enabled in channel1"
    } satisfies IDiscussionboardCategory.ICreate,
  });
  typia.assert(cat1_child_enabled);
  // 2-b. channel2: enabled 루트, disabled 자식
  const cat2_root_enabled = await api.functional.discussionboard.systematic.categories.post(connection, {
    body: {
      discussionboard_channel_id: channel2.id,
      code: RandomGenerator.alphaNumeric(6),
      name: "Root Enabled 2",
      enabled: true,
      description: "Root enabled in channel2"
    } satisfies IDiscussionboardCategory.ICreate,
  });
  typia.assert(cat2_root_enabled);
  const cat2_child_disabled = await api.functional.discussionboard.systematic.categories.post(connection, {
    body: {
      discussionboard_channel_id: channel2.id,
      parent_id: cat2_root_enabled.id,
      code: RandomGenerator.alphaNumeric(6),
      name: "Child Disabled 2",
      enabled: false,
      description: "Disabled child in channel2"
    } satisfies IDiscussionboardCategory.ICreate,
  });
  typia.assert(cat2_child_disabled);

  // 3. 카테고리 목록 다양한 조합별 PATCH 조회 및 검증
  // a. discussionboard_channel_id 필터
  const page_ch1 = await api.functional.discussionboard.systematic.categories.patch(connection, {
    body: { discussionboard_channel_id: channel1.id } satisfies IDiscussionboardCategory.IRequest
  });
  typia.assert(page_ch1);
  TestValidator.predicate("all channel1 only")(page_ch1.data.every(x => x.discussionboard_channel_id === channel1.id));

  // b. enabled==true 필터
  const page_enabled = await api.functional.discussionboard.systematic.categories.patch(connection, {
    body: { enabled: true } satisfies IDiscussionboardCategory.IRequest
  });
  typia.assert(page_enabled);
  TestValidator.predicate("all enabled")(page_enabled.data.every(x => x.enabled === true));

  // c. parent_id로 자식만 조회
  const page_parent = await api.functional.discussionboard.systematic.categories.patch(connection, {
    body: { parent_id: cat1_root_enabled.id } satisfies IDiscussionboardCategory.IRequest
  });
  typia.assert(page_parent);
  TestValidator.predicate("all children of cat1_root_enabled")(page_parent.data.every(x => x.parent_id === cat1_root_enabled.id));

  // d. search(부분검색: "Root Enabled")
  const page_search = await api.functional.discussionboard.systematic.categories.patch(connection, {
    body: { search: "Root Enabled" } satisfies IDiscussionboardCategory.IRequest
  });
  typia.assert(page_search);
  TestValidator.predicate("search matched")(page_search.data.every(x => (x.name + x.code + (x.description ?? "")).includes("Root Enabled")));

  // e. pagination: per page 제한
  const page_limited = await api.functional.discussionboard.systematic.categories.patch(connection, {
    body: { limit: 2, page: 1 } satisfies IDiscussionboardCategory.IRequest
  });
  typia.assert(page_limited);
  TestValidator.equals("limit")(page_limited.pagination.limit)(2);
  TestValidator.equals("current page")(page_limited.pagination.current)(1);
  TestValidator.predicate("maximum 2 items")(page_limited.data.length <= 2);

  // f. 삭제(soft-delete): delete 엔드포인트 없음, skip
}

