/**
 * Validate successful and error responses of fetching category details by ID.
 *
 * Ensures that after creating a discussion board category, it can be successfully retrieved by ID, and that attempts to fetch a non-existent category result in the correct error. Soft-deleted behavior is not tested here due to lack of delete API.
 *
 * Process:
 * 1. Create a new discussionboard category and capture its ID.
 * 2. Fetch the created category by ID; check all DTO fields match input/expectations.
 * 3. Fetch a random (non-existent) UUID; validate a 404 or error is thrown as per not found policy.
 */
export async function test_api_discussionboard_systematic_categories_getById(
  connection: api.IConnection,
) {
  // Step 1: Create a new category for testing
  const createInput: IDiscussionboardCategory.ICreate = {
    discussionboard_channel_id: typia.random<string & tags.Format<"uuid">>(),
    code: RandomGenerator.alphabets(8),
    name: RandomGenerator.alphabets(12),
    enabled: true,
    description: RandomGenerator.paragraph()(),
    parent_id: null,
  };

  const created: IDiscussionboardCategory = await api.functional.discussionboard.systematic.categories.post(
    connection,
    { body: createInput },
  );
  typia.assert(created);

  // Step 2: Retrieve category by ID and verify all fields
  const fetched: IDiscussionboardCategory = await api.functional.discussionboard.systematic.categories.getById(
    connection,
    { id: created.id },
  );
  typia.assert(fetched);

  // Field integrity checks
  TestValidator.equals("id matches")(fetched.id)(created.id);
  TestValidator.predicate("id is valid uuid")(typia.is<string & tags.Format<"uuid">>(fetched.id));
  TestValidator.equals("discussionboard_channel_id matches")(fetched.discussionboard_channel_id)(createInput.discussionboard_channel_id);
  TestValidator.predicate("discussionboard_channel_id is uuid")(typia.is<string & tags.Format<"uuid">>(fetched.discussionboard_channel_id));
  TestValidator.equals("code matches")(fetched.code)(createInput.code);
  TestValidator.equals("name matches")(fetched.name)(createInput.name);
  TestValidator.equals("description matches")(fetched.description)(createInput.description);
  TestValidator.equals("enabled matches")(fetched.enabled)(createInput.enabled);
  TestValidator.equals("parent_id matches")(fetched.parent_id)(createInput.parent_id);
  // Date-time fields checks
  TestValidator.predicate("created_at present, valid ISO format")(!!fetched.created_at && typia.is<string & tags.Format<"date-time">>(fetched.created_at));
  TestValidator.predicate("updated_at present, valid ISO format")(!!fetched.updated_at && typia.is<string & tags.Format<"date-time">>(fetched.updated_at));
  // deleted_at should be null or undefined for newly created
  TestValidator.predicate("deleted_at is null or undefined")(fetched.deleted_at === null || fetched.deleted_at === undefined);

  // Step 3: Try fetching a non-existent category (random uuid)
  const randomUuid = typia.random<string & tags.Format<"uuid">>();
  TestValidator.error("fetching non-existent category throws error")(() =>
    api.functional.discussionboard.systematic.categories.getById(
      connection,
      { id: randomUuid },
    )
  );
  // Step 4: (Soft-deleted scenario omitted due to absence of delete API)
}

