/**
 * Test soft deletion of a discussion board category and verify cascade effects.
 *
 * This test covers the following workflow:
 * 1. Create a channel (parent structure for categories).
 * 2. Create a category under the channel with valid required fields.
 * 3. Delete (soft-delete) the category using the provided API.
 * 4. Confirm the result object contains the right ID and recent deletion timestamp.
 * 5. (If GET endpoint existed) – Would attempt to fetch the deleted category to verify its state or not-found – but omitted due to SDK limitations.
 * 6. (If LIST endpoint existed) – Would verify deleted category is excluded from subsequent listings – but omitted due to SDK limitations.
 *
 * Per implementation constraints, only the create and soft-delete steps are exercised in this test case. Validation relies on the response structure of the soft-delete API.
 */
export async function test_api_discussionboard_test_soft_delete_category_success_and_cascade(
  connection: api.IConnection,
) {
  // 1. Create a channel (required for category creation)
  const channelCode = RandomGenerator.alphaNumeric(8);
  const channelInput: IDiscussionboardChannel.ICreate = {
    code: channelCode,
    name: RandomGenerator.name(),
    description: RandomGenerator.paragraph()(),
    enabled: true,
  };
  const channel = await api.functional.discussionboard.systematic.channels.post(connection, { body: channelInput });
  typia.assert(channel);

  // 2. Create a category under the created channel
  const categoryCode = RandomGenerator.alphaNumeric(8);
  const categoryInput: IDiscussionboardCategory.ICreate = {
    discussionboard_channel_id: channel.id,
    code: categoryCode,
    name: RandomGenerator.name(),
    description: RandomGenerator.paragraph()(),
    enabled: true,
  };
  const category = await api.functional.discussionboard.systematic.categories.post(
    connection,
    { body: categoryInput },
