  typia.assert(removeResult);

  // 4. Validate the soft-delete response
  TestValidator.equals("ID matches on soft-delete result")(removeResult.id)(category.id);
  TestValidator.predicate("Deleted_at timestamp is set")(
    typeof removeResult.deleted_at === "string" && removeResult.deleted_at.length > 0,
  );

  // Note: Further cascade checks would require board/topic APIs not provided.
}

