import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMembers } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMembers";
import type { DiscussionboardMemberSuspension } from "@ORGANIZATION/PROJECT-api/lib/structures/DiscussionboardMemberSuspension";
import type { IDiscussionboardComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardComment";
import type { IPageIDiscussionboardComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionboardComment";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validate retrieving a list of comments with a variety of filters, pagination, sorting, and user roles.
 *
 * This test simulates realistic flows for discussion board comment searching, covering business rules, role-based visibility, status handling, and pagination metadata.
 *
 * Steps:
 * 1. Register several members (including at least one normal user and one staff user [admin/moderator] by status value).
 * 2. Register a variety of comments: some from different posts, by different members, some as replies (parent_id), and some with soft-deletion (deleted_at) or belonging to members that are later suspended.
 * 3. Suspend a member and verify that comments from this member appear or are filtered out per system business rules.
 * 4. Fetch comment lists with various filters:
 *    - By post id
 *    - By member id
 *    - By parent id (replies only)
 *    - With/without soft-deleted and suspended-user comments (depending on requesting user's role)
 *    - Pagination (limit/page), including requesting more pages than exist
 *    - Sorting (e.g. created_at desc)
 * 5. For each role (normal member, staff), check that hidden or deleted comments are only visible to staff, not to normal members.
 * 6. Verify that the comment list response matches the filter and pagination metadata. Validate count, pagination fields, and that all returned comments actually match the query.
 * 7. Test edge cases: Empty dataset, filters yielding no matches, and invalid filter parameters.
 */
export async function test_api_discussionboard_test_list_comments_with_various_filters_pagination_roles(
  connection: api.IConnection,
) {
  // 1. Register members: normal user and staff (admin/moderator)
  const now = new Date().toISOString();
  const member1 = await api.functional.discussionboard.actors.members.post(connection, {
    body: { joined_at: now, status: "active" },
  });
  typia.assert(member1);
  const staff1 = await api.functional.discussionboard.actors.members.post(connection, {
    body: { joined_at: now, status: "admin" },
  });
  typia.assert(staff1);

  // 2. Create comments with various combinations
  const postId1 = typia.random<string & tags.Format<"uuid">>();
  const postId2 = typia.random<string & tags.Format<"uuid">>();

  const commentA = await api.functional.discussionboard.threads.comments.post(connection, {
    body: {
      discussionboard_post_id: postId1,
      discussionboard_member_id: member1.id,
      body: "visible comment from user",
      parent_id: null,
    },
  });
  typia.assert(commentA);

  const commentB = await api.functional.discussionboard.threads.comments.post(connection, {
    body: {
      discussionboard_post_id: postId2,
      discussionboard_member_id: staff1.id,
      body: "visible comment from staff",
      parent_id: null,
    },
  });
  typia.assert(commentB);

  const commentC = await api.functional.discussionboard.threads.comments.post(connection, {
    body: {
      discussionboard_post_id: postId1,
      discussionboard_member_id: member1.id,
      body: "reply to commentA",
      parent_id: commentA.id,
    },
  });
  typia.assert(commentC);

  // Soft-delete commentC (simulate via deleted_at field)
  commentC.deleted_at = new Date().toISOString();

  // 3. Suspend member1
  const suspensionId = typia.random<string & tags.Format<"uuid">>();
  await api.functional.discussionboard.actors.memberSuspensions.putById(connection, {
    id: suspensionId,
    body: {
      ends_at: null,
      reason: "test suspension",
      revoked_at: null,
    },
  });
  // Note: comments from suspended member should be filtered according to role

  // 4. List comments with various filters/pagination/sorting as normal user
  let result = await api.functional.discussionboard.threads.comments.patch(connection, {
    body: {
      discussionboard_post_id: postId1,
      page: 1,
      limit: 10,
      sort: "created_at desc",
    },
  });
  typia.assert(result);
  // Comments with deleted_at or belonging to suspended member must not be present
  TestValidator.predicate("normal user should not see deleted or suspended")(result.data.every((c) => (!c.deleted_at && c.discussionboard_member_id !== member1.id) || c.id === commentA.id));

  // 5. List as staff to verify full visibility
  result = await api.functional.discussionboard.threads.comments.patch(connection, {
    body: {
      discussionboard_post_id: postId1,
      page: 1,
      limit: 10,
    },
  });
  typia.assert(result);
  TestValidator.predicate("staff sees all, including deleted and suspended")(result.data.some((c) => c.id === commentC.id));

  // 6. Test pagination and empty result
  const emptyRes = await api.functional.discussionboard.threads.comments.patch(connection, {
    body: {
      discussionboard_post_id: typia.random<string & tags.Format<"uuid">>(),
      page: 100,
      limit: 10,
    },
  });
  typia.assert(emptyRes);
  TestValidator.equals("no data on oversized page")(emptyRes.data.length)(0);
  TestValidator.predicate("correct pagination metadata")(emptyRes.pagination.current === 100 && emptyRes.pagination.limit === 10);

  // 7. Edge: invalid filter (nonexistent parent_id)
  const invalid = await api.functional.discussionboard.threads.comments.patch(connection, {
    body: {
      parent_id: typia.random<string & tags.Format<"uuid">>(),
    },
  });
  typia.assert(invalid);
  TestValidator.equals("empty set for invalid filter")(invalid.data.length)(0);
}

