import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardComment";

/**
 * Validate discussionboard comment detail view and permission constraints.
 *
 * Test covers:
 * 1. Creating a comment as the original author
 * 2. Retrieving it as the author
 * 3. Attempting retrieval as another member (unrelated user)
 * 4. Simulating soft deletion and validating access rules:
 *    - Author should NOT get the comment detail (expects error)
 *    - 'Moderator' or admin would be able to access soft-deleted, but API to create those is not provided here, so step omitted
 * 5. Attempt to fetch a comment with a random UUID (expect 404)
 * 6. Attempt access to a deeply nested comment (by making a reply, then fetching using its id)
 * 7. Edge case: simulate a reply with parent_id to a deleted/non-existent comment (where feasible)
 */
export async function test_api_discussionboard_test_get_comment_detail_existing_and_nonexistent_permissions(
  connection: api.IConnection,
) {
  // Step 1: Create two distinct members (author and unrelated)
  // Simulating by random member IDs; in practice, account/session endpoints needed
  const authorId = typia.random<string & tags.Format<"uuid">>();
  const unrelatedId = typia.random<string & tags.Format<"uuid">>();
  const postId = typia.random<string & tags.Format<"uuid">>();

  // Step 2: Author posts a new comment
  const comment = await api.functional.discussionboard.threads.comments.post(
    connection,
    {
      body: {
        discussionboard_post_id: postId,
        discussionboard_member_id: authorId,
        body: "This is a test comment.",
        parent_id: null,
      } satisfies IDiscussionboardComment.ICreate,
    },
  );
  typia.assert(comment);

  // Step 3: Fetch the comment as author (should succeed, fields present)
  const fetchedByAuthor = await api.functional.discussionboard.threads.comments.getById(
    connection,
    { id: comment.id },
  );
  typia.assert(fetchedByAuthor);
  TestValidator.equals("comment detail as author")(fetchedByAuthor.id)(comment.id);
  TestValidator.equals("comment body matches")(fetchedByAuthor.body)(comment.body);
  TestValidator.equals("meta: not deleted")(fetchedByAuthor.deleted_at)(null);

  // Step 4: Fetch as unrelated member (simulate via separate member ID)
  // (since auth context interface not modeled, just pass same API)
  const fetchedByUnrelated = await api.functional.discussionboard.threads.comments.getById(
    connection,
    { id: comment.id },
  );
  typia.assert(fetchedByUnrelated);
  TestValidator.equals("comment visible to unrelated")(fetchedByUnrelated.id)(comment.id);

  // Step 5: Soft delete the comment (as author)
  const erased = await api.functional.discussionboard.threads.comments.eraseById(
    connection,
    { id: comment.id },
  );
  typia.assert(erased);
  TestValidator.predicate("should be soft-deleted")(
    !!erased.deleted_at && typeof erased.deleted_at === "string",
  );

  // Step 6: Try retrieving as author again (simulated: API returns the comment, will verify deleted_at is not null)
  const afterDelete = await api.functional.discussionboard.threads.comments.getById(
    connection,
    { id: comment.id },
  );
  typia.assert(afterDelete);
  TestValidator.equals("deleted flag visible")(!!afterDelete.deleted_at)(true);

  // Step 7: Attempt fetching random (non-existent) comment (expect error)
  const nonExistentId = typia.random<string & tags.Format<"uuid">>();
  await TestValidator.error("404 on non-existent")(() =>
    api.functional.discussionboard.threads.comments.getById(
      connection,
      { id: nonExistentId },
    ),
  );

  // Step 8: Deeply nested reply (parent_id set)
  const childComment = await api.functional.discussionboard.threads.comments.post(
    connection,
    {
      body: {
        discussionboard_post_id: postId,
        discussionboard_member_id: authorId,
        body: "Nested reply level 1",
        parent_id: comment.id,
      },
    },
  );
  typia.assert(childComment);
  // Retrieve reply by id
  const childFetched = await api.functional.discussionboard.threads.comments.getById(
    connection,
    { id: childComment.id },
  );
  typia.assert(childFetched);
  TestValidator.equals("reply id matches")(childFetched.id)(childComment.id);
  TestValidator.equals("reply parent matches")(childFetched.parent_id)(comment.id);
  TestValidator.equals("reply not deleted")(childFetched.deleted_at)(null);

  // Step 9: Edge: reply to deleted comment
  // Soft delete parent
  await api.functional.discussionboard.threads.comments.eraseById(
    connection,
    { id: childComment.id },
  );
  // Try posting reply to now-deleted parent - business logic may disallow
  await TestValidator.error("create reply to deleted parent fails")(() =>
    api.functional.discussionboard.threads.comments.post(
      connection,
      {
        body: {
          discussionboard_post_id: postId,
          discussionboard_member_id: authorId,
          body: "Should not work",
          parent_id: childComment.id,
        },
      },
    ),
  );
}

