import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMembers } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMembers";
import type { IDiscussionboardComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardComment";

/**
 * Validate full workflow and permission logic for updating a board comment.
 *
 * This test verifies the following scenarios:
 *   1. Author can update their comment successfully (PUT by author)
 *   2. Non-author cannot update someone else's comment (permission denied)
 *   3. Update is forbidden after comment is deleted (soft-deleted)
 *   4. Update fails with empty body or invalid comment ID
 *
 * Skips staff/admin update and edit window expiration cases, as neither are supported in schema/API.
 * Relies only on DTO and API functions present. Throughout, asserts all major business and data invariants.
 *
 * Step-by-step process:
 * 1. Create author and non-author board members
 * 2. Author creates a discussion comment
 * 3. Author updates comment content successfully
 * 4. Non-author's update attempt fails
 * 5. Author deletes (soft-deletes) the comment
 * 6. Attempts to update deleted comment are rejected
 * 7. Attempts to update with empty body or invalid ID are rejected
 */
export async function test_api_discussionboard_threads_comments_test_update_comment_as_author_and_staff_handling_permissions_and_window(
  connection: api.IConnection,
) {
  // 1. Create author and non-author board members
  const author: IDiscussionboardMembers = await api.functional.discussionboard.actors.members.post(connection, {
    body: {
      joined_at: new Date().toISOString(),
      status: "active"
    }
  });
  typia.assert(author);
  const nonAuthor: IDiscussionboardMembers = await api.functional.discussionboard.actors.members.post(connection, {
    body: {
      joined_at: new Date().toISOString(),
      status: "active"
    }
  });
  typia.assert(nonAuthor);

  // 2. Author creates a discussion comment
  const comment: IDiscussionboardComment = await api.functional.discussionboard.threads.comments.post(connection, {
    body: {
      discussionboard_post_id: typia.random<string & tags.Format<"uuid">>(),
      discussionboard_member_id: author.id,
      body: "Original comment content"
    }
  });
  typia.assert(comment);

  // 3. Author updates the comment content successfully
  const updated: IDiscussionboardComment = await api.functional.discussionboard.threads.comments.putById(connection, {
    id: comment.id,
    body: {
      body: "Edited by author"
    }
  });
  typia.assert(updated);
  TestValidator.equals("comment id unchanged")(updated.id)(comment.id);
  TestValidator.equals("body updated")(updated.body)("Edited by author");
  TestValidator.predicate("updated_at after created_at")(new Date(updated.updated_at) > new Date(comment.created_at));

  // 4. Non-author cannot update (raises error)
  await TestValidator.error("non-author cannot update comment")(async () => {
    await api.functional.discussionboard.threads.comments.putById(connection, {
      id: comment.id,
      body: {
        body: "Malicious edit attempt"
      }
    });
  });

  // 5. Author deletes their comment (soft-delete)
  const deleted: IDiscussionboardComment = await api.functional.discussionboard.threads.comments.eraseById(connection, {
    id: comment.id
  });
  typia.assert(deleted);

  // 6. Cannot update a deleted comment
  await TestValidator.error("cannot update deleted comment")(async () => {
    await api.functional.discussionboard.threads.comments.putById(connection, {
      id: comment.id,
      body: {
        body: "Edit after delete"
      }
    });
  });

  // 7a. Attempt update with empty body fails
  await TestValidator.error("comment body cannot be empty")(async () => {
    await api.functional.discussionboard.threads.comments.putById(connection, {
      id: comment.id,
      body: {
        body: ""
      }
    });
  });

  // 7b. Attempt update to random (likely invalid) id fails
  await TestValidator.error("invalid id update fails")(async () => {
    await api.functional.discussionboard.threads.comments.putById(connection, {
      id: typia.random<string & tags.Format<"uuid">>(),
      body: {
        body: "Random id edit"
      }
    });
  });
}

