import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMembers } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMembers";
import type { IDiscussionboardPosts } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardPosts";
import type { IDiscussionboardPostLike } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardPostLike";
import type { IPageIDiscussionboardPostLike } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionboardPostLike";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validate paginated and filtered retrieval of post likes.
 *
 * This test ensures that listing of post likes supports correct filtering, pagination, and access control by simulating realistic board activity.
 *
 * 1. Create 3 member accounts with different join times and statuses (all initially 'active').
 * 2. Prepare 2 posts authored by different members (cross-member activity).
 * 3. Each member likes various posts:
 *    - Member 1 likes Post A and B
 *    - Member 2 likes Post A
 *    - Member 3 likes Post B
 * 4. Retrieve post likes with various filters:
 *    a. Filter by member 1 ID (should only return likes made by member 1)
 *    b. Filter by post B ID (should only return likes for Post B)
 *    c. Paginate likes with limit=2 (results for all likes, split by pages)
 * 5. Confirm each result set matches expectations for filtering, matches correct members/posts, and pagination meta is correct (current page, limit, total records, pages).
 * 6. Edge case: request a page and filter that returns no records (high page number, or filter on unmatched post/member ID) and ensure empty data with correct pagination meta.
 */
export async function test_api_discussionboard_test_list_post_likes_with_valid_filters_and_pagination(connection: api.IConnection) {
  // 1. Create multiple members
  const now = new Date();
  const members = await ArrayUtil.asyncRepeat(3)(async (i) =>
    await api.functional.discussionboard.actors.members.post(connection, {
      body: {
        joined_at: new Date(now.getTime() - i * 60000).toISOString(),
        status: "active",
      },
    }),
  );
  typia.assert(members);

  // 2. Create posts (each by different member)
  const posts = await ArrayUtil.asyncRepeat(2)(async (i) =>
    await api.functional.discussionboard.threads.posts.post(connection, {
      body: {
        discussionboard_thread_id: typia.random<string & tags.Format<"uuid">>(), // Simulate thread for isolation
        discussionboard_member_id: members[i].id,
        body: `Test post body ${i}`,
        created_at: new Date(now.getTime() + i * 1000).toISOString(),
      },
    }),
  );
  typia.assert(posts);

  // 3. Likes mapping:
  // Member 1 likes Post A & B
  // Member 2 likes Post A
  // Member 3 likes Post B
  const likeRecords: Array<{
    memberIdx: number;
    postIdx: number;
    like: Awaited<ReturnType<typeof api.functional.discussionboard.interactions.postLikes.post>>;
  }> = [];

  // Member 1 likes Post A (0) and B (1)
  likeRecords.push({
    memberIdx: 0,
    postIdx: 0,
    like: await api.functional.discussionboard.interactions.postLikes.post(connection, {
      body: { discussionboard_post_id: posts[0].id, discussionboard_member_id: members[0].id },
    }),
  });
  likeRecords.push({
    memberIdx: 0,
    postIdx: 1,
    like: await api.functional.discussionboard.interactions.postLikes.post(connection, {
      body: { discussionboard_post_id: posts[1].id, discussionboard_member_id: members[0].id },
    }),
  });

  // Member 2 likes Post A
  likeRecords.push({
    memberIdx: 1,
    postIdx: 0,
    like: await api.functional.discussionboard.interactions.postLikes.post(connection, {
      body: { discussionboard_post_id: posts[0].id, discussionboard_member_id: members[1].id },
    }),
  });

  // Member 3 likes Post B
  likeRecords.push({
    memberIdx: 2,
    postIdx: 1,
    like: await api.functional.discussionboard.interactions.postLikes.post(connection, {
      body: { discussionboard_post_id: posts[1].id, discussionboard_member_id: members[2].id },
    }),
  });
  typia.assert(likeRecords.map(x => x.like));

  // 4a. Filter likes by member 1 ID
  const likesByMember1 = await api.functional.discussionboard.interactions.postLikes.patch(connection, {
    body: { discussionboard_member_id: members[0].id },
  });
  typia.assert(likesByMember1);
  TestValidator.equals("member 1 likes count")(likesByMember1.data.length)(2);
  TestValidator.predicate("all member 1 likes")(likesByMember1.data.every(x => x.discussionboard_member_id === members[0].id));

  // 4b. Filter likes by post B ID
  const likesForPostB = await api.functional.discussionboard.interactions.postLikes.patch(connection, {
    body: { discussionboard_post_id: posts[1].id },
  });
  typia.assert(likesForPostB);
  TestValidator.equals("likes for post B")(likesForPostB.data.length)(2);
  TestValidator.predicate("all likes for post B")(likesForPostB.data.every(x => x.discussionboard_post_id === posts[1].id));

  // 4c. Paginate likes with limit=2 (unfiltered, page 1)
  const likesPage1 = await api.functional.discussionboard.interactions.postLikes.patch(connection, {
    body: { page: 1, limit: 2 },
  });
  typia.assert(likesPage1);
  TestValidator.equals("pagination: page 1")(likesPage1.pagination.current)(1);
  TestValidator.equals("pagination: limit")(likesPage1.pagination.limit)(2);
  TestValidator.equals("pagination: total records")(likesPage1.pagination.records)(4);
  TestValidator.predicate("max 2 records on page 1")(likesPage1.data.length <= 2);

  // 5. Edge case: query for a page with no records (page way beyond max; page 5 in this 4-record dataset)
  const likePageNone = await api.functional.discussionboard.interactions.postLikes.patch(connection, {
    body: { page: 5, limit: 2 },
  });
  typia.assert(likePageNone);
  TestValidator.equals("page with no records: count")(likePageNone.data.length)(0);
  TestValidator.equals("page with no records: correct page")(likePageNone.pagination.current)(5);
  TestValidator.equals("page with no records: limit")(likePageNone.pagination.limit)(2);
  TestValidator.equals("page with no records: records")(likePageNone.pagination.records)(4);
  TestValidator.predicate("empty page is actually empty")(likePageNone.data.length === 0);

  // 6. Edge case: filter for likes with impossible member/post id
  const likesNone = await api.functional.discussionboard.interactions.postLikes.patch(connection, {
    body: { discussionboard_member_id: typia.random<string & tags.Format<"uuid">>() },
  });
  typia.assert(likesNone);
  TestValidator.equals("empty result set")(likesNone.data.length)(0);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardPostLike } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardPostLike";
import type { IPageIDiscussionboardPostLike } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionboardPostLike";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Test filtering post likes by a non-existent member ID.
 *
 * This test verifies that when the API is queried for post likes filtered by a member UUID that does not exist in the system, the API correctly returns either an empty list (when filtering is allowed regardless of member existence), or—if access control is strict—a clear, well-documented error. This ensures access control integrity and robust response handling for analytics tools and dashboards that may attempt to filter by arbitrary members.
 *
 * Process:
 * 1. Generate a fresh, random UUID for use as a non-existent member ID.
 * 2. Send a patch request to /discussionboard/interactions/postLikes filtering for likes by that fake member ID.
 * 3. Assert that the API responds with a paginated object containing an empty list OR, if access control rejects such queries, that an appropriate error is returned.
 * 4. Validate response shape and handling according to business rules: no data exposure, correct pagination, no crash or unhandled error.
 */
export async function test_api_discussionboard_test_list_post_likes_access_control_for_nonexistent_member(
  connection: api.IConnection,
) {
  // Step 1: Generate a random, non-existent member UUID
  const fakeMemberId = typia.random<string & tags.Format<"uuid">>();

  // Step 2: Make the API call filtering for that fake member
  const output = await api.functional.discussionboard.interactions.postLikes.patch(connection, {
    body: {
      discussionboard_member_id: fakeMemberId,
    },
  });
  typia.assert(output);

  // Step 3: Assert that response data is empty (no likes for non-existent member)
  TestValidator.equals("data should be empty for nonexistent member")(output.data)([]);
}

