  typia.assert(post);

  // 3. 멤버가 게시글에 좋아요
  const postLike = await api.functional.discussionboard.interactions.postLikes.post(connection, {
    body: {
      discussionboard_post_id: post.id,
      discussionboard_member_id: member.id,
    },
  });
  typia.assert(postLike);

  // 4. ID로 상세조회
  const retrieved = await api.functional.discussionboard.interactions.postLikes.getById(connection, {
    id: postLike.id,
  });
  typia.assert(retrieved);

  // 5. 반환 값 검증
  TestValidator.equals("like id")(retrieved.id)(postLike.id);
  TestValidator.equals("post id")(retrieved.discussionboard_post_id)(post.id);
  TestValidator.equals("member id")(retrieved.discussionboard_member_id)(member.id);
  TestValidator.equals("생성시각<날짜시간> 일치")(
    retrieved.created_at.substring(0, 19)
  )(postLike.created_at.substring(0, 19));
}

