import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMembers } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMembers";
import type { IDiscussionboardPosts } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardPosts";
import type { IDiscussionboardPostLike } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardPostLike";

/**
 * Validate the successful creation of a like on a post by a registered member.
 *
 * This test simulates the typical flow where a new member joins, authors a new post, and then likes that post. It ensures that the system records the like correctly linking both the member and post IDs, that audit timestamps are properly generated, and that business constraints (such as a like not pre-existing) are enforced. Critical fields and foreign key relationships are validated for integrity.
 *
 * Steps:
 * 1. Register a discussion board member via the members API.
 * 2. Create a new post associated with that member and a thread ID.
 * 3. Have that member perform a like action on the newly created post.
 * 4. Validate that the like entity reflects the correct member and post IDs, timestamps, and uniqueness constraint.
 */
export async function test_api_discussionboard_interactions_postLikes_test_create_post_like_with_valid_member_and_post(
  connection: api.IConnection,
) {
  // 1. Register a discussion board member
  const member = await api.functional.discussionboard.actors.members.post(
    connection,
    {
      body: {
        joined_at: new Date().toISOString(),
        status: "active",
      } satisfies IDiscussionboardMembers.ICreate,
    },
  );
  typia.assert(member);

  // 2. Create a new post with a random thread and the new member as the author
  const post = await api.functional.discussionboard.threads.posts.post(
    connection,
    {
      body: {
        discussionboard_thread_id: typia.random<string & tags.Format<"uuid">>(),
        discussionboard_member_id: member.id,
        body: RandomGenerator.paragraph()(),
        created_at: new Date().toISOString(),
      } satisfies IDiscussionboardPosts.ICreate,
    },
  );
  typia.assert(post);

  // 3. Like the newly created post as the same member
  const like = await api.functional.discussionboard.interactions.postLikes.post(
    connection,
    {
      body: {
        discussionboard_post_id: post.id,
        discussionboard_member_id: member.id,
      } satisfies IDiscussionboardPostLike.ICreate,
    },
  );
  typia.assert(like);

  // 4. Validate correct linkage and audit information
  TestValidator.equals("like is linked to member")(like.discussionboard_member_id)(member.id);
  TestValidator.equals("like is linked to post")(like.discussionboard_post_id)(post.id);
  TestValidator.predicate("created_at is ISO 8601 datetime")(typeof like.created_at === "string" && !isNaN(Date.parse(like.created_at)));

  // 5. Ensure the like does not already exist by attempting duplicate like and catching error
  await TestValidator.error("duplicate like should fail")(async () => {
    await api.functional.discussionboard.interactions.postLikes.post(
      connection,
      {
        body: {
          discussionboard_post_id: post.id,
          discussionboard_member_id: member.id,
        } satisfies IDiscussionboardPostLike.ICreate,
      },
    );
  });
}

