      body: {
        discussionboard_post_id: typia.random<string & tags.Format<"uuid">>(),
        discussionboard_member_id: "invalid-uuid",
      },
    })
  );

  // Case 3: Both post and member UUIDs invalid
  await TestValidator.error("both IDs invalid")(() =>
    api.functional.discussionboard.interactions.postLikes.post(connection, {
      body: {
        discussionboard_post_id: "invalid-uuid",
        discussionboard_member_id: "invalid-uuid",
      },
