  // Case 4: Non-existent (well-formed) post UUID, valid member UUID
  await TestValidator.error("non-existent post UUID")(() =>
    api.functional.discussionboard.interactions.postLikes.post(connection, {
      body: {
        discussionboard_post_id: fakePostId,
        discussionboard_member_id: typia.random<string & tags.Format<"uuid">>(),
