/**
 * Test updating (admin/audit) mutable fields of a discussion post like (by the like owner).
 *
 * This test simulates a user registering, posting, liking that post, and then attempts to update metadata on the like (such as re-attributing to another member or post) if allowed by the schema.
 *
 * Steps:
 * 1. Register a new member (future like owner)
 * 2. Create a post (assigned to that member, in a random thread)
 * 3. Like the post as the created member
 * 4. Attempt to update the like (change discussionboard_post_id and discussionboard_member_id)
 * 5. Validate that changes are allowed and persisted (or, if forbidden, that values remain unchanged)
 *
 * The assertion tolerates both outcomes (since schema allows optional assignment): if the change goes through, values update; if not permitted (due to role logic), previous values are retained.
 */
export async function test_api_discussionboard_test_update_post_like_metadata_by_owner(
  connection: api.IConnection,
) {
  // 1. Register member (like owner)
  const member = await api.functional.discussionboard.actors.members.post(connection, {
    body: {
      joined_at: new Date().toISOString(),
      status: "active",
    },
  });
  typia.assert(member);

  // 2. Create post (for a random thread using this member)
  const thread_id = typia.random<string & tags.Format<"uuid">>();
  const post = await api.functional.discussionboard.threads.posts.post(connection, {
    body: {
      discussionboard_thread_id: thread_id,
      discussionboard_member_id: member.id,
      body: "Initial forum post content for like testing.",
      created_at: new Date().toISOString(),
    },
  });
  typia.assert(post);

  // 3. Like the post as this member
  const like = await api.functional.discussionboard.interactions.postLikes.post(connection, {
    body: {
      discussionboard_post_id: post.id,
      discussionboard_member_id: member.id,
    },
  });
  typia.assert(like);

  // 4. Attempt to update like: change post and member (simulate audit/meta scenario)
  const new_post_id = typia.random<string & tags.Format<"uuid">>();
  const new_member_id = typia.random<string & tags.Format<"uuid">>();
  const updated = await api.functional.discussionboard.interactions.postLikes.putById(connection, {
    id: like.id,
    body: {
      discussionboard_post_id: new_post_id,
      discussionboard_member_id: new_member_id,
    },
  });
  typia.assert(updated);

  // 5. Accept either model: writable if allowed, or immutable enforced
  TestValidator.predicate("like metadata updated if policy allows, or unchanged if not")(
    (updated.discussionboard_post_id === new_post_id || updated.discussionboard_post_id === post.id) &&
    (updated.discussionboard_member_id === new_member_id || updated.discussionboard_member_id === member.id),
  );
}

