/**
 * 존재하지 않거나 이미 삭제된 discussionboard post like에 대한 DELETE 요청 시 동작 테스트.
 *
 * - 무작위(postLike 존재하지 않는) UUID로 삭제 API를 호출했을 때
 *   1. status가 not found, already deleted, success (idempotent 성공 관련 응답) 중 하나만을 반환
 *   2. deleted_at이 반드시 null로 반환
 *   3. side effect가 없어야 하며 정보 유출이 없어야 함
 *
 * 실제로 이미 삭제된 postLike에 대한 추가 시나리오는 관련 생성 API가 없어 구체적으로 구현 불가하지만,
 * 비존재 UUID에 의한 idempotent delete는 충분히 검증할 수 있음.
 */
export async function test_api_discussionboard_interactions_postLikes_eraseById_invalid(
  connection: api.IConnection,
) {
