 *
 * This test verifies the end-to-end workflow by:
 * 1. Creating a moderation content flag (simulating moderator flagging a post for 'spam'),
 * 2. Retrieving the newly created flag with the GET endpoint using its returned ID,
 * 3. Confirming that the returned DTO includes all required properties and values match the original creation,
 * 4. Asserting required metadata fields are present and properly formatted (dates, types).
 *
 * This ensures the basic compliance of content flag retrieval for admin or moderator contexts and supports moderation/audit workflow correctness.
 */
export async function test_api_discussionboard_moderation_contentFlags_getById_successful_for_admin(
  connection: api.IConnection,
) {
