  const created: IDiscussionboardContentFlag = await api.functional.discussionboard.moderation.contentFlags.post(
    connection,
    {
      body: {
        flagged_post_id: typia.random<string & tags.Format<"uuid">>(),
        flagged_comment_id: null,
        flagged_by_member_id: null,
        set_by_moderator_id: typia.random<string & tags.Format<"uuid">>(),
        flag_type: "spam",
        auto_flagged: false,
      } satisfies IDiscussionboardContentFlag.ICreate,
    },
  );
  typia.assert(created);

  // 2. Retrieve the content flag by its unique ID
  const output: IDiscussionboardContentFlag = await api.functional.discussionboard.moderation.contentFlags.getById(
    connection,
    {
      id: created.id,
    },
  );
