 * 1. Creating a member and a post as dependencies (prerequisites for flagging)
 * 2. Member creates a content flag (user report, e.g., 'abuse').
 * 3. Moderator creates a content flag (e.g., 'spam' type, simulating admin workflow).
 * 4. Verifies all relevant fields in flag responses for both scenarios (consistency, null handling).
 *
 * Purpose: This test validates the end-to-end business flow of flagging content for moderation,
 * confirming API, DTO, and SDK behavior for member and moderator actors, including field correctness,
 * null handling, and review of primary side effects (content flag record stored and retrievable).
 *
 * Steps:
 * - Create a member who will act as the regular user and as the post author
 * - Create a post to be flagged
 * - (A) Member flags their own post as 'abuse' (flagged_by_member_id set)
 *   - All properties (flagged_post_id, flagged_by_member_id, flag_type, flagged_at, auto_flagged) are verified
 * - (B) Moderator flags the post as 'spam' (set_by_moderator_id set)
 *   - All properties (flagged_post_id, set_by_moderator_id, flag_type, flagged_at, auto_flagged) are verified
 * - Verifies null handling (set_by_moderator_id vs flagged_by_member_id)
 *
 * Note: Audit log presence is assumed correct if the API responds as specified, since direct audit validation
 * is not exposed.
 */
export async function test_api_discussionboard_moderation_contentFlags_post(
  connection: api.IConnection,
) {
  // Step 1: Create a member (post author)
  const memberInput: IDiscussionboardMembers.ICreate = {
    joined_at: new Date().toISOString(),
    status: "active",
  };
  const member = await api.functional.discussionboard.actors.members.post(connection, { body: memberInput });
  typia.assert(member);

  // Step 2: Create a post (with random thread ID)
  const threadId = typia.random<string & tags.Format<"uuid">>();
  const postInput: IDiscussionboardPosts.ICreate = {
    discussionboard_thread_id: threadId,
    discussionboard_member_id: member.id,
    body: "Test markdown body",
    created_at: new Date().toISOString(),
  };
  const post = await api.functional.discussionboard.threads.posts.post(connection, { body: postInput });
  typia.assert(post);

  // Step 3A: Member flags their own post as 'abuse'
  const flagInputMember: IDiscussionboardContentFlag.ICreate = {
    flagged_post_id: post.id,
    flagged_comment_id: null,
    flagged_by_member_id: member.id,
