import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMembers } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMembers";
import type { DiscussionBoardModerators } from "@ORGANIZATION/PROJECT-api/lib/structures/DiscussionBoardModerators";
import type { IDiscussionboardPosts } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardPosts";
import type { IDiscussionboardComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardComment";
import type { IDiscussionboardContentFlag } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardContentFlag";

/**
 * Validates that a moderator can flag a comment for moderation purposes (e.g., due to profanity).
 *
 * Business context: Moderators are empowered to flag inappropriate content
 * (such as comments containing profanity) for further review or action. When a moderator
 * flags a comment, the content flag should correctly record the flagged comment ID, the actioning
 * moderator, the type ('profanity'), and indicate manual (not automated) flagging. The flag creation
 * triggers system processes like notifications and audit trail entries. This test ensures that the
 * content flag is registered with the correct relationships, actor, and metadata for full compliance
 * and traceability.
 *
 * Step-by-step process:
 * 1. Register a regular member account
 * 2. Register a second account to be promoted to moderator
 * 3. Create a post in a thread by the regular member
 * 4. Create a comment in that post by the regular member
 * 5. Promote the second account to moderator via the appropriate endpoint
 * 6. As moderator, flag the previously created comment with flag_type 'profanity', referencing the moderator as actor
 * 7. Check that the content flag record has:
 *    - The correct comment ID and no post ID
 *    - The set_by_moderator_id matches the moderator's member ID, and flagged_by_member_id is null
 *    - The flag_type is 'profanity' and auto_flagged is false
 *    - All required audit fields populated (flagged_at)
 * 8. (If API allowed: Optionally verify system-triggered notification or audit side-effects)
 */
export async function test_api_discussionboard_test_create_content_flag_on_comment_by_moderator(
  connection: api.IConnection,
) {
  // 1. Register regular member
  const member: IDiscussionboardMembers =
    await api.functional.discussionboard.actors.members.post(connection, {
      body: {
        joined_at: new Date().toISOString(),
        status: "active",
      } satisfies IDiscussionboardMembers.ICreate,
    });
  typia.assert(member);

  // 2. Register a second member
  const moderatorMember: IDiscussionboardMembers =
    await api.functional.discussionboard.actors.members.post(connection, {
      body: {
        joined_at: new Date().toISOString(),
        status: "active",
      } satisfies IDiscussionboardMembers.ICreate,
    });
  typia.assert(moderatorMember);

  // 3. Create a post by the first member
  const post: IDiscussionboardPosts =
    await api.functional.discussionboard.threads.posts.post(connection, {
      body: {
        discussionboard_thread_id: typia.random<string & tags.Format<"uuid">>(),
        discussionboard_member_id: member.id,
        body: "This is a test post.",
        created_at: new Date().toISOString(),
      } satisfies IDiscussionboardPosts.ICreate,
    });
  typia.assert(post);

  // 4. Create a comment in the post by the first member
  const comment: IDiscussionboardComment =
    await api.functional.discussionboard.threads.comments.post(connection, {
      body: {
        discussionboard_post_id: post.id,
        discussionboard_member_id: member.id,
        body: "This comment contains bad language!",
      } satisfies IDiscussionboardComment.ICreate,
    });
  typia.assert(comment);

  // 5. Promote the second member to moderator
  const moderator: DiscussionBoardModerators =
    await api.functional.discussionboard.actors.moderators.post(connection, {
      body: {
        discussionboard_member_id: moderatorMember.id,
        promoted_at: new Date().toISOString(),
      } satisfies DiscussionBoardModerators.ICreate,
    });
  typia.assert(moderator);

  // 6. As the moderator, flag the comment
  const flag: IDiscussionboardContentFlag =
    await api.functional.discussionboard.moderation.contentFlags.post(connection, {
      body: {
        flagged_comment_id: comment.id,
        flag_type: "profanity",
        set_by_moderator_id: moderatorMember.id,
        auto_flagged: false,
      } satisfies IDiscussionboardContentFlag.ICreate,
    });
  typia.assert(flag);

  // 7. Confirm the returned flag has correct relationships and metadata
  TestValidator.equals("flagged_comment_id")(flag.flagged_comment_id)(comment.id);
  TestValidator.equals("flagged_post_id is null")(flag.flagged_post_id)(null);
  TestValidator.equals("set_by_moderator_id")(flag.set_by_moderator_id)(moderatorMember.id);
  TestValidator.equals("flagged_by_member_id is null")(flag.flagged_by_member_id)(null);
  TestValidator.equals("flag_type")(flag.flag_type)("profanity");
  TestValidator.equals("auto_flagged")(flag.auto_flagged)(false);
  TestValidator.predicate("flagged_at exists")(
    typeof flag.flagged_at === "string" && flag.flagged_at.length > 0,
  );
  // 8. (Optionally) Notification/audit checks would go here if endpoints existed
}

