  const member = await api.functional.discussionboard.actors.members.post(connection, {
    body: {
      joined_at: new Date().toISOString(),
      status: "active",
    } satisfies IDiscussionboardMembers.ICreate,
  });
  typia.assert(member);

  // 2. Create a moderator
  const moderator = await api.functional.discussionboard.actors.members.post(connection, {
    body: {
      joined_at: new Date().toISOString(),
      status: "active",
    } satisfies IDiscussionboardMembers.ICreate,
  });
  typia.assert(moderator);

  // 3. Create a post attached to a synthetic thread
  const threadId = typia.random<string & tags.Format<"uuid">>();
  const post = await api.functional.discussionboard.threads.posts.post(connection, {
    body: {
      discussionboard_thread_id: threadId,
      discussionboard_member_id: member.id,
      body: RandomGenerator.paragraph()(),
      created_at: new Date().toISOString(),
    } satisfies IDiscussionboardPosts.ICreate,
  });
  typia.assert(post);

  // 4. Create a flag on the post, initially by the member
  const initialFlagType = "spam";
  const flag = await api.functional.discussionboard.moderation.contentFlags.post(connection, {
    body: {
      flagged_post_id: post.id,
      flagged_comment_id: null,
      flagged_by_member_id: member.id,
      set_by_moderator_id: null,
      flag_type: initialFlagType,
      auto_flagged: false,
    } satisfies IDiscussionboardContentFlag.ICreate,
