/**
 * E2E test: Soft-delete a content flag as an admin.
 *
 * This test ensures the soft-delete (logical removal) of a moderation content flag from the discussion board.
 * It validates that an admin user can delete a flag, receives a correct deletion result, and all audit fields
 * are present and valid. The flow follows required business logic: user/member creation, admin elevation,
 * content/post creation, flagging, and moderation action by admin.
 *
 * Steps:
 * 1. Create a board member
 * 2. Promote the member to admin (role elevation)
 * 3. Create a post to flag (using the member)
 * 4. Flag the post for moderation (by the member)
 * 5. As admin, soft-delete the flag
 * 6. Validate the API result: correct id, non-empty deleted_at (ISO8601) and success true
 * 7. (SDK does not provide content flag GET API, so post-delete fetch validation cannot be performed)
 */
export async function test_api_discussionboard_moderation_contentFlags_test_delete_content_flag_by_admin(
  connection: api.IConnection,
) {
  // 1. Create a new member
  const memberJoinedAt: string = new Date().toISOString();
  const memberStatus = "active";
