  // 2. Promote to admin
  const adminElevationTime = new Date().toISOString();
  const admin = await api.functional.discussionboard.actors.admins.post(connection, {
    body: {
      discussionboard_member_id: member.id,
      elevated_at: adminElevationTime,
    },
  });
  typia.assert(admin);

  // 3. Create a post (to be flagged)
  const threadId = typia.random<string & tags.Format<"uuid">>();
  const postCreatedAt = new Date().toISOString();
