  const deletion = await api.functional.discussionboard.moderation.contentFlags.eraseById(connection, {
    id: flag.id,
  });
  typia.assert(deletion);

  // 6. Validate deletion response
  TestValidator.equals("deleted flag id matches")(deletion.id)(flag.id);
  TestValidator.predicate("success true")(deletion.success === true);
  TestValidator.predicate("deleted_at present")(typeof deletion.deleted_at === "string" && deletion.deleted_at.length > 0);
  // No post-delete GET validation possible (endpoint not available)
}

