 * 4. Attempt to delete the flag as an unauthenticated (public) user — should also receive a permission or authentication error.
 *
 * This test validates that only privileged roles (admin/moderator) may delete content flags, and all other attempts are properly rejected by the API.
 */
export async function test_api_discussionboard_moderation_contentFlags_test_delete_content_flag_permission_error_for_non_admin_moderator(
