/**
 * E2E test for comment dislike deletion by various roles.
 *
 * This test covers the following scenarios for the comment dislike entity:
 *
 * 1. The owner (memberA) can delete their own dislike (success).
 * 2. A privileged user (admin) can delete any user's dislike (success).
 * 3. A regular user (memberA) attempting to delete another user's dislike (failure; should receive permission error).
 * 4. Attempting to delete an already deleted or non-existent dislike should fail (appropriate error).
 * 5. After deletion, the user can re-create a dislike record for the same comment (ownership is released on deletion).
 *
 * Test sequence:
 * - Register regular members (memberA, memberB) and an admin (adminMember).
 * - Create a comment to receive dislikes.
 * - memberA creates dislikeA, memberB creates dislikeB.
 * - memberA deletes dislikeA (success).
 * - Try to delete dislikeA again (should fail; already deleted).
 * - Admin deletes dislikeB (success).
 * - memberA attempts to delete memberB's (dislikeB) (should fail; not owner nor privileged).
 * - memberA re-creates a dislike (dislikeA2) on the same comment (should succeed).
 *
 * Note: User context switching (for correct permissions) is conceptually represented here; actual connection switching would be managed by auth/session in a real test suite. This test validates core permission, deletion, error, and business logic for dislike lifecycle.
 */
export async function test_api_discussionboard_test_delete_comment_dislike_by_owner_and_privileged_user(
  connection: api.IConnection,
) {
  // Register memberA (regular user)
  const memberA = await api.functional.discussionboard.actors.members.post(connection, {
    body: {
      joined_at: new Date().toISOString(),
      status: 'active',
    },
  });
  typia.assert(memberA);

  // Register memberB (regular user)
  const memberB = await api.functional.discussionboard.actors.members.post(connection, {
    body: {
      joined_at: new Date().toISOString(),
      status: 'active',
    },
  });
  typia.assert(memberB);

  // Register admin (as member + privilege elevation)
  const adminMember = await api.functional.discussionboard.actors.members.post(connection, {
    body: {
      joined_at: new Date().toISOString(),
      status: 'active',
    },
  });
  typia.assert(adminMember);
  const adminRecord = await api.functional.discussionboard.actors.admins.post(connection, {
    body: {
      discussionboard_member_id: adminMember.id,
      elevated_at: new Date().toISOString(),
    },
  });
  typia.assert(adminRecord);

  // memberA creates a comment
  const comment = await api.functional.discussionboard.threads.comments.post(connection, {
    body: {
      discussionboard_post_id: typia.random<string & tags.Format<'uuid'>>(), // Simulate a valid post UUID
      discussionboard_member_id: memberA.id,
      body: 'Sample comment for dislike deletion tests.',
      parent_id: null,
    },
  });
  typia.assert(comment);

  // memberA creates dislikeA
  const dislikeA = await api.functional.discussionboard.interactions.commentDislikes.post(connection, {
    body: {
      discussionboard_comment_id: comment.id,
    },
  });
  typia.assert(dislikeA);

  // memberB creates dislikeB
  const dislikeB = await api.functional.discussionboard.interactions.commentDislikes.post(connection, {
    body: {
      discussionboard_comment_id: comment.id,
    },
  });
  typia.assert(dislikeB);

  // [1] memberA deletes their own dislikeA (should succeed)
  await api.functional.discussionboard.interactions.commentDislikes.eraseById(connection, {
    id: dislikeA.id,
  });

  // [2] Try to delete dislikeA again (should fail: already deleted or not found)
  await TestValidator.error('dislike already deleted or not found')(() =>
    api.functional.discussionboard.interactions.commentDislikes.eraseById(connection, {
      id: dislikeA.id,
    })
  );

  // [3] Admin deletes dislikeB (should succeed)
  await api.functional.discussionboard.interactions.commentDislikes.eraseById(connection, {
    id: dislikeB.id,
  });

  // [4] memberA attempts to delete memberB's (dislikeB) after admin deleted it (should fail: already deleted or permission error)
  await TestValidator.error('regular member cannot delete another user\'s dislike')(() =>
    api.functional.discussionboard.interactions.commentDislikes.eraseById(connection, {
      id: dislikeB.id,
    })
  );

  // [5] memberA re-creates a dislike for the same comment (should succeed)
  const dislikeA2 = await api.functional.discussionboard.interactions.commentDislikes.post(connection, {
    body: {
      discussionboard_comment_id: comment.id,
    },
  });
  typia.assert(dislikeA2);
}

