import type { IDiscussionboardModerationLog } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardModerationLog";

/**
 * End-to-end test for deletion of a moderation log entry by admin, permission checks, and compliance audit.
 *
 * Validates that:
 * 1. An admin is able to delete a moderation log entry by ID
 * 2. The deletion operation marks the entry as deleted (or removes it) according to business rules
 * 3. The deleted log entry is inaccessible for further operations (subsequent operations fail)
 * 4. Deletion as a non-admin (regular member) is forbidden and returns the expected error
 * 5. Deletion of a non-existent log returns a suitable error (404 Not Found or similar)
 *
 * Compliance/audit log verification is commented, as there is no GET or audit trail endpoint available.
 *
 * Steps:
 * 1. Register a member and promote them to admin
 * 2. Create a moderation log entry with that admin as moderator
 * 3. Delete the moderation log as admin
 * 4. Attempt deletion as a non-admin (should fail)
 * 5. Attempt deletion of a random (non-existent) log (should fail)
 */
export async function test_api_discussionboard_test_delete_moderation_log_entry_by_admin_and_permission_denial(
  connection: api.IConnection,
) {
  // 1. Register a new member (will become admin)
  const member = await api.functional.discussionboard.actors.members.post(connection, {
    body: {
      joined_at: new Date().toISOString(),
      status: "active",
    },
  });
  typia.assert(member);

  // 2. Promote the member to admin
  const admin = await api.functional.discussionboard.actors.admins.post(connection, {
    body: {
      discussionboard_member_id: member.id,
      elevated_at: new Date().toISOString(),
    },
  });
  typia.assert(admin);

  // 3. Create a moderation log entry using this admin as the moderator
  const log = await api.functional.discussionboard.moderation.moderationLogs.post(connection, {
    body: {
      moderator_id: member.id,
      action_type: "delete_post",
    },
  });
  typia.assert(log);

  // 4. Delete the moderation log as admin
  await api.functional.discussionboard.moderation.moderationLogs.eraseById(connection, {
    id: log.id,
  });
  // There is no GET to confirm deletion, but subsequent operation (repeat deletion) will yield error if log is gone
  await TestValidator.error("deleting already deleted or missing log should fail")(async () => {
    await api.functional.discussionboard.moderation.moderationLogs.eraseById(connection, {
      id: log.id,
    });
  });

  // 5. Register a non-admin member
  const member2 = await api.functional.discussionboard.actors.members.post(connection, {
    body: {
      joined_at: new Date().toISOString(),
      status: "active",
    },
