  await TestValidator.error("non-admin cannot delete moderation log")(async () => {
    await api.functional.discussionboard.moderation.moderationLogs.eraseById(connection, {
      id: log.id,
    });
  });

  // 6. Try to delete a non-existent moderation log (random UUID) as admin
  await TestValidator.error("admin cannot delete non-existent log")(async () => {
    await api.functional.discussionboard.moderation.moderationLogs.eraseById(connection, {
      id: typia.random<string & tags.Format<"uuid">>(),
    });
