/**
 * Validate that non-admin users (regular members or unauthenticated) cannot access the channel listing endpoint.
 *
 * Business context:
 * The /discussionboard/systematic/channels (PATCH) endpoint is restricted to admins and moderators. Regular members and unauthenticated users must NOT be able to retrieve channel lists, ensuring that forum structure management remains secure and privileged. This test guards against privilege escalation and access control regression.
 *
 * Step-by-step validation:
 * 1. Attempt to access the list channels endpoint with no authentication at all (unauthenticated user)
 *    - Expectation: Access is denied (error is thrown: forbidden/unauthorized)
 * 2. Register a new regular member (using members.post)
 * 3. Attempt to access the same endpoint as this regular member
 *    - Expectation: Access is denied (error is thrown: forbidden/unauthorized)
 *
 * No test is performed with admin/moderator credentials; only denied access scenarios are in scope.
 */
export async function test_api_discussionboard_test_list_channels_permission_denied_for_non_admin_user(
  connection: api.IConnection,
) {
  // 1. Attempt channel listing as an unauthenticated user
  await TestValidator.error("unauthenticated user cannot list channels")(
    async () => {
      await api.functional.discussionboard.systematic.channels.patch(connection, {
        body: {},
      });
    },
  );

  // 2. Register a regular member
  const member = await api.functional.discussionboard.actors.members.post(connection, {
    body: {
      joined_at: new Date().toISOString(),
      status: "active",
    },
  });
  typia.assert(member);

  // 3. Attempt channel listing as the authenticated regular member
  await TestValidator.error("regular member user cannot list channels")(
    async () => {
      await api.functional.discussionboard.systematic.channels.patch(connection, {
        body: {},
      });
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardChannel } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardChannel";
import type { IPageIDiscussionboardChannel } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionboardChannel";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Test correct handling of soft-deleted (archived) channels in listing API.
 *
 * This scenario verifies that channels with deleted_at set (soft-deleted)
 * are either hidden from the general list or indicated as deleted, depending
 * on request parameters. The following steps simulate a typical admin workflow:
 *
 * 1. Create three channels via the POST API.
 * 2. Soft-delete (archive) the second channel using DELETE.
 * 3. Retrieve the channel list without filters and confirm the deleted channel is hidden.
 * 4. Retrieve the channel list with no enabled/disabled filter and confirm the deleted channel is still hidden (unless soft-deleted are always included).
 * 5. (If supported by implementation) Test retrieval with a filter or search parameter which could include or expose soft-deleted records (e.g. paging/sorting/searching edge cases) and check that the deleted channel appears with deleted_at set.
 * 6. Confirm that all existing (non-deleted) channels appear in list and not marked deleted.
 */
export async function test_api_discussionboard_test_list_channels_show_soft_deleted_when_requested(
  connection: api.IConnection,
) {
  // 1. Create three channels with distinct codes/names
  const channels: IDiscussionboardChannel[] = await Promise.all([
    api.functional.discussionboard.systematic.channels.post(connection, {
      body: {
        code: RandomGenerator.alphabets(5),
        name: RandomGenerator.alphabets(8),
        enabled: true,
      },
    }),
    api.functional.discussionboard.systematic.channels.post(connection, {
      body: {
        code: RandomGenerator.alphabets(5),
        name: RandomGenerator.alphabets(8),
        enabled: true,
      },
    }),
    api.functional.discussionboard.systematic.channels.post(connection, {
      body: {
        code: RandomGenerator.alphabets(5),
        name: RandomGenerator.alphabets(8),
        enabled: false,
      },
    }),
  ]);
  channels.forEach(ch => typia.assert(ch));

  // 2. Soft-delete the second channel
  const deletedChannel = channels[1];
  const removeResult = await api.functional.discussionboard.systematic.channels.eraseById(connection, { id: deletedChannel.id });
  typia.assert(removeResult);

  // 3. List all channels (default - should not include soft-deleted)
  const listDefault = await api.functional.discussionboard.systematic.channels.patch(connection, { body: {} });
  typia.assert(listDefault);
  // Confirm soft-deleted channel is not included
  TestValidator.predicate("deleted channel hidden by default")(
    !listDefault.data.some(ch => ch.id === deletedChannel.id)
  );

  // 4. List channels with explicit enabled: null (should also not include soft-deleted)
  const listNoStatus = await api.functional.discussionboard.systematic.channels.patch(connection, { body: { enabled: null } });
  typia.assert(listNoStatus);
  TestValidator.predicate("deleted channel hidden when enabled: null")(
    !listNoStatus.data.some(ch => ch.id === deletedChannel.id)
  );

