  typia.assert(admin);

  const moderator = await api.functional.discussionboard.actors.members.post(connection, { body: { joined_at: now, status: "moderator" } });
  typia.assert(moderator);

  // 2. Creator writes a comment
  const postId = typia.random<string & tags.Format<"uuid">>();
  const comment = await api.functional.discussionboard.threads.comments.post(connection, {
    body: {
      discussionboard_post_id: postId,
      discussionboard_member_id: creator.id,
      body: "Test comment for like-deletion e2e scenario",
    } satisfies IDiscussionboardComment.ICreate,
  });
