  TestValidator.equals("matched discussionboard_member_id")(fetched.discussionboard_member_id)(member.id);
  TestValidator.equals("in_app_enabled matches")(fetched.in_app_enabled)(createPayload.in_app_enabled);
  TestValidator.equals("email_enabled matches")(fetched.email_enabled)(createPayload.email_enabled);
