import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMembers } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMembers";
import type { DiscussionBoardAdmins } from "@ORGANIZATION/PROJECT-api/lib/structures/DiscussionBoardAdmins";
import type { IDiscussionboardMemberNotificationSettings } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMemberNotificationSettings";
import type { IPageDiscussionboardMemberNotificationSettings } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageDiscussionboardMemberNotificationSettings";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { discussionboardMemberNotificationSettings } from "@ORGANIZATION/PROJECT-api/lib/structures/discussionboardMemberNotificationSettings";

/**
 * Validates admin listing, filtering, and pagination of member notification settings.
 *
 * - Ensures multiple members exist and have notification settings with various flag combinations.
 * - Assigns admin role to an account to enable admin-level listing.
 * - Checks that listing API (PATCH /discussionboard/notifications/memberNotificationSettings) supports:
 *   - Filtering by member ID
 *   - Filtering by notification type enabled status
 *   - Pagination: page and limit
 *   - That returned entries all match filter criteria, and pagination metadata is correct.
 *
 * Steps:
 * 1. Create multiple members (at least 3 for variety).
 * 2. For each member, create a notification setting record with distinct combinations of notification booleans.
 * 3. Assign admin privileges to one member (the 'admin').
 * 4. As admin, list notification settings:
 *    a. Filter by a specific member_id and verify only that member’s setting is present.
 *    b. Filter for a type=enabled flag (e.g. in_app_enabled=true), verify only matching records are returned.
 *    c. Paginate: use limit=2, page=2, verify pagination metadata and that results align with expectations.
 */
export async function test_api_discussionboard_test_list_member_notification_settings_as_admin_with_filters(
  connection: api.IConnection,
) {
  // 1. Create members
  const members: IDiscussionboardMembers[] = await ArrayUtil.asyncRepeat(3)(async (i: number) => {
    const statusOptions = ["active", "pending", "suspended"];
    const member = await api.functional.discussionboard.actors.members.post(connection, {
      body: {
        joined_at: new Date(Date.now() - 10000 * (i + 1)).toISOString(),
        status: statusOptions[i % statusOptions.length],
      },
    });
    typia.assert(member);
    return member;
  });

  // 2. Create notification settings with distinct flag combinations
  const flagCombos: Array<Omit<IDiscussionboardMemberNotificationSettings.ICreate, "discussionboard_member_id">> = [
    {
      in_app_enabled: true,
      email_enabled: false,
      reply_notification_enabled: true,
      mention_notification_enabled: false,
      moderation_notification_enabled: true,
      announcement_notification_enabled: false,
    },
    {
      in_app_enabled: false,
      email_enabled: true,
      reply_notification_enabled: false,
      mention_notification_enabled: true,
      moderation_notification_enabled: false,
      announcement_notification_enabled: true,
    },
    {
      in_app_enabled: true,
      email_enabled: true,
      reply_notification_enabled: false,
      mention_notification_enabled: true,
      moderation_notification_enabled: true,
      announcement_notification_enabled: true,
    },
  ];
  const settings: IDiscussionboardMemberNotificationSettings[] = await ArrayUtil.asyncMap(members)(async (m: IDiscussionboardMembers, i: number) => {
    const body: IDiscussionboardMemberNotificationSettings.ICreate = {
      discussionboard_member_id: m.id,
      ...flagCombos[i % flagCombos.length],
    };
    const setting = await api.functional.discussionboard.notifications.memberNotificationSettings.post(connection, { body });
    typia.assert(setting);
    return setting;
  });

  // 3. Assign admin rights to member[0]
  const admin: IDiscussionboardMembers = members[0];
  const adminAssign = await api.functional.discussionboard.actors.admins.post(connection, {
    body: {
      discussionboard_member_id: admin.id,
      elevated_at: new Date().toISOString(),
    },
  });
  typia.assert(adminAssign);

  // 4a. Admin: list settings, filter by member_id
  const byMemberId: IPageDiscussionboardMemberNotificationSettings = await api.functional.discussionboard.notifications.memberNotificationSettings.patch(connection, {
    body: { discussionboard_member_id: members[1].id },
  });
  typia.assert(byMemberId);
  TestValidator.equals("filter by member id")(byMemberId.data.length)(1);
  TestValidator.equals("member id matches")(byMemberId.data[0].discussionboard_member_id)(members[1].id);

  // 4b. Filter for in_app_enabled=true, should get all settings whose in_app_enabled is true
  const byInAppEnabled: IPageDiscussionboardMemberNotificationSettings = await api.functional.discussionboard.notifications.memberNotificationSettings.patch(connection, {
    body: { in_app_enabled: true },
  });
  typia.assert(byInAppEnabled);
  TestValidator.predicate("all in_app_enabled")(byInAppEnabled.data.every((x: discussionboardMemberNotificationSettings) => x.in_app_enabled === true));

  // 4c. Pagination: limit=2, page=2 (should return the 3rd record if present)
  const paged: IPageDiscussionboardMemberNotificationSettings = await api.functional.discussionboard.notifications.memberNotificationSettings.patch(connection, {
    body: { page: 2, limit: 2 },
  });
  typia.assert(paged);
  TestValidator.equals("page is 2")(paged.pagination.current)(2);
  TestValidator.equals("limit is 2")(paged.pagination.limit)(2);
  // The third element should be alone on page 2 if total is 3
  if (settings.length === 3) {
    TestValidator.equals("one record on page 2")(paged.data.length)(1);
  }
}

