import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMembers } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMembers";
import type { IDiscussionboardMemberNotificationSettings } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMemberNotificationSettings";
import type { discussionboardMemberNotificationSettings } from "@ORGANIZATION/PROJECT-api/lib/structures/discussionboardMemberNotificationSettings";

/**
 * Validate updating a discussion board member's notification settings by the owner.
 *
 * This test ensures a member can update their own notification settings and that all updated preferences are correctly persisted. It covers the complete workflow: member creation, initial notification settings creation, and then owner-driven update.
 *
 * Steps:
 * 1. Create a new member (simulates user registration, status 'active').
 * 2. Create initial notification settings for the member with a realistic mix of enabled/disabled flags for different notification types.
 * 3. As the same owner (member), update multiple notification preferences: e.g., toggle email, reply notifications, moderation notifications, and announcement notifications (flip several booleans from their original values).
 * 4. Assert the update response: validate all fields, and check the updated fields changed as expected while non-updated fields remain the same.
 * 5. (Optional) Retrieve settings again if the API supports it to further confirm, but as only update is available, validate using the returned object from the update endpoint.
 *
 * Owner/privilege authentication is assumed by virtue of acting as the original creator within the same test connection context. Edge case (e.g., updating non-existent record, updating another member's settings) is not tested here since focus is on owner flow.
 */
export async function test_api_discussionboard_test_update_member_notification_settings_by_owner(
  connection: api.IConnection,
) {
  // 1. Create member (simulate registration, status 'active', provide join date)
  const memberInput = {
    joined_at: new Date().toISOString(),
    status: "active",
  } satisfies IDiscussionboardMembers.ICreate;
  const member = await api.functional.discussionboard.actors.members.post(connection, {
    body: memberInput,
  });
  typia.assert(member);

  // 2. Create notification settings for this member
  const initialSettingsInput = {
    discussionboard_member_id: member.id,
    in_app_enabled: true,
    email_enabled: false,
    reply_notification_enabled: true,
    mention_notification_enabled: false,
    moderation_notification_enabled: true,
    announcement_notification_enabled: false,
  } satisfies IDiscussionboardMemberNotificationSettings.ICreate;
  const initialSettings = await api.functional.discussionboard.notifications.memberNotificationSettings.post(
    connection,
    {
      body: initialSettingsInput,
    }
  );
  typia.assert(initialSettings);

  // 3. Prepare the updates: flip several booleans from the original settings
  const updateInput = {
    email_enabled: !initialSettings.email_enabled,
    reply_notification_enabled: !initialSettings.reply_notification_enabled,
    moderation_notification_enabled: !initialSettings.moderation_notification_enabled,
    announcement_notification_enabled: !initialSettings.announcement_notification_enabled,
    // Leave in_app_enabled and mention_notification_enabled unchanged
  } satisfies discussionboardMemberNotificationSettings.IUpdate;

  // 4. Update notification settings as the owner
  const updatedSettings = await api.functional.discussionboard.notifications.memberNotificationSettings.putById(
    connection,
    {
      id: initialSettings.id,
      body: updateInput,
    }
  );
  typia.assert(updatedSettings);

  // 5. Assert that updates persisted as expected
  TestValidator.equals("email_enabled updated")(updatedSettings.email_enabled)(updateInput.email_enabled);
  TestValidator.equals("reply_notification_enabled updated")(updatedSettings.reply_notification_enabled)(updateInput.reply_notification_enabled);
  TestValidator.equals("moderation_notification_enabled updated")(updatedSettings.moderation_notification_enabled)(updateInput.moderation_notification_enabled);
  TestValidator.equals("announcement_notification_enabled updated")(updatedSettings.announcement_notification_enabled)(updateInput.announcement_notification_enabled);
  TestValidator.equals("in_app_enabled unchanged")(updatedSettings.in_app_enabled)(initialSettings.in_app_enabled);
  TestValidator.equals("mention_notification_enabled unchanged")(updatedSettings.mention_notification_enabled)(initialSettings.mention_notification_enabled);
  // Confirm member id linkage remains correct
  TestValidator.equals("discussionboard_member_id unchanged")(updatedSettings.discussionboard_member_id)(initialSettings.discussionboard_member_id);
}

