/**
 * Validates that an admin can update notification settings on behalf of another member.
 *
 * Business rationale:
 * In many platforms, administrators must have the privilege to update user notification preferences for support, troubleshooting, or compliance needs. This test verifies that admins can successfully update the notification settings for another member, with all changes saved and correctly reflected.
 *
 * Steps:
 * 1. Create a regular member (target of settings mgmt).
 * 2. Create a separate member to be elevated as admin.
 * 3. Assign admin role to that member.
 * 4. As admin, create initial notification settings for the regular member.
 * 5. As admin, update several notification flags for the member (change a subset of booleans).
 * 6. Assert that both changed and unchanged values are correct, and that the update is tracked by `updated_at` timestamp.
 */
export async function test_api_discussionboard_test_update_member_notification_settings_by_admin(
  connection: api.IConnection,
) {
  // 1. Create a regular member whose notification settings will be administered
  const member = await api.functional.discussionboard.actors.members.post(connection, {
    body: {
      joined_at: new Date().toISOString(),
      status: "active",
    } satisfies IDiscussionboardMembers.ICreate,
  });
  typia.assert(member);

  // 2. Create a second member and promote to admin
  const adminCandidate = await api.functional.discussionboard.actors.members.post(connection, {
    body: {
      joined_at: new Date().toISOString(),
      status: "active",
    } satisfies IDiscussionboardMembers.ICreate,
  });
  typia.assert(adminCandidate);

  // 3. Assign admin role to the new member
  const admin = await api.functional.discussionboard.actors.admins.post(connection, {
    body: {
      discussionboard_member_id: adminCandidate.id,
      elevated_at: new Date().toISOString(),
    } satisfies DiscussionBoardAdmins.ICreate,
  });
  typia.assert(admin);

  // 4. As admin, create notification settings for the target member
  const notificationSettings = await api.functional.discussionboard.notifications.memberNotificationSettings.post(connection, {
    body: {
      discussionboard_member_id: member.id,
      in_app_enabled: true,
      email_enabled: false,
      reply_notification_enabled: true,
      mention_notification_enabled: true,
      moderation_notification_enabled: false,
      announcement_notification_enabled: true,
    } satisfies IDiscussionboardMemberNotificationSettings.ICreate,
  });
  typia.assert(notificationSettings);

  // 5. As admin, update a subset of notification preferences on this member
  const updated = await api.functional.discussionboard.notifications.memberNotificationSettings.putById(connection, {
    id: notificationSettings.id,
    body: {
      in_app_enabled: false,
      moderation_notification_enabled: true,
    } satisfies discussionboardMemberNotificationSettings.IUpdate,
  });
  typia.assert(updated);

  // 6. Assert changes: updated and unchanged fields
  TestValidator.equals("in_app_enabled updated")(updated.in_app_enabled)(false);
  TestValidator.equals("moderation_notification_enabled updated")(updated.moderation_notification_enabled)(true);
  TestValidator.equals("unchanged email_enabled")(updated.email_enabled)(notificationSettings.email_enabled);
  TestValidator.equals("unchanged reply_notification_enabled")(updated.reply_notification_enabled)(notificationSettings.reply_notification_enabled);
  TestValidator.equals("unchanged mention_notification_enabled")(updated.mention_notification_enabled)(notificationSettings.mention_notification_enabled);
  TestValidator.equals("unchanged announcement_notification_enabled")(updated.announcement_notification_enabled)(notificationSettings.announcement_notification_enabled);
  TestValidator.predicate("updated_at is updated")(updated.updated_at !== notificationSettings.updated_at);
}

