/**
 * Test updating an existing admin assignment (DiscussionBoardAdmins) by ID.
 *
 * Business context:
 * This test covers the workflow where privileged admin users update other admin assignments—such as changing elevation time (demotion/recertification). It validates correct privilege enforcement, property persistence, and ensures that changes (like new elevation timestamps) are stored and auditable. The setup ensures a member is created and promoted to admin, then that admin assignment is updated. We also validate that only admins are allowed and changes are persisted according to the schema. (Audit logging validation is acknowledged but not implemented due to API limitations.)
 *
 * Steps:
 * 1. Create a regular member (gained UUID).
 * 2. Promote this member to admin (creates an admin assignment with a unique ID).
 * 3. Update the admin assignment via PUT, changing the elevation timestamp.
 * 4. Verify the returned admin assignment reflects the new elevation timestamp and unchanged fields persist.
 * 5. (Negative Case): Confirm that if a non-admin tries to perform the PUT, access is denied. (Cannot implement: no login or session API in scope. Step acknowledged.)
 */
export async function test_api_discussionboard_admins_test_update_admin_assignment_with_valid_attributes(connection: api.IConnection) {
  // 1. Create a member (simulate registration with random join date and status)
  const member = await api.functional.discussionboard.actors.members.post(connection, {
    body: {
      joined_at: typia.random<string & tags.Format<"date-time">>(),
      status: "active",
    },
  });
