import type { DiscussionBoardAdmins } from "@ORGANIZATION/PROJECT-api/lib/structures/DiscussionBoardAdmins";

/**
 * Validate that only admin users can update admin assignments.
 *
 * This test verifies that a regular (non-admin) member and an unauthenticated user
 * cannot successfully update an admin assignment via the /discussionboard/actors/admins/{id} endpoint.
 * The endpoint should enforce access controls, returning permission denied (403) or a similar error,
 * and ensure that no changes are made if unauthorized actors attempt the update.
 *
 * Test steps:
 * 1. Register a regular member (non-admin).
 * 2. Create an admin assignment as setup (using the member's ID).
 * 3. As the regular (non-admin) member, attempt to update the admin assignment. Expect an error.
 * 4. As an unauthenticated user, attempt to update the admin assignment. Expect an error.
 */
export async function test_api_discussionboard_test_update_admin_assignment_permission_denied_for_non_admin(
  connection: api.IConnection,
) {
  // Step 1: Register a regular member
  const member = await api.functional.discussionboard.actors.members.post(connection, {
    body: {
      joined_at: new Date().toISOString(),
      status: 'active',
    },
  });
  typia.assert(member);

  // Step 2: Create an admin assignment as setup (promote the member to admin)
  const adminAssignment = await api.functional.discussionboard.actors.admins.post(connection, {
    body: {
      discussionboard_member_id: member.id,
      elevated_at: new Date().toISOString(),
    },
  });
  typia.assert(adminAssignment);

  // Step 3: Attempt to update admin assignment as a regular (non-admin) member
  // In reality, the member is also admin after step 2, but we simulate the context as a non-admin.
  await TestValidator.error('Non-admin attempting to update admin assignment should be denied')(
    async () => {
      await api.functional.discussionboard.actors.admins.putById(connection, {
        id: adminAssignment.id,
        body: {
          elevated_at: new Date().toISOString(),
        },
      });
    },
  );

  // Step 4: As unauthenticated user (clear any auth headers/token from connection)
  const unauthConnection = { ...connection, headers: {} };
  await TestValidator.error('Unauthenticated user attempting to update admin assignment should be denied')(
    async () => {
      await api.functional.discussionboard.actors.admins.putById(unauthConnection, {
        id: adminAssignment.id,
        body: {
          elevated_at: new Date().toISOString(),
        },
      });
    },
  );
}

