 * Steps:
 * 1. Attempt to update using a completely random (but valid format) UUID that should not correspond to any real admin assignment.
 * 2. Assert that an error is thrown and no update occurs.
 * 3. Attempt to update using a malformed (invalid format) UUID, and check that API returns a validation error (if supported by backend validation).
 */
export async function test_api_discussionboard_actors_admins_putById_test_update_admin_assignment_with_invalid_id_returns_error(connection: api.IConnection) {
