import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMembers } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMembers";
import type { DiscussionBoardAdmins } from "@ORGANIZATION/PROJECT-api/lib/structures/DiscussionBoardAdmins";

/**
 * Test admin assignment deletion (revocation) via admin DELETE API.
 *
 * Validates both successful revocation of an admin role assignment (given minimum admin coverage)
 * and business logic enforcement that deletion of the last remaining admin is disallowed.
 *
 * 1. Create a regular member (to promote for deletion scenario)
 * 2. Promote that member to admin
 * 3. Create and promote another member to admin (ensure two admins exist for safe deletion)
 * 4. Delete admin assignment for the first promoted admin (should succeed)
 * 5. Attempt deletion of remaining (last) admin assignment, expecting business error
 *
 * Note: Audit log checks are mentioned in the scenario description but cannot be performed
 * directly here, as no audit log query API exists. Should such functionality be added,
 * extend this test to validate that a log entry is recorded for the delete action.
 */
export async function test_api_discussionboard_test_delete_admin_assignment_with_valid_id(
  connection: api.IConnection,
) {
  // 1. Create a regular member to be promoted to admin
  const memberToPromote = await api.functional.discussionboard.actors.members.post(connection, {
    body: {
      joined_at: new Date().toISOString(),
      status: "active",
    } satisfies IDiscussionboardMembers.ICreate,
  });
  typia.assert(memberToPromote);

  // 2. Promote this member to admin
  const adminAssignment = await api.functional.discussionboard.actors.admins.post(connection, {
    body: {
      discussionboard_member_id: memberToPromote.id,
      elevated_at: new Date().toISOString(),
    } satisfies DiscussionBoardAdmins.ICreate,
  });
  typia.assert(adminAssignment);

  // 3. Promote a second member to admin to guarantee at least two admins exist
  const secondMember = await api.functional.discussionboard.actors.members.post(connection, {
    body: {
      joined_at: new Date().toISOString(),
      status: "active",
    } satisfies IDiscussionboardMembers.ICreate,
  });
  typia.assert(secondMember);

  const secondAdminAssignment = await api.functional.discussionboard.actors.admins.post(connection, {
    body: {
      discussionboard_member_id: secondMember.id,
      elevated_at: new Date().toISOString(),
    } satisfies DiscussionBoardAdmins.ICreate,
  });
  typia.assert(secondAdminAssignment);

  // 4. Delete the admin assignment of the first promoted admin (success case)
  await api.functional.discussionboard.actors.admins.eraseById(connection, {
    id: adminAssignment.id,
  });

  // 5. Attempt to delete the second (now last) admin assignment, expecting business error
  await TestValidator.error("deleting last admin must be blocked")(
    async () =>
      await api.functional.discussionboard.actors.admins.eraseById(connection, {
        id: secondAdminAssignment.id,
      })
  );

  // Note: If/when audit log listing API becomes available, add validation of audit log entry for admin revocation here.
}

