import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { DiscussionBoardAdmins } from "@ORGANIZATION/PROJECT-api/lib/structures/DiscussionBoardAdmins";
import type { DiscussionboardModeratorAction } from "@ORGANIZATION/PROJECT-api/lib/structures/DiscussionboardModeratorAction";
import type { IPageDiscussionboardModeratorAction } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageDiscussionboardModeratorAction";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Test retrieval of moderator actions with search and pagination filters.
 *
 * Validates that an admin may retrieve and filter moderator action logs with various parameters:
 * - Moderator ID, action type, target type, and time range filters
 * - Pagination (page, limit)
 * - Edge case: filters that match no data (expect empty results)
 * - Multiple filters combined
 * - Pagination (limit=1) returns a single result page
 *
 * The test also ensures insufficiently privileged users (non-admin/non-moderator roles) receive a 403 forbidden error.
 *
 * Steps:
 * 1. Assign admin role to a random member
 * 2. Create a moderator action log record with known fields
 * 3. List actions filtered by moderator ID and check result includes the created action
 * 4. List actions filtered by action_type, target_type, and time window and verify correct filter
 * 5. List actions with a nonexistent moderator_id filter, expect empty
 * 6. Pagination: limit=1, validate result and metadata
 * 7. Attempt action as unauthorized user, expect forbidden error
 */
export async function test_api_discussionboard_test_list_moderator_actions_with_search_and_pagination_filters(
  connection: api.IConnection,
) {
  // 1. Assign admin privileges to a random member (creates admin role)
  const admin: DiscussionBoardAdmins = await api.functional.discussionboard.actors.admins.post(connection, {
    body: {
      discussionboard_member_id: typia.random<string & tags.Format<"uuid">>(),
      elevated_at: new Date().toISOString(),
    },
  });
  typia.assert(admin);

  // 2. Create a test moderator action log entry
  const modAction: DiscussionboardModeratorAction = await api.functional.discussionboard.actors.moderatorActions.post(connection, {
    body: {
      discussionboard_moderator_id: typia.random<string & tags.Format<"uuid">>(),
      action_type: "delete_comment",
      target_type: "comment",
      target_id: typia.random<string & tags.Format<"uuid">>(),
      details: "Test action for filter validation",
      action_at: new Date().toISOString(),
    },
  });
  typia.assert(modAction);

  // 3. Filtered list by moderator ID (should include created action)
  let result = await api.functional.discussionboard.actors.moderatorActions.patch(connection, {
    body: {
      discussionboard_moderator_id: modAction.discussionboard_moderator_id,
      page: 1,
      limit: 10,
    },
  });
  typia.assert(result);
  TestValidator.predicate("filtered by moderator ID includes created action")(
    result.data.some(a => a.id === modAction.id)
  );

  // 4. Filter by action_type, target_type, and time window (should match created action)
  result = await api.functional.discussionboard.actors.moderatorActions.patch(connection, {
    body: {
      action_type: modAction.action_type,
      target_type: modAction.target_type,
      action_at_from: modAction.action_at,
      action_at_to: modAction.action_at,
      page: 1,
      limit: 10,
    },
  });
  typia.assert(result);
  TestValidator.predicate("all results have correct action/type/target")(
    result.data.every(a => a.action_type === "delete_comment" && a.target_type === "comment")
  );

  // 5. Restrictive filter: unknown moderator ID (expect empty)
  result = await api.functional.discussionboard.actors.moderatorActions.patch(connection, {
    body: {
      discussionboard_moderator_id: typia.random<string & tags.Format<"uuid">>(),
      page: 1,
      limit: 5,
    },
  });
  typia.assert(result);
  TestValidator.equals("empty for invalid moderator")(result.data.length)(0);

  // 6. Pagination: limit=1 (if available)
  result = await api.functional.discussionboard.actors.moderatorActions.patch(connection, {
    body: {
      action_type: modAction.action_type,
      limit: 1,
      page: 1,
    },
  });
  typia.assert(result);
  if (result.data.length > 0) {
    TestValidator.equals("single record page")(result.data.length)(1);
  }

  // 7. Unauthorized user (no admin/moderator role) gets 403
  await TestValidator.error("unauthorized forbidden")(
    async () => {
      const unauthConn: api.IConnection = { ...connection, headers: {} };
      await api.functional.discussionboard.actors.moderatorActions.patch(unauthConn, {
        body: { page: 1, limit: 5 },
      });
    },
  );
}

