import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMembers } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMembers";
import type { DiscussionboardBoard } from "@ORGANIZATION/PROJECT-api/lib/structures/DiscussionboardBoard";
import type { DiscussionBoardBoardTopic } from "@ORGANIZATION/PROJECT-api/lib/structures/DiscussionBoardBoardTopic";

/**
 * Test updating an existing board topic's fields such as title and description, verifying that update is allowed for the creator or authorized members and that the changes are reflected in the API response.
 *
 * Business context:
 * Board topics are discussion threads organized under boards. A member (user) creates a board topic with title/description. Editing/updating topics is permitted by the creator or authorized roles. Topic properties such as title, code, and description can be updated (PUT endpoint accepts partial update). System must enforce validation and ensure final topic reflects the updates.
 *
 * Test workflow:
 * 1. Create a board (as per dependency)
 * 2. Create a member who will be the topic creator (as per dependency)
 * 3. Create a topic under the board, authored by the member (as per dependency)
 * 4. Prepare new values for updatable fields (e.g., title, code, description)
 * 5. Update the topic using the PUT endpoint (acting as the creator)
 * 6. Verify that the response object has the updated values and matches our expectations. Check that fields not updated remain unchanged if omitted.
 */
export async function test_api_discussionboard_test_update_board_topic_success(
  connection: api.IConnection,
) {
  // 1. Create a board so a topic can be made under it
  const categoryId: string = typia.random<string & tags.Format<"uuid">>();
  const boardCreateInput = {
    discussionboard_category_id: categoryId,
    code: RandomGenerator.alphaNumeric(8),
    name: RandomGenerator.content()(16)(),
    description: RandomGenerator.paragraph()(),
    is_active: true,
  } satisfies DiscussionboardBoard.ICreate;
  const board = await api.functional.discussionboard.boards.boards.post(
    connection,
    { body: boardCreateInput },
  );
  typia.assert(board);

  // 2. Create a member (user)
  const joinedAt = new Date().toISOString();
  const memberCreateInput = {
    joined_at: joinedAt,
    status: "active",
  } satisfies IDiscussionboardMembers.ICreate;
  const member = await api.functional.discussionboard.actors.members.post(
    connection,
    { body: memberCreateInput },
  );
  typia.assert(member);

  // 3. Create a topic under the board, by this member
  const topicCode = RandomGenerator.alphaNumeric(10);
  const topicTitle = RandomGenerator.content()(24)();
  const topicDescription = RandomGenerator.paragraph()();
  const topicCreateInput = {
    discussionboard_board_id: board.id,
    code: topicCode,
    title: topicTitle,
    description: topicDescription,
    created_by_member_id: member.id,
  } satisfies DiscussionBoardBoardTopic.ICreate;
  const topic = await api.functional.discussionboard.boards.boardTopics.post(
    connection,
    { body: topicCreateInput },
  );
  typia.assert(topic);

  // 4. Prepare update data (change title, description, and possibly code)
  const newTitle = RandomGenerator.content()(32)();
  const newDescription = RandomGenerator.paragraph()();
  const newCode = RandomGenerator.alphaNumeric(12);
  const updateInput = {
    title: newTitle,
    description: newDescription,
    code: newCode,
  } satisfies DiscussionBoardBoardTopic.IUpdate;

  // 5. Update the topic using the PUT endpoint
  const updatedTopic = await api.functional.discussionboard.boards.boardTopics.putById(
    connection,
    { id: topic.id, body: updateInput },
  );
  typia.assert(updatedTopic);

  // 6. Validation: updated fields are changed, non-updated ones stay the same
  TestValidator.equals("updated title")(updatedTopic.title)(newTitle);
  TestValidator.equals("updated description")(updatedTopic.description)(newDescription);
  TestValidator.equals("updated code")(updatedTopic.code)(newCode);
  TestValidator.equals("updated id unchanged")(updatedTopic.id)(topic.id);
  TestValidator.equals("updated board unchanged")(updatedTopic.discussionboard_board_id)(topic.discussionboard_board_id);
  TestValidator.equals("updated creator unchanged")(updatedTopic.created_by_member_id)(topic.created_by_member_id);
}

