  // Step 2: Create a notification for this member
  const notifType = "announcement";
  const notifTitle = "Test Notification Title";
  const notifBody = "This is a test notification body.";
  const notifUrl = null;
  const notifDeliveredAt = new Date().toISOString();

  const notification = await api.functional.discussionboard.notifications.notifications.post(connection, {
    body: {
      discussionboard_member_id: member.id,
      type: notifType,
      title: notifTitle,
      body: notifBody,
      url: notifUrl,
      delivered_at: notifDeliveredAt,
    } satisfies IDiscussionboardNotification.ICreate,
  });
