import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMembers } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMembers";
import type { IDiscussionboardThreads } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardThreads";
import type { IDiscussionboardPosts } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardPosts";
import type { IPageIDiscussionboardPosts } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionboardPosts";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validate listing posts of a discussion thread, with filtering and paging.
 *
 * This test creates a member, a discussion thread, and several posts. It then calls the post-listing API with filters (thread ID, optional page/limit/sort) to emulate a forum browse scenario.
 *
 * Steps:
 * 1. Create a member who will author posts.
 * 2. Create a new thread by the member on some board.
 * 3. Create several posts under the thread, authored by the same member.
 * 4. Call the PATCH /discussionboard/threads/posts with a filter for thread ID and page/limit/sort params.
 * 5. Assert that only posts from the thread are returned, the pagination structure is correct, and post order matches expectation.
 */
export async function test_api_discussionboard_test_list_posts_with_valid_filters_and_pagination(
  connection: api.IConnection,
) {
  // 1. Create a new member
  const member = await api.functional.discussionboard.actors.members.post(connection, {
    body: {
      joined_at: new Date().toISOString(),
      status: "active",
    },
  });
  typia.assert(member);

  // 2. Create a thread on a board (board_id random, just needs to exist for DTO)
  const thread = await api.functional.discussionboard.threads.threads.post(connection, {
    body: {
      discussionboard_board_id: typia.random<string & tags.Format<"uuid">>(),
      discussionboard_member_id: member.id,
      title: RandomGenerator.paragraph()(6),
      description: RandomGenerator.paragraph()(10),
      status: "open",
      created_at: new Date().toISOString(),
    },
  });
  typia.assert(thread);

  // 3. Create 7 posts in the thread
  const postCount = 7;
  const posts: IDiscussionboardPosts[] = [];
  for (let i = 0; i < postCount; ++i) {
    const post = await api.functional.discussionboard.threads.posts.post(connection, {
      body: {
        discussionboard_thread_id: thread.id,
        discussionboard_member_id: member.id,
        body: `Test post body ${i + 1}`,
        created_at: new Date(Date.now() + i * 1000).toISOString(),
      },
    });
    typia.assert(post);
    posts.push(post);
  }

  // 4. List posts with thread filter and limit 5 (page 1, sorted by created_at desc)
  const listResult = await api.functional.discussionboard.threads.posts.patch(connection, {
    body: {
      discussionboard_thread_id: thread.id,
      page: 1,
      limit: 5,
      sort: "created_at desc",
    },
  });
  typia.assert(listResult);
  TestValidator.equals("pagination.current")(listResult.pagination.current)(1);
  TestValidator.equals("pagination.limit")(listResult.pagination.limit)(5);
  TestValidator.equals("pagination.records")(listResult.pagination.records)(postCount);
  TestValidator.equals("data.length")(listResult.data.length)(5);

  // Posts should be newest-first
  const sortedPosts = [...posts].sort((a, b) => b.created_at.localeCompare(a.created_at));
  for (let i = 0; i < listResult.data.length; ++i) {
    TestValidator.equals(`post id at index ${i}`)(listResult.data[i].id)(sortedPosts[i].id);
    TestValidator.equals(`post thread id at index ${i}`)(listResult.data[i].discussionboard_thread_id)(thread.id);
  }

  // 5. Test the last page (should contain only remaining posts)
  const pages = Math.ceil(postCount / 5);
  const lastPageResult = await api.functional.discussionboard.threads.posts.patch(connection, {
    body: {
      discussionboard_thread_id: thread.id,
      page: pages,
      limit: 5,
      sort: "created_at desc",
    },
  });
  typia.assert(lastPageResult);
  TestValidator.equals("last page current")(lastPageResult.pagination.current)(pages);
  TestValidator.equals("data.length")(lastPageResult.data.length)(postCount - 5);
  for (let i = 0; i < lastPageResult.data.length; ++i) {
    TestValidator.equals(`last page post id at index ${i}`)(lastPageResult.data[i].id)(sortedPosts[5 + i].id);
    TestValidator.equals(`last page post thread id at index ${i}`)(lastPageResult.data[i].discussionboard_thread_id)(thread.id);
  }
}

