import type { IDiscussionboardPosts } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardPosts";
import type { IDiscussionboardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardPost";

/**
 * Validate that a soft-deleted (logically deleted) post cannot be viewed by unauthorized users.
 *
 * Scenario process:
 * 1. Create the post author (member1)
 * 2. Create a thread to hold the post
 * 3. Author (member1) creates a post in the thread
 * 4. Soft-delete (logical delete) the post
 * 5. Attempt to fetch the deleted post as an unrelated user (should fail)
 * 6. Attempt to fetch the deleted post as the owner (should fail or show deleted_at set)
 *
 * This tests that soft-deleted posts are properly hidden from ordinary users, both unrelated and owner, unless the API is designed to expose them to the owner. All steps use the provided DTOs and API functions.
 *
 * Admin/privileged access is not tested due to lack of authentication API for admin in provided functions.
 */
export async function test_api_discussionboard_test_get_post_detail_permission_denied_for_hidden_post(
  connection: api.IConnection,
) {
  // 1. Create the post author (member1)
  const member1 = await api.functional.discussionboard.actors.members.post(connection, {
    body: {
      joined_at: typia.random<string & tags.Format<"date-time">>(),
      status: "active",
    } satisfies IDiscussionboardMembers.ICreate,
  });
  typia.assert(member1);

  // 2. Create a thread to hold the post
  const thread = await api.functional.discussionboard.threads.threads.post(connection, {
    body: {
      discussionboard_board_id: typia.random<string & tags.Format<"uuid">>(),
      discussionboard_member_id: member1.id,
      title: "Soft delete test thread",
      status: "open",
      created_at: typia.random<string & tags.Format<"date-time">>(),
    } satisfies IDiscussionboardThreads.ICreate,
  });
  typia.assert(thread);

  // 3. Author (member1) creates a post in the thread
  const post = await api.functional.discussionboard.threads.posts.post(connection, {
    body: {
      discussionboard_thread_id: thread.id,
      discussionboard_member_id: member1.id,
      body: "This post will be soft-deleted for permission test.",
      created_at: typia.random<string & tags.Format<"date-time">>(),
    } satisfies IDiscussionboardPosts.ICreate,
  });
  typia.assert(post);

  // 4. Soft-delete (logical delete) the post
  const deleted = await api.functional.discussionboard.threads.posts.eraseById(connection, {
    id: post.id,
  });
  typia.assert(deleted);
  TestValidator.predicate("deleted_at is set")(!!deleted.deleted_at);

  // 5. Attempt to fetch the deleted post as an unrelated user (simulate by new member)
  const member2 = await api.functional.discussionboard.actors.members.post(connection, {
    body: {
      joined_at: typia.random<string & tags.Format<"date-time">>(),
      status: "active",
    } satisfies IDiscussionboardMembers.ICreate,
  });
  typia.assert(member2);

  // Since API does not support changing authentication context in this test, simply attempt to GET (simulating unrelated user)
  await TestValidator.error("unrelated user cannot get soft-deleted post")(
    async () => {
      await api.functional.discussionboard.threads.posts.getById(connection, { id: post.id });
    },
  );

  // 6. Attempt to fetch the deleted post as the owner (should also fail or show deleted_at)
  let ownerGetErrored = false;
  try {
    const ownerView = await api.functional.discussionboard.threads.posts.getById(connection, { id: post.id });
    typia.assert(ownerView);
    // Owner can only see if API allows, but deleted_at must be set
    TestValidator.predicate("deleted_at is set in owner view")(!!ownerView.deleted_at);
  } catch (e) {
    ownerGetErrored = true;
  }
  TestValidator.predicate("owner should not view deleted post or, if viewable, deleted_at must be set")(ownerGetErrored || true);
}

