    body: {
      discussionboard_thread_id: thread.id,
      discussionboard_member_id: owner.id,
      body: "This is the original post body.",
      created_at: new Date().toISOString(),
    } satisfies IDiscussionboardPosts.ICreate,
  });
  typia.assert(post);

  // 5. As user B, attempt to update the post created by user A
