 * Test that deleting another user's post is denied for a non-author, non-moderator member.
 *
 * Business context:
 * - Only the original post author or privileged users (moderators/admins) are allowed to delete posts.
 * - A standard member (member B) should not be able to delete a post created by another member (member A).
 *
 * Test process:
 * 1. Register two members: member A (the author), and member B (unprivileged user).
 * 2. As member A, create a thread in some board.
 * 3. As member A, create a post in the thread.
 * 4. As member B (not the author), attempt to delete the post using DELETE /discussionboard/threads/posts/{id}.
 * 5. Assert that the deletion is blocked by a runtime error, verifying permission enforcement works and no type violation occurs.
 * 6. (Optional) If the API allows, check the post is still not deleted (deleted_at still null) -- but this may require extra API support which is out of scope here.
 */
export async function test_api_discussionboard_test_delete_post_fails_for_non_author_user(
  connection: api.IConnection,
) {
  // 1. Register author member (A)
  const now: string = new Date().toISOString();
  const memberA = await api.functional.discussionboard.actors.members.post(connection, {
    body: {
      joined_at: now,
      status: "active",
