      discussionboard_member_id: memberA.id,
      body: "This post should only be deletable by its author.",
      created_at: now,
    } satisfies IDiscussionboardPosts.ICreate,
  });
  typia.assert(post);

  // 5. As member B, attempt to delete member A's post — expect runtime permission error.
