    body: {
      discussionboard_member_id: moderator.id,
      promoted_at: new Date().toISOString(),
    } satisfies DiscussionBoardModerators.ICreate,
  });
  typia.assert(modAssignment);

  // 4. Create a new thread as the author (needs a random board id)
  const boardId: string & tags.Format<"uuid"> = typia.random<string & tags.Format<"uuid">>();
  const thread: IDiscussionboardThreads = await api.functional.discussionboard.threads.threads.post(connection, {
    body: {
      discussionboard_board_id: boardId,
      discussionboard_member_id: author.id,
      title: RandomGenerator.paragraph()(4),
      description: RandomGenerator.paragraph()(6),
      status: "open",
      created_at: new Date().toISOString(),
    } satisfies IDiscussionboardThreads.ICreate,
  });
  typia.assert(thread);

  // 5. Author creates a post in the thread
  const post: IDiscussionboardPosts = await api.functional.discussionboard.threads.posts.post(connection, {
    body: {
