import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validates advanced filtering and pagination for listing topic tags in the discussion board system.
 *
 * Ensures that both authenticated members and public users can retrieve paginated lists of topic tags
 * using a combination of filters (such as active-only, partial tag search) and pagination parameters.
 * Also checks handling of empty results, last-page boundary, and accurate pagination metadata.
 *
 * Steps:
 * 1. List all topic tags without filters (baseline).
 * 2. List only active topic tags and verify all returned tags are active.
 * 3. Search using a partial name substring from an actual tag to test tag name filtering.
 * 4. Paginate using (page=2, limit=1) to validate page navigation.
 * 5. Query the exact last page with a specific limit and verify the result set does not exceed the page size.
 * 6. Filter by a random gibberish string to confirm the system returns an empty set.
 */
export async function test_api_discussionboard_test_list_topic_tags_with_filtering_and_pagination(
  connection: api.IConnection,
) {
  // 1. List all topic tags without filters (baseline)
  const baseline: IPageDiscussionBoardTopicTag = await api.functional.discussionboard.boards.topicTags.patch(connection, {
    body: {},
  });
  typia.assert(baseline);

  // Confirm at least one tag exists for search/filter scenarios
  TestValidator.predicate("topic tag(s) exist for meaningful tests")(baseline.data.length > 0);
  const refTag = baseline.data[0];

  // 2. List only active topic tags
  const active: IPageDiscussionBoardTopicTag = await api.functional.discussionboard.boards.topicTags.patch(connection, {
    body: { is_active: true },
  });
  typia.assert(active);
  active.data.forEach(tag => {
    TestValidator.equals("tag is active")(tag.is_active)(true);
  });

  // 3. Search topic tags by a partial tag name substring
  const searchSub = refTag.name.slice(0, Math.max(1, Math.floor(refTag.name.length / 2)));
  const partialSearch: IPageDiscussionBoardTopicTag = await api.functional.discussionboard.boards.topicTags.patch(connection, {
    body: { filter: searchSub },
  });
  typia.assert(partialSearch);
  partialSearch.data.forEach(tag => {
    TestValidator.predicate("tag name contains search substring")(tag.name.includes(searchSub));
  });

  // 4. Paginate with page=2, limit=1 (if enough tags)
  if (baseline.pagination.records > 1) {
    const paged: IPageDiscussionBoardTopicTag = await api.functional.discussionboard.boards.topicTags.patch(connection, {
      body: { page: 2, limit: 1 },
    });
    typia.assert(paged);
    TestValidator.equals("pagination current page")(paged.pagination.current)(2);
    TestValidator.equals("pagination limit")(paged.pagination.limit)(1);
    TestValidator.predicate("one or zero records on small page")(paged.data.length <= 1);
  }

  // 5. Query the computed last page (with limit=2)
  const pageLimit = 2;
  const baseLimited: IPageDiscussionBoardTopicTag = await api.functional.discussionboard.boards.topicTags.patch(connection, {
    body: { limit: pageLimit },
  });
  typia.assert(baseLimited);
  const lastPageIndex = baseLimited.pagination.pages;
  if (lastPageIndex > 0) {
    const lastPage: IPageDiscussionBoardTopicTag = await api.functional.discussionboard.boards.topicTags.patch(connection, {
      body: { page: lastPageIndex, limit: pageLimit },
    });
    typia.assert(lastPage);
    TestValidator.equals("last page number")(lastPage.pagination.current)(lastPageIndex);
    TestValidator.predicate("does not overflow page size")(lastPage.data.length <= pageLimit);
  }

  // 6. Use a filter that yields no results
  const empty: IPageDiscussionBoardTopicTag = await api.functional.discussionboard.boards.topicTags.patch(connection, {
    body: { filter: "no-such-tag-gibberish-randstring" },
  });
  typia.assert(empty);
  TestValidator.equals("no results with bogus filter")(empty.data.length)(0);
}

